export const ALL_KURALS: Thirukkural[] = [
  { id: 1, kural_number: 1, tamil_text: 'அகர முதல எழுத்தெல்லாம் ஆதி பகவன் முதற்றே உலகு.', transliteration: 'Akara Mudhala Ezhuththellaam Aadhi Pakavan Mudhatre Ulaku', english_meaning: 'As the letter A is the first of all letters, so the eternal God is first in the world', career_application: 'As the letter A is the first of all letters, so the eternal God is first in the world', chapter: 'The Praise of God' },
  { id: 2, kural_number: 2, tamil_text: 'கற்றதனால் ஆய பயனென்கொல் வாலறிவன் நற்றாள் தொழாஅர் எனின்.', transliteration: 'Katradhanaal Aaya Payanenkol Vaalarivan Natraal Thozhaaar Enin', english_meaning: 'What Profit have those derived from learning, who worship not the good feet of Him who is possessed of pure knowledge ?', career_application: 'What Profit have those derived from learning, who worship not the good feet of Him who is possessed of pure knowledge ?', chapter: 'The Praise of God' },
  { id: 3, kural_number: 3, tamil_text: 'மலர்மிசை ஏகினான் மாணடி சேர்ந்தார் நிலமிசை நீடுவாழ் வார்.', transliteration: 'Malarmisai Ekinaan Maanati Serndhaar Nilamisai Neetuvaazh Vaar', english_meaning: 'They who are united to the glorious feet of Him who passes swiftly over the flower of the mind, shall flourish long above all worlds', career_application: 'They who are united to the glorious feet of Him who passes swiftly over the flower of the mind, shall flourish long above all worlds', chapter: 'The Praise of God' },
  { id: 4, kural_number: 4, tamil_text: 'வேண்டுதல் வேண்டாமை இலானடி சேர்ந்தார்க்கு யாண்டும் இடும்பை இல.', transliteration: 'Ventudhal Ventaamai Ilaanati Serndhaarkku Yaantum Itumpai Ila', english_meaning: 'To those who meditate the feet of Him who is void of desire or aversion, evil shall never come', career_application: 'To those who meditate the feet of Him who is void of desire or aversion, evil shall never come', chapter: 'The Praise of God' },
  { id: 5, kural_number: 5, tamil_text: 'இருள்சேர் இருவினையும் சேரா இறைவன் பொருள்சேர் புகழ்புரிந்தார் மாட்டு.', transliteration: 'Irulser Iruvinaiyum Seraa Iraivan Porulser Pukazhpurindhaar Maattu', english_meaning: 'The two-fold deeds that spring from darkness shall not adhere to those who delight in the true praise of God', career_application: 'The two-fold deeds that spring from darkness shall not adhere to those who delight in the true praise of God', chapter: 'The Praise of God' },
  { id: 6, kural_number: 6, tamil_text: 'பொறிவாயில் ஐந்தவித்தான் பொய்தீர் ஒழுக்க நெறிநின்றார் நீடுவாழ் வார்.', transliteration: 'Porivaayil Aindhaviththaan Poidheer Ozhukka Nerinindraar Neetuvaazh Vaar', english_meaning: 'Those shall long proposer who abide in the faultless way of Him who has destroyed the five desires of the senses', career_application: 'Those shall long proposer who abide in the faultless way of Him who has destroyed the five desires of the senses', chapter: 'The Praise of God' },
  { id: 7, kural_number: 7, tamil_text: 'தனக்குவமை இல்லாதான் தாள்சேர்ந்தார்க் கல்லால் மனக்கவலை மாற்றல் அரிது.', transliteration: 'Thanakkuvamai Illaadhaan Thaalserndhaark Kallaal Manakkavalai Maatral Aridhu', english_meaning: 'Anxiety of mind cannot be removed, except from those who are united to the feet of Him who is incomparable', career_application: 'Anxiety of mind cannot be removed, except from those who are united to the feet of Him who is incomparable', chapter: 'The Praise of God' },
  { id: 8, kural_number: 8, tamil_text: 'அறவாழி அந்தணன் தாள்சேர்ந்தார்க் கல்லால் பிறவாழி நீந்தல் அரிது.', transliteration: 'Aravaazhi Andhanan Thaalserndhaark Kallaal Piravaazhi Neendhal Aridhu', english_meaning: 'None can swim the sea of vice, but those who are united to the feet of that gracious Being who is a sea of virtue', career_application: 'None can swim the sea of vice, but those who are united to the feet of that gracious Being who is a sea of virtue', chapter: 'The Praise of God' },
  { id: 9, kural_number: 9, tamil_text: 'கோளில் பொறியின் குணமிலவே எண்குணத்தான் தாளை வணங்காத் தலை.', transliteration: 'Kolil Poriyin Kunamilave Enkunaththaan Thaalai Vanangaath Thalai', english_meaning: 'The head that worships not the feet of Him who is possessed of eight attributes, is as useless as a sense without the power of sensation', career_application: 'The head that worships not the feet of Him who is possessed of eight attributes, is as useless as a sense without the power of sensation', chapter: 'The Praise of God' },
  { id: 10, kural_number: 10, tamil_text: 'பிறவிப் பெருங்கடல் நீந்துவர் நீந்தார் இறைவன் அடிசேரா தார்.', transliteration: 'Piravip Perungatal Neendhuvar Neendhaar Iraivan Atiseraa Thaar', english_meaning: 'None can swim the great sea of births but those who are united to the feet of God', career_application: 'None can swim the great sea of births but those who are united to the feet of God', chapter: 'The Praise of God' },
  { id: 11, kural_number: 11, tamil_text: 'வான்நின்று உலகம் வழங்கி வருதலால் தான்அமிழ்தம் என்றுணரற் பாற்று.', transliteration: 'Vaannindru Ulakam Vazhangi Varudhalaal Thaanamizhdham Endrunarar Paatru', english_meaning: 'By the continuance of rain the world is preserved in existence; it is therefore worthy to be called ambrosia', career_application: 'By the continuance of rain the world is preserved in existence; it is therefore worthy to be called ambrosia', chapter: 'The Blessing of Rain' },
  { id: 12, kural_number: 12, tamil_text: 'துப்பார்க்குத் துப்பாய துப்பாக்கித் துப்பார்க்குத் துப்பாய தூஉம் மழை.', transliteration: 'Thuppaarkkuth Thuppaaya Thuppaakkith Thuppaarkkuth Thuppaaya Thooum Mazhai', english_meaning: 'Rain produces good food, and is itself food', career_application: 'Rain produces good food, and is itself food', chapter: 'The Blessing of Rain' },
  { id: 13, kural_number: 13, tamil_text: 'விண்இன்று பொய்ப்பின் விரிநீர் வியனுலகத்து உள்நின்று உடற்றும் பசி.', transliteration: 'Vinindru Poippin Virineer Viyanulakaththu Ulnindru Utatrum Pasi', english_meaning: 'If the cloud, withholding rain, deceive (our hopes) hunger will long distress the sea-girt spacious world', career_application: 'If the cloud, withholding rain, deceive (our hopes) hunger will long distress the sea-girt spacious world', chapter: 'The Blessing of Rain' },
  { id: 14, kural_number: 14, tamil_text: 'ஏரின் உழாஅர் உழவர் புயல்என்னும் வாரி வளங்குன்றிக் கால்.', transliteration: 'Erin Uzhaaar Uzhavar Puyalennum Vaari Valangundrik Kaal', english_meaning: 'If the abundance of wealth imparting rain diminish, the labour of the plough must cease', career_application: 'If the abundance of wealth imparting rain diminish, the labour of the plough must cease', chapter: 'The Blessing of Rain' },
  { id: 15, kural_number: 15, tamil_text: 'கெடுப்பதூஉம் கெட்டார்க்குச் சார்வாய்மற் றாங்கே எடுப்பதூஉம் எல்லாம் மழை.', transliteration: 'Ketuppadhooum Kettaarkkuch Chaarvaaimar Raange Etuppadhooum Ellaam Mazhai', english_meaning: 'Rain by its absence ruins men; and by its existence restores them to fortune', career_application: 'Rain by its absence ruins men; and by its existence restores them to fortune', chapter: 'The Blessing of Rain' },
  { id: 16, kural_number: 16, tamil_text: 'விசும்பின் துளிவீழின் அல்லால்மற் றாங்கே பசும்புல் தலைகாண்பு அரிது.', transliteration: 'Visumpin Thuliveezhin Allaalmar Raange Pasumpul Thalaikaanpu Aridhu', english_meaning: 'If no drop falls from the clouds, not even the green blade of grass will be seen', career_application: 'If no drop falls from the clouds, not even the green blade of grass will be seen', chapter: 'The Blessing of Rain' },
  { id: 17, kural_number: 17, tamil_text: 'நெடுங்கடலும் தன்நீர்மை குன்றும் தடிந்தெழிலி தான்நல்கா தாகி விடின்.', transliteration: 'Netungatalum Thanneermai Kundrum Thatindhezhili Thaannalkaa Thaaki Vitin', english_meaning: 'Even the wealth of the wide sea will be diminished, if the cloud that has drawn (its waters) up gives them not back again (in rain)', career_application: 'Even the wealth of the wide sea will be diminished, if the cloud that has drawn (its waters) up gives them not back again (in rain)', chapter: 'The Blessing of Rain' },
  { id: 18, kural_number: 18, tamil_text: 'சிறப்பொடு பூசனை செல்லாது வானம் வறக்குமேல் வானோர்க்கும் ஈண்டு.', transliteration: 'Sirappotu Poosanai Sellaadhu Vaanam Varakkumel Vaanorkkum Eentu', english_meaning: 'If the heaven dry up, neither yearly festivals, nor daily worship will be offered in this world, to the celestials', career_application: 'If the heaven dry up, neither yearly festivals, nor daily worship will be offered in this world, to the celestials', chapter: 'The Blessing of Rain' },
  { id: 19, kural_number: 19, tamil_text: 'தானம் தவம்இரண்டும் தங்கா வியன்உலகம் வானம் வழங்கா தெனின்.', transliteration: 'Thaanam Thavamirantum Thangaa Viyanulakam Vaanam Vazhangaa Thenin', english_meaning: 'If rain fall not, penance and alms-deeds will not dwell within this spacious world', career_application: 'If rain fall not, penance and alms-deeds will not dwell within this spacious world', chapter: 'The Blessing of Rain' },
  { id: 20, kural_number: 20, tamil_text: 'நீர்இன்று அமையாது உலகெனின் யார்யார்க்கும் வான்இன்று அமையாது ஒழுக்கு.', transliteration: 'Neerindru Amaiyaadhu Ulakenin Yaaryaarkkum Vaanindru Amaiyaadhu Ozhukku', english_meaning: 'If it be said that the duties of life cannot be discharged by any person without water, so without rain there cannot be the flowing of water', career_application: 'If it be said that the duties of life cannot be discharged by any person without water, so without rain there cannot be the flowing of water', chapter: 'The Blessing of Rain' },
  { id: 21, kural_number: 21, tamil_text: 'ஒழுக்கத்து நீத்தார் பெருமை விழுப்பத்து வேண்டும் பனுவல் துணிவு.', transliteration: 'Ozhukkaththu Neeththaar Perumai Vizhuppaththu Ventum Panuval Thunivu', english_meaning: 'The end and aim of all treatise is to extol beyond all other excellence, the greatness of those who, while abiding in the rule of conduct peculiar to their state, have abandoned all desire', career_application: 'The end and aim of all treatise is to extol beyond all other excellence, the greatness of those who, while abiding in the rule of conduct peculiar to their state, have abandoned all desire', chapter: 'The Greatness of Ascetics' },
  { id: 22, kural_number: 22, tamil_text: 'துறந்தார் பெருமை துணைக்கூறின் வையத்து இறந்தாரை எண்ணிக்கொண் டற்று.', transliteration: 'Thurandhaar Perumai Thunaikkoorin Vaiyaththu Irandhaarai Ennikkon Tatru', english_meaning: 'To describe the measure of the greatness of those who have forsaken the two-fold desires, is like counting the dead', career_application: 'To describe the measure of the greatness of those who have forsaken the two-fold desires, is like counting the dead', chapter: 'The Greatness of Ascetics' },
  { id: 23, kural_number: 23, tamil_text: 'இருமை வகைதெரிந்து ஈண்டுஅறம் பூண்டார் பெருமை பிறங்கிற்று உலகு.', transliteration: 'Irumai Vakaidherindhu Eentuaram Poontaar Perumai Pirangitru Ulaku', english_meaning: 'The greatness of those who have discovered the properties of both states of being, and renounced the world, shines forth on earth (beyond all others)', career_application: 'The greatness of those who have discovered the properties of both states of being, and renounced the world, shines forth on earth (beyond all others)', chapter: 'The Greatness of Ascetics' },
  { id: 24, kural_number: 24, tamil_text: 'உரனென்னும் தோட்டியான் ஓரைந்தும் காப்பான் வரனென்னும் வைப்பிற்கோர் வித்து.', transliteration: 'Uranennum Thottiyaan Oraindhum Kaappaan Varanennum Vaippirkor Viththu', english_meaning: 'He who guides his five senses by the hook of wisdom will be a seed in the world of heaven', career_application: 'He who guides his five senses by the hook of wisdom will be a seed in the world of heaven', chapter: 'The Greatness of Ascetics' },
  { id: 25, kural_number: 25, tamil_text: 'ஐந்தவித்தான் ஆற்றல் அகல்விசும்பு ளார்கோமான் இந்திரனே சாலுங் கரி.', transliteration: 'Aindhaviththaan Aatral Akalvisumpu Laarkomaan Indhirane Saalung Kari', english_meaning: 'Indra, the king of the inhabitants of the spacious heaven, is himself, a sufficient proof of the strength of him who has subdued his five senses', career_application: 'Indra, the king of the inhabitants of the spacious heaven, is himself, a sufficient proof of the strength of him who has subdued his five senses', chapter: 'The Greatness of Ascetics' },
  { id: 26, kural_number: 26, tamil_text: 'செயற்கரிய செய்வார் பெரியர் சிறியர் செயற்கரிய செய்கலா தார்.', transliteration: 'Seyarkariya Seyvaar Periyar Siriyar Seyarkariya Seykalaa Thaar', english_meaning: 'The great will do those things which is difficult to be done; but the mean cannot do them', career_application: 'The great will do those things which is difficult to be done; but the mean cannot do them', chapter: 'The Greatness of Ascetics' },
  { id: 27, kural_number: 27, tamil_text: 'சுவைஒளி ஊறுஓசை நாற்றமென ஐந்தின் வகைதெரிவான் கட்டே உலகு.', transliteration: 'Suvaioli Ooruosai Naatramendru Aindhin Vakaidherivaan Katte Ulaku', english_meaning: 'The world is within the knowledge of him who knows the properties of taste, sight, touch, hearing and smell', career_application: 'The world is within the knowledge of him who knows the properties of taste, sight, touch, hearing and smell', chapter: 'The Greatness of Ascetics' },
  { id: 28, kural_number: 28, tamil_text: 'நிறைமொழி மாந்தர் பெருமை நிலத்து மறைமொழி காட்டி விடும்.', transliteration: 'Niraimozhi Maandhar Perumai Nilaththu Maraimozhi Kaatti Vitum', english_meaning: 'The hidden words of the men whose words are full of effect, will shew their greatness to the world', career_application: 'The hidden words of the men whose words are full of effect, will shew their greatness to the world', chapter: 'The Greatness of Ascetics' },
  { id: 29, kural_number: 29, tamil_text: 'குணமென்னும் குன்றேறி நின்றார் வெகுளி கணமேயும் காத்தல் அரிது.', transliteration: 'Kunamennum Kundreri Nindraar Vekuli Kanameyum Kaaththal Aridhu', english_meaning: 'The anger of those who have ascended the mountain of goodness, though it continue but for a moment, cannot be resisted', career_application: 'The anger of those who have ascended the mountain of goodness, though it continue but for a moment, cannot be resisted', chapter: 'The Greatness of Ascetics' },
  { id: 30, kural_number: 30, tamil_text: 'அந்தணர் என்போர் அறவோர்மற் றெவ்வுயிர்க்கும் செந்தண்மை பூண்டொழுக லான்.', transliteration: 'Andhanar Enpor Aravormar Revvuyir Kkum Sendhanmai Poontozhuka Laan', english_meaning: 'The virtuous are truly called Anthanar; because in their conduct towards all creatures they are clothed in kindness', career_application: 'The virtuous are truly called Anthanar; because in their conduct towards all creatures they are clothed in kindness', chapter: 'The Greatness of Ascetics' },
  { id: 31, kural_number: 31, tamil_text: 'சிறப்புஈனும் செல்வமும் ஈனும் அறத்தினூஉங்கு ஆக்கம் எவனோ உயிர்க்கு.', transliteration: 'Sirappu Eenum Selvamum Eenum Araththinooungu Aakkam Evano Uyirkku', english_meaning: 'Virtue will confer heaven and wealth; what greater source of happiness can man possess ?', career_application: 'Virtue will confer heaven and wealth; what greater source of happiness can man possess ?', chapter: 'Assertion of the Strength of Virtue' },
  { id: 32, kural_number: 32, tamil_text: 'அறத்தினூஉங்கு ஆக்கமும் இல்லை அதனை மறத்தலின் ஊங்கில்லை கேடு.', transliteration: 'Araththinooungu Aakkamum Illai Adhanai Maraththalin Oongillai Ketu', english_meaning: 'There can be no greater source of good than (the practice of) virtue; there can be no greater source of evil than the forgetfulness of it', career_application: 'There can be no greater source of good than (the practice of) virtue; there can be no greater source of evil than the forgetfulness of it', chapter: 'Assertion of the Strength of Virtue' },
  { id: 33, kural_number: 33, tamil_text: 'ஒல்லும் வகையான் அறவினை ஓவாதே செல்லும்வாய் எல்லாஞ் செயல்.', transliteration: 'Ollum Vakaiyaan Aravinai Ovaadhe Sellumvaai Ellaanj Cheyal', english_meaning: 'As much as possible, in every way, incessantly practise virtue', career_application: 'As much as possible, in every way, incessantly practise virtue', chapter: 'Assertion of the Strength of Virtue' },
  { id: 34, kural_number: 34, tamil_text: 'மனத்துக்கண் மாசிலன் ஆதல் அனைத்தறன் ஆகுல நீர பிற.', transliteration: 'Manaththukkan Maasilan Aadhal Anaiththu Aran Aakula Neera Pira', english_meaning: 'Let him who does virtuous deeds be of spotless mind; to that extent is virtue; all else is vain show', career_application: 'Let him who does virtuous deeds be of spotless mind; to that extent is virtue; all else is vain show', chapter: 'Assertion of the Strength of Virtue' },
  { id: 35, kural_number: 35, tamil_text: 'அழுக்காறு அவாவெகுளி இன்னாச்சொல் நான்கும் இழுக்கா இயன்றது அறம்.', transliteration: 'Azhukkaaru Avaavekuli Innaachchol Naankum Izhukkaa Iyandradhu Aram', english_meaning: 'That conduct is virtue which is free from these four things, viz, malice, desire, anger and bitter speech', career_application: 'That conduct is virtue which is free from these four things, viz, malice, desire, anger and bitter speech', chapter: 'Assertion of the Strength of Virtue' },
  { id: 36, kural_number: 36, tamil_text: 'அன்றறிவாம் என்னாது அறஞ்செய்க மற்றது பொன்றுங்கால் பொன்றாத் துணை.', transliteration: 'Andrarivaam Ennaadhu Aranjeyka Matradhu Pondrungaal Pondraath Thunai', english_meaning: 'Defer not virtue to another day; receive her now; and at the dying hour she will be your undying friend', career_application: 'Defer not virtue to another day; receive her now; and at the dying hour she will be your undying friend', chapter: 'Assertion of the Strength of Virtue' },
  { id: 37, kural_number: 37, tamil_text: 'அறத்தாறு இதுவென வேண்டா சிவிகை பொறுத்தானோடு ஊர்ந்தான் இடை.', transliteration: 'Araththaaru Ithuvena Ventaa Sivikai Poruththaanotu Oorndhaan Itai', english_meaning: 'The fruit of virtue need not be described in books; it may be inferred from seeing the bearer of a palanquin and the rider therein', career_application: 'The fruit of virtue need not be described in books; it may be inferred from seeing the bearer of a palanquin and the rider therein', chapter: 'Assertion of the Strength of Virtue' },
  { id: 38, kural_number: 38, tamil_text: 'வீழ்நாள் படாஅமை நன்றாற்றின் அஃதொருவன் வாழ்நாள் வழியடைக்கும் கல்.', transliteration: 'Veezhnaal Pataaamai Nandraatrin Aqdhoruvan Vaazhnaal Vazhiyataikkum Kal', english_meaning: 'If one allows no day to pass without some good being done, his conduct will be a stone to block up the passage to other births', career_application: 'If one allows no day to pass without some good being done, his conduct will be a stone to block up the passage to other births', chapter: 'Assertion of the Strength of Virtue' },
  { id: 39, kural_number: 39, tamil_text: 'அறத்தான் வருவதே இன்பம் மற்றெல்லாம் புறத்த புகழும் இல.', transliteration: 'Araththaan Varuvadhe Inpam Mar Rellaam Puraththa Pukazhum Ila', english_meaning: 'Only that pleasure which flows from domestic virtue is pleasure; all else is not pleasure, and it is without praise', career_application: 'Only that pleasure which flows from domestic virtue is pleasure; all else is not pleasure, and it is without praise', chapter: 'Assertion of the Strength of Virtue' },
  { id: 40, kural_number: 40, tamil_text: 'செயற்பால தோரும் அறனே ஒருவற்கு உயற்பால தோரும் பழி.', transliteration: 'Seyarpaala Thorum Arane Oruvarku Uyarpaala Thorum Pazhi', english_meaning: 'That is virtue which each ought to do, and that is vice which each should shun', career_application: 'That is virtue which each ought to do, and that is vice which each should shun', chapter: 'Assertion of the Strength of Virtue' },
  { id: 41, kural_number: 41, tamil_text: 'இல்வாழ்வான் என்பான் இயல்புடைய மூவர்க்கும் நல்லாற்றின் நின்ற துணை.', transliteration: 'Ilvaazhvaan Enpaan Iyalputaiya Moovarkkum Nallaatrin Nindra Thunai', english_meaning: 'He will be called a (true) householder, who is a firm support to the virtuous of the three orders in', career_application: 'He will be called a (true) householder, who is a firm support to the virtuous of the three orders in', chapter: 'Domestic Life' },
  { id: 42, kural_number: 42, tamil_text: 'துறந்தார்க்கும் துவ்வாதவர்க்கும் இறந்தார்க்கும் இல்வாழ்வான் என்பான் துணை.', transliteration: 'Thurandhaarkkum Thuvvaa Dhavarkkum Irandhaarkkum Ilvaazhvaan Enpaan Thunai', english_meaning: 'He will be said to flourish in domestic virtue who aids the forsaken, the poor, and the dead', career_application: 'He will be said to flourish in domestic virtue who aids the forsaken, the poor, and the dead', chapter: 'Domestic Life' },
  { id: 43, kural_number: 43, tamil_text: 'தென்புலத்தார் தெய்வம் விருந்தொக்கல் தானென்றாங்கு ஐம்புலத்தாறு ஓம்பல் தலை.', transliteration: 'Thenpulaththaar Theyvam Virundhokkal Thaanendraangu Aimpulaththaaru Ompal Thalai', english_meaning: 'The chief (duty of the householder) is to preserve the five-fold rule (of conduct) towards the manes, the Gods, his guests, his relations and himself', career_application: 'The chief (duty of the householder) is to preserve the five-fold rule (of conduct) towards the manes, the Gods, his guests, his relations and himself', chapter: 'Domestic Life' },
  { id: 44, kural_number: 44, tamil_text: 'பழியஞ்சிப் பாத்தூண் உடைத்தாயின் வாழ்க்கை வழியெஞ்சல் எஞ்ஞான்றும் இல்.', transliteration: 'Pazhiyanjip Paaththoon Utaiththaayin Vaazhkkai Vazhiyenjal Egngnaandrum Il', english_meaning: 'His descendants shall never fail who, living in the domestic state, fears vice (in the acquisition of property) and shares his food (with others)', career_application: 'His descendants shall never fail who, living in the domestic state, fears vice (in the acquisition of property) and shares his food (with others)', chapter: 'Domestic Life' },
  { id: 45, kural_number: 45, tamil_text: 'அன்பும் அறனும் உடைத்தாயின் இல்வாழ்க்கை பண்பும் பயனும் அது.', transliteration: 'Anpum Aranum Utaiththaayin Ilvaazhkkai Panpum Payanum Adhu', english_meaning: 'If the married life possess love and virtue, these will be both its duty and reward', career_application: 'If the married life possess love and virtue, these will be both its duty and reward', chapter: 'Domestic Life' },
  { id: 46, kural_number: 46, tamil_text: 'அறத்தாற்றின் இல்வாழ்க்கை ஆற்றின் புறத்தாற்றில் போஒய்ப் பெறுவ தெவன்?', transliteration: 'Araththaatrin Ilvaazhkkai Aatrin Puraththaatril Pooip Peruva Thevan?', english_meaning: 'What will he who lives virtuously in the domestic state gain by going into the other, (ascetic) state ?', career_application: 'What will he who lives virtuously in the domestic state gain by going into the other, (ascetic) state ?', chapter: 'Domestic Life' },
  { id: 47, kural_number: 47, tamil_text: 'இயல்பினான் இல்வாழ்க்கை வாழ்பவன் என்பான் முயல்வாருள் எல்லாம் தலை.', transliteration: 'Iyalpinaan Ilvaazhkkai Vaazhpavan Enpaan Muyalvaarul Ellaam Thalai', english_meaning: 'Among all those who labour (for future happiness) he is greatest who lives well in the household state', career_application: 'Among all those who labour (for future happiness) he is greatest who lives well in the household state', chapter: 'Domestic Life' },
  { id: 48, kural_number: 48, tamil_text: 'ஆற்றின் ஒழுக்கி அறனிழுக்கா இல்வாழ்க்கை நோற்பாரின் நோன்மை உடைத்து.', transliteration: 'Aatrin Ozhukki Aranizhukkaa Ilvaazhkkai Norpaarin Nonmai Utaiththu', english_meaning: 'The householder who, not swerving from virtue, helps the ascetic in his way, endures more than those who endure penance', career_application: 'The householder who, not swerving from virtue, helps the ascetic in his way, endures more than those who endure penance', chapter: 'Domestic Life' },
  { id: 49, kural_number: 49, tamil_text: 'அறனெனப் பட்டதே இல்வாழ்க்கை அஃதும் பிறன்பழிப்ப தில்லாயின் நன்று.', transliteration: 'Aran Enap Pattadhe Ilvaazhkkai Aqdhum Piranpazhippa Thillaayin Nandru', english_meaning: 'The marriage state is truly called virtue The other state is also good, if others do not reproach it', career_application: 'The marriage state is truly called virtue The other state is also good, if others do not reproach it', chapter: 'Domestic Life' },
  { id: 50, kural_number: 50, tamil_text: 'வையத்துள் வாழ்வாங்கு வாழ்பவன் வான்உறையும் தெய்வத்துள் வைக்கப் படும்.', transliteration: 'Vaiyaththul Vaazhvaangu Vaazhpavan Vaanu�ryum Theyvaththul Vaikkap Patum', english_meaning: 'He who on earth has lived in the conjugal state as he should live, will be placed among the Gods who dwell in heaven', career_application: 'He who on earth has lived in the conjugal state as he should live, will be placed among the Gods who dwell in heaven', chapter: 'Domestic Life' },
  { id: 51, kural_number: 51, tamil_text: 'மனைக்தக்க மாண்புடையள் ஆகித்தற் கொண்டான் வளத்தக்காள் வாழ்க்கைத் துணை.', transliteration: 'Manaikdhakka Maanputaiyal Aakiththar Kontaan Valaththakkaal Vaazhkkaith Thunai', english_meaning: 'She who has the excellence of home virtues, and can expend within the means of her husband, is a help in the domestic state', career_application: 'She who has the excellence of home virtues, and can expend within the means of her husband, is a help in the domestic state', chapter: 'The Worth of a Wife' },
  { id: 52, kural_number: 52, tamil_text: 'மனைமாட்சி இல்லாள்கண் இல்லாயின் வாழ்க்கை எனைமாட்சித் தாயினும் இல்.', transliteration: 'Manaimaatchi Illaalkan Illaayin Vaazhkkai Enaimaatchith Thaayinum Il', english_meaning: 'If the wife be devoid of domestic excellence, whatever (other) greatness be possessed, the conjugal state, is nothing', career_application: 'If the wife be devoid of domestic excellence, whatever (other) greatness be possessed, the conjugal state, is nothing', chapter: 'The Worth of a Wife' },
  { id: 53, kural_number: 53, tamil_text: 'இல்லதென் இல்லவள் மாண்பானால் உள்ளதென் இல்லவள் மாணாக் கடை?', transliteration: 'Illadhen Illaval Maanpaanaal Ulladhen Illaval Maanaak Katai?', english_meaning: 'If his wife be eminent (in virtue), what does (that man) not possess ? If she be without excellence, what does (he) possess ?', career_application: 'If his wife be eminent (in virtue), what does (that man) not possess ? If she be without excellence, what does (he) possess ?', chapter: 'The Worth of a Wife' },
  { id: 54, kural_number: 54, tamil_text: 'பெண்ணின் பெருந்தக்க யாவுள கற்பென்னும் திண்மைஉண் டாகப் பெறின்.', transliteration: 'Pennin Perundhakka Yaavula Karpennum Thinmaiun Taakap Perin', english_meaning: 'What is more excellent than a wife, if she possess the stability of chastity ?', career_application: 'What is more excellent than a wife, if she possess the stability of chastity ?', chapter: 'The Worth of a Wife' },
  { id: 55, kural_number: 55, tamil_text: 'தெய்வம் தொழாஅள் கொழுநன் தொழுதெழுவாள் பெய்யெனப் பெய்யும் மழை.', transliteration: 'Theyvam Thozhaaal Kozhunan Thozhudhezhuvaal Peyyenap Peyyum Mazhai', english_meaning: 'If she, who does not worship God, but who rising worships her husband, say, "let it rain," it will rain', career_application: 'If she, who does not worship God, but who rising worships her husband, say, "let it rain," it will rain', chapter: 'The Worth of a Wife' },
  { id: 56, kural_number: 56, tamil_text: 'தற்காத்துத் தற்கொண்டாற் பேணித் தகைசான்ற சொற்காத்துச் சோர்விலாள் பெண்.', transliteration: 'Tharkaaththuth Tharkontaar Penith Thakaisaandra Sorkaaththuch Chorvilaal Pen', english_meaning: 'She is a wife who unweariedly guards herself, takes care of her husband, and preserves an unsullied fame', career_application: 'She is a wife who unweariedly guards herself, takes care of her husband, and preserves an unsullied fame', chapter: 'The Worth of a Wife' },
  { id: 57, kural_number: 57, tamil_text: 'சிறைகாக்கும் காப்பெவன் செய்யும் மகளிர் நிறைகாக்கும் காப்பே தலை.', transliteration: 'Siraikaakkum Kaappevan Seyyum Makalir Niraikaakkum Kaappe Thalai', english_meaning: 'What avails the guard of a prison ? The chief guard of a woman is her chastity', career_application: 'What avails the guard of a prison ? The chief guard of a woman is her chastity', chapter: 'The Worth of a Wife' },
  { id: 58, kural_number: 58, tamil_text: 'பெற்றாற் பெறின்பெறுவர் பெண்டிர் பெருஞ்சிறப்புப் புத்தேளிர் வாழும் உலகு.', transliteration: 'Petraar Perinperuvar Pentir Perunjirappup Puththelir Vaazhum Ulaku', english_meaning: 'If women shew reverence to their husbands, they will obtain great excellence in the world where the gods flourish', career_application: 'If women shew reverence to their husbands, they will obtain great excellence in the world where the gods flourish', chapter: 'The Worth of a Wife' },
  { id: 59, kural_number: 59, tamil_text: 'புகழ்புரிந்த இல்லிலோர்க்கு இல்லை இகழ்வார்முன் ஏறுபோல் பீடு நடை.', transliteration: 'Pukazhpurindha Illilorkku Illai Ikazhvaarmun Erupol Peetu Natai', english_meaning: 'The man whose wife seeks not the praise (of chastity) cannot walk with lion-like stately step, before those who revile them', career_application: 'The man whose wife seeks not the praise (of chastity) cannot walk with lion-like stately step, before those who revile them', chapter: 'The Worth of a Wife' },
  { id: 60, kural_number: 60, tamil_text: 'மங்கலம் என்ப மனைமாட்சி மற்று அதன் நன்கலம் நன்மக்கட் பேறு.', transliteration: 'Mangalam Enpa Manaimaatchi Matru Adhan Nankalam Nanmakkat Peru', english_meaning: 'The excellence of a wife is the good of her husband; and good children are the jewels of that goodness', career_application: 'The excellence of a wife is the good of her husband; and good children are the jewels of that goodness', chapter: 'The Worth of a Wife' },
  { id: 61, kural_number: 61, tamil_text: 'பெறுமவற்றுள் யாமறிவது இல்லை அறிவறிந்த மக்கட்பேறு அல்ல பிற.', transliteration: 'Perumavatrul Yaamarivadhu Illai Arivarindha Makkatperu Alla Pira', english_meaning: 'Among all the benefits that may be acquired, we know no greater benefit than the acquisition of intelligent children', career_application: 'Among all the benefits that may be acquired, we know no greater benefit than the acquisition of intelligent children', chapter: 'The Wealth of Children' },
  { id: 62, kural_number: 62, tamil_text: 'எழுபிறப்பும் தீயவை தீண்டா பழிபிறங்காப் பண்புடை மக்கட் பெறின்.', transliteration: 'Ezhupirappum Theeyavai Theentaa Pazhipirangaap Panputai Makkat Perin', english_meaning: 'The evils of the seven births shall not touch those who abtain children of a good disposition, free from vice', career_application: 'The evils of the seven births shall not touch those who abtain children of a good disposition, free from vice', chapter: 'The Wealth of Children' },
  { id: 63, kural_number: 63, tamil_text: 'தம்பொருள் என்பதம் மக்கள் அவர்பொருள் தம்தம் வினையான் வரும்.', transliteration: 'Thamporul Enpadham Makkal Avarporul Thamdham Vinaiyaan Varum', english_meaning: 'Men will call their sons their wealth, because it flows to them through the deeds which they (sons) perform on their behalf', career_application: 'Men will call their sons their wealth, because it flows to them through the deeds which they (sons) perform on their behalf', chapter: 'The Wealth of Children' },
  { id: 64, kural_number: 64, tamil_text: 'அமிழ்தினும் ஆற்ற இனிதேதம் மக்கள் சிறுகை அளாவிய கூழ்.', transliteration: 'Amizhdhinum Aatra Inidhedham Makkal Sirukai Alaaviya Koozh', english_meaning: 'The rice in which the little hand of their children has dabbled will be far sweeter (to the parent) than ambrosia', career_application: 'The rice in which the little hand of their children has dabbled will be far sweeter (to the parent) than ambrosia', chapter: 'The Wealth of Children' },
  { id: 65, kural_number: 65, tamil_text: 'மக்கள்மெய் தீண்டல் உடற்கின்பம் மற்றுஅவர் சொற்கேட்டல் இன்பம் செவிக்கு.', transliteration: 'Makkalmey Theental Utarkinpam Matru Avar Sorkettal Inpam Sevikku', english_meaning: 'The touch of children gives pleasure to the body, and the hearing of their words, pleasure to the ear', career_application: 'The touch of children gives pleasure to the body, and the hearing of their words, pleasure to the ear', chapter: 'The Wealth of Children' },
  { id: 66, kural_number: 66, tamil_text: 'குழல்இனிது யாழ்இனிது என்பதம் மக்கள் மழலைச்சொல் கேளா தவர்.', transliteration: 'Kuzhal Inidhu Yaazhinidhu Enpadham Makkal Mazhalaichchol Kelaa Thavar', english_meaning: '"The pipe is sweet, the lute is sweet," say those who have not heard the prattle of their own children', career_application: '"The pipe is sweet, the lute is sweet," say those who have not heard the prattle of their own children', chapter: 'The Wealth of Children' },
  { id: 67, kural_number: 67, tamil_text: 'தந்தை மகற்காற்றும் நன்றி அவையத்து முந்தி இருப்பச் செயல்.', transliteration: 'Thandhai Makarkaatrum Nandri Avaiyaththu Mundhi Iruppach Cheyal', english_meaning: 'The benefit which a father should confer on his son is to give him precedence in the assembly of the learned', career_application: 'The benefit which a father should confer on his son is to give him precedence in the assembly of the learned', chapter: 'The Wealth of Children' },
  { id: 68, kural_number: 68, tamil_text: 'தம்மின்தம் மக்கள் அறிவுடைமை மாநிலத்து மன்னுயிர்க் கெல்லாம் இனிது.', transliteration: 'Thammindham Makkal Arivutaimai Maanilaththu Mannuyirk Kellaam Inidhu', english_meaning: 'That their children should possess knowledge is more pleasing to all men of this great earth than to themselves', career_application: 'That their children should possess knowledge is more pleasing to all men of this great earth than to themselves', chapter: 'The Wealth of Children' },
  { id: 69, kural_number: 69, tamil_text: 'ஈன்ற பொழுதின் பெரிதுவக்கும் தன்மகனைச் சான்றோன் எனக்கேட்ட தாய்.', transliteration: 'Eendra Pozhudhin Peridhuvakkum Thanmakanaich Chaandron Enakketta Thaai', english_meaning: 'The mother who hears her son called "a wise man" will rejoice more than she did at his birth', career_application: 'The mother who hears her son called "a wise man" will rejoice more than she did at his birth', chapter: 'The Wealth of Children' },
  { id: 70, kural_number: 70, tamil_text: 'மகன்தந்தைக்கு ஆற்றும் உதவி இவன்தந்தை என்நோற்றான் கொல் எனும் சொல்.', transliteration: 'Makandhandhaikku Aatrum Udhavi Ivandhandhai Ennotraan Kol Enum Sol', english_meaning: '(So to act) that it may be said "by what great penance did his father beget him," is the benefit which a son should render to his father', career_application: '(So to act) that it may be said "by what great penance did his father beget him," is the benefit which a son should render to his father', chapter: 'The Wealth of Children' },
  { id: 71, kural_number: 71, tamil_text: 'அன்பிற்கும் உண்டோ அடைக்குந்தாழ் ஆர்வலர் புன்கணீர் பூசல் தரும்.', transliteration: 'Anpirkum Unto Ataikkundhaazh Aarvalar Punkaneer Poosal Tharum', english_meaning: 'Is there any fastening that can shut in love ? Tears of the affectionate will publish the love that is within', career_application: 'Is there any fastening that can shut in love ? Tears of the affectionate will publish the love that is within', chapter: 'The Possession of Love' },
  { id: 72, kural_number: 72, tamil_text: 'அன்பிலார் எல்லாம் தமக்குரியர் அன்புடையார் என்பும் உரியர் பிறர்க்கு.', transliteration: 'Anpilaar Ellaam Thamakkuriyar Anputaiyaar Enpum Uriyar Pirarkku', english_meaning: 'Those who are destitute of love appropriate all they have to themselves; but those who possess love consider even their bones to belong to others', career_application: 'Those who are destitute of love appropriate all they have to themselves; but those who possess love consider even their bones to belong to others', chapter: 'The Possession of Love' },
  { id: 73, kural_number: 73, tamil_text: 'அன்போடு இயைந்த வழக்கென்ப ஆருயிர்க்கு என்போடு இயைந்த தொடர்பு.', transliteration: 'Anpotu Iyaindha Vazhakkenpa Aaruyirkku Enpotu Iyaindha Thotarpu', english_meaning: 'They say that the union of soul and body in man is the fruit of the union of love and virtue (in a former birth)', career_application: 'They say that the union of soul and body in man is the fruit of the union of love and virtue (in a former birth)', chapter: 'The Possession of Love' },
  { id: 74, kural_number: 74, tamil_text: 'அன்புஈனும் ஆர்வம் உடைமை அதுஈனும் நண்பு என்னும் நாடாச் சிறப்பு.', transliteration: 'Anpu Eenum Aarvam Utaimai Adhueenum Nanpu Ennum Naataach', english_meaning: 'Love begets desire: and that (desire) begets the immeasureable excellence of friendship', career_application: 'Love begets desire: and that (desire) begets the immeasureable excellence of friendship', chapter: 'The Possession of Love' },
  { id: 75, kural_number: 75, tamil_text: 'அன்புற்று அமர்ந்த வழக்கென்ப வையகத்து இன்புற்றார் எய்தும் சிறப்பு.', transliteration: 'Anputru Amarndha Vazhakkenpa Vaiyakaththu Inputraar Eydhum Sirappu', english_meaning: 'These are the fruits of tranquil life of love', career_application: 'These are the fruits of tranquil life of love', chapter: 'The Possession of Love' },
  { id: 76, kural_number: 76, tamil_text: 'அறத்திற்கே அன்புசார் பென்ப அறியார் மறத்திற்கும் அஃதே துணை.', transliteration: 'Araththirke Anpusaar Penpa Ariyaar Maraththirkum Aqdhe Thunai', english_meaning: 'The ignorant say that love is an ally to virtue only, but it is also a help to get out of vice', career_application: 'The ignorant say that love is an ally to virtue only, but it is also a help to get out of vice', chapter: 'The Possession of Love' },
  { id: 77, kural_number: 77, tamil_text: 'என்பி லதனை வெயில்போலக் காயுமே அன்பி லதனை அறம்.', transliteration: 'Enpi Ladhanai Veyilpolak Kaayume Anpi Ladhanai Aram', english_meaning: 'Virtue will burn up the soul which is without love, even as the sun burns up the creature which is without bone, ie worms', career_application: 'Virtue will burn up the soul which is without love, even as the sun burns up the creature which is without bone, ie worms', chapter: 'The Possession of Love' },
  { id: 78, kural_number: 78, tamil_text: 'அன்பகத் தில்லா உயிர்வாழ்க்கை வன்பாற்கண் வற்றல் மரந்தளிர்த் தற்று.', transliteration: 'Anpakath Thillaa Uyirvaazhkkai Vanpaarkan Vatral Marandhalirth Thatru', english_meaning: 'The domestic state of that man whose mind is without love is like the flourishing of a withered tree upon the parched desert', career_application: 'The domestic state of that man whose mind is without love is like the flourishing of a withered tree upon the parched desert', chapter: 'The Possession of Love' },
  { id: 79, kural_number: 79, tamil_text: 'புறத்துறுப் பெல்லாம் எவன்செய்யும் யாக்கை அகத்துறுப்பு அன்பி லவர்க்கு.', transliteration: 'Puraththurup Pellaam Evanseyyum Yaakkai Akaththuruppu Anpi Lavarkku', english_meaning: 'Of what avail are all the external members (of the body) to those who are destitute of love, the internal member', career_application: 'Of what avail are all the external members (of the body) to those who are destitute of love, the internal member', chapter: 'The Possession of Love' },
  { id: 80, kural_number: 80, tamil_text: 'அன்பின் வழியது உயிர்நிலை அஃதிலார்க்கு என்புதோல் போர்த்த உடம்பு.', transliteration: 'Anpin Vazhiyadhu Uyirnilai Aqdhilaarkku Enpudhol Porththa Utampu', english_meaning: 'That body alone which is inspired with love contains a living soul: if void of it, (the body) is bone overlaid with skin', career_application: 'That body alone which is inspired with love contains a living soul: if void of it, (the body) is bone overlaid with skin', chapter: 'The Possession of Love' },
  { id: 81, kural_number: 81, tamil_text: 'இருந்தோம்பி இல்வாழ்வ தெல்லாம் விருந்தோம்பி வேளாண்மை செய்தற் பொருட்டு.', transliteration: 'Irundhompi Ilvaazhva Thellaam Virundhompi Velaanmai Seydhar Poruttu', english_meaning: 'The whole design of living in the domestic state and laying up (property) is (to be able) to exercise the benevolence of hospitality', career_application: 'The whole design of living in the domestic state and laying up (property) is (to be able) to exercise the benevolence of hospitality', chapter: 'Hospitality' },
  { id: 82, kural_number: 82, tamil_text: 'விருந்து புறத்ததாத் தானுண்டல் சாவா மருந்தெனினும் வேண் டற்பாற் றன்று.', transliteration: 'Virundhu Puraththadhaath Thaanuntal Saavaa Marundheninum Ventarpaar Randru', english_meaning: 'It is not fit that one should wish his guests to be outside (his house) even though he were eating the food of immortality', career_application: 'It is not fit that one should wish his guests to be outside (his house) even though he were eating the food of immortality', chapter: 'Hospitality' },
  { id: 83, kural_number: 83, tamil_text: 'வருவிருந்து வைகலும் ஓம்புவான் வாழ்க்கை பருவந்து பாழ்படுதல் இன்று.', transliteration: 'Varuvirundhu Vaikalum Ompuvaan Vaazhkkai Paruvandhu Paazhpatudhal Indru', english_meaning: 'The domestic life of the man that daily entertains the guests who come to him shall not be laid waste by poverty', career_application: 'The domestic life of the man that daily entertains the guests who come to him shall not be laid waste by poverty', chapter: 'Hospitality' },
  { id: 84, kural_number: 84, tamil_text: 'அகனமர்ந்து செய்யாள் உறையும் முகனமர்ந்து நல்விருந்து ஓம்புவான் இல்.', transliteration: 'Akanamarndhu Seyyaal Uraiyum Mukanamarndhu Nalvirundhu Ompuvaan Il', english_meaning: 'Lakshmi with joyous mind shall dwell in the house of that man who, with cheerful countenance, entertains the good as guests', career_application: 'Lakshmi with joyous mind shall dwell in the house of that man who, with cheerful countenance, entertains the good as guests', chapter: 'Hospitality' },
  { id: 85, kural_number: 85, tamil_text: 'வித்தும் இடல்வேண்டும் கொல்லோ விருந்தோம்பி மிச்சில் மிசைவான் புலம்.', transliteration: 'Viththum Italventum Kollo Virundhompi Michchil Misaivaan Pulam', english_meaning: 'Is it necessary to sow the field of the man who, having feasted his guests, eats what may remain ?', career_application: 'Is it necessary to sow the field of the man who, having feasted his guests, eats what may remain ?', chapter: 'Hospitality' },
  { id: 86, kural_number: 86, tamil_text: 'செல்விருந்து ஓம்பி வருவிருந்து பார்த்திருப்பான் நல்வருந்து வானத் தவர்க்கு.', transliteration: 'Selvirundhu Ompi Varuvirundhu Paarththiruppaan Nalvarundhu Vaanath Thavarkku', english_meaning: 'He who, having entertained the guests that have come, looks out for others who may yet come, will be a welcome guest to the inhabitants of heaven', career_application: 'He who, having entertained the guests that have come, looks out for others who may yet come, will be a welcome guest to the inhabitants of heaven', chapter: 'Hospitality' },
  { id: 87, kural_number: 87, tamil_text: 'இனைத்துணைத் தென்பதொன் றில்லை விருந்தின் துணைத்துணை வேள்விப் பயன்.', transliteration: 'Inaiththunaith Thenpadhon Rillai Virundhin Thunaiththunai Velvip Payan', english_meaning: 'The advantages of benevolence cannot be measured; the measure (of the virtue) of the guests (entertained) is the only measure', career_application: 'The advantages of benevolence cannot be measured; the measure (of the virtue) of the guests (entertained) is the only measure', chapter: 'Hospitality' },
  { id: 88, kural_number: 88, tamil_text: 'பரிந்தோம்பிப் பற்றற்றேம் என்பர் விருந்தோம்பி வேள்வி தலைப்படா தார்.', transliteration: 'Parindhompip Patratrem Enpar Virundhompi Velvi Thalaippataa Thaar', english_meaning: 'Those who have taken no part in the benevolence of hospitality shall (at length lament) saying, "we have laboured and laid up wealth and are now without support."', career_application: 'Those who have taken no part in the benevolence of hospitality shall (at length lament) saying, "we have laboured and laid up wealth and are now without support."', chapter: 'Hospitality' },
  { id: 89, kural_number: 89, tamil_text: 'உடைமையுள் இன்மை விருந்தோம்பல் ஓம்பா மடமை மடவார்கண் உண்டு.', transliteration: 'Utaimaiyul Inmai Virundhompal Ompaa Matamai Matavaarkan Untu', english_meaning: 'That stupidity which excercises no hospitality is poverty in the midst of wealth It is the property of the stupid', career_application: 'That stupidity which excercises no hospitality is poverty in the midst of wealth It is the property of the stupid', chapter: 'Hospitality' },
  { id: 90, kural_number: 90, tamil_text: 'மோப்பக் குழையும் அனிச்சம் முகந்திரிந்து நோக்கக் குநழ்யும் விருந்து.', transliteration: 'Moppak Kuzhaiyum Anichcham Mukandhirindhu Nokkak Kuzhaiyum Virundhu', english_meaning: 'As the Anicham flower fades in smelling, so fades the guest when the face is turned away', career_application: 'As the Anicham flower fades in smelling, so fades the guest when the face is turned away', chapter: 'Hospitality' },
  { id: 91, kural_number: 91, tamil_text: 'இன்சொலால் ஈரம் அளைஇப் படிறுஇலவாம் செம்பொருள் கண்டார்வாய்ச் சொல்.', transliteration: 'Insolaal Eeram Alaiip Patiruilavaam Semporul Kantaarvaaich Chol', english_meaning: 'Sweet words are those which imbued with love and free from deceit flow from the mouth of the virtuous', career_application: 'Sweet words are those which imbued with love and free from deceit flow from the mouth of the virtuous', chapter: 'The Utterance of Pleasant Words' },
  { id: 92, kural_number: 92, tamil_text: 'அகன்அமர்ந்து ஈதலின் நன்றே முகனமர்ந்து இன்சொலன் ஆகப் பெறின்.', transliteration: 'Akanamarndhu Eedhalin Nandre Mukanamarndhu Insolan Aakap Perin', english_meaning: 'Sweet speech, with a cheerful countenance is better than a gift made with a joyous mind', career_application: 'Sweet speech, with a cheerful countenance is better than a gift made with a joyous mind', chapter: 'The Utterance of Pleasant Words' },
  { id: 93, kural_number: 93, tamil_text: 'முகத்தான் அமர்ந்து இனிதுநோக்கி அகத்தானாம் இன்சொ லினதே அறம்.', transliteration: 'Mukaththaan Amarndhuinidhu Nokki Akaththaanaam Inso Linadhe Aram', english_meaning: 'Sweet speech, flowing from the heart (uttered) with a cheerful countenance and a sweet look, is true virtue', career_application: 'Sweet speech, flowing from the heart (uttered) with a cheerful countenance and a sweet look, is true virtue', chapter: 'The Utterance of Pleasant Words' },
  { id: 94, kural_number: 94, tamil_text: 'துன்புறூஉம் துவ்வாமை இல்லாகும் யார்மாட்டும் இன்புறூஉம் இன்சொ லவர்க்கு.', transliteration: 'Thunpurooum Thuvvaamai Illaakum Yaarmaattum Inpurooum Inso Lavarkku', english_meaning: 'Sorrow-increasing poverty shall not come upon those who use towards all, pleasure-increasing sweetness of speech', career_application: 'Sorrow-increasing poverty shall not come upon those who use towards all, pleasure-increasing sweetness of speech', chapter: 'The Utterance of Pleasant Words' },
  { id: 95, kural_number: 95, tamil_text: 'பணிவுடையன் இன்சொலன் ஆதல் ஒருவற்கு அணியல்ல மற்றுப் பிற.', transliteration: 'Panivutaiyan Insolan Aadhal Oruvarku Aniyalla Matrup Pira', english_meaning: 'Humility and sweetness of speech are the ornaments of man; all others are not (ornaments)', career_application: 'Humility and sweetness of speech are the ornaments of man; all others are not (ornaments)', chapter: 'The Utterance of Pleasant Words' },
  { id: 96, kural_number: 96, tamil_text: 'அல்லவை தேய அறம்பெருகும் நல்லவை நாடி இனிய சொலின்', transliteration: 'Allavai Theya Aramperukum Nallavai Naati Iniya Solin', english_meaning: 'If a man, while seeking to speak usefully, speaks also sweetly, his sins will diminish and his virtue increase', career_application: 'If a man, while seeking to speak usefully, speaks also sweetly, his sins will diminish and his virtue increase', chapter: 'The Utterance of Pleasant Words' },
  { id: 97, kural_number: 97, tamil_text: 'நயன்ஈன்று நன்றி பயக்கும் பயன்ஈன்று பண்பின் தலைப்பிரியாச் சொல்.', transliteration: 'Nayan Eendru Nandri Payakkum Payaneendru Panpin Thalaippiriyaach Chol', english_meaning: 'That speech which, while imparting benefits ceases not to please, will yield righteousness (for this world) and merit (for the next world)', career_application: 'That speech which, while imparting benefits ceases not to please, will yield righteousness (for this world) and merit (for the next world)', chapter: 'The Utterance of Pleasant Words' },
  { id: 98, kural_number: 98, tamil_text: 'சிறுமையுவு நீங்கிய இன்சொல் மறுமையும் இம்மையும் இன்பம் தரும்.', transliteration: 'Sirumaiyul Neengiya Insol Marumaiyum Immaiyum Inpam Tharum', english_meaning: 'Sweet speech, free from harm to others, will give pleasure both in this world and in the next', career_application: 'Sweet speech, free from harm to others, will give pleasure both in this world and in the next', chapter: 'The Utterance of Pleasant Words' },
  { id: 99, kural_number: 99, tamil_text: 'இன்சொல் இனிதீன்றல் காண்பான் எவன்கொலோ வன்சொல் வழங்கு வது?', transliteration: 'Insol Inidheendral Kaanpaan Evankolo Vansol Vazhangu Vadhu?', english_meaning: 'Why does he use harsh words, who sees the pleasure which sweet speech yields ?', career_application: 'Why does he use harsh words, who sees the pleasure which sweet speech yields ?', chapter: 'The Utterance of Pleasant Words' },
  { id: 100, kural_number: 100, tamil_text: 'இனிய உளவாக இன்னாத கூறல் கனிஇருப்பக் காய்கவர்ந் தற்று.', transliteration: 'Iniya Ulavaaka Innaadha Kooral Kaniiruppak Kaaikavarn Thatru', english_meaning: 'To say disagreeable things when agreeable are at hand is like eating unripe fruit when there is ripe', career_application: 'To say disagreeable things when agreeable are at hand is like eating unripe fruit when there is ripe', chapter: 'The Utterance of Pleasant Words' },
  { id: 101, kural_number: 101, tamil_text: 'செய்யாமல் செய்த உதவிக்கு வையகமும் வானகமும் ஆற்றல் அரிது.', transliteration: 'Seyyaamal Seydha Udhavikku Vaiyakamum Vaanakamum Aatral Aridhu', english_meaning: '(The gift of) heaven and earth is not an equivalent for a benefit which is conferred where none had been received', career_application: '(The gift of) heaven and earth is not an equivalent for a benefit which is conferred where none had been received', chapter: 'Gratitude' },
  { id: 102, kural_number: 102, tamil_text: 'காலத்தி னாற்செய்த நன்றி சிறிதெனினும் ஞாலத்தின் மாணப் பெரிது.', transliteration: 'Kaalaththi Naarseydha Nandri Siridheninum Gnaalaththin Maanap Peridhu', english_meaning: 'A favour conferred in the time of need, though it be small (in itself), is (in value) much larger than the world', career_application: 'A favour conferred in the time of need, though it be small (in itself), is (in value) much larger than the world', chapter: 'Gratitude' },
  { id: 103, kural_number: 103, tamil_text: 'பயன்தூக்கார் செய்த உதவி நயன்தூக்கின் நன்மை கடலின் பெரிது.', transliteration: 'Payandhookkaar Seydha Udhavi Nayandhookkin Nanmai Katalin Peridhu', english_meaning: 'If we weigh the excellence of a benefit which is conferred without weighing the return, it is larger than the sea', career_application: 'If we weigh the excellence of a benefit which is conferred without weighing the return, it is larger than the sea', chapter: 'Gratitude' },
  { id: 104, kural_number: 104, tamil_text: 'தினைத்துணை நன்றி செயினும் பனைத்துணையாக் கொள்வர் பயன்தெரி வார்.', transliteration: 'Thinaiththunai Nandri Seyinum Panaiththunaiyaak Kolvar Payandheri Vaar', english_meaning: 'Though the benefit conferred be as small as a millet seed, those who know its advantage will consider it as large as a palmyra fruit', career_application: 'Though the benefit conferred be as small as a millet seed, those who know its advantage will consider it as large as a palmyra fruit', chapter: 'Gratitude' },
  { id: 105, kural_number: 105, tamil_text: 'உதவி வரைத்தன்று உதவி உதவி செயப்பட்டார் சால்பின் வரைத்து.', transliteration: 'Udhavi Varaiththandru Udhavi Udhavi Seyappattaar Saalpin Varaiththu', english_meaning: 'The benefit itself is not the measure of the benefit; the worth of those who have received it is its measure', career_application: 'The benefit itself is not the measure of the benefit; the worth of those who have received it is its measure', chapter: 'Gratitude' },
  { id: 106, kural_number: 106, tamil_text: 'மறவற்க மாசற்றார் கேண்மை துறவற்க துன்பத்துள் துப்பாயார் நட்பு.', transliteration: 'Maravarka Maasatraar Kenmai Thuravarka Thunpaththul Thuppaayaar Natpu', english_meaning: 'Forsake not the friendship of those who have been your staff in adversity Forget not be benevolence of the blameless', career_application: 'Forsake not the friendship of those who have been your staff in adversity Forget not be benevolence of the blameless', chapter: 'Gratitude' },
  { id: 107, kural_number: 107, tamil_text: 'எழுமை எழுபிறப்பும் உள்ளுவர் தங்கண் விழுமந் துடைத்தவர் நட்பு.', transliteration: 'Ezhumai Ezhupirappum Ulluvar Thangan Vizhuman Thutaiththavar Natpu', english_meaning: '(The wise) will remember throughout their seven-fold births the love of those who have wiped away their affliction', career_application: '(The wise) will remember throughout their seven-fold births the love of those who have wiped away their affliction', chapter: 'Gratitude' },
  { id: 108, kural_number: 108, tamil_text: 'நன்றி மறப்பது நன்றன்று நன்றல்லது அன்றே மறப்பது நன்று.', transliteration: 'Nandri Marappadhu Nandrandru Nandralladhu Andre Marappadhu Nandru', english_meaning: 'It is not good to forget a benefit; it is good to forget an injury even in the very moment (in which it is inflicted)', career_application: 'It is not good to forget a benefit; it is good to forget an injury even in the very moment (in which it is inflicted)', chapter: 'Gratitude' },
  { id: 109, kural_number: 109, tamil_text: 'கொன்றன்ன இன்னா செயினும் அவர்செய்த ஒன்றுநன்று உள்ளக் கெடும்.', transliteration: 'Kondranna Innaa Seyinum Avarseydha Ondrunandru Ullak Ketum', english_meaning: 'Though one inflict an injury great as murder, it will perish before the thought of one benefit (formerly) conferred', career_application: 'Though one inflict an injury great as murder, it will perish before the thought of one benefit (formerly) conferred', chapter: 'Gratitude' },
  { id: 110, kural_number: 110, tamil_text: 'எந்நன்றி கொன்றார்க்கும் உய்வுண்டாம் உய்வில்லை செய்ந்நன்றி கொன்ற மகற்கு.', transliteration: 'Ennandri Kondraarkkum Uyvuntaam Uyvillai Seynnandri Kondra Makarku', english_meaning: 'He who has killed every virtue may yet escape; there is no escape for him who has killed a benefit', career_application: 'He who has killed every virtue may yet escape; there is no escape for him who has killed a benefit', chapter: 'Gratitude' },
  { id: 111, kural_number: 111, tamil_text: 'தகுதி எனவொன்று நன்றே பகுதியால் பாற்பட்டு ஒழுகப் பெறின்.', transliteration: 'Thakudhi Enavondru Nandre Pakudhiyaal Paarpattu Ozhukap Perin', english_meaning: 'That equity which consists in acting with equal regard to each of (the three) divisions of men [enemies, strangers and friends] is a pre-eminent virtue', career_application: 'That equity which consists in acting with equal regard to each of (the three) divisions of men [enemies, strangers and friends] is a pre-eminent virtue', chapter: 'Impartiality' },
  { id: 112, kural_number: 112, tamil_text: 'செப்பம் உடையவன் ஆக்கஞ் சிதைவின்றி எச்சத்திற் கேமாப்பு உடைத்து.', transliteration: 'Seppam Utaiyavan Aakkanj Chidhaivindri Echchaththir Kemaappu Utaiththu', english_meaning: 'The wealth of the man of rectitude will not perish, but will bring happiness also to his posterity', career_application: 'The wealth of the man of rectitude will not perish, but will bring happiness also to his posterity', chapter: 'Impartiality' },
  { id: 113, kural_number: 113, tamil_text: 'நன்றே தரினும் நடுவிகந்தாம் ஆக்கத்தை அன்றே யொழிய விடல்.', transliteration: 'Nandre Tharinum Natuvikandhaam Aakkaththai Andre Yozhiya Vital', english_meaning: 'Forsake in the very moment (of acquisition) that gain which, though it should bring advantage, is without equity', career_application: 'Forsake in the very moment (of acquisition) that gain which, though it should bring advantage, is without equity', chapter: 'Impartiality' },
  { id: 114, kural_number: 114, tamil_text: 'தக்கார் தகவிலர் என்பது அவரவர் எச்சத்தாற் காணப்ப படும்.', transliteration: 'Thakkaar Thakavilar Enpadhu Avaravar Echchaththaar Kaanap Patum', english_meaning: 'The worthy and unworthy may be known by the existence or otherwise of good offsprings', career_application: 'The worthy and unworthy may be known by the existence or otherwise of good offsprings', chapter: 'Impartiality' },
  { id: 115, kural_number: 115, tamil_text: 'கேடும் பெருக்கமும் இல்லல்ல நெஞ்சத்துக் கோடாமை சான்றோர்க் கணி.', transliteration: 'Ketum Perukkamum Illalla Nenjaththuk Kotaamai Saandrork Kani', english_meaning: 'Loss and gain come not without cause; it is the ornament of the wise to preserve evenness of mind (under both)', career_application: 'Loss and gain come not without cause; it is the ornament of the wise to preserve evenness of mind (under both)', chapter: 'Impartiality' },
  { id: 116, kural_number: 116, tamil_text: 'கெடுவல்யான் என்பது அறிகதன் நெஞ்சம் நடுவொரீஇ அல்ல செயின்.', transliteration: 'Ketuvalyaan Enpadhu Arikadhan Nenjam Natuvoreei Alla Seyin', english_meaning: 'Let him whose mind departing from equity commits sin well consider thus within himself, "I shall perish."', career_application: 'Let him whose mind departing from equity commits sin well consider thus within himself, "I shall perish."', chapter: 'Impartiality' },
  { id: 117, kural_number: 117, tamil_text: 'கெடுவாக வையாது உலகம் நடுவாக நன்றிக்கண் தங்கியான் தாழ்வு.', transliteration: 'Ketuvaaka Vaiyaadhu Ulakam Natuvaaka Nandrikkan Thangiyaan Thaazhvu', english_meaning: 'The great will not regard as poverty the low estate of that man who dwells in the virtue of equity', career_application: 'The great will not regard as poverty the low estate of that man who dwells in the virtue of equity', chapter: 'Impartiality' },
  { id: 118, kural_number: 118, tamil_text: 'சமன்செய்து சீர்தூக்குங் கோல்போல் அமைந்தொருபால் கோடாமை சான்றோர்க் கணி.', transliteration: 'Samanseydhu Seerdhookkung Kolpol Amaindhorupaal Kotaamai Saandrork Kani', english_meaning: 'To incline to neither side, but to rest impartial as the even-fixed scale is the ornament of the wise', career_application: 'To incline to neither side, but to rest impartial as the even-fixed scale is the ornament of the wise', chapter: 'Impartiality' },
  { id: 119, kural_number: 119, tamil_text: 'சொற்கோட்டம் இல்லது செப்பம் ஒருதலையா உட்கோட்டம் இன்மை பெறின்.', transliteration: 'Sorkottam Illadhu Seppam Orudhalaiyaa Utkottam Inmai Perin', english_meaning: 'Freedom from obliquity of speech is rectitude, if there be (corresponding) freedom from bias of mind', career_application: 'Freedom from obliquity of speech is rectitude, if there be (corresponding) freedom from bias of mind', chapter: 'Impartiality' },
  { id: 120, kural_number: 120, tamil_text: 'வாணிகம் செய்வார்க்கு வாணிகம் பேணிப் பிறவும் தமபோல் செயின்.', transliteration: 'Vaanikam Seyvaarkku Vaanikam Penip Piravum Thamapol Seyin', english_meaning: 'The true merchandize of merchants is to guard and do by the things of others as they do by their own', career_application: 'The true merchandize of merchants is to guard and do by the things of others as they do by their own', chapter: 'Impartiality' },
  { id: 121, kural_number: 121, tamil_text: 'அடக்கம் அமரருள் உய்க்கும் அடங்காமை ஆரிருள் உய்த்து விடும்.', transliteration: 'Atakkam Amararul Uykkum Atangaamai Aarirul Uyththu Vitum', english_meaning: 'Self-control will place (a man) among the Gods; the want of it will drive (him) into the thickest darkness (of hell)', career_application: 'Self-control will place (a man) among the Gods; the want of it will drive (him) into the thickest darkness (of hell)', chapter: 'The Possession of Self-restraint' },
  { id: 122, kural_number: 122, tamil_text: 'காக்க பொருளா அடக்கத்தை ஆக்கம் அதனினூஉங் கில்லை உயிர்க்கு.', transliteration: 'Kaakka Porulaa Atakkaththai Aakkam Adhaninooung Killai Uyirkku', english_meaning: 'Let self-control be guarded as a treasure; there is no greater source of good for man than that', career_application: 'Let self-control be guarded as a treasure; there is no greater source of good for man than that', chapter: 'The Possession of Self-restraint' },
  { id: 123, kural_number: 123, tamil_text: 'செறிவறிந்து சீர்மை பயக்கும் அறிவறிந்து ஆற்றின் அடங்கப் பெறின்.', transliteration: 'Serivarindhu Seermai Payakkum Arivarindhu Aatrin Atangap Perin', english_meaning: 'Knowing that self-control is knowledge, if a man should control himself, in the prescribed course, such self-control will bring him distinction among the wise', career_application: 'Knowing that self-control is knowledge, if a man should control himself, in the prescribed course, such self-control will bring him distinction among the wise', chapter: 'The Possession of Self-restraint' },
  { id: 124, kural_number: 124, tamil_text: 'நிலையின் திரியாது அடங்கியான் தோற்றம் மலையினும் மாணப் பெரிது.', transliteration: 'Nilaiyin Thiriyaadhu Atangiyaan Thotram Malaiyinum Maanap Peridhu', english_meaning: 'More lofty than a mountain will be the greatness of that man who without swerving from his domestic state, controls himself', career_application: 'More lofty than a mountain will be the greatness of that man who without swerving from his domestic state, controls himself', chapter: 'The Possession of Self-restraint' },
  { id: 125, kural_number: 125, tamil_text: 'எல்லார்க்கும் நன்றாம் பணிதல் அவருள்ளும் செல்வர்க்கே செல்வம் தகைத்து.', transliteration: 'Ellaarkkum Nandraam Panidhal Avarullum Selvarkke Selvam Thakaiththu', english_meaning: 'Humility is good in all; but especially in the rich it is (the excellence of) higher riches', career_application: 'Humility is good in all; but especially in the rich it is (the excellence of) higher riches', chapter: 'The Possession of Self-restraint' },
  { id: 126, kural_number: 126, tamil_text: 'ஒருமையுள் ஆமைபோல் ஐந்தடக்கல் ஆற்றின் எழுமையும் ஏமாப் புடைத்து.', transliteration: 'Orumaiyul Aamaipol Aindhatakkal Aatrin Ezhumaiyum Emaap Putaiththu', english_meaning: 'Should one throughout a single birth, like a tortoise keep in his five senses, the fruit of it will prove a safe-guard to him throughout the seven-fold births.', career_application: 'Should one throughout a single birth, like a tortoise keep in his five senses, the fruit of it will prove a safe-guard to him throughout the seven-fold births.', chapter: 'The Possession of Self-restraint' },
  { id: 127, kural_number: 127, tamil_text: 'யாகாவா ராயினும் நாகாக்க காவாக்கால் சோகாப்பர் சொல்லிழுக்குப் பட்டு.', transliteration: 'Yaakaavaa Raayinum Naakaakka Kaavaakkaal Sokaappar Sollizhukkup Pattu', english_meaning: 'Whatever besides you leave unguarded, guard your tongue; otherwise errors of speech and the consequent misery will ensue', career_application: 'Whatever besides you leave unguarded, guard your tongue; otherwise errors of speech and the consequent misery will ensue', chapter: 'The Possession of Self-restraint' },
  { id: 128, kural_number: 128, tamil_text: 'ஒன்றானுந் தீச்சொல் பொருட்பயன் உண்டாயின் நன்றாகா தாகி விடும்.', transliteration: 'Ondraanun Theechchol Porutpayan Untaayin Nandraakaa Thaaki Vitum', english_meaning: 'If a man\'s speech be productive of a single evil, all the good by him will be turned into evil', career_application: 'If a man\'s speech be productive of a single evil, all the good by him will be turned into evil', chapter: 'The Possession of Self-restraint' },
  { id: 129, kural_number: 129, tamil_text: 'தீயினாற் சுட்டபுண் உள்ளாறும் ஆறாதே நாவினாற் சுட்ட வடு.', transliteration: 'Theeyinaar Suttapun Ullaarum Aaraadhe Naavinaar Sutta Vatu', english_meaning: 'The wound which has been burnt in by fire may heal, but a wound burnt in by the tongue will never heal', career_application: 'The wound which has been burnt in by fire may heal, but a wound burnt in by the tongue will never heal', chapter: 'The Possession of Self-restraint' },
  { id: 130, kural_number: 130, tamil_text: 'கதங்காத்துக் கற்றடங்கல் ஆற்றுவான் செவ்வி அறம்பார்க்கும் ஆற்றின் நுழைந்து.', transliteration: 'Kadhangaaththuk Katratangal Aatruvaan Sevvi Arampaarkkum Aatrin Nuzhaindhu', english_meaning: 'Virtue, seeking for an opportunity, will come into the path of that man who, possessed of learning and self-control, guards himself against anger', career_application: 'Virtue, seeking for an opportunity, will come into the path of that man who, possessed of learning and self-control, guards himself against anger', chapter: 'The Possession of Self-restraint' },
  { id: 131, kural_number: 131, tamil_text: 'ஒழுக்கம் விழுப்பந் தரலான் ஒழுக்கம் உயிரினும் ஓம்பப் படும்.', transliteration: 'Ozhukkam Vizhuppan Tharalaan Ozhukkam Uyirinum Ompap Patum', english_meaning: 'Propriety of conduct leads to eminence, it should therefore be preserved more carefully than life', career_application: 'Propriety of conduct leads to eminence, it should therefore be preserved more carefully than life', chapter: 'The Possession of Decorum' },
  { id: 132, kural_number: 132, tamil_text: 'பரிந்தோம்பிக் காக்க ஒழுக்கம் தெரிந்தோம்பித் தேரினும் அஃதே துணை.', transliteration: 'Parindhompik Kaakka Ozhukkam Therindhompith Therinum Aqdhe Thunai', english_meaning: 'Let propriety of conduct be laboriously preserved and guarded; though one know and practise and excel in many virtues, that will be an eminent aid', career_application: 'Let propriety of conduct be laboriously preserved and guarded; though one know and practise and excel in many virtues, that will be an eminent aid', chapter: 'The Possession of Decorum' },
  { id: 133, kural_number: 133, tamil_text: 'ஒழுக்கம் உடைமை குடிமை இழுக்கம் இழிந்த பிறப்பாய் விடும்.', transliteration: 'Ozhukkam Utaimai Kutimai Izhukkam Izhindha Pirappaai Vitum', english_meaning: 'Propriety of conduct is true greatness of birth, and impropriety will sink into a mean birth', career_application: 'Propriety of conduct is true greatness of birth, and impropriety will sink into a mean birth', chapter: 'The Possession of Decorum' },
  { id: 134, kural_number: 134, tamil_text: 'மறப்பினும் ஓத்துக் கொளலாகும் பார்ப்பான் பிறப்பொழுக்கங் குன்றக் கெடும்.', transliteration: 'Marappinum Oththuk Kolalaakum Paarppaan Pirappozhukkang Kundrak Ketum', english_meaning: 'A Brahman though he should forget the Vedas may recover it by reading; but, if he fail in propriety of conduct even his high birth will be destroyed', career_application: 'A Brahman though he should forget the Vedas may recover it by reading; but, if he fail in propriety of conduct even his high birth will be destroyed', chapter: 'The Possession of Decorum' },
  { id: 135, kural_number: 135, tamil_text: 'அழுக்கா றுடையான்கண் ஆக்கம்போன்று இல்லை ஒழுக்க மிலான்கண் உயர்வு.', transliteration: 'Azhukkaa Rutaiyaankan Aakkampondru Illai Ozhukka Milaankan Uyarvu', english_meaning: 'Just as the envious man will be without wealth, so will the man of destitute of propriety of conduct be without greatness', career_application: 'Just as the envious man will be without wealth, so will the man of destitute of propriety of conduct be without greatness', chapter: 'The Possession of Decorum' },
  { id: 136, kural_number: 136, tamil_text: 'ஒழுக்கத்தின் ஒல்கார் உரவோர் இழுக்கத்தின் ஏதம் படுபாக் கறிந்து.', transliteration: 'Ozhukkaththin Olkaar Uravor Izhukkaththin Edham Patupaak Karindhu', english_meaning: 'Those firm in mind will not slacken in their observance of the proprieties of life, knowing, as they do, the misery that flows from the transgression from them', career_application: 'Those firm in mind will not slacken in their observance of the proprieties of life, knowing, as they do, the misery that flows from the transgression from them', chapter: 'The Possession of Decorum' },
  { id: 137, kural_number: 137, tamil_text: 'ஒழுக்கத்தின் எய்துவர் மேன்மை இழுக்கத்தின் எய்துவர் எய்தாப் பழி.', transliteration: 'Ozhukkaththin Eydhuvar Menmai Izhukkaththin Eydhuvar Eydhaap Pazhi', english_meaning: 'From propriety of conduct men obtain greatness; from impropriety comes insufferable disgrace', career_application: 'From propriety of conduct men obtain greatness; from impropriety comes insufferable disgrace', chapter: 'The Possession of Decorum' },
  { id: 138, kural_number: 138, tamil_text: 'நன்றிக்கு வித்தாகும் நல்லொழுக்கம் தீயொழுக்கம் என்றும் இடும்பை தரும்.', transliteration: 'Nandrikku Viththaakum Nallozhukkam Theeyozhukkam Endrum Itumpai Tharum', english_meaning: 'Propriety of conduct is the seed of virtue; impropriety will ever cause sorrow', career_application: 'Propriety of conduct is the seed of virtue; impropriety will ever cause sorrow', chapter: 'The Possession of Decorum' },
  { id: 139, kural_number: 139, tamil_text: 'ஒழுக்க முடையவர்க்கு ஒல்லாவே தீய வழுக்கியும் வாயாற் சொலல்.', transliteration: 'Ozhukka Mutaiyavarkku Ollaave Theeya Vazhukkiyum Vaayaar Solal', english_meaning: 'Those who study propriety of conduct will not speak evil, even forgetfully', career_application: 'Those who study propriety of conduct will not speak evil, even forgetfully', chapter: 'The Possession of Decorum' },
  { id: 140, kural_number: 140, tamil_text: 'உலகத்தோடு ஒட்ட ஒழுகல் பலகற்றும் கல்லார் அறிவிலா தார்', transliteration: 'Ulakaththotu Otta Ozhukal Palakatrum Kallaar Arivilaa Thaar', english_meaning: 'Those who know not how to act agreeably to the world, though they have learnt many things, are still ignorant', career_application: 'Those who know not how to act agreeably to the world, though they have learnt many things, are still ignorant', chapter: 'The Possession of Decorum' },
  { id: 141, kural_number: 141, tamil_text: 'பிறன்பொருளாள் பெட்டொழுகும் பேதைமை ஞாலத்து அறம்பொருள் கண்டார்கண் இல்.', transliteration: 'Piranporulaal Pettozhukum Pedhaimai Gnaalaththu Aramporul Kantaarkan Il', english_meaning: 'The folly of desiring her who is the property of another will not be found in those who know (the attributes of) virtue and (the rights of) property', career_application: 'The folly of desiring her who is the property of another will not be found in those who know (the attributes of) virtue and (the rights of) property', chapter: 'Not coveting another"s Wife' },
  { id: 142, kural_number: 142, tamil_text: 'அறன்கடை நின்றாருள் எல்லாம் பிறன்கடை நின்றாரின் பேதையார் இல்.', transliteration: 'Arankatai Nindraarul Ellaam Pirankatai Nindraarin Pedhaiyaar Il', english_meaning: 'Among all those who stand on the outside of virtue, there are no greater fools than those who stand outside their neighbour\'s door', career_application: 'Among all those who stand on the outside of virtue, there are no greater fools than those who stand outside their neighbour\'s door', chapter: 'Not coveting another"s Wife' },
  { id: 143, kural_number: 143, tamil_text: 'விளிந்தாரின் வேறல்லர் மன்ற தெளிந்தாரில் தீமை புரிந்து ஒழுகு வார்.', transliteration: 'Vilindhaarin Verallar Mandra Thelindhaaril Theemai Purindhu Ozhuku Vaar', english_meaning: 'Certainly they are no better than dead men who desire evil towards the wife of those who', career_application: 'Certainly they are no better than dead men who desire evil towards the wife of those who', chapter: 'Not coveting another"s Wife' },
  { id: 144, kural_number: 144, tamil_text: 'எனைத்துணையர் ஆயினும் என்னாம் தினைத்துணையும் தேரான் பிறனில் புகல்.', transliteration: 'Enaiththunaiyar Aayinum Ennaam Thinaiththunaiyum Theraan Piranil Pukal', english_meaning: 'However great one may be, what does it avail if, without at all considering his guilt, he goes unto the wife of another ?', career_application: 'However great one may be, what does it avail if, without at all considering his guilt, he goes unto the wife of another ?', chapter: 'Not coveting another"s Wife' },
  { id: 145, kural_number: 145, tamil_text: 'எளிதென இல்லிறப்பான் எய்துமெஞ் ஞான்றும் விளியாது நிற்கும் பழி.', transliteration: 'Elidhena Illirappaan Eydhumenj Gnaandrum Viliyaadhu Nirkum Pazhi', english_meaning: 'He who thinks lightly of going into the wife of another acquires guilt that will abide with him imperishably and for ever', career_application: 'He who thinks lightly of going into the wife of another acquires guilt that will abide with him imperishably and for ever', chapter: 'Not coveting another"s Wife' },
  { id: 146, kural_number: 146, tamil_text: 'பகைபாவம் அச்சம் பழியென நான்கும் இகவாவாம் இல்லிறப்பான் கண்.', transliteration: 'Pakaipaavam Achcham Pazhiyena Naankum Ikavaavaam Illirappaan Kan', english_meaning: 'Hatred, sin, fear, disgrace; these four will never leave him who goes in to his neighbour\'s wife', career_application: 'Hatred, sin, fear, disgrace; these four will never leave him who goes in to his neighbour\'s wife', chapter: 'Not coveting another"s Wife' },
  { id: 147, kural_number: 147, tamil_text: 'அறனியலான் இல்வாழ்வான் என்பான் பிறனியலாள் பெண்மை நயவா தவன்.', transliteration: 'Araniyalaan Ilvaazhvaan Enpaan Piraniyalaal Penmai Nayavaa Thavan', english_meaning: 'He who desires not the womanhood of her who should walk according to the will of another will be praised as a virtuous house-holder', career_application: 'He who desires not the womanhood of her who should walk according to the will of another will be praised as a virtuous house-holder', chapter: 'Not coveting another"s Wife' },
  { id: 148, kural_number: 148, tamil_text: 'பிறன்மனை நோக்காத பேராண்மை சான்றோர்க்கு அறனொன்றோ ஆன்ற வொழுக்கு.', transliteration: 'Piranmanai Nokkaadha Peraanmai Saandrorkku Aranondro Aandra Vozhukku', english_meaning: 'That noble manliness which looks not at the wife of another is the virtue and dignity of the great', career_application: 'That noble manliness which looks not at the wife of another is the virtue and dignity of the great', chapter: 'Not coveting another"s Wife' },
  { id: 149, kural_number: 149, tamil_text: 'நலக்குரியார் யாரெனின் நாமநீர் வைப்பின் பிறர்க்குரியாள் தோள்தோயா தார்.', transliteration: 'Nalakkuriyaar Yaarenin Naamaneer Vaippin Pirarkkuriyaal Tholdhoyaa Thaar', english_meaning: 'Is it asked, "who are those who shall obtain good in this world surrounded by the terror-producing sea ?" Those who touch not the shoulder of her who belongs to another', career_application: 'Is it asked, "who are those who shall obtain good in this world surrounded by the terror-producing sea ?" Those who touch not the shoulder of her who belongs to another', chapter: 'Not coveting another"s Wife' },
  { id: 150, kural_number: 150, tamil_text: 'அறன்வரையான் அல்ல செயினும் பிறன்வரையாள் பெண்மை நயவாமை நன்று.', transliteration: 'Aranvaraiyaan Alla Seyinum Piranvaraiyaal Penmai Nayavaamai Nandru', english_meaning: 'Though a man perform no virtuous deeds and commit (every) vice, it will be well if he desire not the womanhood of her who is within the limit (of the house) of another', career_application: 'Though a man perform no virtuous deeds and commit (every) vice, it will be well if he desire not the womanhood of her who is within the limit (of the house) of another', chapter: 'Not coveting another"s Wife' },
  { id: 151, kural_number: 151, tamil_text: 'அகழ்வாரைத் தாங்கும் நிலம்போலத் தம்மை இகழ்வார்ப் பொறுத்தல் தலை.', transliteration: 'Akazhvaaraith Thaangum Nilampolath Thammai Ikazhvaarp Poruththal Thalai', english_meaning: 'To bear with those who revile us, just as the earth bears up those who dig it, is the first of virtues', career_application: 'To bear with those who revile us, just as the earth bears up those who dig it, is the first of virtues', chapter: 'The Possession of Patience, Forbearance' },
  { id: 152, kural_number: 152, tamil_text: 'பொறுத்தல் இறப்பினை என்றும் அதனை மறத்தல் அதனினும் நன்று.', transliteration: 'Poruththal Irappinai Endrum Adhanai Maraththal Adhaninum Nandru', english_meaning: 'Bear with reproach even when you can retaliate; but to forget it will be still better than that', career_application: 'Bear with reproach even when you can retaliate; but to forget it will be still better than that', chapter: 'The Possession of Patience, Forbearance' },
  { id: 153, kural_number: 153, tamil_text: 'இன்மையுள் இன்மை விருந்தொரால் வன்மையுள் வன்மை மடவார்ப் பொறை.', transliteration: 'Inmaiyul Inmai Virundhoraal Vanmaiyul Vanmai Matavaarp Porai', english_meaning: 'To neglect hospitality is poverty of poverty To bear with the ignorant is might of might', career_application: 'To neglect hospitality is poverty of poverty To bear with the ignorant is might of might', chapter: 'The Possession of Patience, Forbearance' },
  { id: 154, kural_number: 154, tamil_text: 'நிறையுடைமை நீங்காமை வேண்டின் பொற்யுடைமை போற்றி யொழுகப் படும்.', transliteration: 'Niraiyutaimai Neengaamai Ventin Poraiyutaimai Potri Yozhukap Patum', english_meaning: 'If you desire that greatness should never leave, you preserve in your conduct the exercise of patience', career_application: 'If you desire that greatness should never leave, you preserve in your conduct the exercise of patience', chapter: 'The Possession of Patience, Forbearance' },
  { id: 155, kural_number: 155, tamil_text: 'ஒறுத்தாரை ஒன்றாக வையாரே வைப்பர் பொறுத்தாரைப் பொன்போற் பொதிந்து.', transliteration: 'Oruththaarai Ondraaka Vaiyaare Vaippar Poruththaaraip Ponpor Podhindhu', english_meaning: '(The wise) will not at all esteem the resentful They will esteem the patient just as the gold which they lay up with care', career_application: '(The wise) will not at all esteem the resentful They will esteem the patient just as the gold which they lay up with care', chapter: 'The Possession of Patience, Forbearance' },
  { id: 156, kural_number: 156, tamil_text: 'ஒறுத்தார்க்கு ஒருநாளை இன்பம் பொறுத்தார்க்குப் பொன்றுந் துணையும் புகழ்.', transliteration: 'Oruththaarkku Orunaalai Inpam Poruththaarkkup Pondrun Thunaiyum Pukazh', english_meaning: 'The pleasure of the resentful continues for a day The praise of the patient will continue until (the final destruction of) the world', career_application: 'The pleasure of the resentful continues for a day The praise of the patient will continue until (the final destruction of) the world', chapter: 'The Possession of Patience, Forbearance' },
  { id: 157, kural_number: 157, tamil_text: 'திறனல்ல தற்பிறர் செய்யினும் நோநொந்து அறனல்ல செய்யாமை நன்று.', transliteration: 'Thiranalla Tharpirar Seyyinum Nonondhu Aranalla Seyyaamai Nandru', english_meaning: 'Though others inflict injuries on you, yet compassionating the evil (that will come upon them) it will be well not to do them anything contrary to virtue', career_application: 'Though others inflict injuries on you, yet compassionating the evil (that will come upon them) it will be well not to do them anything contrary to virtue', chapter: 'The Possession of Patience, Forbearance' },
  { id: 158, kural_number: 158, tamil_text: 'மிகுதியான் மிக்கவை செய்தாரைத் தாந்தம் தகுதியான் வென்று விடல்.', transliteration: 'Mikudhiyaan Mikkavai Seydhaaraith Thaandham Thakudhiyaan Vendru Vital', english_meaning: 'Let a man by patience overcome those who through pride commit excesses', career_application: 'Let a man by patience overcome those who through pride commit excesses', chapter: 'The Possession of Patience, Forbearance' },
  { id: 159, kural_number: 159, tamil_text: 'துறந்தாரின் தூய்மை உடையர் இறந்தார்வாய் இன்னாச்சொல் நோற்கிற் பவர்.', transliteration: 'Thurandhaarin Thooimai Utaiyar Irandhaarvaai Innaachchol Norkir Pavar', english_meaning: 'Those who bear with the uncourteous speech of the insolent are as pure as the ascetics', career_application: 'Those who bear with the uncourteous speech of the insolent are as pure as the ascetics', chapter: 'The Possession of Patience, Forbearance' },
  { id: 160, kural_number: 160, tamil_text: 'உண்ணாது நோற்பார் பெரியர் பிறர்சொல்லும் இன்னாச்சொல் நோற்பாரின் பின்.', transliteration: 'Unnaadhu Norpaar Periyar Pirarsollum Innaachchol Norpaarin Pin', english_meaning: 'Those who endure abstinence from food are great, next to those who endure the uncourteous speech of others', career_application: 'Those who endure abstinence from food are great, next to those who endure the uncourteous speech of others', chapter: 'The Possession of Patience, Forbearance' },
  { id: 161, kural_number: 161, tamil_text: 'ஒழுக்காறாக் கொள்க ஒருவன்தன் நெஞ்சத்து அழுக்காறு இலாத இயல்பு.', transliteration: 'Ozhukkaaraak Kolka Oruvandhan Nenjaththu Azhukkaaru Ilaadha Iyalpu', english_meaning: 'Let a man esteem that disposition which is free from envy in the same manner as propriety of conduct', career_application: 'Let a man esteem that disposition which is free from envy in the same manner as propriety of conduct', chapter: 'Not Envying' },
  { id: 162, kural_number: 162, tamil_text: 'விழுப்பேற்றின் அஃதொப்பது இல்லையார் மாட்டும் அழுக்காற்றின் அன்மை பெறின்.', transliteration: 'Vizhuppetrin Aqdhoppadhu Illaiyaar Maattum Azhukkaatrin Anmai Perin', english_meaning: 'Amongst all attainable excellences there is none equal to that of being free from envy towords others', career_application: 'Amongst all attainable excellences there is none equal to that of being free from envy towords others', chapter: 'Not Envying' },
  { id: 163, kural_number: 163, tamil_text: 'அறன்ஆக்கம் வேண்டாதான் என்பான் பிறனாக்கம் பேணாது அழுக்கறுப் பான்.', transliteration: 'Aranaakkam Ventaadhaan Enpaan Piranaakkam Penaadhu Azhukkarup Paan', english_meaning: 'Of him who instead of rejoicing in the wealth of others, envies it, it will be said "he neither desires virtue not wealth."', career_application: 'Of him who instead of rejoicing in the wealth of others, envies it, it will be said "he neither desires virtue not wealth."', chapter: 'Not Envying' },
  { id: 164, kural_number: 164, tamil_text: 'அழுக்காற்றின் அல்லவை செய்யார் இழுக்காற்றின் ஏதம் படுபாக்கு அறிந்து.', transliteration: 'Azhukkaatrin Allavai Seyyaar Izhukkaatrin Edham Patupaakku Arindhu', english_meaning: '(The wise) knowing the misery that comes from transgression will not through envy commit unrighteous deeds', career_application: '(The wise) knowing the misery that comes from transgression will not through envy commit unrighteous deeds', chapter: 'Not Envying' },
  { id: 165, kural_number: 165, tamil_text: 'அழுக்காறு உடையார்க்கு அதுசாலும் ஒன்னார் வழுக்காயும் கேடீன் பது.', transliteration: 'Azhukkaaru Utaiyaarkku Adhusaalum Onnaar Vazhukka�yum Keteen Padhu', english_meaning: 'To those who cherish envy that is enough Though free from enemies that (envy) will bring destruction', career_application: 'To those who cherish envy that is enough Though free from enemies that (envy) will bring destruction', chapter: 'Not Envying' },
  { id: 166, kural_number: 166, tamil_text: 'கொடுப்பது அழுக்கறுப்பான் சுற்றம் உடுப்பதூஉம் உண்பதூஉம் இன்றிக் கெடும்.', transliteration: 'Kotuppadhu Azhukkaruppaan Sutram Utuppadhooum Unpadhooum Indrik Ketum', english_meaning: 'He who is envious at a gift (made to another) will with his relations utterly perish destitute of food and rainment', career_application: 'He who is envious at a gift (made to another) will with his relations utterly perish destitute of food and rainment', chapter: 'Not Envying' },
  { id: 167, kural_number: 167, tamil_text: 'அவ்வித்து அழுக்காறு உடையானைச் செய்யவள் தவ்வையைக் காட்டி விடும்.', transliteration: 'Avviththu Azhukkaaru Utaiyaanaich Cheyyaval Thavvaiyaik Kaatti Vitum', english_meaning: 'Lakshmi envying (the prosperity) of the envious man will depart and introduce him to her sister', career_application: 'Lakshmi envying (the prosperity) of the envious man will depart and introduce him to her sister', chapter: 'Not Envying' },
  { id: 168, kural_number: 168, tamil_text: 'அழுக்காறு எனஒரு பாவி திருச்செற்றுத் தீயுழி உய்த்து விடும்.', transliteration: 'Azhukkaaru Enaoru Paavi Thiruchchetruth Theeyuzhi Uyththu Vitum', english_meaning: 'Envy will destroy (a man\'s) wealth (in his world) and drive him into the pit of fire (in the world to come.)', career_application: 'Envy will destroy (a man\'s) wealth (in his world) and drive him into the pit of fire (in the world to come.)', chapter: 'Not Envying' },
  { id: 169, kural_number: 169, tamil_text: 'அவ்விய நெஞ்சத்தான் ஆக்கமும் செவ்வியான் கேடும் நினைக்கப் படும்.', transliteration: 'Avviya Nenjaththaan Aakkamum Sevviyaan Ketum Ninaikkap Patum', english_meaning: 'The wealth of a man of envious mind and the poverty of the righteous will be pondered', career_application: 'The wealth of a man of envious mind and the poverty of the righteous will be pondered', chapter: 'Not Envying' },
  { id: 170, kural_number: 170, tamil_text: 'அழுக்கற்று அகன்றாரும் இல்லை அஃதுஇல்லார் பெருக்கத்தில் தீர்ந்தாரும் இல்.', transliteration: 'Azhukkatru Akandraarum Illai Aqdhuillaar Perukkaththil Theerndhaarum Il', english_meaning: 'Never have the envious become great; never have those who are free from envy been without greatness', career_application: 'Never have the envious become great; never have those who are free from envy been without greatness', chapter: 'Not Envying' },
  { id: 171, kural_number: 171, tamil_text: 'நடுவின்றி நன்பொருள் வெஃகின் குடிபொன்றிக் குற்றமும் ஆங்கே தரும்.', transliteration: 'Natuvindri Nanporul Veqkin Kutipondrik Kutramum Aange Tharum', english_meaning: 'If a man departing from equity covet the property (of others), at that very time will his family be destroyed and guilt be incurred', career_application: 'If a man departing from equity covet the property (of others), at that very time will his family be destroyed and guilt be incurred', chapter: 'Not Coveting' },
  { id: 172, kural_number: 172, tamil_text: 'படுபயன் வெஃகிப் பழிப்படுவ செய்யார் நடுவன்மை நாணு பவர்.', transliteration: 'Patupayan Veqkip Pazhippatuva Seyyaar Natuvanmai Naanu Pavar', english_meaning: 'Those who blush at the want of equity will not commit disgraceful acts through desire of the profit that may be gained', career_application: 'Those who blush at the want of equity will not commit disgraceful acts through desire of the profit that may be gained', chapter: 'Not Coveting' },
  { id: 173, kural_number: 173, tamil_text: 'சிற்றின்பம் வெஃகி அறனல்ல செய்யாரே மற்றின்பம் வேண்டு பவர்.', transliteration: 'Sitrinpam Veqki Aranalla Seyyaare Matrinpam Ventu Pavar', english_meaning: 'Those who desire the higher pleasures (of heaven) will not act unjustly through desire of the trifling joy. (in this life.)', career_application: 'Those who desire the higher pleasures (of heaven) will not act unjustly through desire of the trifling joy. (in this life.)', chapter: 'Not Coveting' },
  { id: 174, kural_number: 174, tamil_text: 'இலமென்று வெஃகுதல் செய்யார் புலம்வென்ற புன்மையில் காட்சி யவர்.', transliteration: 'Ilamendru Veqkudhal Seyyaar Pulamvendra Punmaiyil Kaatchi Yavar', english_meaning: 'The wise who have conquered their senses and are free from crime, will not covet (the things of others), with the thought "we are destitute."', career_application: 'The wise who have conquered their senses and are free from crime, will not covet (the things of others), with the thought "we are destitute."', chapter: 'Not Coveting' },
  { id: 175, kural_number: 175, tamil_text: 'அஃகி அகன்ற அறிவென்னாம் யார்மாட்டும் வெஃகி வெறிய செயின்.', transliteration: 'Aqki Akandra Arivennaam Yaarmaattum Veqki Veriya Seyin', english_meaning: 'What is the advantage of extensive and accurate knowledge if a man through covetousness act senselessly towards all ?', career_application: 'What is the advantage of extensive and accurate knowledge if a man through covetousness act senselessly towards all ?', chapter: 'Not Coveting' },
  { id: 176, kural_number: 176, tamil_text: 'அருள்வெஃகி ஆற்றின்கண் நின்றான் பொருள்வெஃகிப் பொல்லாத சூழக் கெடும்.', transliteration: 'Arulveqki Aatrinkan Nindraan Porulveqkip Pollaadha Soozhak Ketum', english_meaning: 'If he, who through desire of the virtue of kindness abides in the domestic state ie, the path in which it may be obtained, covet (the property of others) and think of evil methods (to obtain it), he will perish', career_application: 'If he, who through desire of the virtue of kindness abides in the domestic state ie, the path in which it may be obtained, covet (the property of others) and think of evil methods (to obtain it), he will perish', chapter: 'Not Coveting' },
  { id: 177, kural_number: 177, tamil_text: 'வேண்டற்க வெஃகியாம் ஆக்கம் விளைவயின் மாண்டற் கரிதாம் பயன்.', transliteration: 'Ventarka Veqkiyaam Aakkam Vilaivayin Maantar Karidhaam Payan', english_meaning: 'Desire not the gain of covetousness In the enjoyment of its fruits there is no glory', career_application: 'Desire not the gain of covetousness In the enjoyment of its fruits there is no glory', chapter: 'Not Coveting' },
  { id: 178, kural_number: 178, tamil_text: 'அஃகாமை செல்வத்திற்கு யாதெனின் வெஃகாமை வேண்டும் பிறன்கைப் பொருள்.', transliteration: 'Aqkaamai Selvaththirku Yaadhenin Veqkaamai Ventum Pirankaip Porul', english_meaning: 'If it is weighed, "what is the indestructibility of wealth," it is freedom from covetousness', career_application: 'If it is weighed, "what is the indestructibility of wealth," it is freedom from covetousness', chapter: 'Not Coveting' },
  { id: 179, kural_number: 179, tamil_text: 'அறனறிந்து வெஃகா அறிவுடையார்ச் சேரும் திறன்அறிந் தாங்கே திரு.', transliteration: 'Aranarindhu Veqkaa Arivutaiyaarch Cherum Thiranarin Thaange Thiru', english_meaning: 'Lakshmi, knowing the manner (in which she may approach) will immediately come to those wise men who, knowing that it is virtue, covet not the property of others', career_application: 'Lakshmi, knowing the manner (in which she may approach) will immediately come to those wise men who, knowing that it is virtue, covet not the property of others', chapter: 'Not Coveting' },
  { id: 180, kural_number: 180, tamil_text: 'இறலீனும் எண்ணாது வெஃகின் விறல்ஈனும் வேண்டாமை என்னுஞ் செருக்கு.', transliteration: 'Iraleenum Ennaadhu Veqkin Viraleenum Ventaamai Ennunj Cherukku', english_meaning: 'To covet (the wealth of another) regardless of consequences will bring destruction That greatness (of mind) which covets not will give victory', career_application: 'To covet (the wealth of another) regardless of consequences will bring destruction That greatness (of mind) which covets not will give victory', chapter: 'Not Coveting' },
  { id: 181, kural_number: 181, tamil_text: 'அறங்கூறான் அல்ல செயினும் ஒருவன் புறங்கூறான் என்றல் இனிது.', transliteration: 'Arangooraan Alla Seyinum Oruvan Purangooraan Endral Inidhu', english_meaning: 'Though one do not even speak of virtue and live in sin, it will be well if it be said of him "he does not backbite."', career_application: 'Though one do not even speak of virtue and live in sin, it will be well if it be said of him "he does not backbite."', chapter: 'Not Backbiting' },
  { id: 182, kural_number: 182, tamil_text: 'அறனழீஇ அல்லவை செய்தலின் தீதே புறனழீஇப் பொய்த்து நகை.', transliteration: 'Aranazheei Allavai Seydhalin Theedhe Puranazheeip Poiththu Nakai', english_meaning: 'To smile deceitfully (in another\'s presence) after having reviled him to his destruction (behind his back) is a greater evil than the commission of (every other) sin and the destruction of (every) virtue', career_application: 'To smile deceitfully (in another\'s presence) after having reviled him to his destruction (behind his back) is a greater evil than the commission of (every other) sin and the destruction of (every) virtue', chapter: 'Not Backbiting' },
  { id: 183, kural_number: 183, tamil_text: 'புறங்கூறிப் பொய்த்துயிர் வாழ்தலின் சாதல் அறங்கூற்றும் ஆக்கத் தரும்.', transliteration: 'Purangoorip Poiththuyir Vaazhdhalin Saadhal Arangootrum Aakkath Tharum', english_meaning: 'Death rather than life will confer upon the deceitful backbiter the profit which (the treatises on) virtue point out', career_application: 'Death rather than life will confer upon the deceitful backbiter the profit which (the treatises on) virtue point out', chapter: 'Not Backbiting' },
  { id: 184, kural_number: 184, tamil_text: 'கண்ணின்று கண்ணறச் சொல்லினும் சொல்லற்க முன்னின்று பின்நோக்காச் சொல்.', transliteration: 'Kannindru Kannarach Chollinum Sollarka Munnindru Pinnokkaach Chol', english_meaning: 'Though you speak without kindness before another\'s face speak not in his absence words which regard not the evil subsequently resulting from it', career_application: 'Though you speak without kindness before another\'s face speak not in his absence words which regard not the evil subsequently resulting from it', chapter: 'Not Backbiting' },
  { id: 185, kural_number: 185, tamil_text: 'அறஞ்சொல்லும் நெஞ்சத்தான் அன்மை புறஞ்சொல்லும் புன்மையாற் காணப் படும்.', transliteration: 'Aranjollum Nenjaththaan Anmai Puranjollum Punmaiyaar Kaanap Patum', english_meaning: 'The emptiness of that man\'s mind who (merely) praises virtue will be seen from the meanness of reviling another behind his back', career_application: 'The emptiness of that man\'s mind who (merely) praises virtue will be seen from the meanness of reviling another behind his back', chapter: 'Not Backbiting' },
  { id: 186, kural_number: 186, tamil_text: 'பிறன்பழி கூறுவான் தன்பழி யுள்ளும் திறன்தெரிந்து கூறப் படும்.', transliteration: 'Piranpazhi Kooruvaan Thanpazhi Yullum Thirandherindhu Koorap Patum', english_meaning: 'The character of the faults of that man who publishes abroad the faults of others will be sought out and published', career_application: 'The character of the faults of that man who publishes abroad the faults of others will be sought out and published', chapter: 'Not Backbiting' },
  { id: 187, kural_number: 187, tamil_text: 'பகச்சொல்லிக் கேளிர்ப் பிரிப்பர் நகச்சொல்லி நட்பாடல் தேற்றா தவர்.', transliteration: 'Pakachchollik Kelirp Pirippar Nakachcholli Natpaatal Thetraa Thavar', english_meaning: 'Those who know not to live in friendship with amusing conversation will by back-biting estrange even their relatives', career_application: 'Those who know not to live in friendship with amusing conversation will by back-biting estrange even their relatives', chapter: 'Not Backbiting' },
  { id: 188, kural_number: 188, tamil_text: 'துன்னியார் குற்றமும் தூற்றும் மரபினார் என்னைகொல் ஏதிலார் மாட்டு.', transliteration: 'Thunniyaar Kutramum Thootrum Marapinaar Ennaikol Edhilaar Maattu', english_meaning: 'What will those not do to strangers whose nature leads them to publish abroad the faults of their intimate friends ?', career_application: 'What will those not do to strangers whose nature leads them to publish abroad the faults of their intimate friends ?', chapter: 'Not Backbiting' },
  { id: 189, kural_number: 189, tamil_text: 'அறன்நோக்கி ஆற்றுங்கொல் வையம் புறன்நோக்கிப் புன்சொல் உரைப்பான் பொறை.', transliteration: 'Arannokki Aatrungol Vaiyam Purannokkip Punsol Uraippaan Porai', english_meaning: 'The world through charity supports the weight of those who reproach others observing their absence', career_application: 'The world through charity supports the weight of those who reproach others observing their absence', chapter: 'Not Backbiting' },
  { id: 190, kural_number: 190, tamil_text: 'ஏதிலார் குற்றம்போல் தங்குற்றங் காண்கிற்பின் தீதுண்டோ மன்னும் உயிர்க்கு.', transliteration: 'Edhilaar Kutrampol Thangutrang Kaankirpin Theedhunto Mannum Uyirkku', english_meaning: 'If they observed their own faults as they observe the faults of others, would any evil happen to men ?', career_application: 'If they observed their own faults as they observe the faults of others, would any evil happen to men ?', chapter: 'Not Backbiting' },
  { id: 191, kural_number: 191, tamil_text: 'பல்லார் முனியப் பயனில சொல்லுவான் எல்லாரும் எள்ளப் படும்.', transliteration: 'Pallaar Muniyap Payanila Solluvaan Ellaarum Ellap Patum', english_meaning: 'He who to the disgust of many speaks useless things will be despised by all', career_application: 'He who to the disgust of many speaks useless things will be despised by all', chapter: 'Against Vain Speaking' },
  { id: 192, kural_number: 192, tamil_text: 'பயனில பல்லார்முன் சொல்லல் நயனில நட்டார்கண் செய்தலிற் றீது.', transliteration: 'Payanila Pallaarmun Sollal Nayanila Nattaarkan Seydhalir Reedhu', english_meaning: 'To speak useless things in the presence of many is a greater evil than to do unkind things towards friends', career_application: 'To speak useless things in the presence of many is a greater evil than to do unkind things towards friends', chapter: 'Against Vain Speaking' },
  { id: 193, kural_number: 193, tamil_text: 'நயனிலன் என்பது சொல்லும் பயனில பாரித் துரைக்கும் உரை.', transliteration: 'Nayanilan Enpadhu Sollum Payanila Paarith Thuraikkum Urai', english_meaning: 'That conversation in which a man utters forth useless things will say of him "he is without virtue."', career_application: 'That conversation in which a man utters forth useless things will say of him "he is without virtue."', chapter: 'Against Vain Speaking' },
  { id: 194, kural_number: 194, tamil_text: 'நயன்சாரா நன்மையின் நீக்கும் பயன்சாராப் பண்பில்சொல் பல்லா ரகத்து.', transliteration: 'Nayansaaraa Nanmaiyin Neekkum Payansaaraap Panpilsol Pallaa Rakaththu', english_meaning: 'The words devoid of profit or pleasure which a man speaks will, being inconsistent with virtue,', career_application: 'The words devoid of profit or pleasure which a man speaks will, being inconsistent with virtue,', chapter: 'Against Vain Speaking' },
  { id: 195, kural_number: 195, tamil_text: 'சீர்மை சிறப்பொடு நீங்கும் பயனில நீர்மை யுடையார் சொலின்.', transliteration: 'Seermai Sirappotu Neengum Payanila Neermai Yutaiyaar Solin', english_meaning: 'If the good speak vain words their eminence and excellence will leave them', career_application: 'If the good speak vain words their eminence and excellence will leave them', chapter: 'Against Vain Speaking' },
  { id: 196, kural_number: 196, tamil_text: 'பயனில்சொல் பாராட்டு வானை மகன்எனல் மக்கட் பதடி யெனல்.', transliteration: 'Payanil Sol Paaraattu Vaanai Makanenal Makkat Padhati Yenal', english_meaning: 'Call not him a man who parades forth his empty words Call him the chaff of men', career_application: 'Call not him a man who parades forth his empty words Call him the chaff of men', chapter: 'Against Vain Speaking' },
  { id: 197, kural_number: 197, tamil_text: 'நயனில சொல்லினுஞ் சொல்லுக சான்றோர் பயனில சொல்லாமை நன்று.', transliteration: 'Nayanila Sollinunj Cholluka Saandror Payanila Sollaamai Nandru', english_meaning: 'Let the wise if they will, speak things without excellence; it will be well for them not to speak useless things', career_application: 'Let the wise if they will, speak things without excellence; it will be well for them not to speak useless things', chapter: 'Against Vain Speaking' },
  { id: 198, kural_number: 198, tamil_text: 'அரும்பயன் ஆயும் அறிவினார் சொல்லார் பெரும்பயன் இல்லாத சொல்.', transliteration: 'Arumpayan Aayum Arivinaar Sollaar Perumpayan Illaadha Sol', english_meaning: 'The wise who seek after rare pleasures will not speak words that have not much weight in them', career_application: 'The wise who seek after rare pleasures will not speak words that have not much weight in them', chapter: 'Against Vain Speaking' },
  { id: 199, kural_number: 199, tamil_text: 'பொருள்தீர்ந்த பொச்சாந்துஞ் சொல்லார் மருள்தீர்ந்த மாசறு காட்சி யவர்.', transliteration: 'Poruldheerndha Pochchaandhunj Chollaar Maruldheerndha Maasaru Kaatchi Yavar', english_meaning: 'Those wise men who are without faults and are freed from ignorance will not even forgetfully speak things that profit not', career_application: 'Those wise men who are without faults and are freed from ignorance will not even forgetfully speak things that profit not', chapter: 'Against Vain Speaking' },
  { id: 200, kural_number: 200, tamil_text: 'சொல்லுக சொல்லிற் பயனுடைய சொல்லற்க சொல்லிற் பயனிலாச் சொல்.', transliteration: 'Solluka Sollir Payanutaiya Sollarka Sollir Payanilaach Chol', english_meaning: 'Speak what is useful, and speak not useless words', career_application: 'Speak what is useful, and speak not useless words', chapter: 'Against Vain Speaking' },
  { id: 201, kural_number: 201, tamil_text: 'தீவினையார் அஞ்சார் விழுமியார் அஞ்சுவர் தீவினை என்னும் செருக்கு.', transliteration: 'Theevinaiyaar Anjaar Vizhumiyaar Anjuvar Theevinai Ennum Serukku', english_meaning: 'Those who have experience of evil deeds will not fear, but the excellent will fear the pride of sin', career_application: 'Those who have experience of evil deeds will not fear, but the excellent will fear the pride of sin', chapter: 'Dread of Evil Deeds' },
  { id: 202, kural_number: 202, tamil_text: 'தீயவை தீய பயத்தலால் தீயவை தீயினும் அஞ்சப் படும்.', transliteration: 'Theeyavai Theeya Payaththalaal Theeyavai Theeyinum Anjap Patum', english_meaning: 'Because evil produces evil, therefore should evil be feared more than fire', career_application: 'Because evil produces evil, therefore should evil be feared more than fire', chapter: 'Dread of Evil Deeds' },
  { id: 203, kural_number: 203, tamil_text: 'அறிவினுள் எல்லாந் தலையென்ப தீய செறுவார்க்கும் செய்யா விடல்.', transliteration: 'Arivinul Ellaan Thalaiyenpa Theeya Seruvaarkkum Seyyaa Vital', english_meaning: 'So shalt thou wisdom\'s highest law, \'tis said, fulfil', career_application: 'So shalt thou wisdom\'s highest law, \'tis said, fulfil', chapter: 'Dread of Evil Deeds' },
  { id: 204, kural_number: 204, tamil_text: 'மறந்தும் பிறன்கேடு சூழற்க சூழின் அறஞ்சூழம் சூழ்ந்தவன் கேடு.', transliteration: 'Marandhum Piranketu Soozharka Soozhin Aranjoozham Soozhndhavan Ketu', english_meaning: 'Even though forgetfulness meditate not the ruin of another Virtue will meditate the ruin of him who thus meditates', career_application: 'Even though forgetfulness meditate not the ruin of another Virtue will meditate the ruin of him who thus meditates', chapter: 'Dread of Evil Deeds' },
  { id: 205, kural_number: 205, tamil_text: 'இலன்என்று தீயவை செய்யற்க செய்யின் இலனாகும் மற்றும் பெயர்த்து.', transliteration: 'Ilan Endru Theeyavai Seyyarka Seyyin Ilanaakum Matrum Peyarththu', english_meaning: 'Commit not evil, saying, "I am poor": if you do, you will become poorer still', career_application: 'Commit not evil, saying, "I am poor": if you do, you will become poorer still', chapter: 'Dread of Evil Deeds' },
  { id: 206, kural_number: 206, tamil_text: 'தீப்பால தான்பிறர்கண் செய்யற்க நோய்ப்பால தன்னை அடல்வேண்டா தான்.', transliteration: 'Theeppaala Thaanpirarkan Seyyarka Noippaala Thannai Atalventaa Thaan', english_meaning: 'Let him not do evil to others who desires not that sorrows should pursue him', career_application: 'Let him not do evil to others who desires not that sorrows should pursue him', chapter: 'Dread of Evil Deeds' },
  { id: 207, kural_number: 207, tamil_text: 'எனைப்பகை யுற்றாரும் உய்வர் வினைப்பகை வீயாது பின்சென்று அடும்.', transliteration: 'Enaippakai Yutraarum Uyvar Vinaippakai Veeyaadhu Pinsendru Atum', english_meaning: 'However great be the enmity men have incurred they may still live The enmity of sin will incessantly pursue and kill', career_application: 'However great be the enmity men have incurred they may still live The enmity of sin will incessantly pursue and kill', chapter: 'Dread of Evil Deeds' },
  { id: 208, kural_number: 208, tamil_text: 'தீயவை செய்தார் கெடுதல் நிழல்தன்னை வீயாது அஇஉறைந் தற்று.', transliteration: 'Theeyavai Seydhaar Ketudhal Nizhaldhannai Veeyaadhu Atiurain Thatru', english_meaning: 'Destruction will dwell at the heels of those who commit evil even as their shadow that leaves them not', career_application: 'Destruction will dwell at the heels of those who commit evil even as their shadow that leaves them not', chapter: 'Dread of Evil Deeds' },
  { id: 209, kural_number: 209, tamil_text: 'தன்னைத்தான் காதல னாயின் எனைத்தொன்றும் துன்னற்க தீவினைப் பால்.', transliteration: 'Thannaiththaan Kaadhala Naayin Enaiththondrum Thunnarka Theevinaip Paal', english_meaning: 'If a man love himself, let him not commit any sin however small', career_application: 'If a man love himself, let him not commit any sin however small', chapter: 'Dread of Evil Deeds' },
  { id: 210, kural_number: 210, tamil_text: 'அருங்கேடன் என்பது அறிக மருங்கோடித் தீவினை செய்யான் எனின்.', transliteration: 'Arungetan Enpadhu Arika Marungotith Theevinai Seyyaan Enin', english_meaning: 'Know ye that he is freed from destruction who commits no evil, going to neither side of the right path', career_application: 'Know ye that he is freed from destruction who commits no evil, going to neither side of the right path', chapter: 'Dread of Evil Deeds' },
  { id: 211, kural_number: 211, tamil_text: 'கைம்மாறு வேண்டா கடப்பாடு மாரிமாட்டு என் ஆற்றுங் கொல்லோ உலகு.', transliteration: 'Kaimmaaru Ventaa Katappaatu Maarimaattu En Aatrung Kollo Ulaku', english_meaning: 'Benevolence seeks not a return. What does the world give back to the clouds ?', career_application: 'Benevolence seeks not a return. What does the world give back to the clouds ?', chapter: 'Duty to Society' },
  { id: 212, kural_number: 212, tamil_text: 'தாளாற்றித் தந்த பொருளெல்லாம் தக்கார்க்கு வேளாண்மை செய்தற் பொருட்டு.', transliteration: 'Thaalaatrith Thandha Porulellaam Thakkaarkku Velaanmai Seydhar Poruttu', english_meaning: 'All the wealth acquired with perseverance by the worthy is for the exercise of benevolence', career_application: 'All the wealth acquired with perseverance by the worthy is for the exercise of benevolence', chapter: 'Duty to Society' },
  { id: 213, kural_number: 213, tamil_text: 'புத்தே ளுலகத்தும் ஈண்டும் பெறலரிதே ஒப்புரவின் நல்ல பிற.', transliteration: 'Puththe Lulakaththum Eentum Peralaridhe Oppuravin Nalla Pira', english_meaning: 'It is difficult to obtain another good equal to benevolence either in this world or in that of the gods', career_application: 'It is difficult to obtain another good equal to benevolence either in this world or in that of the gods', chapter: 'Duty to Society' },
  { id: 214, kural_number: 214, tamil_text: 'ஒத்த தறவோன் உயிர்வாழ்வான் மற்றையான் செத்தாருள் வைக்கப் படும்.', transliteration: 'Oththa Tharavon Uyirvaazhvaan Matraiyaan Seththaarul Vaikkap Patum', english_meaning: 'He truly lives who knows (and discharges) the proper duties (of benevolence) He who knows them not will be reckoned among the dead', career_application: 'He truly lives who knows (and discharges) the proper duties (of benevolence) He who knows them not will be reckoned among the dead', chapter: 'Duty to Society' },
  { id: 215, kural_number: 215, tamil_text: 'ஊருணி நீர்நிறைந் தற்றே உலகவாம் பேரறி வாளன் திரு.', transliteration: 'Ooruni Neernirain Thatre Ulakavaam Perari Vaalan Thiru', english_meaning: 'The wealth of that man of eminent knowledge who desires to exercise the benevolence approved of by the world, is like the full waters of a city-tank', career_application: 'The wealth of that man of eminent knowledge who desires to exercise the benevolence approved of by the world, is like the full waters of a city-tank', chapter: 'Duty to Society' },
  { id: 216, kural_number: 216, tamil_text: 'பயன்மரம் உள்ளூர்ப் பழுத்தற்றால் செல்வம் நயனுடை யான்கண் படின்.', transliteration: 'Payanmaram Ulloorp Pazhuththatraal Selvam Nayanutai Yaankan Patin', english_meaning: 'The wealth of a man (possessed of the virtue) of benevolence is like the ripening of a fruitful tree in the midst of a town', career_application: 'The wealth of a man (possessed of the virtue) of benevolence is like the ripening of a fruitful tree in the midst of a town', chapter: 'Duty to Society' },
  { id: 217, kural_number: 217, tamil_text: 'மருந்தாகித் தப்பா மரத்தற்றால் செல்வம் பெருந்தகை யான்கண் படின்.', transliteration: 'Marundhaakith Thappaa Maraththatraal Selvam Perundhakai Yaankan Patin', english_meaning: 'If wealth be in the possession of a man who has the great excellence (of benevolence), it is like a tree which as a medicine is an infallible cure for disease', career_application: 'If wealth be in the possession of a man who has the great excellence (of benevolence), it is like a tree which as a medicine is an infallible cure for disease', chapter: 'Duty to Society' },
  { id: 218, kural_number: 218, tamil_text: 'இடனில் பருவத்தும் ஒப்புரவிற்கு ஒல்கார் கடனறி காட்சி யவர்.', transliteration: 'Itanil Paruvaththum Oppuravirku Olkaar Katanari Kaatchi Yavar', english_meaning: 'The wise who know what is duty will not scant their benevolence even when they are without wealth', career_application: 'The wise who know what is duty will not scant their benevolence even when they are without wealth', chapter: 'Duty to Society' },
  { id: 219, kural_number: 219, tamil_text: 'நயனுடையான் நல்கூர்ந்தா னாதல் செயும்நீர செய்யாது அமைகலா வாறு.', transliteration: 'Nayanutaiyaan Nalkoorndhaa Naadhal Seyumneera Seyyaadhu Amaikalaa Vaaru', english_meaning: 'The poverty of a benevolent man, is nothing but his inability to exercise the same', career_application: 'The poverty of a benevolent man, is nothing but his inability to exercise the same', chapter: 'Duty to Society' },
  { id: 220, kural_number: 220, tamil_text: 'ஒப்புரவி னால்வரும் கேடெனின் அஃதொருவன் விற்றுக்கோள் தக்க துடைத்து.', transliteration: 'Oppuravi Naalvarum Ketenin Aqdhoruvan Vitrukkol Thakka Thutaiththu', english_meaning: 'If it be said that loss will result from benevolence, such loss is worth being procured even by the sale of one\'s self', career_application: 'If it be said that loss will result from benevolence, such loss is worth being procured even by the sale of one\'s self', chapter: 'Duty to Society' },
  { id: 221, kural_number: 221, tamil_text: 'வறியார்க்கொன்று ஈவதே ஈகைமற் றெல்லாம் குறியெதிர்ப்பை நீர துடைத்து.', transliteration: 'Variyaarkkondru Eevadhe Eekaimar Rellaam Kuriyedhirppai Neera Thutaiththu', english_meaning: 'To give to the destitute is true charity All other gifts have the nature of (what is done for) a measured return', career_application: 'To give to the destitute is true charity All other gifts have the nature of (what is done for) a measured return', chapter: 'Giving' },
  { id: 222, kural_number: 222, tamil_text: 'நல்லாறு எனினும் கொளல்தீது மேலுலகம் இல்லெனினும் ஈதலே நன்று.', transliteration: 'Nallaaru Eninum Kolaldheedhu Melulakam Illeninum Eedhale Nandru', english_meaning: 'To beg is evil, even though it were said that it is a good path (to heaven) To give is good, even though it were said that those who do so cannot obtain heaven', career_application: 'To beg is evil, even though it were said that it is a good path (to heaven) To give is good, even though it were said that those who do so cannot obtain heaven', chapter: 'Giving' },
  { id: 223, kural_number: 223, tamil_text: 'இலனென்னும் எவ்வம் உரையாமை ஈதல் குலனுடையான் கண்ணே யுள.', transliteration: 'Ilanennum Evvam Uraiyaamai Eedhal Kulanutaiyaan Kanne Yula', english_meaning: '(Even in a low state) not to adopt the mean expedient of saying "I have nothing," but to give, is the characteristic of the mad of noble birth', career_application: '(Even in a low state) not to adopt the mean expedient of saying "I have nothing," but to give, is the characteristic of the mad of noble birth', chapter: 'Giving' },
  { id: 224, kural_number: 224, tamil_text: 'இன்னாது இரக்கப் படுதல் இரந்தவர் இன்முகங் காணும் அளவு.', transliteration: 'Innaadhu Irakkap Patudhal Irandhavar Inmukang Kaanum Alavu', english_meaning: 'To see men begging from us in disagreeable, until we see their pleasant countenance', career_application: 'To see men begging from us in disagreeable, until we see their pleasant countenance', chapter: 'Giving' },
  { id: 225, kural_number: 225, tamil_text: 'ஆற்றுவார் ஆற்றல் பசிஆற்றல் அப்பசியை மாற்றுவார் ஆற்றலின் பின்.', transliteration: 'Aatruvaar Aatral Pasiaatral Appasiyai Maatruvaar Aatralin Pin', english_meaning: 'The power of those who perform penance is the power of enduring hunger It is inferior to the power of those who remove the hunger (of others)', career_application: 'The power of those who perform penance is the power of enduring hunger It is inferior to the power of those who remove the hunger (of others)', chapter: 'Giving' },
  { id: 226, kural_number: 226, tamil_text: 'அற்றார் அழிபசி தீர்த்தல் அஃதொருவன் பெற்றான் பொருள்வைப் புழி.', transliteration: 'Atraar Azhipasi Theerththal Aqdhoruvan Petraan Porulvaip Puzhi', english_meaning: 'The removal of the killing hunger of the poor is the place for one to lay up his wealth', career_application: 'The removal of the killing hunger of the poor is the place for one to lay up his wealth', chapter: 'Giving' },
  { id: 227, kural_number: 227, tamil_text: 'பாத்தூண் மரீஇ யவனைப் பசியென்னும் தீப்பிணி தீண்டல் அரிது.', transliteration: 'Paaththoon Mareei Yavanaip Pasiyennum Theeppini Theental Aridhu', english_meaning: 'The fiery disease of hunger shall never touch him who habitually distributes his food to others', career_application: 'The fiery disease of hunger shall never touch him who habitually distributes his food to others', chapter: 'Giving' },
  { id: 228, kural_number: 228, tamil_text: 'ஈத்துவக்கும் இன்பம் அறியார்கொல் தாமுடைமை வைத்திழக்கும் வன்க ணவர்.', transliteration: 'Eeththuvakkum Inpam Ariyaarkol Thaamutaimai Vaiththizhakkum Vanka Navar', english_meaning: 'Do the hard-eyed who lay up and lose their possessions not know the happiness which springs from the pleasure of giving ?', career_application: 'Do the hard-eyed who lay up and lose their possessions not know the happiness which springs from the pleasure of giving ?', chapter: 'Giving' },
  { id: 229, kural_number: 229, tamil_text: 'இரத்தலின் இன்னாது மன்ற நிரப்பிய தாமே தமியர் உணல்.', transliteration: 'Iraththalin Innaadhu Mandra Nirappiya Thaame Thamiyar Unal', english_meaning: 'Solitary and unshared eating for the sake of filling up one\'s own riches is certainly much more', career_application: 'Solitary and unshared eating for the sake of filling up one\'s own riches is certainly much more', chapter: 'Giving' },
  { id: 230, kural_number: 230, tamil_text: 'சாதலின் இன்னாத தில்லை இனிததூஉம் ஈதல் இயையாக் கடை.', transliteration: 'Saadhalin Innaadha Thillai Inidhadhooum Eedhal Iyaiyaak Katai', english_meaning: 'Nothing is more unpleasant than death: yet even that is pleasant where charity cannot be exercised', career_application: 'Nothing is more unpleasant than death: yet even that is pleasant where charity cannot be exercised', chapter: 'Giving' },
  { id: 231, kural_number: 231, tamil_text: 'ஈதல் இசைபட வாழ்தல் அதுவல்லது ஊதியம் இல்லை உயிர்க்கு.', transliteration: 'Eedhal Isaipata Vaazhdhal Adhuvalladhu Oodhiyam Illai Uyirkku', english_meaning: 'Give to the poor and live with praise There is no greater profit to man than that', career_application: 'Give to the poor and live with praise There is no greater profit to man than that', chapter: 'Renown' },
  { id: 232, kural_number: 232, tamil_text: 'உரைப்பார் உரைப்பவை எல்லாம் இரப்பார்க்கொன்று ஈவார்மேல் நிற்கும் புகழ்.', transliteration: 'Uraippaar Uraippavai Ellaam Irappaarkkondru Eevaarmel Nirkum Pukazh', english_meaning: 'Whatsoever is spoken in the world will abide as praise upon that man who gives alms to the poor', career_application: 'Whatsoever is spoken in the world will abide as praise upon that man who gives alms to the poor', chapter: 'Renown' },
  { id: 233, kural_number: 233, tamil_text: 'ஒன்றா உலகத்து உயர்ந்த புகழல்லால் பொன்றாது நிற்பதொன் றில்.', transliteration: 'Ondraa Ulakaththu Uyarndha Pukazhallaal Pondraadhu Nirpadhon Ril', english_meaning: 'There is nothing that stands forth in the world imperishable, except fame, exalted in solitary greatness', career_application: 'There is nothing that stands forth in the world imperishable, except fame, exalted in solitary greatness', chapter: 'Renown' },
  { id: 234, kural_number: 234, tamil_text: 'நிலவரை நீள்புகழ் ஆற்றின் புலவரைப் போற்றாது புத்தேள் உலகு.', transliteration: 'Nilavarai Neelpukazh Aatrin Pulavaraip Potraadhu Puththel Ulaku', english_meaning: 'If one has acquired extensive fame within the limits of this earth, the world of the Gods will no longer praise those sages who have attained that world', career_application: 'If one has acquired extensive fame within the limits of this earth, the world of the Gods will no longer praise those sages who have attained that world', chapter: 'Renown' },
  { id: 235, kural_number: 235, tamil_text: 'நத்தம்போல் கேடும் உளதாகும் சாக்காடும் வித்தகர்க் கல்லால் அரிது.', transliteration: 'Naththampol Ketum Uladhaakum Saakkaatum Viththakark Kallaal Aridhu', english_meaning: 'Prosperity to the body of fame, resulting in poverty to the body of flesh and the stability to the former arising from the death of the latter, are achievable only by the wise', career_application: 'Prosperity to the body of fame, resulting in poverty to the body of flesh and the stability to the former arising from the death of the latter, are achievable only by the wise', chapter: 'Renown' },
  { id: 236, kural_number: 236, tamil_text: 'தோன்றின் புகழொடு தோன்றுக அஃதிலார் தோன்றலின் தோன்றாமை நன்று.', transliteration: 'Thondrin Pukazhotu Thondruka Aqdhilaar Thondralin Thondraamai Nandru', english_meaning: 'If you are born (in this world), be born with qualities conductive to fame From those who are destitute of them it will be better not to be born', career_application: 'If you are born (in this world), be born with qualities conductive to fame From those who are destitute of them it will be better not to be born', chapter: 'Renown' },
  { id: 237, kural_number: 237, tamil_text: 'புகழ்பட வாழாதார் தந்நோவார் தம்மை இகழ்வாரை நோவது எவன்?', transliteration: 'Pukazhpata Vaazhaadhaar Thannovaar Thammai Ikazhvaarai Novadhu Evan?', english_meaning: 'Why do those who cannot live with praise, grieve those who despise them, instead of grieving themselves for their own inability', career_application: 'Why do those who cannot live with praise, grieve those who despise them, instead of grieving themselves for their own inability', chapter: 'Renown' },
  { id: 238, kural_number: 238, tamil_text: 'வசையென்ப வையத்தார்க் கெல்லாம் இசையென்னும் எச்சம் பெறாஅ விடின்.', transliteration: 'Vasaiyenpa Vaiyaththaark Kellaam Isaiyennum Echcham Peraaa Vitin', english_meaning: 'Not to beget fame will be esteemed a disgrace by the wise in this world', career_application: 'Not to beget fame will be esteemed a disgrace by the wise in this world', chapter: 'Renown' },
  { id: 239, kural_number: 239, tamil_text: 'வசையிலா வண்பயன் குன்றும் இசையிலா யாக்கை பொறுத்த நிலம்.', transliteration: 'Vasaiyilaa Vanpayan Kundrum Isaiyilaa Yaakkai Poruththa Nilam', english_meaning: 'The ground which supports a body without fame will diminish in its rich produce', career_application: 'The ground which supports a body without fame will diminish in its rich produce', chapter: 'Renown' },
  { id: 240, kural_number: 240, tamil_text: 'வசையொழிய வாழ்வாரே வாழ்வார் இசையொழிய வாழ்வாரே வாழா தவர்.', transliteration: 'Vasaiyozhiya Vaazhvaare Vaazhvaar Isaiyozhiya Vaazhvaare Vaazhaa Thavar', english_meaning: 'Those live who live without disgrace Those who live without fame live not', career_application: 'Those live who live without disgrace Those who live without fame live not', chapter: 'Renown' },
  { id: 241, kural_number: 241, tamil_text: 'அருட்செல்வம் செல்வத்துள் செல்வம் பொருட்செல்வம் பூரியார் கண்ணும் உள.', transliteration: 'Arutchelvam Selvaththul Selvam Porutchelvam Pooriyaar Kannum Ula', english_meaning: 'The wealth of kindness is wealth of wealth, in as much as the wealth of property is possessed by the basest of men', career_application: 'The wealth of kindness is wealth of wealth, in as much as the wealth of property is possessed by the basest of men', chapter: 'Compassion' },
  { id: 242, kural_number: 242, tamil_text: 'நல்லாற்றாள் நாடி அருளாள்க பல்லாற்றால் தேரினும் அஃதே துணை.', transliteration: 'Nallaatraal Naati Arulaalka Pallaatraal Therinum Aqdhe Thunai', english_meaning: '(Stand) in the good path, consider, and be kind. Even considering according to the conflicting tenets of the different sects, kindness will be your best aid, (in the acquisition of heavenly bliss.)', career_application: '(Stand) in the good path, consider, and be kind. Even considering according to the conflicting tenets of the different sects, kindness will be your best aid, (in the acquisition of heavenly bliss.)', chapter: 'Compassion' },
  { id: 243, kural_number: 243, tamil_text: 'அருள்சேர்ந்த நெஞ்சினார்க் கில்லை இருள்சேர்ந்த இன்னா உலகம் புகல்.', transliteration: 'Arulserndha Nenjinaark Killai Irulserndha Innaa Ulakam Pukal', english_meaning: 'They will never enter the world of darkness and wretchedness whose minds are the abode of kindness', career_application: 'They will never enter the world of darkness and wretchedness whose minds are the abode of kindness', chapter: 'Compassion' },
  { id: 244, kural_number: 244, tamil_text: 'மன்னுயிர் ஓம்பி அருளாள்வார்க்கு இல்லென்ப தன்னுயிர் அஞ்சும் வினை.', transliteration: 'Mannuyir Ompi Arulaalvaarkku Illenpa Thannuyir Anjum Vinai', english_meaning: '(The wise) say that the evils, which his soul would dread, will never come upon the man who exercises kindness and protects the life (of other creatures)', career_application: '(The wise) say that the evils, which his soul would dread, will never come upon the man who exercises kindness and protects the life (of other creatures)', chapter: 'Compassion' },
  { id: 245, kural_number: 245, tamil_text: 'அல்லல் அருளாள்வார்க்கு இல்லை வளிவழங்கும் மல்லன்மா ஞாலங் கரி.', transliteration: 'Allal Arulaalvaarkku Illai Valivazhangum Mallanmaa Gnaalang Kari', english_meaning: 'This great rich earth over which the wind blows, is a witness that sorrow never comes upon the kindhearted', career_application: 'This great rich earth over which the wind blows, is a witness that sorrow never comes upon the kindhearted', chapter: 'Compassion' },
  { id: 246, kural_number: 246, tamil_text: 'பொருள்நீங்கிப் பொச்சாந்தார் என்பர் அருள்நீங்கி அல்லவை செய்தொழுகு வார்.', transliteration: 'Porulneengip Pochchaandhaar Enpar Arulneengi Allavai Seydhozhuku Vaar', english_meaning: '(The wise) say that those who neglect kindness and practise cruelties, neglected virtue (in their former birth), and forgot (the sorrows which they must suffer.)', career_application: '(The wise) say that those who neglect kindness and practise cruelties, neglected virtue (in their former birth), and forgot (the sorrows which they must suffer.)', chapter: 'Compassion' },
  { id: 247, kural_number: 247, tamil_text: 'அருளில்லார்க்கு அவ்வுலகம் இல்லை பொருளில்லார்க்கு இவ்வுலகம் இல்லாகி யாங்கு.', transliteration: 'Arulillaarkku Avvulakam Illai Porulillaarkku Ivvulakam Illaaki Yaangu', english_meaning: 'As this world is not for those who are without wealth, so that world is not for those who are without kindness', career_application: 'As this world is not for those who are without wealth, so that world is not for those who are without kindness', chapter: 'Compassion' },
  { id: 248, kural_number: 248, tamil_text: 'பொருளற்றார் பூப்பர் ஒருகால் அருளற்றார் அற்றார்மற் றாதல் அரிது.', transliteration: 'Porulatraar Pooppar Orukaal Arulatraar Atraarmar Raadhal Aridhu', english_meaning: 'Those who are without wealth may, at some future time, become prosperous; those who are destitute of kindness are utterly destitute; for them there is no change', career_application: 'Those who are without wealth may, at some future time, become prosperous; those who are destitute of kindness are utterly destitute; for them there is no change', chapter: 'Compassion' },
  { id: 249, kural_number: 249, tamil_text: 'தெருளாதான் மெய்ப்பொருள் கண்டற்றால் தேரின் அருளாதான் செய்யும் அறம்.', transliteration: 'Therulaadhaan Meypporul Kantatraal Therin Arulaadhaan Seyyum Aram', english_meaning: 'If you consider, the virtue of him who is without kindness is like the perception of the true being by him who is without wisdom', career_application: 'If you consider, the virtue of him who is without kindness is like the perception of the true being by him who is without wisdom', chapter: 'Compassion' },
  { id: 250, kural_number: 250, tamil_text: 'வலியார்முன் தன்னை நினைக்கதான் தன்னின் மெலியார்மேல் செல்லு மிடத்து.', transliteration: 'Valiyaarmun Thannai Ninaikka Thaan Thannin Meliyaarmel Sellu Mitaththu', english_meaning: 'When a man is about to rush upon those who are weaker than himself, let him remember how he has stood (trembling) before those who are stronger than himself', career_application: 'When a man is about to rush upon those who are weaker than himself, let him remember how he has stood (trembling) before those who are stronger than himself', chapter: 'Compassion' },
  { id: 251, kural_number: 251, tamil_text: 'தன்னூன் பெருக்கற்குத் தான்பிறிது ஊனுண்பான் எங்ஙனம் ஆளும் அருள்?', transliteration: 'Thannoon Perukkarkuth Thaanpiridhu Oonunpaan Engnganam Aalum Arul?', english_meaning: 'How can he be possessed of kindness, who to increase his own flesh, eats the flesh of other creatures', career_application: 'How can he be possessed of kindness, who to increase his own flesh, eats the flesh of other creatures', chapter: 'Abstinence from Flesh' },
  { id: 252, kural_number: 252, tamil_text: 'பொருளாட்சி போற்றாதார்க்கு இல்லை அருளாட்சி ஆங்கில்லை ஊன்தின் பவர்க்கு.', transliteration: 'Porulaatchi Potraadhaarkku Illai Arulaatchi Aangillai Oondhin Pavarkku', english_meaning: 'As those possess no property who do not take care of it, so those possess no kindness who feed on flesh', career_application: 'As those possess no property who do not take care of it, so those possess no kindness who feed on flesh', chapter: 'Abstinence from Flesh' },
  { id: 253, kural_number: 253, tamil_text: 'படைகொண்டார் நெஞ்சம்போல் நன்னூக்காது ஒன்றன் உடல்சுவை உண்டார் மனம்.', transliteration: 'Pataikontaar Nenjampol Nannookkaadhu Ondran Utalsuvai Untaar Manam', english_meaning: 'Like the (murderous) mind of him who carries a weapon (in his hand), the mind of him who feasts with pleasure on the body of another (creature), has no regard for goodness', career_application: 'Like the (murderous) mind of him who carries a weapon (in his hand), the mind of him who feasts with pleasure on the body of another (creature), has no regard for goodness', chapter: 'Abstinence from Flesh' },
  { id: 254, kural_number: 254, tamil_text: 'அருளல்ல தியாதெனிற் கொல்லாமை கோறல் பொருளல்லது அவ்வூன் தினல்.', transliteration: 'Arulalladhu Yaadhenin Kollaamai Koral Porulalladhu Avvoon Thinal', english_meaning: 'If it be asked what is kindness and what its opposite, the answer would be preservation and destruction of life; and therefore it is not right to feed on the flesh (obtained by taking away life)', career_application: 'If it be asked what is kindness and what its opposite, the answer would be preservation and destruction of life; and therefore it is not right to feed on the flesh (obtained by taking away life)', chapter: 'Abstinence from Flesh' },
  { id: 255, kural_number: 255, tamil_text: 'உண்ணாமை உள்ளது உயிர்நிலை ஊனுண்ண அண்ணாத்தல் செய்யாது அளறு.', transliteration: 'Unnaamai Ulladhu Uyirnilai Oonunna Annaaththal Seyyaadhu Alaru', english_meaning: 'Not to eat flesh contributes to the continuance of life; therefore if a man eat flesh, hell will not open its mouth (to let him escape out, after he has once fallen in)', career_application: 'Not to eat flesh contributes to the continuance of life; therefore if a man eat flesh, hell will not open its mouth (to let him escape out, after he has once fallen in)', chapter: 'Abstinence from Flesh' },
  { id: 256, kural_number: 256, tamil_text: 'தினற்பொருட்டால் கொல்லாது உலகெனின் யாரும் விலைப்பொருட்டால் ஊன்றருவா ரில்.', transliteration: 'Thinarporuttaal Kollaadhu Ulakenin Yaarum Vilaipporuttaal Oondraruvaa Ril', english_meaning: 'If the world does not destroy life for the purpose of eating, then no one would sell flesh for the sake of money', career_application: 'If the world does not destroy life for the purpose of eating, then no one would sell flesh for the sake of money', chapter: 'Abstinence from Flesh' },
  { id: 257, kural_number: 257, tamil_text: 'உண்ணாமை வேண்டும் புலாஅல் பிறிதொன்றன் புண்ணது உணர்வார்ப் பெறின்.', transliteration: 'Unnaamai Ventum Pulaaal Piridhondran Punnadhu Unarvaarp Perin', english_meaning: 'If men should come to know that flesh is nothing but the unclean ulcer of a body, let them abstain from eating it', career_application: 'If men should come to know that flesh is nothing but the unclean ulcer of a body, let them abstain from eating it', chapter: 'Abstinence from Flesh' },
  { id: 258, kural_number: 258, tamil_text: 'செயிரின் தலைப்பிரிந்த காட்சியார் உண்ணார் உயிரின் தலைப்பிரிந்த ஊன்.', transliteration: 'Seyirin Thalaippirindha Kaatchiyaar Unnaar Uyirin Thalaippirindha Oon', english_meaning: 'The wise, who have freed themselves from mental delusion, will not eat the flesh which has been severed from an animal', career_application: 'The wise, who have freed themselves from mental delusion, will not eat the flesh which has been severed from an animal', chapter: 'Abstinence from Flesh' },
  { id: 259, kural_number: 259, tamil_text: 'அவிசொரிந் தாயிரம் வேட்டலின் ஒன்றன் உயிர்செகுத் துண்ணாமை நன்று.', transliteration: 'Avisorin Thaayiram Vettalin Ondran Uyirsekuth Thunnaamai Nandru', english_meaning: 'Not to kill and eat (the flesh of) an animal, is better than the pouring forth of ghee etc, in a thousand sacrifices', career_application: 'Not to kill and eat (the flesh of) an animal, is better than the pouring forth of ghee etc, in a thousand sacrifices', chapter: 'Abstinence from Flesh' },
  { id: 260, kural_number: 260, tamil_text: 'கொல்லான் புலாலை மறுத்தானைக் கைகூப்பி எல்லா உயிருந் தொழும்.', transliteration: 'Kollaan Pulaalai Maruththaanaik Kaikooppi Ellaa Uyirun Thozhum', english_meaning: 'All creatures will join their hands together, and worship him who has never taken away life, nor eaten flesh', career_application: 'All creatures will join their hands together, and worship him who has never taken away life, nor eaten flesh', chapter: 'Abstinence from Flesh' },
  { id: 261, kural_number: 261, tamil_text: 'உற்றநோய் நோன்றல் உயிர்க்குறுகண் செய்யாமை அற்றே தவத்திற் குரு.', transliteration: 'Utranoi Nondral Uyirkkurukan Seyyaamai Atre Thavaththir Kuru', english_meaning: 'The nature of religious discipline consists, in the endurance (by the ascetic) of the sufferings which it brings on himself, and in abstaining from giving pain to others', career_application: 'The nature of religious discipline consists, in the endurance (by the ascetic) of the sufferings which it brings on himself, and in abstaining from giving pain to others', chapter: 'Penance' },
  { id: 262, kural_number: 262, tamil_text: 'தவமும் தவமுடையார்க்கு ஆகும் அதனை அஃதிலார் மேற்கொள் வது.', transliteration: 'Thavamum Thavamutaiyaarkku Aakum Adhanai Aqdhilaar Merkol Vadhu', english_meaning: 'Austerities can only be borne, and their benefits enjoyed, by those who have practised them (in a former birth); it will be useless for those who have not done so, to attempt to practise them (now)', career_application: 'Austerities can only be borne, and their benefits enjoyed, by those who have practised them (in a former birth); it will be useless for those who have not done so, to attempt to practise them (now)', chapter: 'Penance' },
  { id: 263, kural_number: 263, tamil_text: 'துறந்தார்க்குத் துப்புரவு வேண்டி மறந்தார்கொல் மற்றை யவர்கள் தவம்.', transliteration: 'Thurandhaarkkuth Thuppuravu Venti Marandhaarkol Matrai Yavarkal Thavam', english_meaning: 'It is to provide food etc, for the ascetics who have abandoned (the desire of earthly possessions) that other persons have forgotten (to practise) austerity ?', career_application: 'It is to provide food etc, for the ascetics who have abandoned (the desire of earthly possessions) that other persons have forgotten (to practise) austerity ?', chapter: 'Penance' },
  { id: 264, kural_number: 264, tamil_text: 'ஒன்னார்த் தெறலும் உவந்தாரை ஆக்கலும் எண்ணின் தவத்தான் வரும்.', transliteration: 'Onnaarth Theralum Uvandhaarai Aakkalum Ennin Thavaththaan Varum', english_meaning: 'If (the ascetic) desire the destruction of his enemies, or the aggrandizement of his friends, it will be effected by (the power of) his austerities', career_application: 'If (the ascetic) desire the destruction of his enemies, or the aggrandizement of his friends, it will be effected by (the power of) his austerities', chapter: 'Penance' },
  { id: 265, kural_number: 265, tamil_text: 'வேண்டிய வேண்டியாங் கெய்தலால் செய்தவம் ஈண்டு முயலப் படும்.', transliteration: 'Ventiya Ventiyaang Keydhalaal Seydhavam Eentu Muyalap Patum', english_meaning: 'Religious dislipline is practised in this world, because it secures the attainment of whatever one may wish to enjoy (in the world to come)', career_application: 'Religious dislipline is practised in this world, because it secures the attainment of whatever one may wish to enjoy (in the world to come)', chapter: 'Penance' },
  { id: 266, kural_number: 266, tamil_text: 'தவஞ்செய்வார் தங்கருமஞ் செய்வார்மற் றல்லார் அவஞ்செய்வார் ஆசையுட் பட்டு.', transliteration: 'Thavanj Cheyvaar Thangarumanj Cheyvaarmar Rallaar Avanjeyvaar Aasaiyut Pattu', english_meaning: 'Those discharge their duty who perform austerities; all others accomplish their own destruction, through the entanglement of the desire (of riches and sensual pleasure)', career_application: 'Those discharge their duty who perform austerities; all others accomplish their own destruction, through the entanglement of the desire (of riches and sensual pleasure)', chapter: 'Penance' },
  { id: 267, kural_number: 267, tamil_text: 'சுடச்சுடரும் பொன்போல் ஒளிவிடும் துன்பஞ் சுடச்சுட நோற்கிற் பவர்க்கு.', transliteration: 'Sutachchutarum Ponpol Olivitum Thunpanjjch Utachchuta Norkir Pavarkku', english_meaning: 'Just as gold is purified as heated in the fire, will those shine, who have endured the burning of pain (in frequent austerities)', career_application: 'Just as gold is purified as heated in the fire, will those shine, who have endured the burning of pain (in frequent austerities)', chapter: 'Penance' },
  { id: 268, kural_number: 268, tamil_text: 'தன்னுயிர் தான்அறப் பெற்றானை ஏனைய மன்னுயி ரெல்லாந் தொழும்.', transliteration: 'Thannuyir Thaanarap Petraanai Enaiya Mannuyi Rellaan Thozhum', english_meaning: 'All other creatures will worship him who has attained the control of his own soul', career_application: 'All other creatures will worship him who has attained the control of his own soul', chapter: 'Penance' },
  { id: 269, kural_number: 269, tamil_text: 'கூற்றம் குதித்தலும் கைகூடும் நோற்றலின் ஆற்றல் தலைப்பட் டவர்க்குல்.', transliteration: 'Kootram Kudhiththalum Kaikootum Notralin Aatral Thalaippat Tavarkkul', english_meaning: 'Those who have attained the power which religious discipline confers, will be able also to pass the limit of Yama, (the God of death)', career_application: 'Those who have attained the power which religious discipline confers, will be able also to pass the limit of Yama, (the God of death)', chapter: 'Penance' },
  { id: 270, kural_number: 270, tamil_text: 'இலர்பல ராகிய காரணம் நோற்பார் சிலர்பலர் நோலா தவர்.', transliteration: 'Ilarpala Raakiya Kaaranam Norpaar Silarpalar Nolaa Thavar', english_meaning: 'Because there are few who practise austerity and many who do not, there are many destitute and few rich in this world', career_application: 'Because there are few who practise austerity and many who do not, there are many destitute and few rich in this world', chapter: 'Penance' },
  { id: 271, kural_number: 271, tamil_text: 'வஞ்ச மனத்தான் படிற்றொழுக்கம் பூதங்கள் ஐந்தும் அகத்தே நகும்.', transliteration: 'Vanja Manaththaan Patitrozhukkam Poodhangal Aindhum Akaththe Nakum', english_meaning: 'The five elements (of his body) will laugh within him at the feigned conduct of the deceitful minded man', career_application: 'The five elements (of his body) will laugh within him at the feigned conduct of the deceitful minded man', chapter: 'Imposture' },
  { id: 272, kural_number: 272, tamil_text: 'வானுயர் தோற்றம் எவன்செய்யும் தன்னெஞ்சம் தான்அறி குற்றப் படின்.', transliteration: 'Vaanuyar Thotram Evanseyyum Thannenjam Thaanari Kutrap Patin', english_meaning: 'What avails an appearance (of sanctity) high as heaven, if his mind suffers (the indulgence) of conscious sin', career_application: 'What avails an appearance (of sanctity) high as heaven, if his mind suffers (the indulgence) of conscious sin', chapter: 'Imposture' },
  { id: 273, kural_number: 273, tamil_text: 'வலியில் நிலைமையான் வல்லுருவம் பெற்றம் புலியின்தோல் போர்த்துமேய்ந் தற்று.', transliteration: 'Valiyil Nilaimaiyaan Valluruvam Petram Puliyindhol Porththumeyn Thatru', english_meaning: 'The assumed appearance of power, by a man who has no power (to restrain his senses and perform austerity), is like a cow feeding on grass covered with a tiger\'s skin', career_application: 'The assumed appearance of power, by a man who has no power (to restrain his senses and perform austerity), is like a cow feeding on grass covered with a tiger\'s skin', chapter: 'Imposture' },
  { id: 274, kural_number: 274, tamil_text: 'தவமறைந்து அல்லவை செய்தல் புதல்மறைந்து வேட்டுவன் புள்சிமிழ்த் தற்று.', transliteration: 'Thavamaraindhu Allavai Seydhal Pudhalmaraindhu Vettuvan Pulsimizhth Thatru', english_meaning: 'He who hides himself under the mask of an ascetic and commits sins, like a sportsman who conceals himself in the thicket to catch birds', career_application: 'He who hides himself under the mask of an ascetic and commits sins, like a sportsman who conceals himself in the thicket to catch birds', chapter: 'Imposture' },
  { id: 275, kural_number: 275, tamil_text: 'பற்றற்றேம் என்பார் படிற்றொழுக்கம் எற்றெற்றென்று ஏதம் பலவுந் தரும்.', transliteration: 'Patratrem Enpaar Patitrozhukkam Etretrendru Edham Palavun Tharum', english_meaning: 'The false conduct of those who say they have renounced all desire will one day bring them sorrows that will make them cry out, "Oh! what have we done, what have we done."', career_application: 'The false conduct of those who say they have renounced all desire will one day bring them sorrows that will make them cry out, "Oh! what have we done, what have we done."', chapter: 'Imposture' },
  { id: 276, kural_number: 276, tamil_text: 'நெஞ்சின் துறவார் துறந்தார்போல் வஞ்சித்து வாழ்வாரின் வன்கணார் இல்.', transliteration: 'Nenjin Thuravaar Thurandhaarpol Vanjiththu Vaazhvaarin Vankanaar Il', english_meaning: 'Amongst living men there are none so hard-hearted as those who without to saking (desire) in their heart, falsely take the appearance of those who have forsaken (it)', career_application: 'Amongst living men there are none so hard-hearted as those who without to saking (desire) in their heart, falsely take the appearance of those who have forsaken (it)', chapter: 'Imposture' },
  { id: 277, kural_number: 277, tamil_text: 'புறங்குன்றி கண்டனைய ரேனும் அகங்குன்றி முக்கிற் கரியார் உடைத்து.', transliteration: 'Purangundri Kantanaiya Renum Akangundri Mukkir Kariyaar Utaiththu', english_meaning: '(The world) contains persons whose outside appears (as fair) as the (red) berry of the Abrus, but whose inside is as black as the nose of that berry', career_application: '(The world) contains persons whose outside appears (as fair) as the (red) berry of the Abrus, but whose inside is as black as the nose of that berry', chapter: 'Imposture' },
  { id: 278, kural_number: 278, tamil_text: 'மனத்தது மாசாக மாண்டார் நீராடி மறைந்தொழுகு மாந்தர் பலர்.', transliteration: 'Manaththadhu Maasaaka Maantaar Neeraati Maraindhozhuku Maandhar Palar', english_meaning: 'There are many men of masked conduct, who perform their ablutions, and (make a show) of', career_application: 'There are many men of masked conduct, who perform their ablutions, and (make a show) of', chapter: 'Imposture' },
  { id: 279, kural_number: 279, tamil_text: 'கணைகொடிது யாழ்கோடு செவ்விதுஆங் கன்ன வினைபடு பாலால் கொளல்.', transliteration: 'Kanaikotidhu Yaazhkotu Sevvidhuaang Kanna Vinaipatu Paalaal Kolal', english_meaning: 'As, in its use, the arrow is crooked, and the curved lute is straight, so by their deeds, (and not by their appearance) let (the uprightness or crookedness of) men be estimated', career_application: 'As, in its use, the arrow is crooked, and the curved lute is straight, so by their deeds, (and not by their appearance) let (the uprightness or crookedness of) men be estimated', chapter: 'Imposture' },
  { id: 280, kural_number: 280, tamil_text: 'மழித்தலும் நீட்டலும் வேண்டா உலகம் பழித்தது ஒழித்து விடின்.', transliteration: 'Mazhiththalum Neettalum Ventaa Ulakam Pazhiththadhu Ozhiththu Vitin', english_meaning: 'There is no need of a shaven crown, nor of tangled hair, if a man abstain from those deeds which the wise have condemned', career_application: 'There is no need of a shaven crown, nor of tangled hair, if a man abstain from those deeds which the wise have condemned', chapter: 'Imposture' },
  { id: 281, kural_number: 281, tamil_text: 'எள்ளாமை வேண்டுவான் என்பான் எனைத்தொன்றும் கள்ளாமை காக்கதன் நெஞ்சு.', transliteration: 'Ellaamai Ventuvaan Enpaan Enaiththondrum Kallaamai Kaakkadhan Nenju', english_meaning: 'Let him, who desires not to be despised, keep his mind from (the desire of) defrauding another of the smallest thing', career_application: 'Let him, who desires not to be despised, keep his mind from (the desire of) defrauding another of the smallest thing', chapter: 'The Absence of Fraud' },
  { id: 282, kural_number: 282, tamil_text: 'உள்ளத்தால் உள்ளலும் தீதே பிறன்பொருளைக் கள்ளத்தால் கள்வேம் எனல்.', transliteration: 'Ullaththaal Ullalum Theedhe Piranporulaik Kallaththaal Kalvem Enal', english_meaning: 'Even the thought (of sin) is sin; think not then of crafiily stealing the property of another', career_application: 'Even the thought (of sin) is sin; think not then of crafiily stealing the property of another', chapter: 'The Absence of Fraud' },
  { id: 283, kural_number: 283, tamil_text: 'களவினால் ஆகிய ஆக்கம் அளவிறந்து ஆவது போலக் கெடும்.', transliteration: 'Kalavinaal Aakiya Aakkam Alavirandhu Aavadhu Polak Ketum', english_meaning: 'The property, which is acquired by fraud, will entirely perish, even while it seems to increase', career_application: 'The property, which is acquired by fraud, will entirely perish, even while it seems to increase', chapter: 'The Absence of Fraud' },
  { id: 284, kural_number: 284, tamil_text: 'களவின்கண் கன்றிய காதல் விளைவின்கண் வீயா விழுமம் தரும்.', transliteration: 'Kalavinkan Kandriya Kaadhal Vilaivinkan Veeyaa Vizhumam Tharum', english_meaning: 'The eager desire of defrauding others will, when it brings forth its fruit, produce undying sorrow', career_application: 'The eager desire of defrauding others will, when it brings forth its fruit, produce undying sorrow', chapter: 'The Absence of Fraud' },
  { id: 285, kural_number: 285, tamil_text: 'அருள்கருதி அன்புடைய ராதல் பொருள்கருதிப் பொச்சாப்புப் பார்ப்பார்கண் இல்.', transliteration: 'Arulkarudhi Anputaiya Raadhal Porulkarudhip Pochchaappup Paarppaarkan Il', english_meaning: 'The study of kindness and the exercise of benevolence is not with those who watch for another\'s forgetfulness, though desire of his property', career_application: 'The study of kindness and the exercise of benevolence is not with those who watch for another\'s forgetfulness, though desire of his property', chapter: 'The Absence of Fraud' },
  { id: 286, kural_number: 286, tamil_text: 'அளவின்கண் நின்றொழுகல் ஆற்றார் களவின்கண் கன்றிய காத லவர்.', transliteration: 'Alavinkan Nindrozhukal Aatraar Kalavinkan Kandriya Kaadha Lavar', english_meaning: 'They cannot walk steadfastly, according to rule, who eagerly desire to defraud others', career_application: 'They cannot walk steadfastly, according to rule, who eagerly desire to defraud others', chapter: 'The Absence of Fraud' },
  { id: 287, kural_number: 287, tamil_text: 'களவென்னும் காரறி வாண்மை அளவென்னும் ஆற்றல் புரிந்தார்கண்ட இல்.', transliteration: 'Kalavennum Kaarari Vaanmai Alavennum Aatral Purindhaarkanta Il', english_meaning: 'That black-knowledge which is called fraud, is not in those who desire that greatness which is called rectitude', career_application: 'That black-knowledge which is called fraud, is not in those who desire that greatness which is called rectitude', chapter: 'The Absence of Fraud' },
  { id: 288, kural_number: 288, tamil_text: 'அளவறிந்தார் நெஞ்சத் தறம்போல நிற்கும் களவறிந்தார் நெஞ்சில் கரவு.', transliteration: 'Alavarindhaar Nenjath Tharampola Nirkum Kalavarindhaar Nenjil Karavu', english_meaning: 'Deceit dwells in the mind of those who are conversant with fraud, even as virtue in the minds of those who are conversant with rectitude', career_application: 'Deceit dwells in the mind of those who are conversant with fraud, even as virtue in the minds of those who are conversant with rectitude', chapter: 'The Absence of Fraud' },
  { id: 289, kural_number: 289, tamil_text: 'அளவல்ல செய்தாங்கே வீவர் களவல்ல மற்றைய தேற்றா தவர்.', transliteration: 'Alavalla Seydhaange Veevar Kalavalla Matraiya Thetraa Thavar', english_meaning: 'Those, who are acquainted with nothing but fraud, will perish in the very commission of transgression', career_application: 'Those, who are acquainted with nothing but fraud, will perish in the very commission of transgression', chapter: 'The Absence of Fraud' },
  { id: 290, kural_number: 290, tamil_text: 'கள்வார்க்குத் தள்ளும் உயிர்நிலை கள்வார்க்குத் தள்ளாது புத்தே ளுளகு.', transliteration: 'Kalvaarkkuth Thallum Uyirnilai Kalvaarkkuth Thallaadhu Puththe Lulaku', english_meaning: 'Even their body will fail the fraudulent; but even the world of the gods will not fail those who are free from fraud', career_application: 'Even their body will fail the fraudulent; but even the world of the gods will not fail those who are free from fraud', chapter: 'The Absence of Fraud' },
  { id: 291, kural_number: 291, tamil_text: 'வாய்மை எனப்படுவது யாதெனின் யாதொன்றும் தீமை இலாத சொலல்.', transliteration: 'Vaaimai Enappatuvadhu Yaadhenin Yaadhondrum Theemai Ilaadha Solal', english_meaning: 'Truth is the speaking of such words as are free from the least degree of evil (to others)', career_application: 'Truth is the speaking of such words as are free from the least degree of evil (to others)', chapter: 'Veracity' },
  { id: 292, kural_number: 292, tamil_text: 'பொய்மையும் வாய்மை யிடத்த புரைதீர்ந்த நன்மை பயக்கும் எனின்.', transliteration: 'Poimaiyum Vaaimai Yitaththa Puraidheerndha Nanmai Payakkum Enin', english_meaning: 'Even falsehood has the nature of truth, if it confer a benefit that is free from fault', career_application: 'Even falsehood has the nature of truth, if it confer a benefit that is free from fault', chapter: 'Veracity' },
  { id: 293, kural_number: 293, tamil_text: 'தன்நெஞ் சறிவது பொய்யற்க பொய்த்தபின் தன்நெஞ்சே தன்னைச் சுடும்.', transliteration: 'Thannenj Charivadhu Poiyarka Poiththapin Thannenje Thannaich Chutum', english_meaning: 'Let not a man knowingly tell a lie; for after he has told the lie, his mind will burn him (with the memory of his guilt)', career_application: 'Let not a man knowingly tell a lie; for after he has told the lie, his mind will burn him (with the memory of his guilt)', chapter: 'Veracity' },
  { id: 294, kural_number: 294, tamil_text: 'உள்ளத்தாற் பொய்யா தொழுகின் உலகத்தார் உள்ளத்து ளெல்லாம் உளன்.', transliteration: 'Ullaththaar Poiyaa Thozhukin Ulakaththaar Ullaththu Lellaam Ulan', english_meaning: 'He who, in his conduct, preserves a mind free from deceit, will dwell in the minds of all men', career_application: 'He who, in his conduct, preserves a mind free from deceit, will dwell in the minds of all men', chapter: 'Veracity' },
  { id: 295, kural_number: 295, tamil_text: 'மனத்தொடு வாய்மை மொழியின் தவத்தொடு தானஞ்செய் வாரின் தலை.', transliteration: 'Manaththotu Vaaimai Mozhiyin Thavaththotu Thaananjey Vaarin Thalai', english_meaning: 'He, who speaks truth with all his heart, is superior to those who make gifts and practise austerities', career_application: 'He, who speaks truth with all his heart, is superior to those who make gifts and practise austerities', chapter: 'Veracity' },
  { id: 296, kural_number: 296, tamil_text: 'பொய்யாமை அன்ன புகழில்லை எய்யாமை எல்லா அறமுந் தரும்.', transliteration: 'Poiyaamai Anna Pukazhillai Eyyaamai Ellaa Aramun Tharum', english_meaning: 'There is no praise like the praise of never uttering a falsehood: without causing any suffering, it will lead to every virtue', career_application: 'There is no praise like the praise of never uttering a falsehood: without causing any suffering, it will lead to every virtue', chapter: 'Veracity' },
  { id: 297, kural_number: 297, tamil_text: 'பொய்யாமை பொய்யாமை ஆற்றின் அறம்பிற செய்யாமை செய்யாமை நன்று.', transliteration: 'Poiyaamai Poiyaamai Aatrin Arampira Seyyaamai Seyyaamai Nandru', english_meaning: 'If a man has the power to abstain from falsehood, it will be well with him, even though he practise no other virtue', career_application: 'If a man has the power to abstain from falsehood, it will be well with him, even though he practise no other virtue', chapter: 'Veracity' },
  { id: 298, kural_number: 298, tamil_text: 'புறள்தூய்மை நீரான் அமையும் அகந்தூய்மை வாய்மையால் காணப் படும்.', transliteration: 'Puraldhooimai Neeraan Amaiyum Akandhooimai Vaaimaiyaal Kaanap Patum', english_meaning: 'Purity of body is produced by water and purity of mind by truthfulness', career_application: 'Purity of body is produced by water and purity of mind by truthfulness', chapter: 'Veracity' },
  { id: 299, kural_number: 299, tamil_text: 'எல்லா விளக்கும் விளக்கல்ல சான்றோர்க்குப் பொய்யா விளக்கே விளக்கு.', transliteration: 'Ellaa Vilakkum Vilakkalla Saandrorkkup Poiyaa Vilakke Vilakku', english_meaning: 'All lamps of nature are not lamps; the lamp of truth is the lamp of the wise', career_application: 'All lamps of nature are not lamps; the lamp of truth is the lamp of the wise', chapter: 'Veracity' },
  { id: 300, kural_number: 300, tamil_text: 'யாமெய்யாக் கண்டவற்றுள் இல்லை எனைத்தொன்றும் வாய்மையின் நல்ல பிற.', transliteration: 'Yaameyyaak Kantavatrul Illai Enaiththondrum Vaaimaiyin Nalla Pira', english_meaning: 'Amidst all that we have seen (described) as real (excellence), there is nothing so good as truthfulness', career_application: 'Amidst all that we have seen (described) as real (excellence), there is nothing so good as truthfulness', chapter: 'Veracity' },
  { id: 301, kural_number: 301, tamil_text: 'செல்லிடத்துக் காப்பான் சினங்காப்பான் அல்லிடத்துக் காக்கின்என் காவாக்கால் என்?', transliteration: 'Sellitaththuk Kaappaan Sinangaappaan Allitaththuk Kaakkinen Kaavaakkaal En?', english_meaning: 'He restrains his anger who restrains it when it can injure; when it cannot injure, what does it matter whether he restrain it, or not ?', career_application: 'He restrains his anger who restrains it when it can injure; when it cannot injure, what does it matter whether he restrain it, or not ?', chapter: 'Restraining Anger' },
  { id: 302, kural_number: 302, tamil_text: 'செல்லா இடத்துச் சினந்தீது செல்லிடத்தும் இல்அதனின் தீய பிற.', transliteration: 'Sellaa Itaththuch Chinandheedhu Sellitaththum Iladhanin Theeya Pira', english_meaning: 'Anger is bad, even when it cannot injure; when it can injure; there is no greater evil', career_application: 'Anger is bad, even when it cannot injure; when it can injure; there is no greater evil', chapter: 'Restraining Anger' },
  { id: 303, kural_number: 303, tamil_text: 'மறத்தல் வெகுளியை யார்மாட்டும் தீய பிறத்தல் அதனான் வரும்.', transliteration: 'Maraththal Vekuliyai Yaarmaattum Theeya Piraththal Adhanaan Varum', english_meaning: 'Forget anger towards every one, as fountains of evil spring from it', career_application: 'Forget anger towards every one, as fountains of evil spring from it', chapter: 'Restraining Anger' },
  { id: 304, kural_number: 304, tamil_text: 'நகையும் உவகையும் கொல்லும் சினத்தின் பகையும் உளவோ பிற.', transliteration: 'Nakaiyum Uvakaiyum Kollum Sinaththin Pakaiyum Ulavo Pira', english_meaning: 'What other foe to man works such annoy?', career_application: 'What other foe to man works such annoy?', chapter: 'Restraining Anger' },
  { id: 305, kural_number: 305, tamil_text: 'தன்னைத்தான் காக்கின் சினங்காக்க காவாக்கால் தன்னையே கொல்லுஞ் சினம்.', transliteration: 'Thannaiththaan Kaakkin Sinangaakka Kaavaakkaal Thannaiye Kollunj Chinam', english_meaning: 'If a man would guard himself, let him guard against anger; if he do not guard it, anger will kill him', career_application: 'If a man would guard himself, let him guard against anger; if he do not guard it, anger will kill him', chapter: 'Restraining Anger' },
  { id: 306, kural_number: 306, tamil_text: 'சினமென்னும் சேர்ந்தாரைக் கொல்லி இனமென்னும் ஏமப் புணையைச் சுடும்.', transliteration: 'Sinamennum Serndhaaraik Kolli Inamennum Emap Punaiyaich Chutum', english_meaning: 'The fire of anger will burn up even the pleasant raft of friendship', career_application: 'The fire of anger will burn up even the pleasant raft of friendship', chapter: 'Restraining Anger' },
  { id: 307, kural_number: 307, tamil_text: 'சினத்தைப் பொருளென்று கொண்டவன் கேடு நிலத்தறைந்தான் கைபிழையா தற்று.', transliteration: 'Sinaththaip Porulendru Kontavan Ketu Nilaththaraindhaan Kaipizhaiyaa Thatru', english_meaning: 'Destruction will come upon him who ragards anger as a good thing, as surely as the hand of him who strikes the ground will not fail', career_application: 'Destruction will come upon him who ragards anger as a good thing, as surely as the hand of him who strikes the ground will not fail', chapter: 'Restraining Anger' },
  { id: 308, kural_number: 308, tamil_text: 'இணர்எரி தோய்வன்ன இன்னா செயினும் புணரின் வெகுளாமை நன்று.', transliteration: 'Inareri Thoivanna Innaa Seyinum Punarin Vekulaamai Nandru', english_meaning: 'Though one commit things against you as painful (to bear) as if a bundle of fire had been thrust upon you, it will be well, to refrain, if possible, from anger', career_application: 'Though one commit things against you as painful (to bear) as if a bundle of fire had been thrust upon you, it will be well, to refrain, if possible, from anger', chapter: 'Restraining Anger' },
  { id: 309, kural_number: 309, tamil_text: 'உள்ளிய தெல்லாம் உடனெய்தும் உள்ளத்தால் உள்ளான் வெகுளி எனின்.', transliteration: 'Ulliya Thellaam Utaneydhum Ullaththaal Ullaan Vekuli Enin', english_meaning: 'If a man never indulges anger in his heart, he will at once obtain whatever he has thought of', career_application: 'If a man never indulges anger in his heart, he will at once obtain whatever he has thought of', chapter: 'Restraining Anger' },
  { id: 310, kural_number: 310, tamil_text: 'இறந்தார் இறந்தார் அனையர் சினத்தைத் துறந்தார் துறந்தார் துணை.', transliteration: 'Irandhaar Irandhaar Anaiyar Sinaththaith Thurandhaar Thurandhaar Thunai', english_meaning: 'Those, who give way to excessive anger, are no better than dead men; but those, who are freed from it, are equal to those who are freed (from death)', career_application: 'Those, who give way to excessive anger, are no better than dead men; but those, who are freed from it, are equal to those who are freed (from death)', chapter: 'Restraining Anger' },
  { id: 311, kural_number: 311, tamil_text: 'சிறப்பீனும் செல்வம் பெறினும் பிறர்க்குஇன்னா செய்யாமை மாசற்றார் கோள்.', transliteration: 'Sirappeenum Selvam Perinum Pirarkku Innaa Seyyaamai Maasatraar Kol', english_meaning: 'It is the determination of the spotless not to cause sorrow to others, although they could (by so causing) obtain the wealth which confers greatness', career_application: 'It is the determination of the spotless not to cause sorrow to others, although they could (by so causing) obtain the wealth which confers greatness', chapter: 'Not doing Evil' },
  { id: 312, kural_number: 312, tamil_text: 'கறுத்துஇன்னா செய்தவக் கண்ணும் மறுத்தின்னா செய்யாமை மாசற்றார் கோள்.', transliteration: 'Karuththuinnaa Seydhavak Kannum Maruththinnaa Seyyaamai Maasatraar Kol', english_meaning: 'It is the determination of the spotless not to do evil, even in return, to those who have cherished enmity and done them evil', career_application: 'It is the determination of the spotless not to do evil, even in return, to those who have cherished enmity and done them evil', chapter: 'Not doing Evil' },
  { id: 313, kural_number: 313, tamil_text: 'செய்யாமல் செற்றார்க்கும் இன்னாத செய்தபின் உய்யா விழுமந் தரும்.', transliteration: 'Seyyaamal Setraarkkum Innaadha Seydhapin Uyyaa Vizhuman Tharum', english_meaning: 'In an ascetic inflict suffering even on those who hate him, when he has not done them any evil, it will afterwards give him irretrievable sorrow', career_application: 'In an ascetic inflict suffering even on those who hate him, when he has not done them any evil, it will afterwards give him irretrievable sorrow', chapter: 'Not doing Evil' },
  { id: 314, kural_number: 314, tamil_text: 'இன்னாசெய் தாரை ஒறுத்தல் அவர்நாண நன்னயஞ் செய்து விடல்.', transliteration: 'Innaasey Thaarai Oruththal Avarnaana Nannayanj Cheydhu Vital', english_meaning: 'The (proper) punishment to those who have done evil (to you), is to put them to shame by showing them kindness, in return and to forget both the evil and the good done on both sides', career_application: 'The (proper) punishment to those who have done evil (to you), is to put them to shame by showing them kindness, in return and to forget both the evil and the good done on both sides', chapter: 'Not doing Evil' },
  { id: 315, kural_number: 315, tamil_text: 'அறிவினான் ஆகுவ துண்டோ பிறிதின்நோய் தந்நோய்போல் போற்றாக் கடை.', transliteration: 'Arivinaan Aakuva Thunto Piridhinnoi Thannoipol Potraak Katai', english_meaning: 'What benefit has he derived from his knowledge, who does not endeavour to keep off pain from another as much as from himself ?', career_application: 'What benefit has he derived from his knowledge, who does not endeavour to keep off pain from another as much as from himself ?', chapter: 'Not doing Evil' },
  { id: 316, kural_number: 316, tamil_text: 'இன்னா எனத்தான் உணர்ந்தவை துன்னாமை வேண்டும் பிறன்கண் செயல்.', transliteration: 'Innaa Enaththaan Unarndhavai Thunnaamai Ventum Pirankan Seyal', english_meaning: 'Let not a man consent to do those things to another which, he knows, will cause sorrow', career_application: 'Let not a man consent to do those things to another which, he knows, will cause sorrow', chapter: 'Not doing Evil' },
  { id: 317, kural_number: 317, tamil_text: 'எனைத்தானும் எஞ்ஞான்றும் யார்க்கும் மனத்தானாம் மாணாசெய் யாமை தலை.', transliteration: 'Enaiththaanum Egngnaandrum Yaarkkum Manaththaanaam Maanaasey Yaamai Thalai', english_meaning: 'It is the chief of all virtues not knowingly to do any person evil, even in the lowest degree, and at any time', career_application: 'It is the chief of all virtues not knowingly to do any person evil, even in the lowest degree, and at any time', chapter: 'Not doing Evil' },
  { id: 318, kural_number: 318, tamil_text: 'தன்னுயிர்ககு ஏன்னாமை தானறிவான் என்கொலோ மன்னுயிர்க்கு இன்னா செயல்.', transliteration: 'Thannuyirkaku Ennaamai Thaanarivaan Enkolo Mannuyirkku Innaa Seyal', english_meaning: 'Why does a man inflict upon other creatures those sufferings, which he has found by experience are sufferings to himself ?', career_application: 'Why does a man inflict upon other creatures those sufferings, which he has found by experience are sufferings to himself ?', chapter: 'Not doing Evil' },
  { id: 319, kural_number: 319, tamil_text: 'பிறர்க்கின்னா முற்பகல் செய்யின் தமக்குஇன்னா பிற்பகல் தாமே வரும்.', transliteration: 'Pirarkkinnaa Murpakal Seyyin Thamakku Innaa Pirpakal Thaame Varum', english_meaning: 'If a man inflict sorrow upon others in the morning, it will come upon him unsought in the very evening', career_application: 'If a man inflict sorrow upon others in the morning, it will come upon him unsought in the very evening', chapter: 'Not doing Evil' },
  { id: 320, kural_number: 320, tamil_text: 'நோயெல்லாம் நோய்செய்தார் மேலவாம் நோய்செய்யார் நோயின்மை வேண்டு பவர்.', transliteration: 'Noyellaam Noiseydhaar Melavaam Noiseyyaar Noyinmai Ventu Pavar', english_meaning: 'Sorrow will come upon those who cause pain to others; therfore those, who desire to be free from sorrow, give no pain to others', career_application: 'Sorrow will come upon those who cause pain to others; therfore those, who desire to be free from sorrow, give no pain to others', chapter: 'Not doing Evil' },
  { id: 321, kural_number: 321, tamil_text: 'அறவினை யாதெனின் கொல்லாமை கோறல் பிறவினை எல்லாந் தரும்.', transliteration: 'Aravinai Yaadhenin Kollaamai Koral Piravinai Ellaan Tharum', english_meaning: 'Never to destroy life is the sum of all virtuous conduct The destruction of life leads to every evil', career_application: 'Never to destroy life is the sum of all virtuous conduct The destruction of life leads to every evil', chapter: 'Not killing' },
  { id: 322, kural_number: 322, tamil_text: 'பகுத்துண்டு பல்லுயிர் ஓம்புதல் நூலோர் தொகுத்தவற்றுள் எல்லாந் தலை.', transliteration: 'Pakuththuntu Palluyir Ompudhal Noolor Thokuththavatrul Ellaan Thalai', english_meaning: 'The chief of all (the virtues) which authors have summed up, is the partaking of food that has been shared with others, and the preservation of the mainfold life of other creatures', career_application: 'The chief of all (the virtues) which authors have summed up, is the partaking of food that has been shared with others, and the preservation of the mainfold life of other creatures', chapter: 'Not killing' },
  { id: 323, kural_number: 323, tamil_text: 'ஒன்றாக நல்லது கொல்லாமை மற்றதன் பின்சாரப் பொய்யாமை நன்று.', transliteration: 'Ondraaka Nalladhu Kollaamai Matradhan Pinsaarap Poiyaamai Nandru', english_meaning: 'Not to destroy life is an incomparably (great) good next to it in goodness ranks freedom from falsehood', career_application: 'Not to destroy life is an incomparably (great) good next to it in goodness ranks freedom from falsehood', chapter: 'Not killing' },
  { id: 324, kural_number: 324, tamil_text: 'நல்லாறு எனப்படுவது யாதெனின் யாதொன்றும் கொல்லாமை சூழும் நெறி.', transliteration: 'Nallaaru Enappatuvadhu Yaadhenin Yaadhondrum Kollaamai Soozhum Neri', english_meaning: 'Good path is that which considers how it may avoid killing any creature', career_application: 'Good path is that which considers how it may avoid killing any creature', chapter: 'Not killing' },
  { id: 325, kural_number: 325, tamil_text: 'நிலைஅஞ்சி நீத்தாருள் எல்லாம் கொலைஅஞ்சிக் கொல்லாமை சூழ்வான் தலை.', transliteration: 'Nilaianji Neeththaarul Ellaam Kolaianjik Kollaamai Soozhvaan Thalai', english_meaning: 'Of all those who, fearing the permanence of earthly births, have abandoned desire, he is the chief who, fearing (the guilt of) murder, considers how he may avoid the destruction of life', career_application: 'Of all those who, fearing the permanence of earthly births, have abandoned desire, he is the chief who, fearing (the guilt of) murder, considers how he may avoid the destruction of life', chapter: 'Not killing' },
  { id: 326, kural_number: 326, tamil_text: 'கொல்லாமை மேற்கொண் டொழுகுவான் வாழ்நாள்மேல் செல்லாது உயிருண்ணுங் கூற்று.', transliteration: 'Kollaamai Merkon Tozhukuvaan Vaazhnaalmel Sellaadhu Uyirunnung Kootru', english_meaning: 'Yama, the destroyer of life, will not attack the life of him, who acts under the determination of never destroying life', career_application: 'Yama, the destroyer of life, will not attack the life of him, who acts under the determination of never destroying life', chapter: 'Not killing' },
  { id: 327, kural_number: 327, tamil_text: 'தன்னுயிர் நீப்பினும் செய்யற்க தான்பிறிது இன்னுயிர் நீக்கும் வினை.', transliteration: 'Thannuyir Neeppinum Seyyarka Thaanpiridhu Innuyir Neekkum Vinai', english_meaning: 'Let no one do that which would destroy the life of another, although he should by so doing, lose his own life', career_application: 'Let no one do that which would destroy the life of another, although he should by so doing, lose his own life', chapter: 'Not killing' },
  { id: 328, kural_number: 328, tamil_text: 'நன்றாகும் ஆக்கம் பெரிதெனினும் சான்றோர்க்குக் கொன்றாகும் ஆக்கங் கடை.', transliteration: 'Nandraakum Aakkam Peridheninum Saandrorkkuk Kondraakum Aakkang Katai', english_meaning: 'The advantage which might flow from destroying life in sacrifice, is dishonourable to the wise (who renounced the world), even although it should be said to be productive of great good', career_application: 'The advantage which might flow from destroying life in sacrifice, is dishonourable to the wise (who renounced the world), even although it should be said to be productive of great good', chapter: 'Not killing' },
  { id: 329, kural_number: 329, tamil_text: 'கொலைவினைய ராகிய மாக்கள் புலைவினையர் புன்மை தெரிவா ரகத்து.', transliteration: 'Kolaivinaiya Raakiya Maakkal Pulaivinaiyar Punmai Therivaa Rakaththu', english_meaning: 'To minds of them who what is vileness know', career_application: 'To minds of them who what is vileness know', chapter: 'Not killing' },
  { id: 330, kural_number: 330, tamil_text: 'உயிருடம்பின் நீக்கியா ரென்ப செயிருடம்பின் செல்லாத்தீ வாழ்க்கை யவர்.', transliteration: 'Uyir Utampin Neekkiyaar Enpa Seyir Utampin Sellaaththee Vaazhkkai', english_meaning: '(The wise) will say that men of diseased bodies, who live in degradation and in poverty, are those who separated the life from the body of animals (in a former birth)', career_application: '(The wise) will say that men of diseased bodies, who live in degradation and in poverty, are those who separated the life from the body of animals (in a former birth)', chapter: 'Not killing' },
  { id: 331, kural_number: 331, tamil_text: 'நில்லாத வற்றை நிலையின என்றுணரும் புல்லறி வாண்மை கடை.', transliteration: 'Nillaadha Vatrai Nilaiyina Endrunarum Pullari Vaanmai Katai', english_meaning: 'That ignorance which considers those things to be stable which are not so, is dishonourable (to the wise)', career_application: 'That ignorance which considers those things to be stable which are not so, is dishonourable (to the wise)', chapter: 'Instability' },
  { id: 332, kural_number: 332, tamil_text: 'கூத்தாட்டு அவைக்குழாத் தற்றே பெருஞ்செல்வம் போக்கும் அதுவிளிந் தற்று.', transliteration: 'Kooththaattu Avaik Kuzhaath Thatre Perunjelvam Pokkum Adhuvilin Thatru', english_meaning: 'The acquisition of wealth is like the gathering together of an assembly for a theatre; its expenditure is like the breaking up of that assembly', career_application: 'The acquisition of wealth is like the gathering together of an assembly for a theatre; its expenditure is like the breaking up of that assembly', chapter: 'Instability' },
  { id: 333, kural_number: 333, tamil_text: 'அற்கா இயல்பிற்றுச் செல்வம் அதுபெற்றால் அற்குப ஆங்கே செயல்.', transliteration: 'Arkaa Iyalpitruch Chelvam Adhupetraal Arkupa Aange Seyal', english_meaning: 'Wealth is perishable; let those who obtain it immediately practise those (virtues) which are imperishable', career_application: 'Wealth is perishable; let those who obtain it immediately practise those (virtues) which are imperishable', chapter: 'Instability' },
  { id: 334, kural_number: 334, tamil_text: 'நாளென ஒன்றுபோற் காட்டி உயிர்ஈரும் வாளது உணர்வார்ப் பெறின்.', transliteration: 'Naalena Ondrupor Kaatti Uyir Eerum Vaaladhu Unarvaarp Perin', english_meaning: 'Time, which shows itself (to the ignorant) as if it were something (real) is in the estimation of the wise (only) a saw which cuts down life', career_application: 'Time, which shows itself (to the ignorant) as if it were something (real) is in the estimation of the wise (only) a saw which cuts down life', chapter: 'Instability' },
  { id: 335, kural_number: 335, tamil_text: 'நாச்செற்று விக்குள்மேல் வாராமுன் நல்வினை மேற்சென்று செய்யப் படும்', transliteration: 'Naachchetru Vikkulmel Vaaraamun Nalvinai Mersendru Seyyap Patum', english_meaning: 'Let virtuous deeds be done quickly, before the hiccup comes making the tongue silent', career_application: 'Let virtuous deeds be done quickly, before the hiccup comes making the tongue silent', chapter: 'Instability' },
  { id: 336, kural_number: 336, tamil_text: 'நெருநல் உளனொருவன் இன்றில்லை என்னும் பெருமை உடைத்துஇவ் வுலகு.', transliteration: 'Nerunal Ulanoruvan Indrillai Ennum Perumai Utaiththuiv Vulaku', english_meaning: 'This world possesses the greatness that one who yesterday was is not today', career_application: 'This world possesses the greatness that one who yesterday was is not today', chapter: 'Instability' },
  { id: 337, kural_number: 337, tamil_text: 'ஒருபொழுதும் வாழ்வது அறியார் கருதுப கோடியும் அல்ல பல.', transliteration: 'Orupozhudhum Vaazhvadhu Ariyaar Karudhupa Kotiyum Alla Pala', english_meaning: 'Innumerable are the thoughts which occupy the mind of (the unwise), who know not that they shall live another moment', career_application: 'Innumerable are the thoughts which occupy the mind of (the unwise), who know not that they shall live another moment', chapter: 'Instability' },
  { id: 338, kural_number: 338, tamil_text: 'குடம்பை தனித்துஒழியப் புள்பறந் தற்றே உடம்பொடு உயிரிடை நட்பு.', transliteration: 'Kutampai Thaniththu Ozhiyap Pulparan Thatre Utampotu Uyiritai Natpu', english_meaning: 'The love of the soul to the body is like (the love of) a bird to its egg which it flies away from and leaves empty', career_application: 'The love of the soul to the body is like (the love of) a bird to its egg which it flies away from and leaves empty', chapter: 'Instability' },
  { id: 339, kural_number: 339, tamil_text: 'உறங்கு வதுபோலுஞ் சாக்காடு உறங்கி விழிப்பது போலும் பிறப்பு.', transliteration: 'Urangu Vadhupolunj Chaakkaatu Urangi Vizhippadhu Polum Pirappu', english_meaning: 'Death is like sleep; birth is like awaking from it', career_application: 'Death is like sleep; birth is like awaking from it', chapter: 'Instability' },
  { id: 340, kural_number: 340, tamil_text: 'புக்கில் அமைந்தின்று கொல்லோ உடம்பினுள் துச்சில் இருந்த உயிர்க்கு.', transliteration: 'Pukkil Amaindhindru Kollo Utampinul Thuchchil Irundha Uyirkku', english_meaning: 'It seems as if the soul, which takes a temporary shelter in a body, had not attained a home', career_application: 'It seems as if the soul, which takes a temporary shelter in a body, had not attained a home', chapter: 'Instability' },
  { id: 341, kural_number: 341, tamil_text: 'யாதனின் யாதனின் நீங்கியான் நோதல் அதனின் அதனின் இலன்.', transliteration: 'Yaadhanin Yaadhanin Neengiyaan Nodhal Adhanin Adhanin Ilan', english_meaning: 'Whatever thing, a man has renounced, by that thing; he cannot suffer pain', career_application: 'Whatever thing, a man has renounced, by that thing; he cannot suffer pain', chapter: 'Renunciation' },
  { id: 342, kural_number: 342, tamil_text: 'வேண்டின்உண் டாகத் துறக்க துறந்தபின் ஈண்டுஇயற் பால பல.', transliteration: 'Ventin Un Taakath Thurakka Thurandhapin Eentuiyar Paala Pala', english_meaning: 'After a man has renounced (all things), there will still be many things in this world (which he may enjoy); if he should desire them, let him, while it is time abandon (the world)', career_application: 'After a man has renounced (all things), there will still be many things in this world (which he may enjoy); if he should desire them, let him, while it is time abandon (the world)', chapter: 'Renunciation' },
  { id: 343, kural_number: 343, tamil_text: 'அடல்வேண்டும் ஐந்தன் புலத்தை விடல்வேண்டும் வேண்டிய வெல்லாம் ஒருங்கு.', transliteration: 'Atalventum Aindhan Pulaththai Vitalventum Ventiya Vellaam Orungu', english_meaning: 'Let the five senses be destroyed; and at the same time, let everything be abandoned that (the ascetic) has (formerly) desired', career_application: 'Let the five senses be destroyed; and at the same time, let everything be abandoned that (the ascetic) has (formerly) desired', chapter: 'Renunciation' },
  { id: 344, kural_number: 344, tamil_text: 'இயல்பாகும் நோன்பிற்கொன்று இன்மை உடைமை மயலாகும் மற்றும் பெயர்த்து.', transliteration: 'Iyalpaakum Nonpirkondru Inmai Utaimai Mayalaakum Matrum Peyarththu', english_meaning: 'To be altogether destitute is the proper condition of those who perform austerities; if they possess anything, it will change (their resolution) and bring them back to their confused state', career_application: 'To be altogether destitute is the proper condition of those who perform austerities; if they possess anything, it will change (their resolution) and bring them back to their confused state', chapter: 'Renunciation' },
  { id: 345, kural_number: 345, tamil_text: 'மற்றும் தொடர்ப்பாடு எவன்கொல் பிறப்பறுக்கல் உற்றார்க்கு உடம்பும் மிகை.', transliteration: 'Matrum Thotarppaatu Evankol Pirapparukkal Utraarkku Utampum Mikai', english_meaning: 'What means the addition of other things those who are attempting to cut off (future) births, when even their body is too much (for them)', career_application: 'What means the addition of other things those who are attempting to cut off (future) births, when even their body is too much (for them)', chapter: 'Renunciation' },
  { id: 346, kural_number: 346, tamil_text: 'யான்எனது என்னும் செருக்குஅறுப்பான் வானோர்க்கு உயர்ந்த உலகம் புகும்.', transliteration: 'Yaan Enadhu Ennum Serukku Aruppaan Vaanorkku Uyarndha Ulakam', english_meaning: 'Shall enter realms above the powers divine', career_application: 'Shall enter realms above the powers divine', chapter: 'Renunciation' },
  { id: 347, kural_number: 347, tamil_text: 'பற்றி விடாஅ இடும்பைகள் பற்றினைப் பற்றி விடாஅ தவர் க்கு.', transliteration: 'Patri Vitaaa Itumpaikal Patrinaip Patri Vitaaa Thavarkku', english_meaning: 'Sorrows will never let go their hold of those who give not up their hold of desire', career_application: 'Sorrows will never let go their hold of those who give not up their hold of desire', chapter: 'Renunciation' },
  { id: 348, kural_number: 348, tamil_text: 'தலைப்பட்டார் தீரத் துறந்தார் மயங்கி வலைப்பட்டார் மற்றை யவர்.', transliteration: 'Thalaippattaar Theerath Thurandhaar Mayangi Valaippattaar Matrai Yavar', english_meaning: 'Those who have entirely renounced (all things and all desire) have obtained (absorption into God); all others wander in confusion, entangled in the net of (many) births', career_application: 'Those who have entirely renounced (all things and all desire) have obtained (absorption into God); all others wander in confusion, entangled in the net of (many) births', chapter: 'Renunciation' },
  { id: 349, kural_number: 349, tamil_text: 'பற்றற்ற கண்ணே பிறப்பறுக்கும் மற்று நிலையாமை காணப் படும்.', transliteration: 'Patratra Kanne Pirapparukkum Matru Nilaiyaamai Kaanap Patum', english_meaning: 'At the moment in which desire has been abandoned, (other) births will be cut off; when that has not been done, instability will be seen', career_application: 'At the moment in which desire has been abandoned, (other) births will be cut off; when that has not been done, instability will be seen', chapter: 'Renunciation' },
  { id: 350, kural_number: 350, tamil_text: 'பற்றுக பற்றற்றான் பற்றினை அப்பற்றைப் பற்றுக பற்று விடற்கு.', transliteration: 'Patruka Patratraan Patrinai Appatraip Patruka Patru Vitarku', english_meaning: 'Desire the desire of Him who is without desire; in order to renounce desire, desire that desire', career_application: 'Desire the desire of Him who is without desire; in order to renounce desire, desire that desire', chapter: 'Renunciation' },
  { id: 351, kural_number: 351, tamil_text: 'பொருளல்ல வற்றைப் பொருளென்று உணரும் மருளானாம் மாணாப் பிறப்பு.', transliteration: 'Porulalla Vatraip Porulendru Unarum Marulaanaam Maanaap Pirappu', english_meaning: 'Inglorious births are produced by the confusion (of mind) which considers those things to be real which are not real', career_application: 'Inglorious births are produced by the confusion (of mind) which considers those things to be real which are not real', chapter: 'Truth-Conciousness' },
  { id: 352, kural_number: 352, tamil_text: 'இருள்நீங்கி இன்பம் பயக்கும் மருள்நீங்கி மாசறு காட்சி யவர்க்கு.', transliteration: 'Irulneengi Inpam Payakkum Marulneengi Maasaru Kaatchi Yavarkku', english_meaning: 'A clear, undimmed vision of things will deliver its possessors from the darkness of future births, and confer the felicity (of heaven)', career_application: 'A clear, undimmed vision of things will deliver its possessors from the darkness of future births, and confer the felicity (of heaven)', chapter: 'Truth-Conciousness' },
  { id: 353, kural_number: 353, tamil_text: 'ஐயத்தின் நீங்கித் தெளிந்தார்க்கு வையத்தின் வானம் நணிய துடைத்து.', transliteration: 'Aiyaththin Neengith Thelindhaarkku Vaiyaththin Vaanam Naniya Thutaiththu', english_meaning: 'Heaven is nearer than earth to those men of purified minds who are freed from from doubt', career_application: 'Heaven is nearer than earth to those men of purified minds who are freed from from doubt', chapter: 'Truth-Conciousness' },
  { id: 354, kural_number: 354, tamil_text: 'ஐயுணர்வு எய்தியக் கண்ணும் பயமின்றே மெய்யுணர்வு இல்லா தவர்க்கு.', transliteration: 'Aiyunarvu Eydhiyak Kannum Payamindre Meyyunarvu Illaa Thavarkku', english_meaning: 'Even those who have all the knowledge which can be attained by the five senses, will derive no benefit from it, if they are without a knowledge of the true nature of things', career_application: 'Even those who have all the knowledge which can be attained by the five senses, will derive no benefit from it, if they are without a knowledge of the true nature of things', chapter: 'Truth-Conciousness' },
  { id: 355, kural_number: 355, tamil_text: 'எப்பொருள் எத்தன்மைத் தாயினும் அப்பொருள் மெய்ப்பொருள் காண்பது அறிவு.', transliteration: 'Epporul Eththanmaith Thaayinum Apporul Meypporul Kaanpadhu Arivu', english_meaning: '(True) knowledge is the perception concerning every thing of whatever kind, that that thing is the true thing', career_application: '(True) knowledge is the perception concerning every thing of whatever kind, that that thing is the true thing', chapter: 'Truth-Conciousness' },
  { id: 356, kural_number: 356, tamil_text: 'கற்றீண்டு மெய்ப்பொருள் கண்டார் தலைப்படுவர் மற்றீண்டு வாரா நெறி.', transliteration: 'Katreentu Meypporul Kantaar Thalaippatuvar Matreentu Vaaraa Neri', english_meaning: 'They, who in this birth have learned to know the True Being, enter the road which returns not into this world', career_application: 'They, who in this birth have learned to know the True Being, enter the road which returns not into this world', chapter: 'Truth-Conciousness' },
  { id: 357, kural_number: 357, tamil_text: 'ஓர்த்துள்ளம் உள்ளது உணரின் ஒருதலையாப் பேர்த்துள்ள வேண்டா பிறப்பு.', transliteration: 'Orththullam Ulladhu Unarin Orudhalaiyaap Perththulla Ventaa Pirappu', english_meaning: 'Let it not be thought that there is another birth for him whose mind having thoroughly considered (all it has been taught) has known the True Being', career_application: 'Let it not be thought that there is another birth for him whose mind having thoroughly considered (all it has been taught) has known the True Being', chapter: 'Truth-Conciousness' },
  { id: 358, kural_number: 358, tamil_text: 'பிறப்பென்னும் பேதைமை நீங்கச் சிறப்பென்னும் செம்பொருள் காண்பது அறிவு.', transliteration: 'Pirappennum Pedhaimai Neengach Chirappennum Semporul Kaanpadhu Arivu', english_meaning: 'True knowledge consists in the removal of ignorance; which is (the cause of) births, and the perception of the True Being who is (the bestower of) heaven', career_application: 'True knowledge consists in the removal of ignorance; which is (the cause of) births, and the perception of the True Being who is (the bestower of) heaven', chapter: 'Truth-Conciousness' },
  { id: 359, kural_number: 359, tamil_text: 'சார்புணர்ந்து சார்பு கெடஒழுகின் மற்றழித்துச் சார்தரா சார்தரு நோய்.', transliteration: 'Saarpunarndhu Saarpu Ketaozhukin Matrazhiththuch Chaardharaa Saardharu Noi', english_meaning: 'He who so lives as to know Him who is the support of all things and abandon all desire, will be freed from the evils which would otherwise cleave to him and destroy (his efforts after absorption)', career_application: 'He who so lives as to know Him who is the support of all things and abandon all desire, will be freed from the evils which would otherwise cleave to him and destroy (his efforts after absorption)', chapter: 'Truth-Conciousness' },
  { id: 360, kural_number: 360, tamil_text: 'காமம் வெகுளி மயக்கம் இவ்மூன்றன் நாமம் கெடக்கெடும் நோய்.', transliteration: 'Kaamam Vekuli Mayakkam Ivaimundran Naamam Ketakketum Noi', english_meaning: 'If the very names of these three things, desire, anger, and confusion of mind, be destroyed, then will also perish evils (which flow from them)', career_application: 'If the very names of these three things, desire, anger, and confusion of mind, be destroyed, then will also perish evils (which flow from them)', chapter: 'Truth-Conciousness' },
  { id: 361, kural_number: 361, tamil_text: 'அவாஎன்ப எல்லா உயிர்க்கும் எஞ்ஞான்றும் தவாஅப் பிறப்பீனும் வித்து.', transliteration: 'Avaaenpa Ellaa Uyirkkum Enj Gnaandrum Thavaaap Pirappeenum Viththu', english_meaning: '(The wise) say that the seed, which produces unceasing births, at all times, to all creatures, is desire', career_application: '(The wise) say that the seed, which produces unceasing births, at all times, to all creatures, is desire', chapter: 'Curbing of Desire' },
  { id: 362, kural_number: 362, tamil_text: 'வேண்டுங்கால் வேண்டும் பிறவாமை மற்றது வேண்டாமை வேண்ட வரும்.', transliteration: 'Ventungaal Ventum Piravaamai Matradhu Ventaamai Venta Varum', english_meaning: 'If anything be desired, freedom from births should be desired; that (freedom from births) will be attained by desiring to be without desire', career_application: 'If anything be desired, freedom from births should be desired; that (freedom from births) will be attained by desiring to be without desire', chapter: 'Curbing of Desire' },
  { id: 363, kural_number: 363, tamil_text: 'வேண்டாமை அன்ன விழுச்செல்வம் ஈண்டில்லை ஆண்டும் அஃதொப்பது இல்.', transliteration: 'Ventaamai Anna Vizhuchchelvam Eentillai Aantum Aqdhoppadhu Il', english_meaning: 'There is in this world no excellence equal to freedom from desire; and even in that world, there is nothing like it', career_application: 'There is in this world no excellence equal to freedom from desire; and even in that world, there is nothing like it', chapter: 'Curbing of Desire' },
  { id: 364, kural_number: 364, tamil_text: 'தூஉய்மை என்பது அவாவின்மை மற்றது வாஅய்மை வேண்ட வரும்.', transliteration: 'Thoouymai Enpadhu Avaavinmai Matradhu Vaaaimai Venta Varum', english_meaning: 'Purity (of mind) consists in freedom from desire; and that (freedom from desire) is the fruit of the love of truth', career_application: 'Purity (of mind) consists in freedom from desire; and that (freedom from desire) is the fruit of the love of truth', chapter: 'Curbing of Desire' },
  { id: 365, kural_number: 365, tamil_text: 'அற்றவர் என்பார் அவாஅற்றார் மற்றையார் அற்றாக அற்றது இலர்.', transliteration: 'Atravar Enpaar Avaaatraar Matraiyaar Atraaka Atradhu Ilar', english_meaning: 'They are said to be free (from future birth) who are freed from desire; all others (who, whatever else they may be free from, are not freed from desire) are not thus free', career_application: 'They are said to be free (from future birth) who are freed from desire; all others (who, whatever else they may be free from, are not freed from desire) are not thus free', chapter: 'Curbing of Desire' },
  { id: 366, kural_number: 366, tamil_text: 'அஞ்சுவ தோரும் அறனே ஒருவனை வஞ்சிப்ப தோரும் அவா.', transliteration: 'Anjuva Thorum Arane Oruvanai Vanjippa Thorum Avaa', english_meaning: 'It is the chief duty of (an ascetic) to watch against desire with (jealous) fear; for it has power to deceive (and destroy) him', career_application: 'It is the chief duty of (an ascetic) to watch against desire with (jealous) fear; for it has power to deceive (and destroy) him', chapter: 'Curbing of Desire' },
  { id: 367, kural_number: 367, tamil_text: 'அவாவினை ஆற்ற அறுப்பின் தவாவினை தான்வேண்டு மாற்றான் வரும்.', transliteration: 'Avaavinai Aatra Aruppin Thavaavinai Thaanventu Maatraan Varum', english_meaning: 'If a man thoroughly cut off all desire, the deeds, which confer immortality, will come to him, in the path in which he seeks them', career_application: 'If a man thoroughly cut off all desire, the deeds, which confer immortality, will come to him, in the path in which he seeks them', chapter: 'Curbing of Desire' },
  { id: 368, kural_number: 368, tamil_text: 'அவாஇல்லார்க் கில்லாகுந் துன்பம் அஃதுண்டேல் தவாஅது மேன்மேல் வரும்.', transliteration: 'Avaaillaark Killaakun Thunpam Aqdhuntel Thavaaadhu Menmel Varum', english_meaning: 'There is no sorrow to those who are without desire; but where that is, (sorrow) will incessantly come, more and more', career_application: 'There is no sorrow to those who are without desire; but where that is, (sorrow) will incessantly come, more and more', chapter: 'Curbing of Desire' },
  { id: 369, kural_number: 369, tamil_text: 'இன்பம் இடையறா தீண்டும் அவாவென்னும் துன்பத்துள் துன்பங் கெடின்.', transliteration: 'Inpam Itaiyaraa Theentum Avaavennum Thunpaththul Thunpang Ketin', english_meaning: 'Even while in this body, joy will never depart (from the mind, in which) desire, that sorrow of sorrows, has been destroyed', career_application: 'Even while in this body, joy will never depart (from the mind, in which) desire, that sorrow of sorrows, has been destroyed', chapter: 'Curbing of Desire' },
  { id: 370, kural_number: 370, tamil_text: 'ஆரா இயற்கை அவாநீப்பின் அந்நிலையே பேரா இயற்கை தரும்.', transliteration: 'Aaraa Iyarkai Avaaneeppin Annilaiye Peraa Iyarkai Tharum', english_meaning: 'The removal of desire, whose nature it is never to be satisfied, will immediately confer a nature that can never be changed', career_application: 'The removal of desire, whose nature it is never to be satisfied, will immediately confer a nature that can never be changed', chapter: 'Curbing of Desire' },
  { id: 371, kural_number: 371, tamil_text: 'ஆகூழால் தோன்றும் அசைவின்மை கைப்பொருள் போகூழால் தோன்றும் மடி.', transliteration: 'Aakoozhaal Thondrum Asaivinmai Kaipporul Pokoozhaal Thondrum Mati', english_meaning: 'Perseverance comes from a prosperous fate, and idleness from an adverse fate', career_application: 'Perseverance comes from a prosperous fate, and idleness from an adverse fate', chapter: 'Fate' },
  { id: 372, kural_number: 372, tamil_text: 'பேதைப் படுக்கும் இழவூழ் அறிவகற்றும் ஆகலூழ் உற்றக் கடை.', transliteration: 'Pedhaip Patukkum Izhavoozh Arivakatrum Aakaloozh Utrak Katai', english_meaning: 'An adverse fate produces folly, and a prosperous fate produces enlarged knowledge', career_application: 'An adverse fate produces folly, and a prosperous fate produces enlarged knowledge', chapter: 'Fate' },
  { id: 373, kural_number: 373, tamil_text: 'நுண்ணிய நூல்பல கற்பினும் மற்றுந்தன் உண்மை யறிவே மிகும்.', transliteration: 'Nunniya Noolpala Karpinum Matrundhan Unmai Yarive Mikum', english_meaning: 'Although (a man) may study the most polished treatises, the knowledge which fate has decreed to him will still prevail', career_application: 'Although (a man) may study the most polished treatises, the knowledge which fate has decreed to him will still prevail', chapter: 'Fate' },
  { id: 374, kural_number: 374, tamil_text: 'இருவேறு உலகத்து இயற்கை திருவேறு தெள்ளிய ராதலும் வேறு.', transliteration: 'Iruveru Ulakaththu Iyarkai Thiruveru Thelliya Raadhalum Veru', english_meaning: 'There are (through fate) two different natures in the world, hence the difference (observable in men) in (their acquisition of) wealth, and in their attainment of knowledge', career_application: 'There are (through fate) two different natures in the world, hence the difference (observable in men) in (their acquisition of) wealth, and in their attainment of knowledge', chapter: 'Fate' },
  { id: 375, kural_number: 375, tamil_text: 'நல்லவை எல்லாஅந் தீயவாம் தீயவும் நல்லவாம் செல்வம் செயற்கு.', transliteration: 'Nallavai Ellaaan Theeyavaam Theeyavum Nallavaam Selvam Seyarku', english_meaning: 'In the acquisition of property, every thing favourable becomes unfavourable, and (on the other hand) everything unfavourable becomes favourable, (through the power of fate)', career_application: 'In the acquisition of property, every thing favourable becomes unfavourable, and (on the other hand) everything unfavourable becomes favourable, (through the power of fate)', chapter: 'Fate' },
  { id: 376, kural_number: 376, tamil_text: 'பரியினும் ஆகாவாம் பாலல்ல உய்த்துச் சொரியினும் போகா தம.', transliteration: 'Pariyinum Aakaavaam Paalalla Uyththuch Choriyinum Pokaa Thama', english_meaning: 'Whatever is not conferred by fate cannot be preserved although it be guarded with most painful care; and that, which fate has made his, cannot be lost, although one should even take it and throw it away', career_application: 'Whatever is not conferred by fate cannot be preserved although it be guarded with most painful care; and that, which fate has made his, cannot be lost, although one should even take it and throw it away', chapter: 'Fate' },
  { id: 377, kural_number: 377, tamil_text: 'வகுத்தான் வகுத்த வகையல்லால் கோடி தொகுத்தார்க்கு துய்த்தல் அரிது.', transliteration: 'Vakuththaan Vakuththa Vakaiyallaal Koti Thokuththaarkku Thuyththal Aridhu', english_meaning: 'Even those who gather together millions will only enjoy them, as it has been determined by the disposer (of all things)', career_application: 'Even those who gather together millions will only enjoy them, as it has been determined by the disposer (of all things)', chapter: 'Fate' },
  { id: 378, kural_number: 378, tamil_text: 'துறப்பார்மன் துப்புர வில்லார் உறற்பால ஊட்டா கழியு மெனின்.', transliteration: 'Thurappaarman Thuppura Villaar Urarpaala Oottaa Kazhiyu Menin', english_meaning: 'The destitute will renounce desire (and become ascetics), if (fate) do not make them suffer the hindrances to which they are liable, and they pass away', career_application: 'The destitute will renounce desire (and become ascetics), if (fate) do not make them suffer the hindrances to which they are liable, and they pass away', chapter: 'Fate' },
  { id: 379, kural_number: 379, tamil_text: 'நன்றாங்கால் நல்லவாக் காண்பவர் அன்றாங்கால் அல்லற் படுவ தெவன்?', transliteration: 'Nandraangaal Nallavaak Kaanpavar Andraangaal Allar Patuva Thevan?', english_meaning: 'How is it that those, who are pleased with good fortune, trouble themselves when evil comes, (since both are equally the decree of fate) ?', career_application: 'How is it that those, who are pleased with good fortune, trouble themselves when evil comes, (since both are equally the decree of fate) ?', chapter: 'Fate' },
  { id: 380, kural_number: 380, tamil_text: 'ஊழிற் பெருவலி யாவுள மற்றொன்று சூழினுந் தான்முந் துறும்.', transliteration: 'Oozhir Peruvali Yaavula Matrondru Soozhinun Thaanmun Thurum', english_meaning: 'What is stronger than fate ? If we think of an expedient (to avert it), it will itself be with us before (the thought)', career_application: 'What is stronger than fate ? If we think of an expedient (to avert it), it will itself be with us before (the thought)', chapter: 'Fate' },
  { id: 381, kural_number: 381, tamil_text: 'படைகுடி கூழ்அமைச்சு நட்பரண் ஆறும் உடையான் அரசருள் ஏறு.', transliteration: 'Pataikuti Koozhamaichchu Natparan Aarum Utaiyaan Arasarul Eru', english_meaning: 'He who possesses these six things, an army, a people, wealth, ministers, friends and a fortress, is a lion among kings', career_application: 'He who possesses these six things, an army, a people, wealth, ministers, friends and a fortress, is a lion among kings', chapter: 'The Greatness of a King' },
  { id: 382, kural_number: 382, tamil_text: 'அஞ்சாமை ஈகை அறிவூக்கம் இந்நான்கும் எஞ்சாமை வேந்தர்க் கியல்பு.', transliteration: 'Anjaamai Eekai Arivookkam Innaankum Enjaamai Vendhark Kiyalpu', english_meaning: 'Never to fail in these four things, fearlessness, liberality, wisdom, and energy, is the kingly character', career_application: 'Never to fail in these four things, fearlessness, liberality, wisdom, and energy, is the kingly character', chapter: 'The Greatness of a King' },
  { id: 383, kural_number: 383, tamil_text: 'தூங்காமை கல்வி துணிவுடைமை இம்மூன்றும் நீங்கா நிலனான் பவர்க்கு.', transliteration: 'Thoongaamai Kalvi Thunivutaimai Immoondrum Neengaa Nilanaan Pavarkku', english_meaning: 'These three things, viz, vigilance, learning, and bravery, should never be wanting in the ruler of a country', career_application: 'These three things, viz, vigilance, learning, and bravery, should never be wanting in the ruler of a country', chapter: 'The Greatness of a King' },
  { id: 384, kural_number: 384, tamil_text: 'அறனிழுக்கா தல்லவை நீக்கி மறனிழுக்கா மானம் உடைய தரசு.', transliteration: 'Aranizhukkaa Thallavai Neekki Maranizhukkaa Maanam Utaiya Tharasu', english_meaning: 'He is a king who, with manly modesty, swerves not from virtue, and refrains from vice', career_application: 'He is a king who, with manly modesty, swerves not from virtue, and refrains from vice', chapter: 'The Greatness of a King' },
  { id: 385, kural_number: 385, tamil_text: 'இயற்றலும் ஈட்டலுங் காத்தலும் காத்த வகுத்தலும் வல்ல தரசு.', transliteration: 'Iyatralum Eettalung Kaaththalum Kaaththa Vakuththalum Valla Tharasu', english_meaning: 'He is a king who is able to acquire (wealth), to lay it up, to guard, and to distribute it', career_application: 'He is a king who is able to acquire (wealth), to lay it up, to guard, and to distribute it', chapter: 'The Greatness of a King' },
  { id: 386, kural_number: 386, tamil_text: 'காட்சிக் கெளியன் கடுஞ்சொல்லன் அல்லனேல் மீக்கூறும் மன்னன் நிலம்', transliteration: 'Kaatchik Keliyan Katunjollan Allanel Meekkoorum Mannan Nilam', english_meaning: 'The whole world will exalt the country of the king who is easy of access, and who is free from harsh language', career_application: 'The whole world will exalt the country of the king who is easy of access, and who is free from harsh language', chapter: 'The Greatness of a King' },
  { id: 387, kural_number: 387, tamil_text: 'இன்சொலால் ஈத்தளிக்க வல்லார்க்குத் தன்சொலால் தான்கண் டனைத்திவ் வுலகு.', transliteration: 'Insolaal Eeththalikka Vallaarkkuth Thansolaal Thaankan Tanaiththiv Vulaku', english_meaning: 'The world will praise and submit itself to the mind of the king who is able to give with affability, and to protect all who come to him', career_application: 'The world will praise and submit itself to the mind of the king who is able to give with affability, and to protect all who come to him', chapter: 'The Greatness of a King' },
  { id: 388, kural_number: 388, tamil_text: 'முறைசெய்து காப்பாற்றும் மன்னவன் மக்கட்கு இறையென்று வைக்கப் படும்.', transliteration: 'Muraiseydhu Kaappaatrum Mannavan Makkatku Iraiyendru Vaikkap Patum', english_meaning: 'That king, will be esteemed a God among men, who performs his own duties, and protects (his subjects).', career_application: 'That king, will be esteemed a God among men, who performs his own duties, and protects (his subjects).', chapter: 'The Greatness of a King' },
  { id: 389, kural_number: 389, tamil_text: 'செவிகைப்பச் சொற்பொறுக்கும் பண்புடை வேந்தன் கவிகைக்கீழ்த் தங்கும் உலகு.', transliteration: 'Sevikaippach Chorporukkum Panputai Vendhan Kavikaikkeezhth Thangum Ulaku', english_meaning: 'The whole world will dwell under the umbrella of the king, who can bear words that embitter the ear', career_application: 'The whole world will dwell under the umbrella of the king, who can bear words that embitter the ear', chapter: 'The Greatness of a King' },
  { id: 390, kural_number: 390, tamil_text: 'கொடையளி செங்கோல் குடியோம்பல் நான்கும் உடையானாம் வேந்தர்க் கொளி.', transliteration: 'Kotaiyali Sengol Kutiyompal Naankum Utaiyaanaam Vendhark Koli', english_meaning: 'He is the light of kings who has there four things, beneficence, benevolence, rectitude, and care for his people', career_application: 'He is the light of kings who has there four things, beneficence, benevolence, rectitude, and care for his people', chapter: 'The Greatness of a King' },
  { id: 391, kural_number: 391, tamil_text: 'கற்க கசடறக் கற்பவை கற்றபின் நிற்க அதற்குத் தக.', transliteration: 'Karka Kasatarak Karpavai Katrapin Nirka Adharkuth Thaka', english_meaning: 'Let a man learn thoroughly whatever he may learn, and let his conduct be worthy of his learning', career_application: 'Let a man learn thoroughly whatever he may learn, and let his conduct be worthy of his learning', chapter: 'Learning' },
  { id: 392, kural_number: 392, tamil_text: 'எண்ணென்ப ஏனை எழுத்தென்ப இவ்விரண்டும் கண்ணென்ப வாழும் உயிர்க்கு.', transliteration: 'Ennenpa Enai Ezhuththenpa Ivvirantum Kannenpa Vaazhum Uyirkku', english_meaning: 'Letters and numbers are the two eyes of man', career_application: 'Letters and numbers are the two eyes of man', chapter: 'Learning' },
  { id: 393, kural_number: 393, tamil_text: 'கண்ணுடையர் என்பவர் கற்றோர் முகத்திரண்டு புண்ணுடையர் கல்லா தவர்.', transliteration: 'Kannutaiyar Enpavar Katror Mukaththirantu Punnutaiyar Kallaa Thavar', english_meaning: 'The learned are said to have eyes, but the unlearned have (merely) two sores in their face', career_application: 'The learned are said to have eyes, but the unlearned have (merely) two sores in their face', chapter: 'Learning' },
  { id: 394, kural_number: 394, tamil_text: 'உவப்பத் தலைக்கூடி உள்ளப் பிரிதல் அனைத்தே புலவர் தொழில்.', transliteration: 'Uvappath Thalaikkooti Ullap Piridhal Anaiththe Pulavar Thozhil', english_meaning: 'It is the part of the learned to give joy to those whom they meet, and on leaving, to make them think (Oh! when shall we meet them again.)', career_application: 'It is the part of the learned to give joy to those whom they meet, and on leaving, to make them think (Oh! when shall we meet them again.)', chapter: 'Learning' },
  { id: 395, kural_number: 395, tamil_text: 'உடையார்முன் இல்லார்போல் ஏக்கற்றுங் கற்றார் கடையரே கல்லா தவர்.', transliteration: 'Utaiyaarmun Illaarpol Ekkatrung Katraar Kataiyare Kallaa Thavar', english_meaning: 'The unlearned are inferior to the learned, before whom they stand begging, as the destitute before the wealthy', career_application: 'The unlearned are inferior to the learned, before whom they stand begging, as the destitute before the wealthy', chapter: 'Learning' },
  { id: 396, kural_number: 396, tamil_text: 'தொட்டனைத் தூறும் மணற்கேணி மாந்தர்க்குக் கற்றனைத் தூறும் அறிவு.', transliteration: 'Thottanaith Thoorum Manarkeni Maandharkkuk Katranaith Thoorum Arivu', english_meaning: 'Water will flow from a well in the sand in proportion to the depth to which it is dug, and knowledge will flow from a man in proportion to his learning', career_application: 'Water will flow from a well in the sand in proportion to the depth to which it is dug, and knowledge will flow from a man in proportion to his learning', chapter: 'Learning' },
  { id: 397, kural_number: 397, tamil_text: 'யாதானும் நாடாமால் ஊராமால் என்னொருவன் சாந்துணையுங் கல்லாத வாறு.', transliteration: 'Yaadhaanum Naataamaal Ooraamaal Ennoruvan Saandhunaiyung Kallaadha Vaaru', english_meaning: 'How is it that any one can remain without learning, even to his death, when (to the learned man) every country is his own (country), and every town his own (town) ?', career_application: 'How is it that any one can remain without learning, even to his death, when (to the learned man) every country is his own (country), and every town his own (town) ?', chapter: 'Learning' },
  { id: 398, kural_number: 398, tamil_text: 'ஒருமைக்கண் தான்கற்ற கல்வி ஒருவற்கு எழுமையும் ஏமாப் புடைத்து.', transliteration: 'Orumaikkan Thaan Katra Kalvi Oruvarku Ezhumaiyum Emaap Putaiththu', english_meaning: 'The learning, which a man has acquired in one birth, will yield him pleasure during seven births', career_application: 'The learning, which a man has acquired in one birth, will yield him pleasure during seven births', chapter: 'Learning' },
  { id: 399, kural_number: 399, tamil_text: 'தாமின் புறுவது உலகின் புறக்கண்டு காமுறுவர் கற்றறிந் தார்.', transliteration: 'Thaamin Puruvadhu Ulakin Purak Kantu Kaamuruvar Katrarin Thaar', english_meaning: 'The learned will long (for more learning), when they see that while it gives pleasure to themselves, the world also derives pleasure from it', career_application: 'The learned will long (for more learning), when they see that while it gives pleasure to themselves, the world also derives pleasure from it', chapter: 'Learning' },
  { id: 400, kural_number: 400, tamil_text: 'கேடில் விழுச்செல்வம் கல்வி யொருவற்கு மாடல்ல மற்றை யவை.', transliteration: 'Ketil Vizhuchchelvam Kalvi Yoruvarku Maatalla Matrai Yavai', english_meaning: 'Learning is the true imperishable riches; all other things are not riches', career_application: 'Learning is the true imperishable riches; all other things are not riches', chapter: 'Learning' },
  { id: 401, kural_number: 401, tamil_text: 'அரங்கின்றி வட்டாடி யற்றே நிரம்பிய நூலின்றிக் கோட்டி கொளல்.', transliteration: 'Arangindri Vattaati Yatre Nirampiya Noolindrik Kotti Kolal', english_meaning: 'To speak in an assembly (of the learned) without fullness of knowledge, is like playing at chess (on a board) without squares', career_application: 'To speak in an assembly (of the learned) without fullness of knowledge, is like playing at chess (on a board) without squares', chapter: 'Ignorance' },
  { id: 402, kural_number: 402, tamil_text: 'கல்லாதான் சொற்கா முறுதல் முலையிரண்டும் இல்லாதாள் பெண்காமுற் றற்று.', transliteration: 'Kallaadhaan Sorkaa Murudhal Mulaiyirantum Illaadhaal Penkaamur Ratru', english_meaning: 'The desire of the unlearned to speak (in an assembly), is like a woman without breasts desiring (the enjoyment of ) woman-hood', career_application: 'The desire of the unlearned to speak (in an assembly), is like a woman without breasts desiring (the enjoyment of ) woman-hood', chapter: 'Ignorance' },
  { id: 403, kural_number: 403, tamil_text: 'கல்லா தவரும் நனிநல்லர் கற்றார்முன் சொல்லா திருக்கப் பெறின்.', transliteration: 'Kallaa Thavarum Naninallar Katraarmun Sollaa Thirukkap Perin', english_meaning: 'The unlearned also are very excellent men, if they know how to keep silence before the learned', career_application: 'The unlearned also are very excellent men, if they know how to keep silence before the learned', chapter: 'Ignorance' },
  { id: 404, kural_number: 404, tamil_text: 'கல்லாதான் ஒட்பம் கழியநன் றாயினும் கொள்ளார் அறிவுடை யார்.', transliteration: 'Kallaadhaan Otpam Kazhiyanan Raayinum Kollaar Arivutai Yaar', english_meaning: 'Although the natural knowledge of an unlearned man may be very good, the wise will not accept for true knowledge', career_application: 'Although the natural knowledge of an unlearned man may be very good, the wise will not accept for true knowledge', chapter: 'Ignorance' },
  { id: 405, kural_number: 405, tamil_text: 'கல்லா ஒருவன் தகைமை தலைப்பெய்து சொல்லாடச் சோர்வு படும்.', transliteration: 'Kallaa Oruvan Thakaimai Thalaippeydhu Sollaatach Chorvu Patum', english_meaning: 'The self-conceit of an unlearned man will fade away, as soon as he speaks in an assembly (of', career_application: 'The self-conceit of an unlearned man will fade away, as soon as he speaks in an assembly (of', chapter: 'Ignorance' },
  { id: 406, kural_number: 406, tamil_text: 'உளரென்னும் மாத்திரையர் அல்லால் பயவாக் களரனையர் கல்லா தவர்.', transliteration: 'Ularennum Maaththiraiyar Allaal Payavaak Kalaranaiyar Kallaa Thavar', english_meaning: 'The unlearned are like worthless barren land: all that can be said of them is, that they exist', career_application: 'The unlearned are like worthless barren land: all that can be said of them is, that they exist', chapter: 'Ignorance' },
  { id: 407, kural_number: 407, tamil_text: 'நுண்மாண் நுழைபுலம் இல்லான் எழில்நலம் மண்மாண் புனைபாவை யற்று.', transliteration: 'Nunmaan Nuzhaipulam Illaan Ezhilnalam Manmaan Punaipaavai Yatru', english_meaning: 'The beauty and goodness of one who is destitute of knowledge by the study of great and exquisite works, is like (the beauty and goodness) of a painted earthen doll', career_application: 'The beauty and goodness of one who is destitute of knowledge by the study of great and exquisite works, is like (the beauty and goodness) of a painted earthen doll', chapter: 'Ignorance' },
  { id: 408, kural_number: 408, tamil_text: 'நல்லார்கண் பட்ட வறுமையின் இன்னாதே கல்லார்கண் பட் ட திரு.', transliteration: 'Nallaarkan Patta Varumaiyin Innaadhe Kallaarkan Patta Thiru', english_meaning: 'Wealth, gained by the unlearned, will give more sorrow than the poverty which may come upon the learned', career_application: 'Wealth, gained by the unlearned, will give more sorrow than the poverty which may come upon the learned', chapter: 'Ignorance' },
  { id: 409, kural_number: 409, tamil_text: 'மேற்பிறந்தா ராயினும் கல்லாதார் கீழ்ப்பிறந்தும் கற்றார் அனைத்திலர் பாடு.', transliteration: 'Merpirandhaa Raayinum Kallaadhaar Keezhppirandhum Katraar Anaiththilar Paatu', english_meaning: 'The unlearned, though born in a high caste, are not equal in dignity to the learned; though they may have been born in a low caste', career_application: 'The unlearned, though born in a high caste, are not equal in dignity to the learned; though they may have been born in a low caste', chapter: 'Ignorance' },
  { id: 410, kural_number: 410, tamil_text: 'விலங்கொடு மக்கள் அனையர் இலங்குநூல் கற்றாரோடு ஏனை யவர்.', transliteration: 'Vilangotu Makkal Anaiyar Ilangunool Katraarotu Enai Yavar', english_meaning: 'As beasts by the side of men, so are other men by the side of those who are learned in celebrated works', career_application: 'As beasts by the side of men, so are other men by the side of those who are learned in celebrated works', chapter: 'Ignorance' },
  { id: 411, kural_number: 411, tamil_text: 'செல்வத்துட் செல்வஞ் செவிச்செல்வம் அச்செல்வம் செல்வத்து ளெல்லாந் தலை.', transliteration: 'Selvaththut Selvanj Chevichchelvam Achchelvam Selvaththu Lellaan Thalai', english_meaning: 'Wealth (gained) by the ear is wealth of wealth; that wealth is the chief of all wealth', career_application: 'Wealth (gained) by the ear is wealth of wealth; that wealth is the chief of all wealth', chapter: 'Hearing' },
  { id: 412, kural_number: 412, tamil_text: 'செவுக்குண வில்லாத போழ்து சிறிது வயிற்றுக்கும் ஈயப் படும்.', transliteration: 'Sevikkuna Villaadha Pozhdhu Siridhu Vayitrukkum Eeyap Patum', english_meaning: 'When there is no food for the ear, give a little also to the stomach', career_application: 'When there is no food for the ear, give a little also to the stomach', chapter: 'Hearing' },
  { id: 413, kural_number: 413, tamil_text: 'செவியுணவிற் கேள்வி யுடையார் அவியுணவின் ஆன்றாரோ டொப்பர் நிலத்து.', transliteration: 'Seviyunavir Kelvi Yutaiyaar Aviyunavin Aandraaro Toppar Nilaththu', english_meaning: 'Those who in this world enjoy instruction which is the food of the ear, are equal to the Gods, who enjoy the food of the sacrifices', career_application: 'Those who in this world enjoy instruction which is the food of the ear, are equal to the Gods, who enjoy the food of the sacrifices', chapter: 'Hearing' },
  { id: 414, kural_number: 414, tamil_text: 'கற்றில னாயினுங் கேட்க அஃதொருவற்கு ஒற்கத்தின் ஊற்றாந் துணை.', transliteration: 'Katrila Naayinung Ketka Aqdhoruvarku Orkaththin Ootraan Thunai', english_meaning: 'Although a man be without learning, let him listen (to the teaching of the learned); that will be to him a staff in adversity', career_application: 'Although a man be without learning, let him listen (to the teaching of the learned); that will be to him a staff in adversity', chapter: 'Hearing' },
  { id: 415, kural_number: 415, tamil_text: 'இழுக்கல் உடையுழி ஊற்றுக்கோல் அற்றே ஒழுக்க முடையார்வாய்ச் சொல்.', transliteration: 'Izhukkal Utaiyuzhi Ootrukkol Atre Ozhukka Mutaiyaarvaaich Chol', english_meaning: 'The words of the good are like a staff in a slippery place', career_application: 'The words of the good are like a staff in a slippery place', chapter: 'Hearing' },
  { id: 416, kural_number: 416, tamil_text: 'எனைத்தானும் நல்லவை கேட்க அனைத்தானும் ஆன்ற பெருமை தரும்.', transliteration: 'Enaiththaanum Nallavai Ketka Anaiththaanum Aandra Perumai Tharum', english_meaning: 'Let a man listen, never so little, to good (instruction), even that will bring him great dignity', career_application: 'Let a man listen, never so little, to good (instruction), even that will bring him great dignity', chapter: 'Hearing' },
  { id: 417, kural_number: 417, tamil_text: 'பிழைத்துணர்ந்தும் பேதைமை சொல்லா ரிழைத்துணர்ந் தீண்டிய கேள்வி யவர்.', transliteration: 'Pizhaith Thunarndhum Pedhaimai Sollaa Rizhaiththunarn Theentiya Kelvi Yavar', english_meaning: 'Not even when they have imperfectly understood (a matter), will those men speak foolishly, who have profoundly studied and diligently listened (to instruction)', career_application: 'Not even when they have imperfectly understood (a matter), will those men speak foolishly, who have profoundly studied and diligently listened (to instruction)', chapter: 'Hearing' },
  { id: 418, kural_number: 418, tamil_text: 'கேட்பினுங் கேளாத் தகையவே கேள்வியால் தோட்கப் படாத செவி.', transliteration: 'Ketpinung Kelaath Thakaiyave Kelviyaal Thotkap Pataadha Sevi', english_meaning: 'The ear which has not been bored by instruction, although it hears, is deaf', career_application: 'The ear which has not been bored by instruction, although it hears, is deaf', chapter: 'Hearing' },
  { id: 419, kural_number: 419, tamil_text: 'நுணங்கிய கேள்விய ரல்லார் வணங்கிய வாயின ராதல் அரிது.', transliteration: 'Nunangiya Kelviya Rallaar Vanangiya Vaayina Raadhal Aridhu', english_meaning: 'It is a rare thing to find modesty, a reverend mouth- with those who have not received choice instruction', career_application: 'It is a rare thing to find modesty, a reverend mouth- with those who have not received choice instruction', chapter: 'Hearing' },
  { id: 420, kural_number: 420, tamil_text: 'செவியிற் சுவையுணரா வாயுணர்வின் மாக்கள் அவியினும் வாழினும் என்?', transliteration: 'Seviyir Suvaiyunaraa Vaayunarvin Maakkal Aviyinum Vaazhinum En?', english_meaning: 'What does it matter whether those men live or die, who can judge of tastes by the mouth, and not by the ear ?', career_application: 'What does it matter whether those men live or die, who can judge of tastes by the mouth, and not by the ear ?', chapter: 'Hearing' },
  { id: 421, kural_number: 421, tamil_text: 'அறிவற்றங் காக்குங் கருவி செறுவார்க்கும் உள்ளழிக்க லாகா அரண்.', transliteration: 'Arivatrang Kaakkung Karuvi Seruvaarkkum Ullazhikka Laakaa Aran', english_meaning: 'Wisdom is a weapon to ward off destruction; it is an inner fortress which enemies cannot destroy', career_application: 'Wisdom is a weapon to ward off destruction; it is an inner fortress which enemies cannot destroy', chapter: 'The Possession of Knowledge' },
  { id: 422, kural_number: 422, tamil_text: 'சென்ற இடத்தால் செலவிடா தீதொரீஇ நன்றின்பால் உய்ப்ப தறிவு.', transliteration: 'Sendra Itaththaal Selavitaa Theedhoreei Nandrinpaal Uyppa Tharivu', english_meaning: 'Not to permit the mind to go where it lists, to keep it from evil, and to employ it in good, this is wisdom', career_application: 'Not to permit the mind to go where it lists, to keep it from evil, and to employ it in good, this is wisdom', chapter: 'The Possession of Knowledge' },
  { id: 423, kural_number: 423, tamil_text: 'எப்பொருள் யார்யார்வாய்க் கேட்பினும் அப்பொருள் மெய்ப்பொருள் காண்ப தறிவு.', transliteration: 'Epporul Yaaryaarvaaik Ketpinum Apporul Meypporul Kaanpa Tharivu', english_meaning: 'To discern the truth in every thing, by whomsoever spoken, is wisdom', career_application: 'To discern the truth in every thing, by whomsoever spoken, is wisdom', chapter: 'The Possession of Knowledge' },
  { id: 424, kural_number: 424, tamil_text: 'எண்பொருள வாகச் செலச்சொல்லித் தான்பிறர்வாய் நுண்பொருள் காண்ப தறிவு.', transliteration: 'Enporula Vaakach Chelachchollith Thaanpirarvaai Nunporul Kaanpa Tharivu', english_meaning: 'To speak so as that the meaning may easily enter the mind of the hearer, and to discern the subtlest thought which may lie hidden in the words of others, this is wisdom', career_application: 'To speak so as that the meaning may easily enter the mind of the hearer, and to discern the subtlest thought which may lie hidden in the words of others, this is wisdom', chapter: 'The Possession of Knowledge' },
  { id: 425, kural_number: 425, tamil_text: 'உலகம் தழீஇய தொட்பம் மலர்தலும் கூம்பலும் இல்ல தறிவு.', transliteration: 'Ulakam Thazheeiya Thotpam Malardhalum Koompalum Illa Tharivu', english_meaning: 'To secure the friendship of the great is true wisdom; it is (also) wisdom to keep (that friendship unchanged, and) not opening and closing (like the lotus flower)', career_application: 'To secure the friendship of the great is true wisdom; it is (also) wisdom to keep (that friendship unchanged, and) not opening and closing (like the lotus flower)', chapter: 'The Possession of Knowledge' },
  { id: 426, kural_number: 426, tamil_text: 'எவ்வ துறைவது உலகம் உலகத்தோடு அவ்வ துறைவ தறிவு.', transliteration: 'Evva Thuraivadhu Ulakam Ulakaththotu Avva Thuraiva Tharivu', english_meaning: 'To live as the world lives, is wisdom', career_application: 'To live as the world lives, is wisdom', chapter: 'The Possession of Knowledge' },
  { id: 427, kural_number: 427, tamil_text: 'அறிவுடையார் ஆவ தறிவார் அறிவிலார் அஃதறி கல்லா தவர்.', transliteration: 'Arivutaiyaar Aava Tharivaar Arivilaar Aqdhari Kallaa Thavar', english_meaning: 'The wise are those who know beforehand what will happen; those who do not know this are the unwise', career_application: 'The wise are those who know beforehand what will happen; those who do not know this are the unwise', chapter: 'The Possession of Knowledge' },
  { id: 428, kural_number: 428, tamil_text: 'அஞ்சுவ தஞ்சாமை பேதைமை அஞ்சுவது அஞ்சல் அறிவார் தொழில்.', transliteration: 'Anjuva Thanjaamai Pedhaimai Anjuvadhu Anjal Arivaar Thozhil', english_meaning: 'Not to fear what ought to be feared, is folly; it is the work of the wise to fear what should be feared', career_application: 'Not to fear what ought to be feared, is folly; it is the work of the wise to fear what should be feared', chapter: 'The Possession of Knowledge' },
  { id: 429, kural_number: 429, tamil_text: 'எதிரதாக் காக்கும் அறிவினார்க் கில்லை அதிர வருவதோர் நோய்.', transliteration: 'Edhiradhaak Kaakkum Arivinaark Killai Adhira Varuvadhor Noi', english_meaning: 'No terrifying calamity will happen to the wise, who (foresee) and guard against coming evils', career_application: 'No terrifying calamity will happen to the wise, who (foresee) and guard against coming evils', chapter: 'The Possession of Knowledge' },
  { id: 430, kural_number: 430, tamil_text: 'அறிவுடையார் எல்லா முடையார் அறிவிலார் என்னுடைய ரேனும் இலர்.', transliteration: 'Arivutaiyaar Ellaa Mutaiyaar Arivilaar Ennutaiya Renum Ilar', english_meaning: 'Those who possess wisdom, possess every thing; those who have not wisdom, whatever they may possess, have nothing', career_application: 'Those who possess wisdom, possess every thing; those who have not wisdom, whatever they may possess, have nothing', chapter: 'The Possession of Knowledge' },
  { id: 431, kural_number: 431, tamil_text: 'செருக்குஞ் சினமும் சிறுமையும் இல்லார் பெருக்கம் பெருமித நீர்த்து.', transliteration: 'Serukkunj Chinamum Sirumaiyum Illaar Perukkam Perumidha Neerththu', english_meaning: 'Truly great is the excellence of those (kings) who are free from pride, anger, and lust', career_application: 'Truly great is the excellence of those (kings) who are free from pride, anger, and lust', chapter: 'The Correction of Faults' },
  { id: 432, kural_number: 432, tamil_text: 'இவறலும் மாண்பிறந்த மானமும் மாணா உவகையும் ஏதம் இறைக்கு.', transliteration: 'Ivaralum Maanpirandha Maanamum Maanaa Uvakaiyum Edham Iraikku', english_meaning: 'Avarice, undignified pride, and low pleasures are faults in a king', career_application: 'Avarice, undignified pride, and low pleasures are faults in a king', chapter: 'The Correction of Faults' },
  { id: 433, kural_number: 433, tamil_text: 'தினைத்துணையாங் குற்றம் வரினும் பனைத்துணையாக் கொள்வர் பழிநாணு வார்.', transliteration: 'Thinaiththunaiyaang Kutram Varinum Panaiththunaiyaak Kolvar Pazhinaanu Vaar', english_meaning: 'Those who fear guilt, if they commit a fault small as a millet seed, will consider it to be as large as a palmyra tree', career_application: 'Those who fear guilt, if they commit a fault small as a millet seed, will consider it to be as large as a palmyra tree', chapter: 'The Correction of Faults' },
  { id: 434, kural_number: 434, tamil_text: 'குற்றமே காக்க பொருளாகக் குற்றமே அற்றந் த்ரூஉம் பகை.', transliteration: 'Kutrame Kaakka Porulaakak Kutrame Atran Tharooum Pakai', english_meaning: 'Guard against faults as a matter (of great consequence; for) faults are a deadly enemy', career_application: 'Guard against faults as a matter (of great consequence; for) faults are a deadly enemy', chapter: 'The Correction of Faults' },
  { id: 435, kural_number: 435, tamil_text: 'வருமுன்னர்க் காவாதான் வாழ்க்கை எரிமுன்னர் வைத்தூறு போலக் கெடும்.', transliteration: 'Varumunnark Kaavaadhaan Vaazhkkai Erimunnar Vaiththooru Polak Ketum', english_meaning: 'The prosperity of him who does not timely guard against faults, will perish like straw before fire', career_application: 'The prosperity of him who does not timely guard against faults, will perish like straw before fire', chapter: 'The Correction of Faults' },
  { id: 436, kural_number: 436, tamil_text: 'தன்குற்றம் நீக்கிப் பிறர்குற்றங் காண்கிற்பின் என்குற்ற மாகும் இறைக்கு?', transliteration: 'Thankutram Neekkip Pirarkutrang Kaankirpin Enkutra Maakum Iraikku?', english_meaning: 'What fault will remain in the king who has put away his own evils, and looks after the evils of others', career_application: 'What fault will remain in the king who has put away his own evils, and looks after the evils of others', chapter: 'The Correction of Faults' },
  { id: 437, kural_number: 437, tamil_text: 'செயற்பால செய்யா திவறியான் செல்வம் உயற்பால தன்றிக் கெடும்.', transliteration: 'Seyarpaala Seyyaa Thivariyaan Selvam Uyarpaala Thandrik Ketum', english_meaning: 'The wealth of the avaricious man, who does not expend it for the purposes for which he ought to expend it will waste away and not continue', career_application: 'The wealth of the avaricious man, who does not expend it for the purposes for which he ought to expend it will waste away and not continue', chapter: 'The Correction of Faults' },
  { id: 438, kural_number: 438, tamil_text: 'பற்றுள்ளம் என்னும் இவறன்மை எற்றுள்ளும் எண்ணப் படுவதொன் றன்று.', transliteration: 'Patrullam Ennum Ivaranmai Etrullum Ennap Patuvadhon Randru', english_meaning: 'Griping avarice is not to be reckoned as one among other faults; (it stands alone - greater than all)', career_application: 'Griping avarice is not to be reckoned as one among other faults; (it stands alone - greater than all)', chapter: 'The Correction of Faults' },
  { id: 439, kural_number: 439, tamil_text: 'வியவற்க எஞ்ஞான்றும் தன்னை நயவற்க நன்றி பயவா வினை.', transliteration: 'Viyavarka Egngnaandrum Thannai Nayavarka Nandri Payavaa Vinai', english_meaning: 'Let no (one) praise himself, at any time; let him not desire to do useless things', career_application: 'Let no (one) praise himself, at any time; let him not desire to do useless things', chapter: 'The Correction of Faults' },
  { id: 440, kural_number: 440, tamil_text: 'காதல காதல் அறியாமை உய்க்கிற்பின் ஏதில ஏதிலார் நூல்.', transliteration: 'Kaadhala Kaadhal Ariyaamai Uykkirpin Edhila Edhilaar Nool', english_meaning: 'If (a king) enjoys, privately the things which he desires, the designs of his enemies will be useless', career_application: 'If (a king) enjoys, privately the things which he desires, the designs of his enemies will be useless', chapter: 'The Correction of Faults' },
  { id: 441, kural_number: 441, tamil_text: 'அறனறிந்து மூத்த அறிவுடையார் கேண்மை திறனறிந்து தேர்ந்து கொளல்.', transliteration: 'Aranarindhu Mooththa Arivutaiyaar Kenmai Thiranarindhu Therndhu Kolal', english_meaning: 'Let (a king) ponder well its value, and secure the friendship of men of virtue and of mature knowledge', career_application: 'Let (a king) ponder well its value, and secure the friendship of men of virtue and of mature knowledge', chapter: 'Seeking the Aid of Great Men' },
  { id: 442, kural_number: 442, tamil_text: 'உற்றநோய் நீக்கி உறாஅமை முற்காக்கும் பெற்றியார்ப் பேணிக் கொளல்.', transliteration: 'Utranoi Neekki Uraaamai Murkaakkum Petriyaarp Penik Kolal', english_meaning: 'Let (a king) procure and kindly care for men who can overcome difficulties when they occur, and guard against them before they happen', career_application: 'Let (a king) procure and kindly care for men who can overcome difficulties when they occur, and guard against them before they happen', chapter: 'Seeking the Aid of Great Men' },
  { id: 443, kural_number: 443, tamil_text: 'அரியவற்று ளெல்லாம் அரிதே பெரியாரைப் பேணித் தமராக் கொளல்.', transliteration: 'Ariyavatru Lellaam Aridhe Periyaaraip Penith Thamaraak Kolal', english_meaning: 'To cherish great men and make them his own, is the most difficult of all difficult things', career_application: 'To cherish great men and make them his own, is the most difficult of all difficult things', chapter: 'Seeking the Aid of Great Men' },
  { id: 444, kural_number: 444, tamil_text: 'தம்மிற் பெரியார் தமரா ஒழுகுதல் வன்மையு ளெல்லாந் தலை.', transliteration: 'Thammir Periyaar Thamaraa Ozhukudhal Vanmaiyu Lellaan Thalai', english_meaning: 'So to act as to make those men, his own, who are greater than himself is of all powers the highest', career_application: 'So to act as to make those men, his own, who are greater than himself is of all powers the highest', chapter: 'Seeking the Aid of Great Men' },
  { id: 445, kural_number: 445, tamil_text: 'சூழ்வார்கண் ணாக ஒழுகலான் மன்னவன் சூழ்வாரைக் சூழ்ந்து கொளல்.', transliteration: 'Soozhvaarkan Naaka Ozhukalaan Mannavan Soozhvaaraik Soozhndhu Kolal', english_meaning: 'As a king must use his ministers as eyes (in managing his kingdom), let him well examine their character and qualifications before he engages them', career_application: 'As a king must use his ministers as eyes (in managing his kingdom), let him well examine their character and qualifications before he engages them', chapter: 'Seeking the Aid of Great Men' },
  { id: 446, kural_number: 446, tamil_text: 'தக்கா ரினத்தனாய்த் தானொழுக வல்லானைச் செற்றார் செயக்கிடந்த தில்.', transliteration: 'Thakkaa Rinaththanaaith Thaanozhuka Vallaanaich Chetraar Seyakkitandha Thil', english_meaning: 'There will be nothing left for enemies to do, against him who has the power of acting (so as to secure) the fellowship of worthy men', career_application: 'There will be nothing left for enemies to do, against him who has the power of acting (so as to secure) the fellowship of worthy men', chapter: 'Seeking the Aid of Great Men' },
  { id: 447, kural_number: 447, tamil_text: 'இடிக்குந் துணையாரை யாள்வரை யாரே கெடுக்குந் தகைமை யவர்.', transliteration: 'Itikkun Thunaiyaarai Yaalvarai Yaare Ketukkun Thakaimai Yavar', english_meaning: 'Who are great enough to destroy him who has servants that have power to rebuke him ?', career_application: 'Who are great enough to destroy him who has servants that have power to rebuke him ?', chapter: 'Seeking the Aid of Great Men' },
  { id: 448, kural_number: 448, tamil_text: 'இடிப்பாரை இல்லாத ஏமரா மன்னன் கெடுப்பா ரிலானுங் கெடும்.', transliteration: 'Itippaarai Illaadha Emaraa Mannan Ketuppaa Rilaanung Ketum', english_meaning: 'The king, who is without the guard of men who can rebuke him, will perish, even though there be no one to destroy him', career_application: 'The king, who is without the guard of men who can rebuke him, will perish, even though there be no one to destroy him', chapter: 'Seeking the Aid of Great Men' },
  { id: 449, kural_number: 449, tamil_text: 'முதலிலார்க ஊதிய மில்லை மதலையாஞ் சார்பிலார்க் கில்லை நிலை.', transliteration: 'Mudhalilaarkku Oodhiya Millai Madhalaiyaanjjch Aarpilaark Killai Nilai', english_meaning: 'There can be no gain to those who have no capital; and in like manner there can be no permanence to', career_application: 'There can be no gain to those who have no capital; and in like manner there can be no permanence to', chapter: 'Seeking the Aid of Great Men' },
  { id: 450, kural_number: 450, tamil_text: 'பல்லார் பகைகொளலிற் பத்தடுத்த தீமைத்தே நல்லார் தொடர்கை விடல்.', transliteration: 'Pallaar Pakai Kolalir Paththatuththa Theemaiththe Nallaar Thotarkai Vital', english_meaning: 'It is tenfold more injurious to abandon the friendship of the good, than to incur the hatred of the many', career_application: 'It is tenfold more injurious to abandon the friendship of the good, than to incur the hatred of the many', chapter: 'Seeking the Aid of Great Men' },
  { id: 451, kural_number: 451, tamil_text: 'சிற்றினம் அஞ்சும் பெருமை சிறுமைதான் சுற்றமாச் சூழ்ந்து விடும்.', transliteration: 'Sitrinam Anjum Perumai Sirumaidhaan Sutramaach Choozhndhu Vitum', english_meaning: '(True) greatness fears the society of the base; it is only the low - minded who will regard them as friends', career_application: '(True) greatness fears the society of the base; it is only the low - minded who will regard them as friends', chapter: 'Avoiding mean Associations' },
  { id: 452, kural_number: 452, tamil_text: 'நிலத்தியல்பால் நீர்திரிந் தற்றாகும் மாந்தர்க்கு இனத்தியல்ப தாகும் அறிவு.', transliteration: 'Nilaththiyalpaal Neerdhirin Thatraakum Maandharkku Inaththiyalpa Thaakum Arivu', english_meaning: 'As water changes (its nature), from the nature of the soil (in which it flows), so will the character of men resemble that of their associates', career_application: 'As water changes (its nature), from the nature of the soil (in which it flows), so will the character of men resemble that of their associates', chapter: 'Avoiding mean Associations' },
  { id: 453, kural_number: 453, tamil_text: 'மனத்தானாம் மாந்தர்க் குணர்ச்சி இனத்தானாம் இன்னான் எனப்படுஞ் சொல்.', transliteration: 'Manaththaanaam Maandhark Kunarchchi Inaththaanaam Innaan Enappatunj Chol', english_meaning: 'The power of knowing is from the mind; (but) his character is from that of his associates', career_application: 'The power of knowing is from the mind; (but) his character is from that of his associates', chapter: 'Avoiding mean Associations' },
  { id: 454, kural_number: 454, tamil_text: 'மனத்து ளதுபோலக் காட்டி ஒருவற்கு இனத்துள தாகும் அறிவு.', transliteration: 'Manaththu Ladhupolak Kaatti Oruvarku Inaththula Thaakum Arivu', english_meaning: 'Wisdom appears to rest in the mind, but it really exists to a man in his companions', career_application: 'Wisdom appears to rest in the mind, but it really exists to a man in his companions', chapter: 'Avoiding mean Associations' },
  { id: 455, kural_number: 455, tamil_text: 'மனந்தூய்மை செய்வினை தூய்மை இரண்டும் இனந்தூய்மை தூவா வரும்.', transliteration: 'Manandhooimai Seyvinai Thooimai Irantum Inandhooimai Thoovaa Varum', english_meaning: 'Chaste company is the staff on which come, these two things, viz, purity of mind and purity of conduct', career_application: 'Chaste company is the staff on which come, these two things, viz, purity of mind and purity of conduct', chapter: 'Avoiding mean Associations' },
  { id: 456, kural_number: 456, tamil_text: 'மனந்தூயார்க் கெச்சம்நன் றாகும் இனந்தூயார்க்கு இல்லைநன் றாகா வினை.', transliteration: 'Manandhooyaark Kechchamnan Raakum Inandhooyaarkku Illainan Raakaa Vinai', english_meaning: 'To the pure-minded there will be a good posterity By those whose associates are pure, no deeds will be done that are not good', career_application: 'To the pure-minded there will be a good posterity By those whose associates are pure, no deeds will be done that are not good', chapter: 'Avoiding mean Associations' },
  { id: 457, kural_number: 457, tamil_text: 'மனநலம் மன்னுயிர்க் காக்கம் இனநலம் எல்லாப் புகழும் தரும்.', transliteration: 'Mananalam Mannuyirk Kaakkam Inanalam Ellaap Pukazhum Tharum', english_meaning: 'Goodness of mind will give wealth, and good society will bring with it all praise, to men', career_application: 'Goodness of mind will give wealth, and good society will bring with it all praise, to men', chapter: 'Avoiding mean Associations' },
  { id: 458, kural_number: 458, tamil_text: 'மனநலம் நன்குடைய ராயினும் சான்றோர்க்கு இனநலம் ஏமாப் புடைத்து.', transliteration: 'Mananalam Nankutaiya Raayinum Saandrorkku Inanalam Emaap Putaiththu', english_meaning: 'Yet good companionship is confirmation strong', career_application: 'Yet good companionship is confirmation strong', chapter: 'Avoiding mean Associations' },
  { id: 459, kural_number: 459, tamil_text: 'மனநலத்தின் ஆகும் மறுமைமற் றஃதும் இனநலத்தின் ஏமாப் புடைத்து.', transliteration: 'Mananalaththin Aakum Marumaimar Raqdhum Inanalaththin Emaap Putaiththu', english_meaning: 'Future bliss is (the result) of goodness of mind; and even this acquires strength from the society of the good', career_application: 'Future bliss is (the result) of goodness of mind; and even this acquires strength from the society of the good', chapter: 'Avoiding mean Associations' },
  { id: 460, kural_number: 460, tamil_text: 'நல்லினத்தி னூங்குந் துணையில்லை தீயினத்தின் அல்லற் படுப்பதூஉம் இல்.', transliteration: 'Nallinaththi Noongun Thunaiyillai Theeyinaththin Allar Patuppadhooum Il', english_meaning: 'There is no greater help than the company of the good; there is no greater source of sorrow than the company of the wicked', career_application: 'There is no greater help than the company of the good; there is no greater source of sorrow than the company of the wicked', chapter: 'Avoiding mean Associations' },
  { id: 461, kural_number: 461, tamil_text: 'அழிவதூஉம் ஆவதூஉம் ஆகி வழிபயக்கும் ஊதியமும் சூழ்ந்து செயல்.', transliteration: 'Azhivadhooum Aavadhooum Aaki Vazhipayakkum Oodhiyamum Soozhndhu Seyal', english_meaning: 'Let a man reflect on what will be lost, what will be acquired and (from these) what will be his ultimate gain, and (then, let him) act', career_application: 'Let a man reflect on what will be lost, what will be acquired and (from these) what will be his ultimate gain, and (then, let him) act', chapter: 'Acting after due Consideration' },
  { id: 462, kural_number: 462, tamil_text: 'தெரிந்த இனத்தொடு தேர்ந்தெண்ணிச் செய்வார்க்கு அரும்பொருள் யாதொன்றும் இல்', transliteration: 'Therindha Inaththotu Therndhennich Cheyvaarkku Arumporul Yaadhondrum Il', english_meaning: 'There is nothing too difficult to (be attained by) those who, before they act, reflect well themselves, and thoroughly consider (the matter) with chosen friends', career_application: 'There is nothing too difficult to (be attained by) those who, before they act, reflect well themselves, and thoroughly consider (the matter) with chosen friends', chapter: 'Acting after due Consideration' },
  { id: 463, kural_number: 463, tamil_text: 'ஆக்கம் கருதி முதலிழக்கும் செய்வினை ஊக்கார் அறிவுடை யார்.', transliteration: 'Aakkam Karudhi Mudhalizhakkum Seyvinai Ookkaar Arivutai Yaar', english_meaning: 'Wise men will not, in the hopes of profit, undertake works that will consume their principal', career_application: 'Wise men will not, in the hopes of profit, undertake works that will consume their principal', chapter: 'Acting after due Consideration' },
  { id: 464, kural_number: 464, tamil_text: 'தெளிவி லதனைத் தொடங்கார் இளிவென்னும் ஏதப்பாடு அஞ்சு பவர்.', transliteration: 'Thelivi Ladhanaith Thotangaar Ilivennum Edhappaatu Anju Pavar', english_meaning: 'Those who fear reproach will not commence anything which has not been (thoroughly considered) and made clear to them', career_application: 'Those who fear reproach will not commence anything which has not been (thoroughly considered) and made clear to them', chapter: 'Acting after due Consideration' },
  { id: 465, kural_number: 465, tamil_text: 'வகையறச் சூழா தெழுதல் பகைவரைப் பாத்திப் படுப்பதோ ராறு.', transliteration: 'Vakaiyarach Choozhaa Thezhudhal Pakaivaraip Paaththip Patuppadho Raaru', english_meaning: 'One way to promote the prosperity of an enemy, is (for a king) to set out (to war) without having thoroughly weighed his ability (to cope with its chances)', career_application: 'One way to promote the prosperity of an enemy, is (for a king) to set out (to war) without having thoroughly weighed his ability (to cope with its chances)', chapter: 'Acting after due Consideration' },
  { id: 466, kural_number: 466, tamil_text: 'செய்தக்க அல்ல செயக்கெடும் செய்தக்க செய்யாமை யானுங் கெடும்.', transliteration: 'Seydhakka Alla Seyak Ketum Seydhakka Seyyaamai Yaanung Ketum', english_meaning: 'He will perish who does not what is not fit to do; and he also will perish who does not do what it is fit to', career_application: 'He will perish who does not what is not fit to do; and he also will perish who does not do what it is fit to', chapter: 'Acting after due Consideration' },
  { id: 467, kural_number: 467, tamil_text: 'எண்ணித் துணிக கருமம் துணிந்தபின் எண்ணுவம் என்பது இழுக்கு.', transliteration: 'Ennith Thunika Karumam Thunindhapin Ennuvam Enpadhu Izhukku', english_meaning: 'Consider, and then undertake a matter; after having undertaken it, to say "We will consider," is folly', career_application: 'Consider, and then undertake a matter; after having undertaken it, to say "We will consider," is folly', chapter: 'Acting after due Consideration' },
  { id: 468, kural_number: 468, tamil_text: 'ஆற்றின் வருந்தா வருத்தம் பலர்நின்று போற்றினும் பொத்துப் படும்.', transliteration: 'Aatrin Varundhaa Varuththam Palarnindru Potrinum Poththup Patum', english_meaning: 'The work, which is not done by suitable methods, will fail though many stand to uphold it', career_application: 'The work, which is not done by suitable methods, will fail though many stand to uphold it', chapter: 'Acting after due Consideration' },
  { id: 469, kural_number: 469, tamil_text: 'நன்றாற்ற லுள்ளுந் தவுறுண்டு அவரவர் பண்பறிந் தாற்றாக் கடை.', transliteration: 'Nandraatra Lullun Thavuruntu Avaravar Panparin Thaatraak Katai', english_meaning: 'There are failures even in acting well, when it is done without knowing the various dispositions of men', career_application: 'There are failures even in acting well, when it is done without knowing the various dispositions of men', chapter: 'Acting after due Consideration' },
  { id: 470, kural_number: 470, tamil_text: 'எள்ளாத எண்ணிச் செயல்வேண்டும் தம்மோடு கொள்ளாத கொள்ளாது உலகு.', transliteration: 'Ellaadha Ennich Cheyalventum Thammotu Kollaadha Kollaadhu Ulaku', english_meaning: 'Let a man reflect, and do things which bring no reproach; the world will not approve, with him, of things which do not become of his position to adopt', career_application: 'Let a man reflect, and do things which bring no reproach; the world will not approve, with him, of things which do not become of his position to adopt', chapter: 'Acting after due Consideration' },
  { id: 471, kural_number: 471, tamil_text: 'வினைவலியும் தன்வலியும் மாற்றான் வலியும் துணைவலியும் தூக்கிச் செயல்.', transliteration: 'Vinaivaliyum Thanvaliyum Maatraan Valiyum Thunaivaliyum Thookkich Cheyal', english_meaning: 'Let (one) weigh well the strength of the deed (he purposes to do), his own strength, the strength of his enemy, and the strength of the allies (of both), and then let him act', career_application: 'Let (one) weigh well the strength of the deed (he purposes to do), his own strength, the strength of his enemy, and the strength of the allies (of both), and then let him act', chapter: 'The Knowledge of Power' },
  { id: 472, kural_number: 472, tamil_text: 'ஒல்வ தறிவது அறிந்ததன் கண்தங்கிச் செல்வார்க்குச் செல்லாதது இல்.', transliteration: 'Olva Tharivadhu Arindhadhan Kandhangich Chelvaarkkuch Chellaadhadhu Il', english_meaning: 'There is nothing which may not be accomplished by those who, before they attack (an enemy), make themselves acquainted with their own ability, and with whatever else is (needful) to be known, and', career_application: 'There is nothing which may not be accomplished by those who, before they attack (an enemy), make themselves acquainted with their own ability, and with whatever else is (needful) to be known, and', chapter: 'The Knowledge of Power' },
  { id: 473, kural_number: 473, tamil_text: 'உடைத்தம் வலியறியார் ஊக்கத்தின் ஊக்கி இடைக்கண் முரிந்தார் பலர்.', transliteration: 'Utaiththam Valiyariyaar Ookkaththin Ookki Itaikkan Murindhaar Palar', english_meaning: 'There are many who, ignorant of their (want of) power (to meet it), have haughtily set out to war, and broken down in the midst of it', career_application: 'There are many who, ignorant of their (want of) power (to meet it), have haughtily set out to war, and broken down in the midst of it', chapter: 'The Knowledge of Power' },
  { id: 474, kural_number: 474, tamil_text: 'அமைந்தாங் கொழுகான் அளவறியான் தன்னை வியந்தான் விரைந்து கெடும்.', transliteration: 'Amaindhaang Kozhukaan Alavariyaan Thannai Viyandhaan Viraindhu Ketum', english_meaning: 'He will quickly perish who, ignorant of his own resources flatters himself of his greatness, and does', career_application: 'He will quickly perish who, ignorant of his own resources flatters himself of his greatness, and does', chapter: 'The Knowledge of Power' },
  { id: 475, kural_number: 475, tamil_text: 'பீலிபெய் சாகாடும் அச்சிறும் அப்பண்டஞ் சால மிகுத்துப் பெயின்.', transliteration: 'Peelipey Saakaatum Achchirum Appantanjjch Aala Mikuththup Peyin', english_meaning: 'The axle tree of a bandy, loaded only with peacocks\' feathers will break, if it be greatly overloaded', career_application: 'The axle tree of a bandy, loaded only with peacocks\' feathers will break, if it be greatly overloaded', chapter: 'The Knowledge of Power' },
  { id: 476, kural_number: 476, tamil_text: 'நுனிக்கொம்பர் ஏறினார் அஃதிறந் தூக்கின் உயிர்க்கிறுதி ஆகி விடும்.', transliteration: 'Nunikkompar Erinaar Aqdhiran Thookkin Uyirkkirudhi Aaki Vitum', english_meaning: 'There will be an end to the life of him who, having climbed out to the end of a branch, ventures to go further', career_application: 'There will be an end to the life of him who, having climbed out to the end of a branch, ventures to go further', chapter: 'The Knowledge of Power' },
  { id: 477, kural_number: 477, tamil_text: 'ஆற்றின் அறவறிந்து ஈக அதுபொருள் போற்றி வழங்கு நெறி.', transliteration: 'Aatrin Aravarindhu Eeka Adhuporul Potri Vazhangu Neri', english_meaning: 'Let a man know the measure of his ability (to give), and let him give accordingly; such giving is the way to preserve his property', career_application: 'Let a man know the measure of his ability (to give), and let him give accordingly; such giving is the way to preserve his property', chapter: 'The Knowledge of Power' },
  { id: 478, kural_number: 478, tamil_text: 'ஆகாறு அளவிட்டி தாயினுங் கேடில்லை போகாறு அகலாக் கடை.', transliteration: 'Aakaaru Alavitti Thaayinung Ketillai Pokaaru Akalaak Katai', english_meaning: 'Even though the income (of a king) be small, it will not cause his (ruin), if his outgoings be not larger than his income', career_application: 'Even though the income (of a king) be small, it will not cause his (ruin), if his outgoings be not larger than his income', chapter: 'The Knowledge of Power' },
  { id: 479, kural_number: 479, tamil_text: 'அளவறிந்து வாழாதான் வாழ்க்கை உளபோல இல்லாகித் தோன்றாக் கெடும்.', transliteration: 'Alavara�ndhu Vaazhaadhaan Vaazhkkai Ulapola Illaakith Thondraak Ketum', english_meaning: 'The prosperity of him who lives without knowing the measure (of his property), will perish, even while it seems to continue', career_application: 'The prosperity of him who lives without knowing the measure (of his property), will perish, even while it seems to continue', chapter: 'The Knowledge of Power' },
  { id: 480, kural_number: 480, tamil_text: 'உளவரை தூக்காத ஒப்புர வாண்மை வளவரை வல்லைக் கெடும்.', transliteration: 'Ulavarai Thookkaadha Oppura Vaanmai Valavarai Vallaik Ketum', english_meaning: 'The measure of his wealth will quickly perish, whose liberality weighs not the measure of his property', career_application: 'The measure of his wealth will quickly perish, whose liberality weighs not the measure of his property', chapter: 'The Knowledge of Power' },
  { id: 481, kural_number: 481, tamil_text: 'பகல்வெல்லும் கூகையைக் காக்கை இகல்வெல்லும் வேந்தர்க்கு வேண்டும் பொழுது.', transliteration: 'Pakalvellum Kookaiyaik Kaakkai Ikalvellum Vendharkku Ventum Pozhudhu', english_meaning: 'A crow will overcome an owl in the day time; so the king who would conquer his enemy must have (a suitable) time', career_application: 'A crow will overcome an owl in the day time; so the king who would conquer his enemy must have (a suitable) time', chapter: 'Knowing the fitting Time' },
  { id: 482, kural_number: 482, tamil_text: 'பருவத்தோடு ஒட்ட ஒழுகல் திருவினைத் தீராமை ஆர்க்குங் கயிறு.', transliteration: 'Paruvaththotu Otta Ozhukal Thiruvinaith Theeraamai Aarkkung Kayiru', english_meaning: 'Acting at the right season, is a cord that will immoveably bind success (to a king)', career_application: 'Acting at the right season, is a cord that will immoveably bind success (to a king)', chapter: 'Knowing the fitting Time' },
  { id: 483, kural_number: 483, tamil_text: 'அருவினை யென்ப உளவோ கருவியான் காலம் அற஧ந்து செயின்.', transliteration: 'Aruvinai Yenpa Ulavo Karuviyaan Kaalam Arindhu Seyin', english_meaning: 'Is there anything difficult for him to do, who acts, with (the right) instruments at the right time ?', career_application: 'Is there anything difficult for him to do, who acts, with (the right) instruments at the right time ?', chapter: 'Knowing the fitting Time' },
  { id: 484, kural_number: 484, tamil_text: 'ஞாலம் கருதினுங் கைகூடுங் காலம் கருதி இடத்தாற் செயின்.', transliteration: 'Gnaalam Karudhinung Kaikootung Kaalam Karudhi Itaththaar Seyin', english_meaning: 'Though (a man) should meditate (the conquest of) the world, he may accomplish it if he acts in the right time, and at the right place', career_application: 'Though (a man) should meditate (the conquest of) the world, he may accomplish it if he acts in the right time, and at the right place', chapter: 'Knowing the fitting Time' },
  { id: 485, kural_number: 485, tamil_text: 'காலம் கருதி இருப்பர் கலங்காது ஞாலம் கருது பவர்.', transliteration: 'Kaalam Karudhi Iruppar Kalangaadhu Gnaalam Karudhu Pavar', english_meaning: 'They who thoughtfully consider and wait for the (right) time (for action), may successfully meditate (the conquest of) the world', career_application: 'They who thoughtfully consider and wait for the (right) time (for action), may successfully meditate (the conquest of) the world', chapter: 'Knowing the fitting Time' },
  { id: 486, kural_number: 486, tamil_text: 'ஊக்க முடையான் ஒடுக்கம் பொருதகர் தாக்கற்குப் பேருந் தகைத்து.', transliteration: 'Ookka Mutaiyaan Otukkam Porudhakar Thaakkarkup Perun Thakaiththu', english_meaning: 'The self-restraint of the energetic (while waiting for a suitable opportunity), is like the drawing back of a fighting-ram in order to butt', career_application: 'The self-restraint of the energetic (while waiting for a suitable opportunity), is like the drawing back of a fighting-ram in order to butt', chapter: 'Knowing the fitting Time' },
  { id: 487, kural_number: 487, tamil_text: 'பொள்ளென ஆங்கே புறம்வேரார் காலம்பார்த்து உள்வேர்ப்பர் ஒள்ளி யவர்.', transliteration: 'Pollena Aange Puramveraar Kaalampaarththu Ulverppar Olli Yavar', english_meaning: 'The wise will not immediately and hastily shew out their anger; they will watch their time, and restrain it within', career_application: 'The wise will not immediately and hastily shew out their anger; they will watch their time, and restrain it within', chapter: 'Knowing the fitting Time' },
  { id: 488, kural_number: 488, tamil_text: 'செறுநரைக் காணின் சுமக்க இறுவரை காணின் கிழக்காம் தலை.', transliteration: 'Serunaraik Kaanin Sumakka Iruvarai Kaanin Kizhakkaam Thalai', english_meaning: 'If one meets his enemy, let him show him all respect, until the time for his destruction is come; when that is come, his head will be easily brought low', career_application: 'If one meets his enemy, let him show him all respect, until the time for his destruction is come; when that is come, his head will be easily brought low', chapter: 'Knowing the fitting Time' },
  { id: 489, kural_number: 489, tamil_text: 'எய்தற் கரியது இயைந்தக்கால் அந்நிலையே செய்தற் கரிய செயல்.', transliteration: 'Eydhar Kariyadhu Iyaindhakkaal Annilaiye Seydhar Kariya Seyal', english_meaning: 'If a rare opportunity occurs, while it lasts, let a man do that which is rarely to be accomplished (but for such an opportunity)', career_application: 'If a rare opportunity occurs, while it lasts, let a man do that which is rarely to be accomplished (but for such an opportunity)', chapter: 'Knowing the fitting Time' },
  { id: 490, kural_number: 490, tamil_text: 'கொக்கொக்க கூம்பும் பருவத்து மற்றதன் குத்தொக்க சீர்த்த இடத்து.', transliteration: 'Kokkokka Koompum Paruvaththu Matradhan Kuththokka Seerththa Itaththu', english_meaning: 'At the time when one should use self-control, let him restrain himself like a heron; and, let him like it, strike, when there is a favourable opportunity', career_application: 'At the time when one should use self-control, let him restrain himself like a heron; and, let him like it, strike, when there is a favourable opportunity', chapter: 'Knowing the fitting Time' },
  { id: 491, kural_number: 491, tamil_text: 'தொடங்கற்க எவ்வினையும் எள்ளற்க முற்றும் இடங்கண்ட பின்அல் லது.', transliteration: 'Thotangarka Evvinaiyum Ellarka Mutrum Itanganta Pinal Ladhu', english_meaning: 'Let not (a king) despise (an enemy), nor undertake any thing (against him), until he has obtained (a suitable) place for besieging him', career_application: 'Let not (a king) despise (an enemy), nor undertake any thing (against him), until he has obtained (a suitable) place for besieging him', chapter: 'Knowing the Place' },
  { id: 492, kural_number: 492, tamil_text: 'முரண்சேர்ந்த மொய்ம்பி னவர்க்கும் அரண்சேர்ந்தாம் ஆக்கம் பலவுந் தரும்.', transliteration: 'Muranserndha Moimpi Navarkkum Aranserndhaam Aakkam Palavun Tharum', english_meaning: 'Even to those who are men of power and expedients, an attack in connection with a fortification will yield many advantages', career_application: 'Even to those who are men of power and expedients, an attack in connection with a fortification will yield many advantages', chapter: 'Knowing the Place' },
  { id: 493, kural_number: 493, tamil_text: 'ஆற்றாரும் ஆற்றி அடுப இடனறிந்து போற்றார்கண் போற்றிச் செயின்.', transliteration: 'Aatraarum Aatri Atupa Itanarindhu Potraarkan Potrich Cheyin', english_meaning: 'Even the powerless will become powerful and conquer, if they select a proper field (of action), and guard themselves, while they make war on their enemies', career_application: 'Even the powerless will become powerful and conquer, if they select a proper field (of action), and guard themselves, while they make war on their enemies', chapter: 'Knowing the Place' },
  { id: 494, kural_number: 494, tamil_text: 'எண்ணியார் எண்ணம் இழப்பர் இடனறிந்து துன்னியார் துன்னிச் செயின்.', transliteration: 'Enniyaar Ennam Izhappar Itanarindhu Thunniyaar Thunnich Cheyin', english_meaning: 'If they who draw near (to fight) choose a suitable place to approach (their enemy), the latter, will have to relinquish the thought which they once entertained, of conquering them', career_application: 'If they who draw near (to fight) choose a suitable place to approach (their enemy), the latter, will have to relinquish the thought which they once entertained, of conquering them', chapter: 'Knowing the Place' },
  { id: 495, kural_number: 495, tamil_text: 'நெடும்புனலுள் வெல்லும் முதலை அடும்புனலின் நீங்கின் அதனைப் பிற.', transliteration: 'Netumpunalul Vellum Mudhalai Atumpunalin Neengin Adhanaip Pira', english_meaning: 'In deep water, a crocodile will conquer (all other animals); but if it leave the water, other animals will conquer it', career_application: 'In deep water, a crocodile will conquer (all other animals); but if it leave the water, other animals will conquer it', chapter: 'Knowing the Place' },
  { id: 496, kural_number: 496, tamil_text: 'கடலோடா கால்வல் நெடுந்தேர் கடலோடும் நாவாயும் ஓடா நிலத்து.', transliteration: 'Katalotaa Kaalval Netundher Katalotum Naavaayum Otaa Nilaththu', english_meaning: 'Wide chariots, with mighty wheels, will not run on the ocean; neither will ships that the traverse ocean, move on the earth', career_application: 'Wide chariots, with mighty wheels, will not run on the ocean; neither will ships that the traverse ocean, move on the earth', chapter: 'Knowing the Place' },
  { id: 497, kural_number: 497, tamil_text: 'அஞ்சாமை அல்லால் துணைவேண்டா எஞ்சாமை எண்ணி இடத்தால் செயின்.', transliteration: 'Anjaamai Allaal Thunaiventaa Enjaamai Enni Itaththaal Seyin', english_meaning: 'You will need no other aid than fearlessness, if you thoroughly reflect (on what you are to do), and select (a suitable) place for your operations', career_application: 'You will need no other aid than fearlessness, if you thoroughly reflect (on what you are to do), and select (a suitable) place for your operations', chapter: 'Knowing the Place' },
  { id: 498, kural_number: 498, tamil_text: 'சிறுபடையான் செல்லிடம் சேரின் உறுபடையான் ஊக்கம் அழிந்து விடும்.', transliteration: 'Sirupataiyaan Sellitam Serin Urupataiyaan Ookkam Azhindhu Vitum', english_meaning: 'The power of one who has a large army will perish, if he goes into ground where only a small army can act', career_application: 'The power of one who has a large army will perish, if he goes into ground where only a small army can act', chapter: 'Knowing the Place' },
  { id: 499, kural_number: 499, tamil_text: 'சிறைநலனும் சீரும் இலரெனினும் மாந்தர் உறைநிலத்தோடு ஒட்டல் அரிது.', transliteration: 'Sirainalanum Seerum Ilareninum Maandhar Urainilaththotu Ottal Aridhu', english_meaning: 'It is a hazardous thing to attack men in their own country, although they may neither have power nor a good fortress', career_application: 'It is a hazardous thing to attack men in their own country, although they may neither have power nor a good fortress', chapter: 'Knowing the Place' },
  { id: 500, kural_number: 500, tamil_text: 'காலாழ் களரில் நரியடும் கண்ணஞ்சா வேலாள் முகத்த களிறு.', transliteration: 'Kaalaazh Kalaril Nariyatum Kannanjaa Velaal Mukaththa Kaliru', english_meaning: 'A fox can kill a fearless, warrior-faced elephant, if it go into mud in which its legs sink down', career_application: 'A fox can kill a fearless, warrior-faced elephant, if it go into mud in which its legs sink down', chapter: 'Knowing the Place' },
  { id: 501, kural_number: 501, tamil_text: 'அறம்பொருள் இன்பம் உயிரச்சம் நான்கின் திறந்தெரிந்து தேறப் படும்.', transliteration: 'Aramporul Inpam Uyirachcham Naankin Thirandherindhu Therap Patum', english_meaning: 'Let (a minister) be chosen, after he has been tried by means of these four things, viz,-his virtue, (love of) money, (love of) sexual pleasure, and tear of (losing) life', career_application: 'Let (a minister) be chosen, after he has been tried by means of these four things, viz,-his virtue, (love of) money, (love of) sexual pleasure, and tear of (losing) life', chapter: 'Selection and Confidence' },
  { id: 502, kural_number: 502, tamil_text: 'குடிப்பிறந்து குற்றத்தின் நீங்கி வடுப்பரியும் நாணுடையான் சுட்டே தெளிவு.', transliteration: 'Kutippirandhu Kutraththin Neengi Vatuppariyum Naanutaiyaan Sutte Thelivu', english_meaning: '(The king\'s) choice should (fall) on him, who is of good family, who is free from faults, and who has the modesty which fears the wounds (of sin)', career_application: '(The king\'s) choice should (fall) on him, who is of good family, who is free from faults, and who has the modesty which fears the wounds (of sin)', chapter: 'Selection and Confidence' },
  { id: 503, kural_number: 503, tamil_text: 'அரியகற்று ஆசற்றார் கண்ணும் தெரியுங்கால் இன்மை அரிதே வெளிறு.', transliteration: 'Ariyakatru Aasatraar Kannum Theriyungaal Inmai Aridhe Veliru', english_meaning: 'When even men, who have studied the most difficult works, and who are free from faults, are (carefully) examined, it is a rare thing to find them without ignorance', career_application: 'When even men, who have studied the most difficult works, and who are free from faults, are (carefully) examined, it is a rare thing to find them without ignorance', chapter: 'Selection and Confidence' },
  { id: 504, kural_number: 504, tamil_text: 'குணம்நாடிக் குற்றமும் நாடி அவற்றுள் மிகைநாடி மிக்க கொளல்.', transliteration: 'Kunamnaatik Kutramum Naati Avatrul Mikainaati Mikka Kolal', english_meaning: 'Let (a king) consider (a man\'s) good qualities, as well as his faults, and then judge (of his character) by that which prevails', career_application: 'Let (a king) consider (a man\'s) good qualities, as well as his faults, and then judge (of his character) by that which prevails', chapter: 'Selection and Confidence' },
  { id: 505, kural_number: 505, tamil_text: 'பெருமைக்கும் ஏனைச் சிறுமைக்கும் தத்தம் கருமமே கட்டளைக் கல்.', transliteration: 'Perumaikkum Enaich Chirumaikkum Thaththam Karumame Kattalaik Kal', english_meaning: 'A man\'s deeds are the touchstone of his greatness and littleness', career_application: 'A man\'s deeds are the touchstone of his greatness and littleness', chapter: 'Selection and Confidence' },
  { id: 506, kural_number: 506, tamil_text: 'அற்றாரைத் தேறுதல் ஓம்புக மற்றவர் பற்றிலர் நாணார் பழி.', transliteration: 'Atraaraith Therudhal Ompuka Matravar Patrilar Naanaar Pazhi', english_meaning: 'Let (a king) avoid choosing men who have no relations; such men have no attachment, and thereforehave no fear of crime', career_application: 'Let (a king) avoid choosing men who have no relations; such men have no attachment, and thereforehave no fear of crime', chapter: 'Selection and Confidence' },
  { id: 507, kural_number: 507, tamil_text: 'காதன்மை கந்தா அறிவறியார்த் தேறுதல் பேதைமை எல்லாந் தரும்.', transliteration: 'Kaadhanmai Kandhaa Arivariyaarth Therudhal Pedhaimai Ellaan Tharum', english_meaning: 'Yields all his being up to folly\'s blind control', career_application: 'Yields all his being up to folly\'s blind control', chapter: 'Selection and Confidence' },
  { id: 508, kural_number: 508, tamil_text: 'தேரான் பிறனைத் தெளிந்தான் வழிமுறை தீரா இடும்பை தரும்.', transliteration: 'Theraan Piranaith Thelindhaan Vazhimurai Theeraa Itumpai Tharum', english_meaning: 'Sorrow that will not leave even his posterity will come upon him chooses a stranger whose character he has not known', career_application: 'Sorrow that will not leave even his posterity will come upon him chooses a stranger whose character he has not known', chapter: 'Selection and Confidence' },
  { id: 509, kural_number: 509, tamil_text: 'தேறற்க யாரையும் தேராது தேர்ந்தபின் தேறுக தேறும் பொருள்.', transliteration: 'Therarka Yaaraiyum Theraadhu Therndhapin Theruka Therum Porul', english_meaning: 'Let (a king) choose no one without previous consideration; after he has made his choice, let him unhesitatingly select for each such duties as are appropriate', career_application: 'Let (a king) choose no one without previous consideration; after he has made his choice, let him unhesitatingly select for each such duties as are appropriate', chapter: 'Selection and Confidence' },
  { id: 510, kural_number: 510, tamil_text: 'தேரான் தெளிவும் தெளிந்தான்கண் ஐயுறவும் தீரா இடும்பை தரும்.', transliteration: 'Theraan Thelivum Thelindhaankan Aiyuravum Theeraa Itumpai Tharum', english_meaning: 'To make choice of one who has not been examined, and to entertain doubts respecting one who has been chosen, will produce irremediable sorrow', career_application: 'To make choice of one who has not been examined, and to entertain doubts respecting one who has been chosen, will produce irremediable sorrow', chapter: 'Selection and Confidence' },
  { id: 511, kural_number: 511, tamil_text: 'நன்மையும் தீமையும் நாடி நலம்புரிந்த தன்மையான் ஆளப் படும்.', transliteration: 'Nanmaiyum Theemaiyum Naati Nalampurindha Thanmaiyaan Aalap Patum', english_meaning: 'He should be employed (by a king), whose nature leads him to choose the good, after having weighed both the evil and the good in any undertaking', career_application: 'He should be employed (by a king), whose nature leads him to choose the good, after having weighed both the evil and the good in any undertaking', chapter: 'Selection and Employment' },
  { id: 512, kural_number: 512, tamil_text: 'வாரி பெருக்கி வளம்படுத்து உற்றவை ஆராய்வான் செய்க வினை.', transliteration: 'Vaari Perukki Valampatuththu Utravai Aaraaivaan Seyka Vinai', english_meaning: 'Let him do (the king\'s) work who can enlarge the sources (of revenue), increase wealth and considerately prevent the accidents (which would destroy it)', career_application: 'Let him do (the king\'s) work who can enlarge the sources (of revenue), increase wealth and considerately prevent the accidents (which would destroy it)', chapter: 'Selection and Employment' },
  { id: 513, kural_number: 513, tamil_text: 'அன்பறிவு தேற்றம் அவாவின்மை இந்நான்கும் நன்குடையான் கட்டே தெளிவு.', transliteration: 'Anparivu Thetram Avaavinmai Innaankum Nankutaiyaan Katte Thelivu', english_meaning: 'Let the choice (of a king) fall upon him who largely possesses these four things, love, knowledge, a clear mind and freedom from covetousness', career_application: 'Let the choice (of a king) fall upon him who largely possesses these four things, love, knowledge, a clear mind and freedom from covetousness', chapter: 'Selection and Employment' },
  { id: 514, kural_number: 514, tamil_text: 'எனைவகையான் தேறியக் கண்ணும் வினைவகையான் வேறாகும் மாந்தர் பலர்.', transliteration: 'Enaivakaiyaan Theriyak Kannum Vinaivakaiyaan Veraakum Maandhar Palar', english_meaning: 'Even when (a king) has tried them in every possible way, there are many men who change, from the nature of the works (in which they may be employed)', career_application: 'Even when (a king) has tried them in every possible way, there are many men who change, from the nature of the works (in which they may be employed)', chapter: 'Selection and Employment' },
  { id: 515, kural_number: 515, tamil_text: 'அறிந்தாற்றிச் செய்கிற்பாற்கு அல்லால் வினைதான் சிறந்தானென்று ஏவற்பாற் றன்று.', transliteration: 'Arindhaatrich Cheykirpaarku Allaal Vinaidhaan Sirandhaanendru Evarpaar Randru', english_meaning: '(A king\'s) work can only be accomplished by a man of wisdom and patient endurance; it is not of a nature to be given to one from mere personal attachment', career_application: '(A king\'s) work can only be accomplished by a man of wisdom and patient endurance; it is not of a nature to be given to one from mere personal attachment', chapter: 'Selection and Employment' },
  { id: 516, kural_number: 516, tamil_text: 'செய்வானை நாடி வினைநாடிக் காலத்தோடு எய்த உணர்ந்து செயல்.', transliteration: 'Seyvaanai Naati Vinainaatik Kaalaththotu Eydha Unarndhu Seyal', english_meaning: 'Let (a king) act, after having considered the agent (whom he is to employ), the deed (he desires to do), and the time which is suitable to it', career_application: 'Let (a king) act, after having considered the agent (whom he is to employ), the deed (he desires to do), and the time which is suitable to it', chapter: 'Selection and Employment' },
  { id: 517, kural_number: 517, tamil_text: 'இதனை இதனால் இவன்முடிக்கும் என்றாய்ந்து அதனை அவன்கண் விடல்.', transliteration: 'Ithanai Ithanaal Ivanmutikkum Endraaindhu Adhanai Avankan Vital', english_meaning: 'After having considered, "this man can accomplish this, by these means", let (the king) leave with him the discharge of that duty', career_application: 'After having considered, "this man can accomplish this, by these means", let (the king) leave with him the discharge of that duty', chapter: 'Selection and Employment' },
  { id: 518, kural_number: 518, tamil_text: 'வினைக்குரிமை நாடிய பின்றை அவனை அதற்குரிய னாகச் செயல்.', transliteration: 'Vinaik Kurimai Naatiya Pindrai Avanai Adharkuriya Naakach Cheyal', english_meaning: 'Having considered what work a man is fit for, let (the king) employ him in that work', career_application: 'Having considered what work a man is fit for, let (the king) employ him in that work', chapter: 'Selection and Employment' },
  { id: 519, kural_number: 519, tamil_text: 'வினைக்கண் வினையுடையான் கேண்மைவே றாக நினைப்பானை நீங்கும் திரு.', transliteration: 'Vinaikkan Vinaiyutaiyaan Kenmaive Raaka Ninaippaanai Neengum Thiru', english_meaning: 'Prosperity will leave (the king) who doubts the friendship of the man who steadily labours in the discharge of his duties', career_application: 'Prosperity will leave (the king) who doubts the friendship of the man who steadily labours in the discharge of his duties', chapter: 'Selection and Employment' },
  { id: 520, kural_number: 520, tamil_text: 'நாடோறும் நாடுக மன்னன் வினைசெய்வான் கோடாமை கோடா துலகு.', transliteration: 'Naatorum Naatuka Mannan Vinaiseyvaan Kotaamai Kotaa Thulaku', english_meaning: 'Let a king daily examine the conduct of his servants; if they do not act crookedly, the world will not act crookedly', career_application: 'Let a king daily examine the conduct of his servants; if they do not act crookedly, the world will not act crookedly', chapter: 'Selection and Employment' },
  { id: 521, kural_number: 521, tamil_text: 'பற்றற்ற கண்ணும் பழைமைபா ராட்டுதல் சுற்றத்தார் கண்ணே உள.', transliteration: 'Patratra Kannum Pazhaimaipaa Raattudhal Sutraththaar Kanne Ula', english_meaning: 'Even when (a man\'s) property is all gone, relatives will act towards him with their accustomed (kindness)', career_application: 'Even when (a man\'s) property is all gone, relatives will act towards him with their accustomed (kindness)', chapter: 'Cherishing Kinsmen' },
  { id: 522, kural_number: 522, tamil_text: 'விருப்பறாச் சுற்றம் இயையின் அருப்பறா ஆக்கம் பலவும் தரும்.', transliteration: 'Virupparaach Chutram Iyaiyin Arupparaa Aakkam Palavum Tharum', english_meaning: 'If (a man\'s) relatives remain attached to him with unchanging love, it will be a source of everincreasing wealth', career_application: 'If (a man\'s) relatives remain attached to him with unchanging love, it will be a source of everincreasing wealth', chapter: 'Cherishing Kinsmen' },
  { id: 523, kural_number: 523, tamil_text: 'அளவளா வில்லாதான் வாழ்க்கை குளவளாக் கோடின்றி நீர்நிறைந் தற்று.', transliteration: 'Alavalaa Villaadhaan Vaazhkkai Kulavalaak Kotindri Neernirain Thatru', english_meaning: 'The wealth of one who does not mingle freely with his relatives, will be like the filling of water in a', career_application: 'The wealth of one who does not mingle freely with his relatives, will be like the filling of water in a', chapter: 'Cherishing Kinsmen' },
  { id: 524, kural_number: 524, tamil_text: 'சுற்றத்தால் சுற்றப் படஒழுகல் செல்வந்தான் பெற்றத்தால் பெற்ற பயன்.', transliteration: 'Sutraththaal Sutrap Pataozhukal Selvandhaan Petraththaal Petra Payan', english_meaning: 'To live surrounded by relatives, is the advantage to be derived from the acquisition of wealth', career_application: 'To live surrounded by relatives, is the advantage to be derived from the acquisition of wealth', chapter: 'Cherishing Kinsmen' },
  { id: 525, kural_number: 525, tamil_text: 'கொடுத்தலும் இன்சொலும் ஆற்றின் அடுக்கிய சுற்றத்தால் சுற்றப் படும்.', transliteration: 'Kotuththalum Insolum Aatrin Atukkiya Sutraththaal Sutrap Patum', english_meaning: 'He will be surrounded by numerous relatives who manifests generosity and affability', career_application: 'He will be surrounded by numerous relatives who manifests generosity and affability', chapter: 'Cherishing Kinsmen' },
  { id: 526, kural_number: 526, tamil_text: 'பெருங்கொடையான் பேணான் வெகுளி அவனின் மருங்குடையார் மாநிலத்து இல்.', transliteration: 'Perungotaiyaan Penaan Vekuli Avanin Marungutaiyaar Maanilaththu Il', english_meaning: 'No one, in all the world, will have so many relatives (about him), as he who makes large gift, and does not give way to anger', career_application: 'No one, in all the world, will have so many relatives (about him), as he who makes large gift, and does not give way to anger', chapter: 'Cherishing Kinsmen' },
  { id: 527, kural_number: 527, tamil_text: 'காக்கை கரவா கரைந்துண்ணும் ஆக்கமும் அன்னநீ ரார்க்கே உள.', transliteration: 'Kaakkai Karavaa Karaindhunnum Aakkamum Annanee Raarkke Ula', english_meaning: 'The crows do not conceal (their prey), but will call out for others (to share with them) while they eat it; wealth will be with those who show a similar disposition (towards their relatives)', career_application: 'The crows do not conceal (their prey), but will call out for others (to share with them) while they eat it; wealth will be with those who show a similar disposition (towards their relatives)', chapter: 'Cherishing Kinsmen' },
  { id: 528, kural_number: 528, tamil_text: 'பொதுநோக்கான் வேந்தன் வரிசையா நோக்கின் அதுநோக்கி வாழ்வார் பலர்.', transliteration: 'Podhunokkaan Vendhan Varisaiyaa Nokkin Adhunokki Vaazhvaar Palar', english_meaning: 'Many relatives will live near a king, when they observe that he does not look on all alike, but that he looks on each man according to his merit', career_application: 'Many relatives will live near a king, when they observe that he does not look on all alike, but that he looks on each man according to his merit', chapter: 'Cherishing Kinsmen' },
  { id: 529, kural_number: 529, tamil_text: 'தமராகிக் தற்றுறந்தார் சுற்றம் அமராமைக் காரணம் இன்றி வரும்.', transliteration: 'Thamaraakik Thatrurandhaar Sutram Amaraamaik Kaaranam Indri Varum', english_meaning: 'Those who have been friends and have afterwards forsaken him, will return and join themselves (to him), when the cause of disagreement is not to be found in him', career_application: 'Those who have been friends and have afterwards forsaken him, will return and join themselves (to him), when the cause of disagreement is not to be found in him', chapter: 'Cherishing Kinsmen' },
  { id: 530, kural_number: 530, tamil_text: 'உழைப்பிரிந்து காரணத்தின் வந்தானை வேந்தன் இழைத் திருந்து எண்ணிக் கொளல்.', transliteration: 'Uzhaippirindhu Kaaranaththin Vandhaanai Vendhan Izhaith Thirundhu Ennik Kolal', english_meaning: 'When one may have left him, and for some cause has returned to him, let the king fulfil the object (for which he has come back) and thoughtfully receive him again', career_application: 'When one may have left him, and for some cause has returned to him, let the king fulfil the object (for which he has come back) and thoughtfully receive him again', chapter: 'Cherishing Kinsmen' },
  { id: 531, kural_number: 531, tamil_text: 'இறந்த வெகுளியின் தீதே சிறந்த உவகை மகிழ்ச்சியிற் சோர்வு.', transliteration: 'Irandha Vekuliyin Theedhe Sirandha Uvakai Makizhchchiyir Sorvu', english_meaning: 'More evil than excessive anger, is forgetfulness which springs from the intoxication of great joy', career_application: 'More evil than excessive anger, is forgetfulness which springs from the intoxication of great joy', chapter: 'Unforgetfulness' },
  { id: 532, kural_number: 532, tamil_text: 'பொச்சாப்புக் கொல்லும் புகழை அறிவினை நிச்ச நிரப்புக் கொன் றாங்கு.', transliteration: 'Pochchaappuk Kollum Pukazhai Arivinai Nichcha Nirappuk Kon Raangu', english_meaning: 'Forgetfulness will destroy fame, even as constant poverty destroys knowledge', career_application: 'Forgetfulness will destroy fame, even as constant poverty destroys knowledge', chapter: 'Unforgetfulness' },
  { id: 533, kural_number: 533, tamil_text: 'பொச்சாப்பார்க் கில்லை புகழ்மை அதுஉலகத்து எப்பால்நூ லோர்க்கும் துணிவு.', transliteration: 'Pochchaappaark Killai Pukazhmai Adhuulakaththu Eppaalnoo Lorkkum Thunivu', english_meaning: 'Thoughtlessness will never acquire fame; and this tenet is upheld by all treatises in the world', career_application: 'Thoughtlessness will never acquire fame; and this tenet is upheld by all treatises in the world', chapter: 'Unforgetfulness' },
  { id: 534, kural_number: 534, tamil_text: 'அச்ச முடையார்க்கு அரணில்லை ஆங்கில்லை பொச்சாப் புடையார்க்கு நன்கு.', transliteration: 'Achcha Mutaiyaarkku Aranillai Aangillai Pochchaap Putaiyaarkku Nanku', english_meaning: 'Just as the coward has no defence (by whatever fortifications ha may be surrounded), so the thoughtless has no good (whatever advantages he may possess)', career_application: 'Just as the coward has no defence (by whatever fortifications ha may be surrounded), so the thoughtless has no good (whatever advantages he may possess)', chapter: 'Unforgetfulness' },
  { id: 535, kural_number: 535, tamil_text: 'முன்னுறக் காவாது இழுக்கியான் தன்பிழை பின்னூறு இரங்கி விடும்.', transliteration: 'Munnurak Kaavaadhu Izhukkiyaan Thanpizhai Pinnooru Irangi Vitum', english_meaning: 'The thoughtless man, who provides not against the calamities that may happen, will afterwards repent for his fault', career_application: 'The thoughtless man, who provides not against the calamities that may happen, will afterwards repent for his fault', chapter: 'Unforgetfulness' },
  { id: 536, kural_number: 536, tamil_text: 'இழுக்காமை யார்மாட்டும் என்றும் வழுக்காமை வாயின் அதுவொப்பது இல்.', transliteration: 'Izhukkaamai Yaarmaattum Endrum Vazhukkaamai Vaayin Adhuvoppadhu Il', english_meaning: 'There is nothing comparable with the possession of unfailing thoughtfulness at all times; and towards all persons', career_application: 'There is nothing comparable with the possession of unfailing thoughtfulness at all times; and towards all persons', chapter: 'Unforgetfulness' },
  { id: 537, kural_number: 537, tamil_text: 'அரியஎன்று ஆகாத இல்லைபொச் சாவாக் கருவியால் போற்றிச் செயின்.', transliteration: 'Ariyaendru Aakaadha Illaipoch Chaavaak Karuviyaal Potrich Cheyin', english_meaning: 'There is nothing too difficult to be accomplished, if a man set about it carefully, with unflinching endeavour', career_application: 'There is nothing too difficult to be accomplished, if a man set about it carefully, with unflinching endeavour', chapter: 'Unforgetfulness' },
  { id: 538, kural_number: 538, tamil_text: 'புகழ்ந்தவை போற்றிச் செயல்வேண்டும் செய்யாது இகழ்ந்தார்க்கு எழுமையும் இல்.', transliteration: 'Pukazhndhavai Potrich Cheyalventum Seyyaadhu Ikazhndhaarkku Ezhumaiyum Il', english_meaning: 'Let (a man) observe and do these things which have been praised (by the wise); if he neglects and fails to perform them, for him there will be no (happiness) throughout the seven births', career_application: 'Let (a man) observe and do these things which have been praised (by the wise); if he neglects and fails to perform them, for him there will be no (happiness) throughout the seven births', chapter: 'Unforgetfulness' },
  { id: 539, kural_number: 539, tamil_text: 'இகழ்ச்சியின் கெட்டாரை உள்ளுக தாந்தம் மகிழ்ச்சியின் மைந்துறும் போழ்து.', transliteration: 'Ikazhchchiyin Kettaarai Ulluka Thaandham Makizhchchiyin Maindhurum Pozhdhu', english_meaning: 'Let (a king) think of those who have been ruined by neglect, when his mind is elated with joy', career_application: 'Let (a king) think of those who have been ruined by neglect, when his mind is elated with joy', chapter: 'Unforgetfulness' },
  { id: 540, kural_number: 540, tamil_text: 'உள்ளியது எய்தல் எளிதுமன் மற்றுந்தான் உள்ளியது உள்ளப் பெறின்.', transliteration: 'Ulliyadhu Eydhal Elidhuman Matrundhaan Ulliyadhu Ullap Perin', english_meaning: 'It is easy for (one) to obtain whatever he may think of, if he can again think of it', career_application: 'It is easy for (one) to obtain whatever he may think of, if he can again think of it', chapter: 'Unforgetfulness' },
  { id: 541, kural_number: 541, tamil_text: 'ஓர்ந்துகண் ணோடாது இறைபுரிந்து யார்மாட்டும் தேர்ந்துசெய் வஃதே முறை.', transliteration: 'Orndhukan Notaadhu Iraipurindhu Yaarmaattum Therndhusey Vaqdhe Murai', english_meaning: 'To examine into (the crimes which may be committed), to show no favour (to any one), to desire to act with impartiality towards all, and to inflict (such punishments) as may be wisely resolved on,', career_application: 'To examine into (the crimes which may be committed), to show no favour (to any one), to desire to act with impartiality towards all, and to inflict (such punishments) as may be wisely resolved on,', chapter: 'The Right Sceptre' },
  { id: 542, kural_number: 542, tamil_text: 'வானோக்கி வாழும் உலகெல்லாம் மன்னவன் கோல் நோக்கி வாழுங் குடி.', transliteration: 'Vaanokki Vaazhum Ulakellaam Mannavan Kol Nokki Vaazhung Kuti', english_meaning: 'When there is rain, the living creation thrives; and so when the king rules justly, his subjects thrive', career_application: 'When there is rain, the living creation thrives; and so when the king rules justly, his subjects thrive', chapter: 'The Right Sceptre' },
  { id: 543, kural_number: 543, tamil_text: 'அந்தணர் நூற்கும் அறத்திற்கும் ஆதியாய் நின்றது மன்னவன் கோல்.', transliteration: 'Andhanar Noorkum Araththirkum Aadhiyaai Nindradhu Mannavan Kol', english_meaning: 'The sceptre of the king is the firm support of the Vedas of the Brahmin, and of all virtues therein described', career_application: 'The sceptre of the king is the firm support of the Vedas of the Brahmin, and of all virtues therein described', chapter: 'The Right Sceptre' },
  { id: 544, kural_number: 544, tamil_text: 'குடிதழீஇக் கோலோச்சும் மாநில மன்னன் அடிதழீஇ நிற்கும் உலகு.', transliteration: 'Kutidhazheeik Kolochchum Maanila Mannan Atidhazheei Nirkum Ulaku', english_meaning: 'The world will constantly embrace the feet of the great king who rules over his subjects with love', career_application: 'The world will constantly embrace the feet of the great king who rules over his subjects with love', chapter: 'The Right Sceptre' },
  { id: 545, kural_number: 545, tamil_text: 'இயல்புளிக் கோலோச்சும் மன்னவன் நாட்ட பெயலும் விளையுளும் தொக்கு.', transliteration: 'Iyalpulik Kolochchum Mannavan Naatta Peyalum Vilaiyulum Thokku', english_meaning: 'Rain and plentiful crops will ever dwell together in the country of the king who sways his sceptre with justice', career_application: 'Rain and plentiful crops will ever dwell together in the country of the king who sways his sceptre with justice', chapter: 'The Right Sceptre' },
  { id: 546, kural_number: 546, tamil_text: 'வேலன்று வென்றி தருவது மன்னவன் கோலதூஉங் கோடா தெனின்.', transliteration: 'Velandru Vendri Tharuvadhu Mannavan Koladhooung Kotaa Thenin', english_meaning: 'It is not the javelin that gives victory, but the king\'s sceptre, if it do no injustice', career_application: 'It is not the javelin that gives victory, but the king\'s sceptre, if it do no injustice', chapter: 'The Right Sceptre' },
  { id: 547, kural_number: 547, tamil_text: 'இறைகாக்கும் வையகம் எல்லாம் அவனை முறைகாக்கும் முட்டாச் செயின்.', transliteration: 'Iraikaakkum Vaiyakam Ellaam Avanai Muraikaakkum Muttaach Cheyin', english_meaning: 'The king defends the whole world; and justice, when administered without defect, defends the king', career_application: 'The king defends the whole world; and justice, when administered without defect, defends the king', chapter: 'The Right Sceptre' },
  { id: 548, kural_number: 548, tamil_text: 'எண்பதத்தான் ஓரா முறைசெய்யா மன்னவன் தண்பதத்தான் தானே கெடும்.', transliteration: 'Enpadhaththaan Oraa Muraiseyyaa Mannavan Thanpadhaththaan Thaane Ketum', english_meaning: 'The king who gives not facile audience (to those who approach him), and who does not examine and pass judgment (on their complaints), will perish in disgrace', career_application: 'The king who gives not facile audience (to those who approach him), and who does not examine and pass judgment (on their complaints), will perish in disgrace', chapter: 'The Right Sceptre' },
  { id: 549, kural_number: 549, tamil_text: 'குடிபுறங் காத்தோம்பிக் குற்றம் கடிதல் வடுவன்று வேந்தன் தொழில்.', transliteration: 'Kutipurang Kaaththompik Kutram Katidhal Vatuvandru Vendhan Thozhil', english_meaning: 'In guarding his subjects (against injury from others), and in preserving them himself; to punish crime', career_application: 'In guarding his subjects (against injury from others), and in preserving them himself; to punish crime', chapter: 'The Right Sceptre' },
  { id: 550, kural_number: 550, tamil_text: 'கொலையிற் கொடியாரை வேந்தொறுத்தல் பைங்கூழ் களைகட் டதனொடு நேர்.', transliteration: 'Kolaiyir Kotiyaarai Vendhoruththal Paingoozh Kalaikat Tadhanotu Ner', english_meaning: 'For a king to punish criminals with death, is like pulling up the weeds in the green corn', career_application: 'For a king to punish criminals with death, is like pulling up the weeds in the green corn', chapter: 'The Right Sceptre' },
  { id: 551, kural_number: 551, tamil_text: 'கொலைமேற்கொண் டாரிற் கொடிதே அலைமேற்கொண்டு அல்லவை செய்தொழுகும் வேந்து.', transliteration: 'Kolaimerkon Taarir Kotidhe Alaimerkontu Allavai Seydhozhukum Vendhu', english_meaning: 'The king who gives himself up to oppression and acts unjustly (towards his subjects) is more cruel than the man who leads the life of a murderer', career_application: 'The king who gives himself up to oppression and acts unjustly (towards his subjects) is more cruel than the man who leads the life of a murderer', chapter: 'The Cruel Sceptre' },
  { id: 552, kural_number: 552, tamil_text: 'வேலொடு நின்றான் இடுவென் றதுபோலும் கோலொடு நின்றான் இரவு.', transliteration: 'Velotu Nindraan Ituven Radhupolum Kolotu Nindraan Iravu', english_meaning: 'The request (for money) of him who holds the sceptre is like the word of a highway robber who stands with a weapon in hand and says "give up your wealth"', career_application: 'The request (for money) of him who holds the sceptre is like the word of a highway robber who stands with a weapon in hand and says "give up your wealth"', chapter: 'The Cruel Sceptre' },
  { id: 553, kural_number: 553, tamil_text: 'நாடொறும் நாடி முறைசெய்யா மன்னவன் நாடொறும் நாடு கெடும்.', transliteration: 'Naatorum Naati Muraiseyyaa Mannavan Naatorum Naatu Ketum', english_meaning: 'The country of the king who does not daily examine into the wrongs done and distribute justice, will daily fall to ruin', career_application: 'The country of the king who does not daily examine into the wrongs done and distribute justice, will daily fall to ruin', chapter: 'The Cruel Sceptre' },
  { id: 554, kural_number: 554, tamil_text: 'கூழுங் குடியும் ஒருங்கிழக்கும் கோல்கோடிச் சூழாது செய்யும் அரசு.', transliteration: 'Koozhung Kutiyum Orungizhakkum Kolkotich Choozhaadhu Seyyum Arasu', english_meaning: 'The king, who, without reflecting (on its evil consequences), perverts justice, will lose at once both his wealth and his subjects', career_application: 'The king, who, without reflecting (on its evil consequences), perverts justice, will lose at once both his wealth and his subjects', chapter: 'The Cruel Sceptre' },
  { id: 555, kural_number: 555, tamil_text: 'அல்லற்பட்டு ஆற்றாது அழுதகண் ணீரன்றே செல்வத்தைத் தேய்க்கும் படை', transliteration: 'Allarpattu Aatraadhu Azhudhakan Neerandre Selvaththaith Theykkum Patai', english_meaning: 'Will not the tears, shed by a people who cannot endure the oppression which they suffer (from their king), become a saw to waste away his wealth ?', career_application: 'Will not the tears, shed by a people who cannot endure the oppression which they suffer (from their king), become a saw to waste away his wealth ?', chapter: 'The Cruel Sceptre' },
  { id: 556, kural_number: 556, tamil_text: 'மன்னர்க்கு மன்னுதல் செங்கோன்மை அஃதின்றேல் மன்னாவாம் மன்னர்க் கொளி.', transliteration: 'Mannarkku Mannudhal Sengonmai Aqdhindrel Mannaavaam Mannark Koli', english_meaning: 'Righteous government gives permanence to (the fame of) kings; without that their fame will have no endurance', career_application: 'Righteous government gives permanence to (the fame of) kings; without that their fame will have no endurance', chapter: 'The Cruel Sceptre' },
  { id: 557, kural_number: 557, tamil_text: 'துளியின்மை ஞாலத்திற்கு எற்றற்றே வேந்தன் அளியின்மை வாழும் உயிர்க்கு.', transliteration: 'Thuliyinmai Gnaalaththirku Etratre Vendhan Aliyinmai Vaazhum Uyirkku', english_meaning: 'As is the world without rain, so live a people whose king is without kindness', career_application: 'As is the world without rain, so live a people whose king is without kindness', chapter: 'The Cruel Sceptre' },
  { id: 558, kural_number: 558, tamil_text: 'இன்மையின் இன்னாது உடைமை முறைசெய்யா மன்னவன் கோற்கீழ்ப் படின்.', transliteration: 'Inmaiyin Innaadhu Utaimai Muraiseyyaa Mannavan Korkeezhp Patin', english_meaning: 'Property gives more sorrow than poverty, to those who live under the sceptre of a king without justice', career_application: 'Property gives more sorrow than poverty, to those who live under the sceptre of a king without justice', chapter: 'The Cruel Sceptre' },
  { id: 559, kural_number: 559, tamil_text: 'முறைகோடி மன்னவன் செய்யின் உறைகோடி ஒல்லாது வானம் பெயல்.', transliteration: 'Muraikoti Mannavan Seyyin Uraikoti Ollaadhu Vaanam Peyal', english_meaning: 'If the king acts contrary to justice, rain will become unseasonable, and the heavens will withhold their showers', career_application: 'If the king acts contrary to justice, rain will become unseasonable, and the heavens will withhold their showers', chapter: 'The Cruel Sceptre' },
  { id: 560, kural_number: 560, tamil_text: 'ஆபயன் குன்றும் அறுதொழிலோர் நூல்மறப்பர் காவலன் காவான் எனின்.', transliteration: 'Aapayan Kundrum Arudhozhilor Noolmarappar Kaavalan Kaavaan Enin', english_meaning: 'If the guardian (of the country) neglects to guard it, the produce of the cows will fail, and the men of six duties viz, the Brahmins will forget the vedas', career_application: 'If the guardian (of the country) neglects to guard it, the produce of the cows will fail, and the men of six duties viz, the Brahmins will forget the vedas', chapter: 'The Cruel Sceptre' },
  { id: 561, kural_number: 561, tamil_text: 'தக்காங்கு நாடித் தலைச்செல்லா வண்ணத்தால் ஒத்தாங்கு ஒறுப்பது வேந்து.', transliteration: 'Thakkaangu Naatith Thalaichchellaa Vannaththaal Oththaangu Oruppadhu Vendhu', english_meaning: 'He is a king who having equitably examined (any injustice which has been brought to his notice), suitably punishes it, so that it may not be again committed', career_application: 'He is a king who having equitably examined (any injustice which has been brought to his notice), suitably punishes it, so that it may not be again committed', chapter: 'Absence of Terrorism' },
  { id: 562, kural_number: 562, tamil_text: 'கடிதோச்சி மெல்ல எறிக நெடிதாக்கம் நீங்காமை வேண்டு பவர்.', transliteration: 'Katidhochchi Mella Erika Netidhaakkam Neengaamai Ventu Pavar', english_meaning: 'Let the king, who desires that his prosperity may long remain, commence his preliminary enquires with strictness, and then punish with mildness', career_application: 'Let the king, who desires that his prosperity may long remain, commence his preliminary enquires with strictness, and then punish with mildness', chapter: 'Absence of Terrorism' },
  { id: 563, kural_number: 563, tamil_text: 'வெருவந்த செய்தொழுகும் வெங்கோல னாயின் ஒருவந்தம் ஒல்லைக் கெடும்.', transliteration: 'Veruvandha Seydhozhukum Vengola Naayin Oruvandham Ollaik Ketum', english_meaning: 'The cruel-sceptred king, who acts so as to put his subjects in fear, will certainly and quickly come to ruin', career_application: 'The cruel-sceptred king, who acts so as to put his subjects in fear, will certainly and quickly come to ruin', chapter: 'Absence of Terrorism' },
  { id: 564, kural_number: 564, tamil_text: 'இறைகடியன் என்றுரைக்கும் இன்னாச்சொல் வேந்தன் உறைகடுகி ஒல்லைக் கெடும்.', transliteration: 'Iraikatiyan Endruraikkum Innaachchol Vendhan Uraikatuki Ollaik Ketum', english_meaning: 'The king who is spoken of as cruel will quickly perish; his life becoming shortened', career_application: 'The king who is spoken of as cruel will quickly perish; his life becoming shortened', chapter: 'Absence of Terrorism' },
  { id: 565, kural_number: 565, tamil_text: 'அருஞ்செவ்வி இன்னா முகத்தான் பெருஞ்செல்வம் பேஎய்கண் டன்னது உடைத்து.', transliteration: 'Arunjevvi Innaa Mukaththaan Perunjelvam Peeykan Tannadhu Utaiththu', english_meaning: 'The great wealth of him who is difficult of access and possesses a sternness of countenance, is like that which has been obtained by a devil', career_application: 'The great wealth of him who is difficult of access and possesses a sternness of countenance, is like that which has been obtained by a devil', chapter: 'Absence of Terrorism' },
  { id: 566, kural_number: 566, tamil_text: 'கடுஞ்சொல்லன் கண்ணிலன் ஆயின் நெடுஞ்செல்வம் நீடின்றி ஆங்கே கெடும்.', transliteration: 'Katunjollan Kannilan Aayin Netunjelvam Neetindri Aange Ketum', english_meaning: 'The abundant wealth of the king whose words are harsh and whose looks are void of kindness, will instantly perish instead of abiding long, with him', career_application: 'The abundant wealth of the king whose words are harsh and whose looks are void of kindness, will instantly perish instead of abiding long, with him', chapter: 'Absence of Terrorism' },
  { id: 567, kural_number: 567, tamil_text: 'கடுமொழியும் கையிகந்த தண்டமும் வேந்தன் அடுமுரண் தேய்க்கும் அரம்.', transliteration: 'Katumozhiyum Kaiyikandha Thantamum Vendhan Atumuran Theykkum Aram', english_meaning: 'Severe words and excessive punishments will be a file to waste away a king\'s power for destroying (his enemies)', career_application: 'Severe words and excessive punishments will be a file to waste away a king\'s power for destroying (his enemies)', chapter: 'Absence of Terrorism' },
  { id: 568, kural_number: 568, tamil_text: 'இனத்தாற்றி எண்ணாத வேந்தன் சினத்தாற்றிச் சீறிற் சிறுகும் திரு.', transliteration: 'Inaththaatri Ennaadha Vendhan Sinaththaatrich Cheerir Sirukum Thiru', english_meaning: 'The prosperity of that king will waste away, who without reflecting (on his affairs himself), commits them to his ministers, and (when a failure occurs) gives way to anger, and rages against them', career_application: 'The prosperity of that king will waste away, who without reflecting (on his affairs himself), commits them to his ministers, and (when a failure occurs) gives way to anger, and rages against them', chapter: 'Absence of Terrorism' },
  { id: 569, kural_number: 569, tamil_text: 'செருவந்த போழ்திற் சிறைசெய்யா வேந்தன் வெருவந்து வெய்து கெடும்.', transliteration: 'Seruvandha Pozhdhir Siraiseyyaa Vendhan Veruvandhu Veydhu Ketum', english_meaning: 'The king who has not provided himself with a place of defence, will in times of war be seized with fear and quickly perish', career_application: 'The king who has not provided himself with a place of defence, will in times of war be seized with fear and quickly perish', chapter: 'Absence of Terrorism' },
  { id: 570, kural_number: 570, tamil_text: 'கல்லார்ப் பிணிக்கும் கடுங்கோல் அதுவல்லது இல்லை நிலக்குப் பொறை.', transliteration: 'Kallaarp Pinikkum Katungol Adhuvalladhu Illai Nilakkup Porai', english_meaning: 'The earth bears up no greater burden than ignorant men whom a cruel sceptre attaches to itself (as the ministers of its evil deeds)', career_application: 'The earth bears up no greater burden than ignorant men whom a cruel sceptre attaches to itself (as the ministers of its evil deeds)', chapter: 'Absence of Terrorism' },
  { id: 571, kural_number: 571, tamil_text: 'கண்ணோட்டம் என்னும் கழிபெருங் காரிகை உண்மையான் உண்டிவ் வுலகு.', transliteration: 'Kannottam Ennum Kazhiperung Kaarikai Unmaiyaan Untiv Vulaku', english_meaning: 'The world exists through that greatest ornament (of princes), a gracious demeanour', career_application: 'The world exists through that greatest ornament (of princes), a gracious demeanour', chapter: 'Benignity' },
  { id: 572, kural_number: 572, tamil_text: 'கண்ணோட்டத் துள்ளது உலகியல் அஃதிலார் உண்மை நிலக்குப் பொறை.', transliteration: 'Kannottath Thulladhu Ulakiyal Aqdhilaar Unmai Nilakkup Porai', english_meaning: 'The prosperity of the world springs from the kindliness, the existence of those who have no (kindliness) is a burden to the earth', career_application: 'The prosperity of the world springs from the kindliness, the existence of those who have no (kindliness) is a burden to the earth', chapter: 'Benignity' },
  { id: 573, kural_number: 573, tamil_text: 'பண்என்னாம் பாடற்கு இயைபின்றேல் கண்என்னாம் கண்ணோட்டம் இல்லாத கண்.', transliteration: 'Panennaam Paatarku Iyaipindrel Kanennaam Kannottam Illaadha Kan', english_meaning: 'Of what avail is a song if it be inconsistent with harmony ? what is the use of eyes which possess no kindliness', career_application: 'Of what avail is a song if it be inconsistent with harmony ? what is the use of eyes which possess no kindliness', chapter: 'Benignity' },
  { id: 574, kural_number: 574, tamil_text: 'உளபோல் முகத்தெவன் செய்யும் அளவினால் கண்ணோட்டம் இல்லாத கண்.', transliteration: 'Ulapol Mukaththevan Seyyum Alavinaal Kannottam Illaadha Kan', english_meaning: 'Beyond appearing to be in the face, what good do they do, those eyes in which is no well-regulated kindness ?', career_application: 'Beyond appearing to be in the face, what good do they do, those eyes in which is no well-regulated kindness ?', chapter: 'Benignity' },
  { id: 575, kural_number: 575, tamil_text: 'கண்ணிற்கு அணிகலம் கண்ணோட்டம் அஃதின்றேல் புண்ணென்று உணரப் படும்', transliteration: 'Kannirku Anikalam Kannottam Aqdhindrel Punnendru Unarap Patum', english_meaning: 'Kind looks are the ornaments of the eyes; without these they will be considered (by the wise) to be merely two sores', career_application: 'Kind looks are the ornaments of the eyes; without these they will be considered (by the wise) to be merely two sores', chapter: 'Benignity' },
  { id: 576, kural_number: 576, tamil_text: 'மண்ணோ டியைந்த மரத்தனையர் கண்ணோ டியைந்துகண் ணோடா தவர்.', transliteration: 'Manno Tiyaindha Maraththanaiyar Kanno Tiyaindhukan Notaa Thavar', english_meaning: 'They resemble the trees of the earth, who although they have eyes, never look kindly (on others)', career_application: 'They resemble the trees of the earth, who although they have eyes, never look kindly (on others)', chapter: 'Benignity' },
  { id: 577, kural_number: 577, tamil_text: 'கண்ணோட்டம் இல்லவர் கண்ணிலர் கண்ணுடையார் கண்ணோட்டம் இன்மையும் இல்.', transliteration: 'Kannottam Illavar Kannilar Kannutaiyaar Kannottam Inmaiyum Il', english_meaning: 'Men without kind looks are men without eyes; those who (really) have eyes are also not devoid of kind looks', career_application: 'Men without kind looks are men without eyes; those who (really) have eyes are also not devoid of kind looks', chapter: 'Benignity' },
  { id: 578, kural_number: 578, tamil_text: 'கருமம் சிதையாமல் கண்ணோட வல்லார்க்கு உரிமை உடைத்திவ் வுலகு.', transliteration: 'Karumam Sidhaiyaamal Kannota Vallaarkku Urimai Utaiththiv Vulaku', english_meaning: 'The world is theirs (kings) who are able to show kindness, without injury to their affairs, (administration of justice)', career_application: 'The world is theirs (kings) who are able to show kindness, without injury to their affairs, (administration of justice)', chapter: 'Benignity' },
  { id: 579, kural_number: 579, tamil_text: 'ஒறுத்தாற்றும் பண்பினார் கண்ணும்கண் ணோடிப் பொறுத்தாற்றும் பண்பே தலை.', transliteration: 'Oruththaatrum Panpinaar Kannumkan Notip Poruththaatrum Panpe Thalai', english_meaning: 'Patiently to bear with, and show kindness to those who grieve us, is the most excellent of all dispositions', career_application: 'Patiently to bear with, and show kindness to those who grieve us, is the most excellent of all dispositions', chapter: 'Benignity' },
  { id: 580, kural_number: 580, tamil_text: 'பெயக்கண்டும் நஞ்சுண் டமைவர் நயத்தக்க நாகரிகம் வேண்டு பவர்.', transliteration: 'Peyakkantum Nanjun Tamaivar Nayaththakka Naakarikam Ventu Pavar', english_meaning: 'Those who desire (to cultivate that degree of) urbanity which all shall love, even after swallowing the poison served to them by their friends, will be friendly with them', career_application: 'Those who desire (to cultivate that degree of) urbanity which all shall love, even after swallowing the poison served to them by their friends, will be friendly with them', chapter: 'Benignity' },
  { id: 581, kural_number: 581, tamil_text: 'ஒற்றும் உரைசான்ற நூலும் இவையிரண்டும் தெற்றென்க மன்னவன் கண்.', transliteration: 'Otrum Uraisaandra Noolum Ivaiyirantum Thetrenka Mannavan Kan', english_meaning: 'Let a king consider as his eyes these two things, a spy and a book (of laws) universally esteemed', career_application: 'Let a king consider as his eyes these two things, a spy and a book (of laws) universally esteemed', chapter: 'Detectives' },
  { id: 582, kural_number: 582, tamil_text: 'எல்லார்க்கும் எல்லாம் நிகழ்பவை எஞ்ஞான்றும் வல்லறிதல் வேந்தன் தொழில்.', transliteration: 'Ellaarkkum Ellaam Nikazhpavai Egngnaandrum Vallaridhal Vendhan Thozhil', english_meaning: '\'Tis duty of the king to learn with speed', career_application: '\'Tis duty of the king to learn with speed', chapter: 'Detectives' },
  { id: 583, kural_number: 583, tamil_text: 'ஒற்றினான் ஒற்றிப் பொருள்தெரியா மன்னவன் கொற்றங் கொளக்கிடந்தது இல்.', transliteration: 'Otrinaan Otrip Poruldheriyaa Mannavan Kotrang Kolakkitandhadhu Il', english_meaning: 'There is no way for a king to obtain conquests, who knows not the advantage of discoveries made by a spy', career_application: 'There is no way for a king to obtain conquests, who knows not the advantage of discoveries made by a spy', chapter: 'Detectives' },
  { id: 584, kural_number: 584, tamil_text: 'வினைசெய்வார் தம்சுற்றம் வேண்டாதார் என்றாங்கு அனைவரையும் ஆராய்வது ஒற்று.', transliteration: 'Vinaiseyvaar Thamsutram Ventaadhaar Endraangu Anaivaraiyum Aaraaivadhu Otru', english_meaning: 'He is a spy who watches all men, to wit, those who are in the king\'s employment, his relatives, and his enemies', career_application: 'He is a spy who watches all men, to wit, those who are in the king\'s employment, his relatives, and his enemies', chapter: 'Detectives' },
  { id: 585, kural_number: 585, tamil_text: 'கடாஅ உருவொடு கண்ணஞ்சாது யாண்டும் உகாஅமை வல்லதே ஒற்று.', transliteration: 'Kataaa Uruvotu Kannanjaadhu Yaantum Ukaaamai Valladhe Otru', english_meaning: 'A spy is one who is able to assume an appearance which may create no suspicion (in the minds of others), who fears no man\'s face, and who never reveals (his purpose)', career_application: 'A spy is one who is able to assume an appearance which may create no suspicion (in the minds of others), who fears no man\'s face, and who never reveals (his purpose)', chapter: 'Detectives' },
  { id: 586, kural_number: 586, tamil_text: 'துறந்தார் படிவத்த ராகி இறந்தாராய்ந்து என்செயினும் சோர்விலது ஒற்று.', transliteration: 'Thurandhaar Pativaththa Raaki Irandhaaraaindhu Enseyinum Sorviladhu Otru', english_meaning: 'He is a spy who, assuming the appearance of an ascetic, goes into (whatever place he wishes), examines into (all, that is needful), and never discovers himself, whatever may be done to him', career_application: 'He is a spy who, assuming the appearance of an ascetic, goes into (whatever place he wishes), examines into (all, that is needful), and never discovers himself, whatever may be done to him', chapter: 'Detectives' },
  { id: 587, kural_number: 587, tamil_text: 'மறைந்தவை கேட்கவற் றாகி அறிந்தவை ஐயப்பாடு இல்லதே ஒற்று.', transliteration: 'Maraindhavai Ketkavar Raaki Arindhavai Aiyappaatu Illadhe Otru', english_meaning: 'A spy is one who is able to discover what is hidden and who retains no doubt concerning what he has known', career_application: 'A spy is one who is able to discover what is hidden and who retains no doubt concerning what he has known', chapter: 'Detectives' },
  { id: 588, kural_number: 588, tamil_text: 'ஒற்றொற்றித் தந்த பொருளையும் மற்றுமோர் ஒற்றினால் ஒற்றிக் கொளல்.', transliteration: 'Otrotrith Thandha Porulaiyum Matrumor Otrinaal Otrik Kolal', english_meaning: 'Let not a king receive the information which a spy has discovered and made known to him, until he has examined it by another spy', career_application: 'Let not a king receive the information which a spy has discovered and made known to him, until he has examined it by another spy', chapter: 'Detectives' },
  { id: 589, kural_number: 589, tamil_text: 'ஒற்றெற் றுணராமை ஆள்க உடன்மூவர் சொற்றொக்க தேறப் படும்.', transliteration: 'Otrer Runaraamai Aalka Utanmoovar Sotrokka Therap Patum', english_meaning: 'Let a king employ spies so that one may have no knowledge of the other; and when the information of three agrees together, let him receive it', career_application: 'Let a king employ spies so that one may have no knowledge of the other; and when the information of three agrees together, let him receive it', chapter: 'Detectives' },
  { id: 590, kural_number: 590, tamil_text: 'சிறப்பறிய ஒற்றின்கண் செய்யற்க செய்யின் புறப்படுத்தான் ஆகும் மறை.', transliteration: 'Sirappariya Otrinkan Seyyarka Seyyin Purappatuththaan Aakum Marai', english_meaning: 'Let not a king publicly confer on a spy any marks of his favour; if he does, he will divulge his own secret', career_application: 'Let not a king publicly confer on a spy any marks of his favour; if he does, he will divulge his own secret', chapter: 'Detectives' },
  { id: 591, kural_number: 591, tamil_text: 'உடையர் எனப்படுவது ஊக்கம் அஃதில்லார் உடையது உடையரோ மற்று.', transliteration: 'Utaiyar Enappatuvadhu Ookkam Aqdhillaar Utaiyadhu Utaiyaro Matru', english_meaning: 'Energy makes out the man of property; as for those who are destitute of it, do they (really) possess what they possess ?', career_application: 'Energy makes out the man of property; as for those who are destitute of it, do they (really) possess what they possess ?', chapter: 'Energy' },
  { id: 592, kural_number: 592, tamil_text: 'உள்ளம் உடைமை உடைமை பொருளுடைமை நில்லாது நீங்கி விடும்.', transliteration: 'Ullam Utaimai Utaimai Porulutaimai Nillaadhu Neengi Vitum', english_meaning: 'The possession of (energy of) mind is true property; the possession of wealth passes away and abides not', career_application: 'The possession of (energy of) mind is true property; the possession of wealth passes away and abides not', chapter: 'Energy' },
  { id: 593, kural_number: 593, tamil_text: 'ஆக்கம் இழந்தேமென்று அல்லாவார் ஊக்கம் ஒருவந்தம் கைத்துடை யார்.', transliteration: 'Aakkam Izhandhemendru Allaavaar Ookkam Oruvandham Kaiththutai Yaar', english_meaning: 'They who are possessed of enduring energy will not trouble themselves, saying, "we have lost our property."', career_application: 'They who are possessed of enduring energy will not trouble themselves, saying, "we have lost our property."', chapter: 'Energy' },
  { id: 594, kural_number: 594, tamil_text: 'ஆக்கம் அதர்வினாய்ச் செல்லும் அசைவிலா ஊக்க முடையா னுழை.', transliteration: 'Aakkam Adharvinaaich Chellum Asaivilaa Ookka Mutaiyaa Nuzhai', english_meaning: 'Wealth will find its own way to the man of unfailing energy', career_application: 'Wealth will find its own way to the man of unfailing energy', chapter: 'Energy' },
  { id: 595, kural_number: 595, tamil_text: 'வெள்ளத் தனைய மலர்நீட்டம் மாந்தர்தம் உள்ளத் தனையது உயர்வு.', transliteration: 'Vellath Thanaiya Malarneettam Maandhardham Ullath Thanaiyadhu Uyarvu', english_meaning: 'The stalks of water-flowers are proportionate to the depth of water; so is men\'s greatness proportionate to their minds', career_application: 'The stalks of water-flowers are proportionate to the depth of water; so is men\'s greatness proportionate to their minds', chapter: 'Energy' },
  { id: 596, kural_number: 596, tamil_text: 'உள்ளுவ தெல்லாம் உயர்வுள்ளல் மற்றது தள்ளினுந் தள்ளாமை நீர்த்து.', transliteration: 'Ulluva Thellaam Uyarvullal Matradhu Thallinun Thallaamai Neerththu', english_meaning: 'In all that a king thinks of, let him think of his greatness; and if it should be thrust from him (by fate), it will have the nature of not being thrust from him', career_application: 'In all that a king thinks of, let him think of his greatness; and if it should be thrust from him (by fate), it will have the nature of not being thrust from him', chapter: 'Energy' },
  { id: 597, kural_number: 597, tamil_text: 'சிதைவிடத்து ஒல்கார் உரவோர் புதையம்பிற் பட்டுப்பா டூன்றுங் களிறு.', transliteration: 'Sidhaivitaththu Olkaar Uravor Pudhaiyampir Pattuppaa Toondrung Kaliru', english_meaning: 'The strong minded will not faint, even when all is lost; the elephant stands firm, even when wounded by a shower of arrows', career_application: 'The strong minded will not faint, even when all is lost; the elephant stands firm, even when wounded by a shower of arrows', chapter: 'Energy' },
  { id: 598, kural_number: 598, tamil_text: 'உள்ளம் இலாதவர் எய்தார் உலகத்து வள்ளியம் என்னுஞ் செருக்கு.', transliteration: 'Ullam Ilaadhavar Eydhaar Ulakaththu Valliyam Ennunj Cherukku', english_meaning: 'Those who have no (greatness of) mind, will not acquire the joy of saying in the world, "we have excercised liaberality"', career_application: 'Those who have no (greatness of) mind, will not acquire the joy of saying in the world, "we have excercised liaberality"', chapter: 'Energy' },
  { id: 599, kural_number: 599, tamil_text: 'பரியது கூர்ங்கோட்டது ஆயினும் யானை ஦வ்ருஉம் புலிதாக் குறின்.', transliteration: 'Pariyadhu Koorngottadhu Aayinum Yaanai Veruum Pulidhaak Kurin', english_meaning: 'Although the elephant has a large body, and a sharp tusk, yet it fears the attack of the tiger', career_application: 'Although the elephant has a large body, and a sharp tusk, yet it fears the attack of the tiger', chapter: 'Energy' },
  { id: 600, kural_number: 600, tamil_text: 'உரமொருவற்கு உள்ள வெறுக்கைஅஃ தில்லார் மரம்மக்க ளாதலே வேறு.', transliteration: 'Uramoruvarku Ulla Verukkaiaq Thillaar Marammakka Laadhale Veru', english_meaning: 'Energy is mental wealth; those men who are destitute of it are only trees in the form of men', career_application: 'Energy is mental wealth; those men who are destitute of it are only trees in the form of men', chapter: 'Energy' },
  { id: 601, kural_number: 601, tamil_text: 'குடியென்னும் குன்றா விளக்கம் மடியென்னும் மாசூர மாய்ந்து கெடும்.', transliteration: 'Kutiyennum Kundraa Vilakkam Matiyennum Maasoora Maaindhu Ketum', english_meaning: 'By the darkness, of idleness, the indestructible lamp of family (rank) will be extinguished', career_application: 'By the darkness, of idleness, the indestructible lamp of family (rank) will be extinguished', chapter: 'Unsluggishness' },
  { id: 602, kural_number: 602, tamil_text: 'மடியை மடியா ஒழுகல் குடியைக் குடியாக வேண்டு பவர்.', transliteration: 'Matiyai Matiyaa Ozhukal Kutiyaik Kutiyaaka Ventu Pavar', english_meaning: 'Let those, who desire that their family may be illustrious, put away all idleness from their conduct', career_application: 'Let those, who desire that their family may be illustrious, put away all idleness from their conduct', chapter: 'Unsluggishness' },
  { id: 603, kural_number: 603, tamil_text: 'மடிமடிக் கொண்டொழுகும் பேதை பிறந்த குடிமடியும் தன்னினும் முந்து.', transliteration: 'Matimatik Kontozhukum Pedhai Pirandha Kutimatiyum Thanninum Mundhu', english_meaning: 'The (lustre of the) family of the ignorant man, who acts under the influence of destructive laziness will perish, even before he is dead', career_application: 'The (lustre of the) family of the ignorant man, who acts under the influence of destructive laziness will perish, even before he is dead', chapter: 'Unsluggishness' },
  { id: 604, kural_number: 604, tamil_text: 'குடிமடிந்து குற்றம் பெருகும் மடிமடிந்து மாண்ட உஞற்றி லவர்க்கு.', transliteration: 'Kutimatindhu Kutram Perukum Matimatindhu Maanta Ugnatri Lavarkku', english_meaning: 'Family (greatness) will be destroyed, and faults will increase, in those men who give way to laziness, and put forth no dignified exertions', career_application: 'Family (greatness) will be destroyed, and faults will increase, in those men who give way to laziness, and put forth no dignified exertions', chapter: 'Unsluggishness' },
  { id: 605, kural_number: 605, tamil_text: 'நெடுநீர் மறவி மடிதுயில் நான்கும் கெடுநீரார் காமக் கலன்.', transliteration: 'Netuneer Maravi Matidhuyil Naankum Ketuneeraar Kaamak Kalan', english_meaning: 'Procrastination, forgetfulness, idleness, and sleep, these four things, form the vessel which is desired by those destined to destruction', career_application: 'Procrastination, forgetfulness, idleness, and sleep, these four things, form the vessel which is desired by those destined to destruction', chapter: 'Unsluggishness' },
  { id: 606, kural_number: 606, tamil_text: 'படியுடையார் பற்றமைந்தக் கண்ணும் மடியுடையார் மாண்பயன் எய்தல் அரிது.', transliteration: 'Patiyutaiyaar Patramaindhak Kannum Matiyutaiyaar Maanpayan Eydhal Aridhu', english_meaning: 'It is a rare thing for the idle, even when possessed of the riches of kings who ruled over the whole earth, to derive any great benefit from it', career_application: 'It is a rare thing for the idle, even when possessed of the riches of kings who ruled over the whole earth, to derive any great benefit from it', chapter: 'Unsluggishness' },
  { id: 607, kural_number: 607, tamil_text: 'இடிபுரிந்து எள்ளுஞ்சொல் கேட்பர் மடிபுரிந்து மாண்ட உஞற்றி லவர்.', transliteration: 'Itipurindhu Ellunj Chol Ketpar Matipurindhu Maanta Ugnatri Lavar', english_meaning: 'Those who through idleness, and do not engage themselves in dignified exertion, will subject', career_application: 'Those who through idleness, and do not engage themselves in dignified exertion, will subject', chapter: 'Unsluggishness' },
  { id: 608, kural_number: 608, tamil_text: 'மடிமை குடிமைக்கண் தங்கின்தன் ஒன்னார்க்கு அடிமை புகுத்தி விடும்.', transliteration: 'Matimai Kutimaikkan Thangindhan Onnaarkku Atimai Pukuththi Vitum', english_meaning: 'If idleness take up its abode in a king of high birth, it will make him a slave of his enemies', career_application: 'If idleness take up its abode in a king of high birth, it will make him a slave of his enemies', chapter: 'Unsluggishness' },
  { id: 609, kural_number: 609, tamil_text: 'குடியாண்மை யுள்வந்த குற்றம் ஒருவன் மடியாண்மை மாற்றக் கெடும்.', transliteration: 'Kutiyaanmai Yulvandha Kutram Oruvan Matiyaanmai Maatrak Ketum', english_meaning: 'When a man puts away idleness, the reproach which has come upon himself and his family will disappear', career_application: 'When a man puts away idleness, the reproach which has come upon himself and his family will disappear', chapter: 'Unsluggishness' },
  { id: 610, kural_number: 610, tamil_text: 'மடியிலா மன்னவன் எய்தும் அடியளந்தான் தாஅய தெல்லாம் ஒருங்கு.', transliteration: 'Matiyilaa Mannavan Eydhum Atiyalandhaan Thaaaya Thellaam Orungu', english_meaning: 'The king who never gives way to idleness will obtain entire possession of (the whole earth) passed over by him who measured (the worlds) with His foot', career_application: 'The king who never gives way to idleness will obtain entire possession of (the whole earth) passed over by him who measured (the worlds) with His foot', chapter: 'Unsluggishness' },
  { id: 611, kural_number: 611, tamil_text: 'அருமை உடைத்தென்று அசாவாமை வேண்டும் பெருமை முயற்சி தரும்.', transliteration: 'Arumai Utaiththendru Asaavaamai Ventum Perumai Muyarsi Tharum', english_meaning: 'Yield not to the feebleness which says, "this is too difficult to be done"; labour will give the greatness (of mind) which is necessary (to do it)', career_application: 'Yield not to the feebleness which says, "this is too difficult to be done"; labour will give the greatness (of mind) which is necessary (to do it)', chapter: 'Manly Effort' },
  { id: 612, kural_number: 612, tamil_text: 'வினைக்கண் வினைகெடல் ஓம்பல் வினைக்குறை தீர்ந்தாரின் தீர்ந்தன்று உலகு.', transliteration: 'Vinaikkan Vinaiketal Ompal Vinaikkurai Theerndhaarin Theerndhandru Ulaku', english_meaning: 'Take care not to give up exertion in the midst of a work; the world will abandon those who abandon their unfinished work', career_application: 'Take care not to give up exertion in the midst of a work; the world will abandon those who abandon their unfinished work', chapter: 'Manly Effort' },
  { id: 613, kural_number: 613, tamil_text: 'தாளாண்மை என்னும் தகைமைக்கண் தங்கிற்றே வேளாண்மை என்னுஞ் செருக்கு.', transliteration: 'Thaalaanmai Ennum Thakaimaikkan Thangitre Velaanmai Ennunj Cherukku', english_meaning: 'The lustre of munificence will dwell only with the dignity of laboriousness or efforts', career_application: 'The lustre of munificence will dwell only with the dignity of laboriousness or efforts', chapter: 'Manly Effort' },
  { id: 614, kural_number: 614, tamil_text: 'தாளாண்மை இல்லாதான் வேளாண்மை பேடிகை வாளாண்மை போலக் கெடும்.', transliteration: 'Thaalaanmai Illaadhaan Velaanmai Petikai Vaalaanmai Polak Ketum', english_meaning: 'The liberality of him, who does not labour, will fail, like the manliness of a hermaphrodite, who has a sword in its hand', career_application: 'The liberality of him, who does not labour, will fail, like the manliness of a hermaphrodite, who has a sword in its hand', chapter: 'Manly Effort' },
  { id: 615, kural_number: 615, tamil_text: 'இன்பம் விழையான் வினைவிழைவான் தன்கேளிர் துன்பம் துடைத்தூன்றும் தூண்.', transliteration: 'Inpam Vizhaiyaan Vinaivizhaivaan Thankelir Thunpam Thutaiththoondrum Thoon', english_meaning: 'He who desires not pleasure, but desires labour, will be a pillar to sustain his relations, wiping away their sorrows', career_application: 'He who desires not pleasure, but desires labour, will be a pillar to sustain his relations, wiping away their sorrows', chapter: 'Manly Effort' },
  { id: 616, kural_number: 616, tamil_text: 'முயற்சி திருவினை ஆக்கும் முயற்றின்மை இன்மை புகுத்தி விடும்.', transliteration: 'Muyarsi Thiruvinai Aakkum Muyatrinmai Inmai Pukuththi Vitum', english_meaning: 'Labour will produce wealth; idleness will bring poverty', career_application: 'Labour will produce wealth; idleness will bring poverty', chapter: 'Manly Effort' },
  { id: 617, kural_number: 617, tamil_text: 'மடியுளாள் மாமுகடி என்ப மடியிலான் தாளுளான் தாமரையி னாள்.', transliteration: 'Matiyulaal Maamukati Enpa Matiyilaan Thaalulaan Thaamaraiyi Naal', english_meaning: 'They say that the black Mudevi (the goddess of adversity) dwells with laziness, and the Latchmi (the goddess of prosperity) dwells with the labour of the industrious', career_application: 'They say that the black Mudevi (the goddess of adversity) dwells with laziness, and the Latchmi (the goddess of prosperity) dwells with the labour of the industrious', chapter: 'Manly Effort' },
  { id: 618, kural_number: 618, tamil_text: 'பொறியின்மை யார்க்கும் பழியன்று அறிவறிந்து ஆள்வினை இன்மை பழி.', transliteration: 'Poriyinmai Yaarkkum Pazhiyandru Arivarindhu Aalvinai Inmai Pazhi', english_meaning: 'Adverse fate is no disgrace to any one; to be without exertion and without knowing what should be known, is disgrace', career_application: 'Adverse fate is no disgrace to any one; to be without exertion and without knowing what should be known, is disgrace', chapter: 'Manly Effort' },
  { id: 619, kural_number: 619, tamil_text: 'தெய்வத்தான் ஆகா தெனினும் முயற்சிதன் மெய்வருத்தக் கூலி தரும்.', transliteration: 'Theyvaththaan Aakaa Theninum Muyarsidhan Meyvaruththak Kooli Tharum', english_meaning: 'Although it be said that, through fate, it cannot be attained, yet labour, with bodily exertion, will yield its reward', career_application: 'Although it be said that, through fate, it cannot be attained, yet labour, with bodily exertion, will yield its reward', chapter: 'Manly Effort' },
  { id: 620, kural_number: 620, tamil_text: 'ஊழையும் உப்பக்கம் காண்பர் உலைவின்றித் தாழாது உஞற்று பவர்.', transliteration: 'Oozhaiyum Uppakkam Kaanpar Ulaivindrith Thaazhaadhu Ugnatru Pavar', english_meaning: 'They who labour on, without fear and without fainting will see even fate (put) behind their back', career_application: 'They who labour on, without fear and without fainting will see even fate (put) behind their back', chapter: 'Manly Effort' },
  { id: 621, kural_number: 621, tamil_text: 'இடுக்கண் வருங்கால் நகுக அதனை அடுத்தூர்வது அஃதொப்ப தில்.', transliteration: 'Itukkan Varungaal Nakuka Adhanai Atuththoorvadhu Aqdhoppa Thil', english_meaning: 'If troubles come, laugh; there is nothing like that, to press upon and drive away sorrow', career_application: 'If troubles come, laugh; there is nothing like that, to press upon and drive away sorrow', chapter: 'Hopefulness in Trouble' },
  { id: 622, kural_number: 622, tamil_text: 'வெள்ளத் தனைய இடும்பை அறிவுடையான் உள்ளத்தின் உள்ளக் கெடும்.', transliteration: 'Vellath Thanaiya Itumpai Arivutaiyaan Ullaththin Ullak Ketum', english_meaning: 'A flood of troubles will be overcome by the (courageous) thought which the minds of the wise will entertain, even in sorrow', career_application: 'A flood of troubles will be overcome by the (courageous) thought which the minds of the wise will entertain, even in sorrow', chapter: 'Hopefulness in Trouble' },
  { id: 623, kural_number: 623, tamil_text: 'இடும்பைக்கு இடும்பை படுப்பர் இடும்பைக்கு இடும்பை படாஅ தவர்.', transliteration: 'Itumpaikku Itumpai Patuppar Itumpaikku Itumpai Pataaa Thavar', english_meaning: 'They give sorrow to sorrow, who in sorrow do not suffer sorrow', career_application: 'They give sorrow to sorrow, who in sorrow do not suffer sorrow', chapter: 'Hopefulness in Trouble' },
  { id: 624, kural_number: 624, tamil_text: 'மடுத்தவா யெல்லாம் பகடன்னான் உற்ற இடுக்கண் இடர்ப்பாடு உடைத்து.', transliteration: 'Matuththavaa Yellaam Pakatannaan Utra Itukkan Itarppaatu Utaiththu', english_meaning: 'Troubles will vanish (i.e., will be troubled) before the man who (struggles against difficulties) as a', career_application: 'Troubles will vanish (i.e., will be troubled) before the man who (struggles against difficulties) as a', chapter: 'Hopefulness in Trouble' },
  { id: 625, kural_number: 625, tamil_text: 'அடுக்கி வரினும் அழிவிலான் உற்ற இடுக்கண் இடுக்கட் படும்.', transliteration: 'Atukki Varinum Azhivilaan Utra Itukkan Itukkat Patum', english_meaning: 'The troubles of that man will be troubled (and disappear) who, however thickly they may come upon him, does not abandon (his purpose)', career_application: 'The troubles of that man will be troubled (and disappear) who, however thickly they may come upon him, does not abandon (his purpose)', chapter: 'Hopefulness in Trouble' },
  { id: 626, kural_number: 626, tamil_text: 'அற்றேமென்று அல்லற் படுபவோ பெற்றேமென்று ஓம்புதல் தேற்றா தவர்.', transliteration: 'Atremendru Allar Patupavo Petremendru Ompudhal Thetraa Thavar', english_meaning: 'Will those men ever cry out in sorrow, "we are destitute" who, (in their prosperity), give not way to (undue desire) to keep their wealth', career_application: 'Will those men ever cry out in sorrow, "we are destitute" who, (in their prosperity), give not way to (undue desire) to keep their wealth', chapter: 'Hopefulness in Trouble' },
  { id: 627, kural_number: 627, tamil_text: 'இலக்கம் உடம்பிடும்பைக் கென்று கலக்கத்தைக் கையாறாக் கொள்ளாதாம் மேல்.', transliteration: 'Ilakkam Utampitumpaik Kendru Kalakkaththaik Kaiyaaraak Kollaadhaam Mel', english_meaning: 'The great will not regard trouble as trouble, knowing that the body is the butt of trouble', career_application: 'The great will not regard trouble as trouble, knowing that the body is the butt of trouble', chapter: 'Hopefulness in Trouble' },
  { id: 628, kural_number: 628, tamil_text: 'இன்பம் விழையான் இடும்பை இயல்பென்பான் துன்பம் உறுதல் இலன்.', transliteration: 'Inpam Vizhaiyaan Itumpai Iyalpenpaan Thunpam Urudhal Ilan', english_meaning: 'That man never experiences sorrow, who does not seek for pleasure, and who considers distress to be natural (to man)', career_application: 'That man never experiences sorrow, who does not seek for pleasure, and who considers distress to be natural (to man)', chapter: 'Hopefulness in Trouble' },
  { id: 629, kural_number: 629, tamil_text: 'இன்பத்துள் இன்பம் விழையாதான் துன்பத்துள் துன்பம் உறுதல் இலன்.', transliteration: 'Inpaththul Inpam Vizhaiyaadhaan Thunpaththul Thunpam Urudhal Ilan', english_meaning: 'He does not suffer sorrow, in sorrow who does not look for pleasure in pleasure', career_application: 'He does not suffer sorrow, in sorrow who does not look for pleasure in pleasure', chapter: 'Hopefulness in Trouble' },
  { id: 630, kural_number: 630, tamil_text: 'இன்னாமை இன்பம் எனக்கொளின் ஆகுந்தன் ஒன்னார் விழையுஞ் சிறப்பு.', transliteration: 'Innaamai Inpam Enakkolin Aakundhan Onnaar Vizhaiyunj Chirappu', english_meaning: 'The elevation, which even his enemies will esteem, will be gained by him, who regards pain as pleasure', career_application: 'The elevation, which even his enemies will esteem, will be gained by him, who regards pain as pleasure', chapter: 'Hopefulness in Trouble' },
  { id: 631, kural_number: 631, tamil_text: 'கருவியும் காலமும் செய்கையும் செய்யும் அருவினையும் மாண்டது அமைச்சு.', transliteration: 'Karuviyum Kaalamum Seykaiyum Seyyum Aruvinaiyum Maantadhu Amaichchu', english_meaning: 'The minister is one who can make an excellent choice of means, time, manner of execution, and the difficult undertaking (itself)', career_application: 'The minister is one who can make an excellent choice of means, time, manner of execution, and the difficult undertaking (itself)', chapter: 'The Office of Minister of state' },
  { id: 632, kural_number: 632, tamil_text: 'வன்கண் குடிகாத்தல் கற்றறிதல் ஆள்வினையோடு ஐந்துடன் மாண்டது அமைச்சு.', transliteration: 'Vankan Kutikaaththal Katraridhal Aalvinaiyotu Aindhutan Maantadhu Amaichchu', english_meaning: 'The minister is one who in addition to the aforesaid five things excels in the possession of firmness,', career_application: 'The minister is one who in addition to the aforesaid five things excels in the possession of firmness,', chapter: 'The Office of Minister of state' },
  { id: 633, kural_number: 633, tamil_text: 'பிரித்தலும் பேணிக் கொளலும் பிரிந்தார்ப் பொருத்தலும் வல்ல தமைச்சு.', transliteration: 'Piriththalum Penik Kolalum Pirindhaarp Poruththalum Valla Thamaichchu', english_meaning: 'The minister is one who can effect discord (among foes), maintain the good-will of his friends and restore to friendship those who have seceded (from him)', career_application: 'The minister is one who can effect discord (among foes), maintain the good-will of his friends and restore to friendship those who have seceded (from him)', chapter: 'The Office of Minister of state' },
  { id: 634, kural_number: 634, tamil_text: 'தெரிதலும் தேர்ந்து செயலும் ஒருதலையாச் சொல்லலும் வல்லது அமைச்சு.', transliteration: 'Theridhalum Therndhu Seyalum Orudhalaiyaach Chollalum Valladhu Amaichchu', english_meaning: 'The minister is one who is able to comprehend (the whole nature of an undertaking), execute it in the best manner possible, and offer assuring advice (in time of necessity)', career_application: 'The minister is one who is able to comprehend (the whole nature of an undertaking), execute it in the best manner possible, and offer assuring advice (in time of necessity)', chapter: 'The Office of Minister of state' },
  { id: 635, kural_number: 635, tamil_text: 'அறனறிந்து ஆன்றமைந்த சொல்லான்எஞ் ஞான்றுந் திறனறிந்தான் தேர்ச்சித் துணை.', transliteration: 'Aranarindhu Aandramaindha Sollaanenj Gnaandrun Thiranarindhaan Therchchith Thunai', english_meaning: 'He is the best helper (of the king) who understanding the duties, of the latter, is by his special learning, able to tender the fullest advice, and at all times conversant with the best method (of', career_application: 'He is the best helper (of the king) who understanding the duties, of the latter, is by his special learning, able to tender the fullest advice, and at all times conversant with the best method (of', chapter: 'The Office of Minister of state' },
  { id: 636, kural_number: 636, tamil_text: 'மதிநுட்பம் நூலோடு உடையார்க்கு அதிநுட்பம் யாவுள முன்நிற் பவை.', transliteration: 'Madhinutpam Noolotu Utaiyaarkku Adhinutpam Yaavula Munnir Pavai', english_meaning: 'What (contrivances) are there so acute as to resist those who possess natural acuteness in addition to learning ?', career_application: 'What (contrivances) are there so acute as to resist those who possess natural acuteness in addition to learning ?', chapter: 'The Office of Minister of state' },
  { id: 637, kural_number: 637, tamil_text: 'செயற்கை அறிந்தக் கடைத்தும் உலகத்து இயற்கை அறிந்து செயல்.', transliteration: 'Seyarkai Arindhak Kataiththum Ulakaththu Iyarkai Arindhu Seyal', english_meaning: 'Though you are acquainted with the (theoretical) methods (of performing an act), understand the ways of the world and act accordingly', career_application: 'Though you are acquainted with the (theoretical) methods (of performing an act), understand the ways of the world and act accordingly', chapter: 'The Office of Minister of state' },
  { id: 638, kural_number: 638, tamil_text: 'அறிகொன்று அறியான் எனினும் உறுதி உழையிருந்தான் கூறல் கடன்.', transliteration: 'Arikondru Ariyaan Eninum Urudhi Uzhaiyirundhaan Kooral Katan', english_meaning: 'Although the king be utterly ignorant, it is the duty of the minister to give (him) sound advice', career_application: 'Although the king be utterly ignorant, it is the duty of the minister to give (him) sound advice', chapter: 'The Office of Minister of state' },
  { id: 639, kural_number: 639, tamil_text: 'பழுதெண்ணும் மந்திரியின் பக்கததுள் தெவ்வோர் எழுபது கோடி உறும்.', transliteration: 'Pazhudhennum Mandhiriyin Pakkadhadhul Thevvor Ezhupadhu Koti Urum', english_meaning: 'Far better are seventy crores of enemies (for a king) than a minister at his side who intends (his) ruin', career_application: 'Far better are seventy crores of enemies (for a king) than a minister at his side who intends (his) ruin', chapter: 'The Office of Minister of state' },
  { id: 640, kural_number: 640, tamil_text: 'முறைப்படச் சூழ்ந்தும் முடிவிலவே செய்வர் திறப்பாடு இலாஅ தவர்.', transliteration: 'Muraippatach Choozhndhum Mutivilave Seyvar Thirappaatu Ilaaa Thavar', english_meaning: 'Those ministers who are destitute of (executive) ability will fail to carry out their projects, although they may have contrived aright', career_application: 'Those ministers who are destitute of (executive) ability will fail to carry out their projects, although they may have contrived aright', chapter: 'The Office of Minister of state' },
  { id: 641, kural_number: 641, tamil_text: 'நாநலம் என்னும் நலனுடைமை அந்நலம் யாநலத்து உள்ளதூஉம் அன்று.', transliteration: 'Naanalam Ennum Nalanutaimai Annalam Yaanalaththu Ulladhooum Andru', english_meaning: 'The possession of that goodness which is called the goodness of speech is (even to others) better than any other goodness', career_application: 'The possession of that goodness which is called the goodness of speech is (even to others) better than any other goodness', chapter: 'Power of Speech' },
  { id: 642, kural_number: 642, tamil_text: 'ஆக்கமுங் கேடும் அதனால் வருதலால் காத்தோம்பல் சொல்லின்கட் சோர்வு.', transliteration: 'Aakkamung Ketum Adhanaal Varudhalaal Kaaththompal Sollinkat Sorvu', english_meaning: 'Since (both) wealth and evil result from (their) speech, ministers should most carefully guard themselves against faultiness therein', career_application: 'Since (both) wealth and evil result from (their) speech, ministers should most carefully guard themselves against faultiness therein', chapter: 'Power of Speech' },
  { id: 643, kural_number: 643, tamil_text: 'கேட்டார்ப் பிணிக்கும் தகையவாய்க் கேளாரும் வேட்ப மொழிவதாம் சொல்.', transliteration: 'Kettaarp Pinikkum Thakaiyavaaik Kelaarum Vetpa Mozhivadhaam Sol', english_meaning: 'The (minister\'s) speech is that which seeks (to express) elements as bind his friends (to himself) and is so delivered as to make even his enemies desire (his friendship)', career_application: 'The (minister\'s) speech is that which seeks (to express) elements as bind his friends (to himself) and is so delivered as to make even his enemies desire (his friendship)', chapter: 'Power of Speech' },
  { id: 644, kural_number: 644, tamil_text: 'திறனறிந்து சொல்லுக சொல்லை அறனும் பொருளும் அதனினூஉங்கு இல்.', transliteration: 'Thiranarindhu Solluka Sollai Aranum Porulum Adhaninooungu Il', english_meaning: 'Understand the qualities (of your hearers) and (then) make your speech; for superior to it, there is neither virtue nor wealth', career_application: 'Understand the qualities (of your hearers) and (then) make your speech; for superior to it, there is neither virtue nor wealth', chapter: 'Power of Speech' },
  { id: 645, kural_number: 645, tamil_text: 'சொல்லுக சொல்லைப் பிறிதோர்சொல் அச்சொல்லை வெல்லுஞ்சொல் இன்மை அறிந்து.', transliteration: 'Solluka Sollaip Piridhorsol Achchollai Vellunjol Inmai Arindhu', english_meaning: 'Deliver your speech, after assuring yourself that no counter speech can defeat your own', career_application: 'Deliver your speech, after assuring yourself that no counter speech can defeat your own', chapter: 'Power of Speech' },
  { id: 646, kural_number: 646, tamil_text: 'வேட்பத்தாஞ் சொல்லிப் பிறர்சொல் பயன்கோடல் மாட்சியின் மாசற்றார் கோள்.', transliteration: 'Vetpaththaanj Chollip Pirarsol Payankotal Maatchiyin Maasatraar Kol', english_meaning: 'It is the opinion of those who are free from defects in diplomacy that the minister should speak so as to make his hearers desire (to hear more) and grasp the meaning of what he hears himself', career_application: 'It is the opinion of those who are free from defects in diplomacy that the minister should speak so as to make his hearers desire (to hear more) and grasp the meaning of what he hears himself', chapter: 'Power of Speech' },
  { id: 647, kural_number: 647, tamil_text: 'சொலல்வல்லன் சோர்விலன் அஞ்சான் அவனை இகல்வெல்லல் யார்க்கும் அரிது.', transliteration: 'Solalvallan Sorvilan Anjaan Avanai Ikalvellal Yaarkkum Aridhu', english_meaning: 'It is impossible for any one to conquer him by intrique who possesses power of speech, and is neither faulty nor timid', career_application: 'It is impossible for any one to conquer him by intrique who possesses power of speech, and is neither faulty nor timid', chapter: 'Power of Speech' },
  { id: 648, kural_number: 648, tamil_text: 'விரைந்து தொழில்கேட்கும் ஞாலம் நிரந்தினிது சொல்லுதல் வல்லார்ப் பெறின்.', transliteration: 'Viraindhu Thozhilketkum Gnaalam Nirandhinidhu Solludhal Vallaarp Perin', english_meaning: 'If there be those who can speak on various subjects in their proper order and in a pleasing manner, the world would readily accept them', career_application: 'If there be those who can speak on various subjects in their proper order and in a pleasing manner, the world would readily accept them', chapter: 'Power of Speech' },
  { id: 649, kural_number: 649, tamil_text: 'பலசொல்லக் காமுறுவர் மன்றமா சற்ற சிலசொல்லல் தேற்றா தவர்.', transliteration: 'Palasollak Kaamuruvar Mandramaa Satra Silasollal Thetraa Thavar', english_meaning: 'They will desire to utter many words, who do not know how to speak a few faultless ones', career_application: 'They will desire to utter many words, who do not know how to speak a few faultless ones', chapter: 'Power of Speech' },
  { id: 650, kural_number: 650, tamil_text: 'இணருழ்த்தும் நாறா மலரனையர் கற்றது உணர விரித்துரையா தார்.', transliteration: 'Inaruzhththum Naaraa Malaranaiyar Katradhu Unara Viriththuraiyaa Thaar', english_meaning: 'Those who are unable to set forth their acquirements (before others) are like flowers blossoming in a cluster and yet without fragrance', career_application: 'Those who are unable to set forth their acquirements (before others) are like flowers blossoming in a cluster and yet without fragrance', chapter: 'Power of Speech' },
  { id: 651, kural_number: 651, tamil_text: 'துணைநலம் ஆக்கம் த்ருஉம் வினைநலம் வேண்டிய எல்லாந் தரும்.', transliteration: 'Thunainalam Aakkam Tharuum Vinainalam Ventiya Ellaan Tharum', english_meaning: 'The efficacy of support will yield (only) wealth; (but) the efficacy of action will yield all that is desired', career_application: 'The efficacy of support will yield (only) wealth; (but) the efficacy of action will yield all that is desired', chapter: 'Purity in Action' },
  { id: 652, kural_number: 652, tamil_text: 'என்றும் ஒருவுதல் வேண்டும் புகழொடு நன்றி பயவா வினை.', transliteration: 'Endrum Oruvudhal Ventum Pukazhotu Nandri Payavaa Vinai', english_meaning: 'Ministers should at all times avoid acts which, in addition to fame, yield no benefit (for the future)', career_application: 'Ministers should at all times avoid acts which, in addition to fame, yield no benefit (for the future)', chapter: 'Purity in Action' },
  { id: 653, kural_number: 653, tamil_text: 'ஒஓதல் வேண்டும் ஒளிமாழ்கும் செய்வினை ஆஅதும் என்னு மவர்.', transliteration: 'Oodhal Ventum Olimaazhkum Seyvinai Aaadhum Ennu Mavar', english_meaning: 'Those who say, "we will become (better)" should avoid the performance of acts that would destroy (their fame)', career_application: 'Those who say, "we will become (better)" should avoid the performance of acts that would destroy (their fame)', chapter: 'Purity in Action' },
  { id: 654, kural_number: 654, tamil_text: 'இடுக்கண் படினும் இளிவந்த செய்யார் நடுக்கற்ற காட்சி யவர்.', transliteration: 'Itukkan Patinum Ilivandha Seyyaar Natukkatra Kaatchi Yavar', english_meaning: 'Those who have infallible judgement though threatened with peril will not do acts which have brought disgrace (on former ministers)', career_application: 'Those who have infallible judgement though threatened with peril will not do acts which have brought disgrace (on former ministers)', chapter: 'Purity in Action' },
  { id: 655, kural_number: 655, tamil_text: 'எற்றென்று இரங்குவ செய்யற்க செய்வானேல் மற்றன்ன செய்யாமை நன்று.', transliteration: 'Etrendru Iranguva Seyyarka Seyvaanel Matranna Seyyaamai Nandru', english_meaning: 'Let a minister never do acts of which he would have to grieve saying, "what is this I have done"; (but) should he do (them), it were good that he grieved not', career_application: 'Let a minister never do acts of which he would have to grieve saying, "what is this I have done"; (but) should he do (them), it were good that he grieved not', chapter: 'Purity in Action' },
  { id: 656, kural_number: 656, tamil_text: 'ஈன்றாள் பசிகாண்பான் ஆயினுஞ் செய்யற்க சான்றோர் பழிக்கும் வினை.', transliteration: 'Eendraal Pasikaanpaan Aayinunj Cheyyarka Saandror Pazhikkum Vinai', english_meaning: 'Though a minister may see his mother starve; let him do not act which the wise would (treat with contempt)', career_application: 'Though a minister may see his mother starve; let him do not act which the wise would (treat with contempt)', chapter: 'Purity in Action' },
  { id: 657, kural_number: 657, tamil_text: 'பழிமலைந்து எய்திய ஆக்கத்தின் சான்றோர் கழிநல் குரவே தலை.', transliteration: 'Pazhimalaindhu Eydhiya Aakkaththin Saandror Kazhinal Kurave Thalai', english_meaning: 'Far more excellent is the extreme poverty of the wise than wealth obtained by heaping up of sinful', career_application: 'Far more excellent is the extreme poverty of the wise than wealth obtained by heaping up of sinful', chapter: 'Purity in Action' },
  { id: 658, kural_number: 658, tamil_text: 'கடிந்த கடிந்தொரார் செய்தார்க்கு அவைதாம் முடிந்தாலும் பீழை தரும்.', transliteration: 'Katindha Katindhoraar Seydhaarkku Avaidhaam Mutindhaalum Peezhai Tharum', english_meaning: 'The actions of those, who have not desisted from doing deeds forbidden (by the great), will, even if they succeed, cause them sorrow', career_application: 'The actions of those, who have not desisted from doing deeds forbidden (by the great), will, even if they succeed, cause them sorrow', chapter: 'Purity in Action' },
  { id: 659, kural_number: 659, tamil_text: 'அழக்கொண்ட எல்லாம் அழப்போம் இழப்பினும் பிற்பயக்கும் நற்பா லவை.', transliteration: 'Azhak Konta Ellaam Azhappom Izhappinum Pirpayakkum Narpaa Lavai', english_meaning: 'All that has been obtained with tears (to the victim) will depart with tears (to himself); but what has been by fair means; though with loss at first, will afterwards yield fruit', career_application: 'All that has been obtained with tears (to the victim) will depart with tears (to himself); but what has been by fair means; though with loss at first, will afterwards yield fruit', chapter: 'Purity in Action' },
  { id: 660, kural_number: 660, tamil_text: 'சலத்தால் பொருள்செய்தே மார்த்தல் பசுமண் கலத்துள்நீர் பெய்திரீஇ யற்று.', transliteration: 'Salaththaal Porulseydhe Maarththal Pasuman Kalaththulneer Peydhireei Yatru', english_meaning: '(For a minister) to protect (his king) with wealth obtained by foul means is like preserving a vessel of wet clay by filling it with water', career_application: '(For a minister) to protect (his king) with wealth obtained by foul means is like preserving a vessel of wet clay by filling it with water', chapter: 'Purity in Action' },
  { id: 661, kural_number: 661, tamil_text: 'வினைத்திட்பம் என்பது ஒருவன் மனத்திட்பம் மற்றைய எல்லாம் பிற.', transliteration: 'Vinaiththitpam Enpadhu Oruvan Manaththitpam Matraiya Ellaam Pira', english_meaning: 'Firmness in action is (simply) one\'s firmness of mind; all other (abilities) are not of this nature', career_application: 'Firmness in action is (simply) one\'s firmness of mind; all other (abilities) are not of this nature', chapter: 'Power in Action' },
  { id: 662, kural_number: 662, tamil_text: 'ஊறொரால் உற்றபின் ஒல்காமை இவ்விரண்டின் ஆறென்பர் ஆய்ந்தவர் கோள்.', transliteration: 'Oororaal Utrapin Olkaamai Ivvirantin Aarenpar Aaindhavar Kol', english_meaning: 'Not to perform a ruinous act, and not to be discouraged by the ruinous termination of an act, are the two maxims which, the wise say, from the principles of those who have investigated the subject', career_application: 'Not to perform a ruinous act, and not to be discouraged by the ruinous termination of an act, are the two maxims which, the wise say, from the principles of those who have investigated the subject', chapter: 'Power in Action' },
  { id: 663, kural_number: 663, tamil_text: 'கடைக்கொட்கச் செய்தக்க தாண்மை இடைக்கொட்கின் எற்றா விழுமந் தரும்.', transliteration: 'Kataikkotkach Cheydhakka Thaanmai Itaikkotkin Etraa Vizhuman Tharum', english_meaning: 'So to perform an act as to publish it (only) at its termination is (true) manliness; for to announce it beforehand, will cause irremediable sorrow', career_application: 'So to perform an act as to publish it (only) at its termination is (true) manliness; for to announce it beforehand, will cause irremediable sorrow', chapter: 'Power in Action' },
  { id: 664, kural_number: 664, tamil_text: 'சொல்லுதல் யார்க்கும் எளிய அரியவாம் சொல்லிய வண்ணம் செயல்.', transliteration: 'Solludhal Yaarkkum Eliya Ariyavaam Solliya Vannam Seyal', english_meaning: 'To say (how an act is to be performed) is (indeed) easy for any one; but far difficult it is to do according to what has been said', career_application: 'To say (how an act is to be performed) is (indeed) easy for any one; but far difficult it is to do according to what has been said', chapter: 'Power in Action' },
  { id: 665, kural_number: 665, tamil_text: 'வீறெய்தி மாண்டார் வினைத்திட்பம் வேந்தன்கண் ஊறெய்தி உள்ளப் படும்.', transliteration: 'Veereydhi Maantaar Vinaiththitpam Vendhankan Ooreydhi Ullap Patum', english_meaning: 'The firmness in action of those who have become great by the excellence (of their counsel) will, by attaining its fulfilment in the person of the king, be esteemed (by all).', career_application: 'The firmness in action of those who have become great by the excellence (of their counsel) will, by attaining its fulfilment in the person of the king, be esteemed (by all).', chapter: 'Power in Action' },
  { id: 666, kural_number: 666, tamil_text: 'எண்ணிய எண்ணியாங்கு எய்துவர் எண்ணியார் திண்ணியர் ஆகப் பெறின்.', transliteration: 'Enniya Enniyaangu Eydhu Enniyaar Thinniyar Aakap Perin', english_meaning: 'If those who have planned (an undertaking) possess firmness (in executing it) they will obtain what they have desired even as they have desired it', career_application: 'If those who have planned (an undertaking) possess firmness (in executing it) they will obtain what they have desired even as they have desired it', chapter: 'Power in Action' },
  { id: 667, kural_number: 667, tamil_text: 'உருவுகண்டு எள்ளாமை வேண்டும் உருள்பெருந்தேர்க்கு அச்சாணி அன்னார் உடைத்து.', transliteration: 'Uruvukantu Ellaamai Ventum Urulperundherkku Achchaani Annaar Utaiththu', english_meaning: 'Let none be despised for (their) size; (for) the world has those who resemble the linch-pin of the big rolling car', career_application: 'Let none be despised for (their) size; (for) the world has those who resemble the linch-pin of the big rolling car', chapter: 'Power in Action' },
  { id: 668, kural_number: 668, tamil_text: 'கலங்காது கண்ட வினைக்கண் துளங்காது தூக்கங் கடிந்து செயல்.', transliteration: 'Kalangaadhu Kanta Vinaikkan Thulangaadhu Thookkang Katindhu Seyal', english_meaning: 'An act that has been firmly resolved on must be as firmly carried out without delay', career_application: 'An act that has been firmly resolved on must be as firmly carried out without delay', chapter: 'Power in Action' },
  { id: 669, kural_number: 669, tamil_text: 'துன்பம் உறவரினும் செய்க துணிவாற்றி இன்பம் பயக்கும் வினை.', transliteration: 'Thunpam Uravarinum Seyka Thunivaatri Inpam Payakkum Vinai', english_meaning: 'Though it should cause increasing sorrow (at the outset), do with firmness the act that yield bliss (in the end)', career_application: 'Though it should cause increasing sorrow (at the outset), do with firmness the act that yield bliss (in the end)', chapter: 'Power in Action' },
  { id: 670, kural_number: 670, tamil_text: 'எனைத்திட்பம் எய்தியக் கண்ணும் வினைத்திட்பம் வேண்டாரை வேண்டாது உலகு.', transliteration: 'Enaiththitpam Ey Thiyak Kannum Vinaiththitpam Ventaarai Ventaadhu Ulaku', english_meaning: 'The great will not esteem those who esteem not firmness of action, whatever other abilities the latter may possess', career_application: 'The great will not esteem those who esteem not firmness of action, whatever other abilities the latter may possess', chapter: 'Power in Action' },
  { id: 671, kural_number: 671, tamil_text: 'சூழ்ச்சி முடிவு துணிவெய்தல் அத்துணிவு தாழ்ச்சியுள் தங்குதல் தீது.', transliteration: 'Soozhchchi Mutivu Thuniveydhal Aththunivu Thaazhchchiyul Thangudhal Theedhu', english_meaning: 'Consultation ends in forming a resolution (to act); (but) delay in the execution of that resolve is an evil', career_application: 'Consultation ends in forming a resolution (to act); (but) delay in the execution of that resolve is an evil', chapter: 'Modes of Action' },
  { id: 672, kural_number: 672, tamil_text: 'தூங்குக தூங்கிச் செயற்பால தூங்கற்க தூங்காது செய்யும் வினை.', transliteration: 'Thoonguka Thoongich Cheyarpaala Thoongarka Thoongaadhu Seyyum Vinai', english_meaning: 'Sleep over such (actions) as may be slept over; (but) never over such as may not be slept over', career_application: 'Sleep over such (actions) as may be slept over; (but) never over such as may not be slept over', chapter: 'Modes of Action' },
  { id: 673, kural_number: 673, tamil_text: 'ஒல்லும்வா யெல்லாம் வினைநன்றே ஒல்லாக்கால் செல்லும்வாய் நோக்கிச் செயல்.', transliteration: 'Ollumvaa Yellaam Vinainandre Ollaakkaal Sellumvaai Nokkich Cheyal', english_meaning: 'Whenever it is possible (to overcome your enemy) the act (of fighting) is certainly good; if not, endeavour to employ some more successful method', career_application: 'Whenever it is possible (to overcome your enemy) the act (of fighting) is certainly good; if not, endeavour to employ some more successful method', chapter: 'Modes of Action' },
  { id: 674, kural_number: 674, tamil_text: 'வினைபகை என்றிரண்டின் எச்சம் நினையுங்கால் தீயெச்சம் போலத் தெறும்.', transliteration: 'Vinaipakai Endrirantin Echcham Ninaiyungaal Theeyechcham Polath Therum', english_meaning: 'When duly considered, the incomplete execution of an undertaking and hostility will grow and destroy one like the (unextinguished) remnant of a fire', career_application: 'When duly considered, the incomplete execution of an undertaking and hostility will grow and destroy one like the (unextinguished) remnant of a fire', chapter: 'Modes of Action' },
  { id: 675, kural_number: 675, tamil_text: 'பொருள்கருவி காலம் வினையிடனொடு ஐந்தும் இருள்தீர எண்ணிச் செயல்.', transliteration: 'Porulkaruvi Kaalam Vinaiyitanotu Aindhum Iruldheera Ennich Cheyal', english_meaning: 'Do an act after a due consideration of the (following) five, viz money, means, time, execution and place', career_application: 'Do an act after a due consideration of the (following) five, viz money, means, time, execution and place', chapter: 'Modes of Action' },
  { id: 676, kural_number: 676, tamil_text: 'முடிவும் இடையூறும் முற்றியாங்கு எய்தும் படுபயனும் பார்த்துச் செயல்.', transliteration: 'Mutivum Itaiyoorum Mutriyaangu Eydhum Patupayanum Paarththuch Cheyal', english_meaning: 'An act is to be performed after considering the exertion required, the obstacles to be encountered, and the great profit to be gained (on its completion)', career_application: 'An act is to be performed after considering the exertion required, the obstacles to be encountered, and the great profit to be gained (on its completion)', chapter: 'Modes of Action' },
  { id: 677, kural_number: 677, tamil_text: 'செய்வினை செய்வான் செயன்முறை அவ்வினை உள்ளறிவான் உள்ளம் கொளல்.', transliteration: 'Seyvinai Seyvaan Seyanmurai Avvinai Ullarivaan Ullam Kolal', english_meaning: 'The method of performance for one who has begun an act is to ascertain the mind of him who knows the secret thereof', career_application: 'The method of performance for one who has begun an act is to ascertain the mind of him who knows the secret thereof', chapter: 'Modes of Action' },
  { id: 678, kural_number: 678, tamil_text: 'வினையான் வினையாக்கிக் கோடல் நனைகவுள் யானையால் யானையாத் தற்று.', transliteration: 'Vinaiyaan Vinaiyaakkik Kotal Nanaikavul Yaanaiyaal Yaanaiyaath Thatru', english_meaning: 'To make one undertaking the means of accomplishing another (similar to it) is like making one rutting elephant the means of capturing another', career_application: 'To make one undertaking the means of accomplishing another (similar to it) is like making one rutting elephant the means of capturing another', chapter: 'Modes of Action' },
  { id: 679, kural_number: 679, tamil_text: 'நட்டார்க்கு நல்ல செயலின் விரைந்ததே ஒட்டாரை ஒட்டிக் கொளல்.', transliteration: 'Nattaarkku Nalla Seyalin Viraindhadhe Ottaarai Ottik Kolal', english_meaning: 'One should rather hasten to secure the alliance of the foes (of one\'s foes) than perform good offices to one\'s friends', career_application: 'One should rather hasten to secure the alliance of the foes (of one\'s foes) than perform good offices to one\'s friends', chapter: 'Modes of Action' },
  { id: 680, kural_number: 680, tamil_text: 'உறைசிறியார் உள்நடுங்கல் அஞ்சிக் குறைபெறின் கொள்வர் பெரியார்ப் பணிந்து.', transliteration: 'Uraisiriyaar Ulnatungal Anjik Kuraiperin Kolvar Periyaarp Panindhu', english_meaning: 'Ministers of small states, afraid of their people being frightened, will yield to and acknowledge their superior foes, if the latter offer them a chance of reconciliation', career_application: 'Ministers of small states, afraid of their people being frightened, will yield to and acknowledge their superior foes, if the latter offer them a chance of reconciliation', chapter: 'Modes of Action' },
  { id: 681, kural_number: 681, tamil_text: 'அன்புடைமை ஆன்ற குடிப்பிறத்தல் வேந்தவாம் பண்புடைமை தூதுரைப்பான் பண்பு.', transliteration: 'Anputaimai Aandra Kutippiraththal Vendhavaam Panputaimai Thoodhuraippaan Panpu', english_meaning: 'The qualification of an ambassador are affection (for his relations) a fitting birth, and the possession of attributes pleasing to royalty', career_application: 'The qualification of an ambassador are affection (for his relations) a fitting birth, and the possession of attributes pleasing to royalty', chapter: 'The Envoy' },
  { id: 682, kural_number: 682, tamil_text: 'அன்பறிவு ஆராய்ந்த சொல்வன்மை தூதுரைப்பார்க்கு இன்றி யமையாத மூன்று.', transliteration: 'Anparivu Aaraaindha Solvanmai Thoodhuraippaarkku Indri Yamaiyaadha Moondru', english_meaning: 'Love (to his sovereign), knowledge (of his affairs), and a discriminating power of speech (before other sovereigns) are the three sine qua non qualifications of an ambassador', career_application: 'Love (to his sovereign), knowledge (of his affairs), and a discriminating power of speech (before other sovereigns) are the three sine qua non qualifications of an ambassador', chapter: 'The Envoy' },
  { id: 683, kural_number: 683, tamil_text: 'நூலாருள் நூல்வல்லன் ஆகுதல் வேலாருள் வென்றி வினையுரைப்பான் பண்பு.', transliteration: 'Noolaarul Noolvallan Aakudhal Velaarul Vendri Vinaiyuraippaan Panpu', english_meaning: 'To be powerful in politics among those who are learned (in ethics) is the character of him who speaks', career_application: 'To be powerful in politics among those who are learned (in ethics) is the character of him who speaks', chapter: 'The Envoy' },
  { id: 684, kural_number: 684, tamil_text: 'அறிவுரு வாராய்ந்த கல்விஇம் மூன்றன் செறிவுடையான் செல்க வினைக்கு.', transliteration: 'Arivuru Vaaraaindha Kalviim Moondran Serivutaiyaan Selka Vinaikku', english_meaning: 'He may go on a mission (to foreign rulers) who has combined in him all these three viz, (natural) sense, an attractive bearing and well-tried learning', career_application: 'He may go on a mission (to foreign rulers) who has combined in him all these three viz, (natural) sense, an attractive bearing and well-tried learning', chapter: 'The Envoy' },
  { id: 685, kural_number: 685, tamil_text: 'தொகச்சொல்லித் தூவாத நீக்கி நகச்சொல்லி நன்றி பயப்பதாந் தூது.', transliteration: 'Thokach Chollith Thoovaadha Neekki Nakachcholli Nandri Payappadhaan Thoodhu', english_meaning: 'He is an ambassador who (in the presence of foreign rulers) speaks briefly, avoids harshness, talks so as to make them smile, and thus brings good (to his own sovereign)', career_application: 'He is an ambassador who (in the presence of foreign rulers) speaks briefly, avoids harshness, talks so as to make them smile, and thus brings good (to his own sovereign)', chapter: 'The Envoy' },
  { id: 686, kural_number: 686, tamil_text: 'கற்றுக்கண் அஞ்சான் செலச்சொல்லிக் காலத்தால் தக்கது அறிவதாம் தூது.', transliteration: 'Katrukkan Anjaan Selachchollik Kaalaththaal Thakkadhu Arivadhaam Thoodhu', english_meaning: 'He is an ambassador who having studied (politics) talks impressively, is not afraid of angry looks, and knows (to employ) the art suited to the time', career_application: 'He is an ambassador who having studied (politics) talks impressively, is not afraid of angry looks, and knows (to employ) the art suited to the time', chapter: 'The Envoy' },
  { id: 687, kural_number: 687, tamil_text: 'கடனறிந்து காலங் கருதி இடனறிந்து எண்ணி உரைப்பான் தலை.', transliteration: 'Katanarindhu Kaalang Karudhi Itanarindhu Enni Uraippaan Thalai', english_meaning: 'He is chief (among ambassadors) who understands the proper decorum (before foreign princes), seeks the (proper) occasion, knows the (most suitable) place, and delivers his message after (due)', career_application: 'He is chief (among ambassadors) who understands the proper decorum (before foreign princes), seeks the (proper) occasion, knows the (most suitable) place, and delivers his message after (due)', chapter: 'The Envoy' },
  { id: 688, kural_number: 688, tamil_text: 'தூய்மை துணைமை துணிவுடைமை இம்மூன்றின் வாய்மை வழியுரைப்பான் பண்பு.', transliteration: 'Thooimai Thunaimai Thunivutaimai Immoondrin Vaaimai Vazhiyuraippaan Panpu', english_meaning: 'The qualifications of him who faithfully delivers his (sovereign\'s) message are purity, the support (of foreign ministers), and boldness, with truthfulness in addition to the (aforesaid) three', career_application: 'The qualifications of him who faithfully delivers his (sovereign\'s) message are purity, the support (of foreign ministers), and boldness, with truthfulness in addition to the (aforesaid) three', chapter: 'The Envoy' },
  { id: 689, kural_number: 689, tamil_text: 'விடுமாற்றம் வேந்தர்க்கு உரைப்பான் வடுமாற்றம் வாய்சேரா வன்கணவன்.', transliteration: 'Vitumaatram Vendharkku Uraippaan Vatumaatram Vaaiseraa Vanka Navan', english_meaning: 'He alone is fit to communicate (his sovereign\'s) reply, who possesses the firmness not to utter even inadvertently what may reflect discredit (on the latter)', career_application: 'He alone is fit to communicate (his sovereign\'s) reply, who possesses the firmness not to utter even inadvertently what may reflect discredit (on the latter)', chapter: 'The Envoy' },
  { id: 690, kural_number: 690, tamil_text: 'இறுதி பயப்பினும் எஞ்சாது இறைவற்கு உறுதி பயப்பதாம் தூது.', transliteration: 'Irudhi Payappinum Enjaadhu Iraivarku Urudhi Payappadhaam Thoodhu', english_meaning: 'He is the ambassador who fearlessly seeks his sovereign\'s good though it should cost him his life (to deliver his message)', career_application: 'He is the ambassador who fearlessly seeks his sovereign\'s good though it should cost him his life (to deliver his message)', chapter: 'The Envoy' },
  { id: 691, kural_number: 691, tamil_text: 'அகலாது அணுகாது தீக்காய்வார் போல்க இகல்வேந்தர்ச் சேர்ந்தொழுகு வார்.', transliteration: 'Akalaadhu Anukaadhu Theekkaaivaar Polka Ikalvendharch Cherndhozhuku Vaar', english_meaning: 'Thus let them act who dwell beneath of warlike kings the palace-roof', career_application: 'Thus let them act who dwell beneath of warlike kings the palace-roof', chapter: 'Conduct in the Presence of the King' },
  { id: 692, kural_number: 692, tamil_text: 'மன்னர் விழைப விழையாமை மன்னரால் மன்னிய ஆக்கந் தரும்.', transliteration: 'Mannar Vizhaipa Vizhaiyaamai Mannaraal Manniya Aakkan Tharum', english_meaning: 'For ministers not to cover the things desired by their kings will through the kings themselves yield them everlasting wealth', career_application: 'For ministers not to cover the things desired by their kings will through the kings themselves yield them everlasting wealth', chapter: 'Conduct in the Presence of the King' },
  { id: 693, kural_number: 693, tamil_text: 'போற்றின் அரியவை போற்றல் கடுத்தபின் தேற்றுதல் யார்க்கும் அரிது.', transliteration: 'Potrin Ariyavai Potral Katuththapin Thetrudhal Yaarkkum Aridhu', english_meaning: 'Ministers who would save themselves should avoid (the commission of) serious errors for if the king\'s suspicion is once roused, no one can remove it', career_application: 'Ministers who would save themselves should avoid (the commission of) serious errors for if the king\'s suspicion is once roused, no one can remove it', chapter: 'Conduct in the Presence of the King' },
  { id: 694, kural_number: 694, tamil_text: 'செவிச்சொல்லும் சேர்ந்த நகையும் அவித்தொழுகல் ஆன்ற பெரியா ரகத்து.', transliteration: 'Sevichchollum Serndha Nakaiyum Aviththozhukal Aandra Periyaa Rakaththu', english_meaning: 'While in the presence of the sovereign, ministers should neither whisper to nor smile at others', career_application: 'While in the presence of the sovereign, ministers should neither whisper to nor smile at others', chapter: 'Conduct in the Presence of the King' },
  { id: 695, kural_number: 695, tamil_text: 'எப்பொருளும் ஓரார் தொடரார்மற் றப்பொருளை விட்டக்கால் கேட்க மறை.', transliteration: 'Epporulum Oraar Thotaraarmar Rapporulai Vittakkaal Ketka Marai', english_meaning: '(When the king is engaged) in secret counsel (with others), ministers should neither over-hear anything whatever nor pry into it with inquisitive questions, but (wait to) listen when it is divulged (by', career_application: '(When the king is engaged) in secret counsel (with others), ministers should neither over-hear anything whatever nor pry into it with inquisitive questions, but (wait to) listen when it is divulged (by', chapter: 'Conduct in the Presence of the King' },
  { id: 696, kural_number: 696, tamil_text: 'குறிப்பறிந்து காலங் கருதி வெறுப்பில வேண்டுப வேட்பச் சொலல்.', transliteration: 'Kuripparindhu Kaalang Karudhi Veruppila Ventupa Vetpach Cholal', english_meaning: 'Knowing the (king\'s disposition and seeking the right time, (the minister) should in a pleasing manner suggest things such as are desirable and not disagreeable', career_application: 'Knowing the (king\'s disposition and seeking the right time, (the minister) should in a pleasing manner suggest things such as are desirable and not disagreeable', chapter: 'Conduct in the Presence of the King' },
  { id: 697, kural_number: 697, tamil_text: 'வேட்பன சொல்லி வினையில எஞ்ஞான்றும் கேட்பினும் சொல்லா விடல்.', transliteration: 'Vetpana Solli Vinaiyila Egngnaandrum Ketpinum Sollaa Vital', english_meaning: 'Ministers should (always) give agreeable advice but on no occasion recommend useless actions, though requested (to do so)', career_application: 'Ministers should (always) give agreeable advice but on no occasion recommend useless actions, though requested (to do so)', chapter: 'Conduct in the Presence of the King' },
  { id: 698, kural_number: 698, tamil_text: 'இளையர் இனமுறையர் என்றிகழார் நின்ற ஒளியோடு ஒழுகப் படும்.', transliteration: 'Ilaiyar Inamuraiyar Endrikazhaar Nindra Oliyotu Ozhukap Patum', english_meaning: 'Ministers should behave in accordance with the (Divine) light in the person of kings and not despise them saying, "He is our junior (in age) and connected with our family!"', career_application: 'Ministers should behave in accordance with the (Divine) light in the person of kings and not despise them saying, "He is our junior (in age) and connected with our family!"', chapter: 'Conduct in the Presence of the King' },
  { id: 699, kural_number: 699, tamil_text: 'கொளப்பட்டேம் என்றெண்ணிக் கொள்ளாத செய்யார் துளக்கற்ற காட்சி யவர்.', transliteration: 'Kolappattem Endrennik Kollaadha Seyyaar Thulakkatra Kaatchi Yavar', english_meaning: 'Those whose judgement is firm will not do what is disagreeable (to the sovereign) saying (within', career_application: 'Those whose judgement is firm will not do what is disagreeable (to the sovereign) saying (within', chapter: 'Conduct in the Presence of the King' },
  { id: 700, kural_number: 700, tamil_text: 'பழையம் எனக்கருதிப் பண்பல்ல செய்யும் கெழுதகைமை கேடு தரும்.', transliteration: 'Pazhaiyam Enakkarudhip Panpalla Seyyum Kezhudhakaimai Ketu Tharum', english_meaning: 'The (foolish) claim with which a minister does unbecoming acts because of his (long) familiarity (with the king) will ensure his ruin', career_application: 'The (foolish) claim with which a minister does unbecoming acts because of his (long) familiarity (with the king) will ensure his ruin', chapter: 'Conduct in the Presence of the King' },
  { id: 701, kural_number: 701, tamil_text: 'கூறாமை நோக்கக் குறிப்பறிவான் எஞ்ஞான்றும் மாறாநீர் வையக் கணி.', transliteration: 'Kooraamai Nokkake Kuripparivaan Egngnaandrum Maaraaneer Vaiyak Kani', english_meaning: 'The minister who by looking (at the king) understands his mind without being told (of it), will be a perpetual ornament to the world which is surrounded by a never-drying sea', career_application: 'The minister who by looking (at the king) understands his mind without being told (of it), will be a perpetual ornament to the world which is surrounded by a never-drying sea', chapter: 'The Knowledge of Indications' },
  { id: 702, kural_number: 702, tamil_text: 'ஐயப் படாஅது அகத்தது உணர்வானைத் தெய்வத்தோ டொப்பக் கொளல்.', transliteration: 'Aiyap Pataaadhu Akaththadhu Unarvaanaith Theyvaththo Toppak Kolal', english_meaning: 'He is to be esteemed a god who is able to ascertain without a doubt what is within (one\'s mind)', career_application: 'He is to be esteemed a god who is able to ascertain without a doubt what is within (one\'s mind)', chapter: 'The Knowledge of Indications' },
  { id: 703, kural_number: 703, tamil_text: 'குறிப்பிற் குறிப்புணர் வாரை உறுப்பினுள் யாது கொடுத்தும் கொளல்.', transliteration: 'Kurippir Kurippunar Vaarai Uruppinul Yaadhu Kotuththum Kolal', english_meaning: 'The king should ever give whatever (is asked) of his belongings and secure him who, by the indications (of his own mind) is able to read those of another', career_application: 'The king should ever give whatever (is asked) of his belongings and secure him who, by the indications (of his own mind) is able to read those of another', chapter: 'The Knowledge of Indications' },
  { id: 704, kural_number: 704, tamil_text: 'குறித்தது கூறாமைக் கொள்வாரோ டேனை உறுப்போ ரனையரால் வேறு.', transliteration: 'Kuriththadhu Kooraamaik Kolvaaro Tenai Uruppo Ranaiyaraal Veru', english_meaning: 'Those who understand one\'s thoughts without being informed (thereof) and those who do not, may (indeed) resemble one another bodily; still are they different (mentally)', career_application: 'Those who understand one\'s thoughts without being informed (thereof) and those who do not, may (indeed) resemble one another bodily; still are they different (mentally)', chapter: 'The Knowledge of Indications' },
  { id: 705, kural_number: 705, tamil_text: 'குறிப்பிற் குறிப்புணரா வாயின் உறுப்பினுள் என்ன பயத்தவோ கண்?', transliteration: 'Kurippir Kurippunaraa Vaayin Uruppinul Enna Payaththavo Kan?', english_meaning: 'Of what use are the eyes amongst one\'s members, if they cannot by their own indications dive those of another ?', career_application: 'Of what use are the eyes amongst one\'s members, if they cannot by their own indications dive those of another ?', chapter: 'The Knowledge of Indications' },
  { id: 706, kural_number: 706, tamil_text: 'அடுத்தது காட்டும் பளிங்குபோல் நெஞ்சம் கடுத்தது காட்டும் முகம்.', transliteration: 'Atuththadhu Kaattum Palingupol Nenjam Katuththadhu Kaattum Mukam', english_meaning: 'As the mirror reflects what is near so does the face show what is uppermost in the mind', career_application: 'As the mirror reflects what is near so does the face show what is uppermost in the mind', chapter: 'The Knowledge of Indications' },
  { id: 707, kural_number: 707, tamil_text: 'முகத்தின் முதுக்குறைந்தது உண்டோ உவப்பினும் காயினும் தான்முந் துறும்.', transliteration: 'Mukaththin Mudhukkuraindhadhu Unto Uvappinum Kaayinum Thaanmun Thurum', english_meaning: 'Is there anything so full of knowledge as the face ? (No) it precedes the mind, whether (the latter is) pleased or vexed', career_application: 'Is there anything so full of knowledge as the face ? (No) it precedes the mind, whether (the latter is) pleased or vexed', chapter: 'The Knowledge of Indications' },
  { id: 708, kural_number: 708, tamil_text: 'முகம்நோக்கி நிற்க அமையும் அகம்நோக்கி உற்ற துணர்வார்ப் பெறின்.', transliteration: 'Mukamnokki Nirka Amaiyum Akamnokki Utra Thunarvaarp Perin', english_meaning: 'If the king gets those who by looking into his mind can understand (and remove) what has occurred (to him) it is enough that he stand looking at their face', career_application: 'If the king gets those who by looking into his mind can understand (and remove) what has occurred (to him) it is enough that he stand looking at their face', chapter: 'The Knowledge of Indications' },
  { id: 709, kural_number: 709, tamil_text: 'பகைமையும் கேண்மையும் கண்ணுரைக்கும் கண்ணின் வகைமை உணர்வார்ப் பெறின்.', transliteration: 'Pakaimaiyum Kenmaiyum Kannuraikkum Kannin Vakaimai Unarvaarp Perin', english_meaning: 'If a king gets ministers who can read the movements of the eye, the eyes (of foreign kings) will (themselves) reveal (to him) their hatred or friendship', career_application: 'If a king gets ministers who can read the movements of the eye, the eyes (of foreign kings) will (themselves) reveal (to him) their hatred or friendship', chapter: 'The Knowledge of Indications' },
  { id: 710, kural_number: 710, tamil_text: 'நுண்ணியம் என்பார் அளக்குங்கோல் காணுங்கால் கண்ணல்லது இல்லை பிற.', transliteration: 'Nunniyam Enpaar Alakkungol Kaanungaal Kannalladhu Illai Pira', english_meaning: 'The measuring-rod of those (ministers) who say "we are acute" will on inquiry be found to be their (own) eyes and nothing else', career_application: 'The measuring-rod of those (ministers) who say "we are acute" will on inquiry be found to be their (own) eyes and nothing else', chapter: 'The Knowledge of Indications' },
  { id: 711, kural_number: 711, tamil_text: 'அவையறிநது ஆராய்ந்து சொல்லுக சொல்லின் தொகையறிந்த தூய்மை யவர்.', transliteration: 'Avaiyarinadhu Aaraaindhu Solluka Sollin Thokaiyarindha Thooimai Yavar', english_meaning: 'Let the pure who know the arrangement of words speak with deliberation after ascertaining (the nature of) the court (then assembled)', career_application: 'Let the pure who know the arrangement of words speak with deliberation after ascertaining (the nature of) the court (then assembled)', chapter: 'The Knowledge of the Council Chamber' },
  { id: 712, kural_number: 712, tamil_text: 'இடைதெரிந்து நன்குணர்ந்து சொல்லுக சொல்லின் நடைதெரிந்த நன்மை யவர்.', transliteration: 'Itaidherindhu Nankunarndhu Solluka Sollin Nataidherindha Nanmai Yavar', english_meaning: 'Let the good who know the uses of words speak with a clear knowledge after ascertaining the time (suited to the court)', career_application: 'Let the good who know the uses of words speak with a clear knowledge after ascertaining the time (suited to the court)', chapter: 'The Knowledge of the Council Chamber' },
  { id: 713, kural_number: 713, tamil_text: 'அவையறியார் சொல்லல்மேற் கொள்பவர் சொல்லின் வகையறியார் வல்லதூஉம் இல்.', transliteration: 'Avaiyariyaar Sollalmer Kolpavar Sollin Vakaiyariyaar Valladhooum Il', english_meaning: 'Those who undertake to speak without knowing the (nature of the) court are ignorant of the quality of words as well as devoid of the power (of learning)', career_application: 'Those who undertake to speak without knowing the (nature of the) court are ignorant of the quality of words as well as devoid of the power (of learning)', chapter: 'The Knowledge of the Council Chamber' },
  { id: 714, kural_number: 714, tamil_text: 'ஒளியார்முன் ஒள்ளிய ராதல் வெளியார்முன் வான்சுதை வண்ணம் கொளல்.', transliteration: 'Oliyaarmun Olliya Raadhal Veliyaarmun Vaansudhai Vannam Kolal', english_meaning: 'Ministers should be lights in the assembly of the enlightned, but assume the pure whiteness of mortar (ignorance) in that of fools', career_application: 'Ministers should be lights in the assembly of the enlightned, but assume the pure whiteness of mortar (ignorance) in that of fools', chapter: 'The Knowledge of the Council Chamber' },
  { id: 715, kural_number: 715, tamil_text: 'நன்றென்ற வற்றுள்ளும் நன்றே முதுவருள் முந்து கிளவாச் செறிவு.', transliteration: 'Nandrendra Vatrullum Nandre Mudhuvarul Mundhu Kilavaach Cherivu', english_meaning: 'The modesty by which one does not rush forward and speak in (an assembly of) superiors is the best among all (one\'s) good qualities', career_application: 'The modesty by which one does not rush forward and speak in (an assembly of) superiors is the best among all (one\'s) good qualities', chapter: 'The Knowledge of the Council Chamber' },
  { id: 716, kural_number: 716, tamil_text: 'ஆற்றின் நிலைதளர்ந் தற்றே வியன்புலம் ஏற்றுணர்வார் முன்னர் இழுக்கு.', transliteration: 'Aatrin Nilaidhalarn Thatre Viyanpulam Etrunarvaar Munnar Izhukku', english_meaning: '(For a minister) to blunder in the presence of those who have acquired a vast store of learning and know (the value thereof) is like a good man stumbling (and falling away) from the path (of virtue)', career_application: '(For a minister) to blunder in the presence of those who have acquired a vast store of learning and know (the value thereof) is like a good man stumbling (and falling away) from the path (of virtue)', chapter: 'The Knowledge of the Council Chamber' },
  { id: 717, kural_number: 717, tamil_text: 'கற்றறிந்தார் கல்வி விளங்கும் கசடறச் சொல்தெரிதல் வல்லார் அகத்து.', transliteration: 'Katrarindhaar Kalvi Vilangum Kasatarach Choldheridhal Vallaar Akaththu', english_meaning: 'The learning of those who have read and understood (much) will shine in the assembly of those who faultlessly examine (the nature of) words', career_application: 'The learning of those who have read and understood (much) will shine in the assembly of those who faultlessly examine (the nature of) words', chapter: 'The Knowledge of the Council Chamber' },
  { id: 718, kural_number: 718, tamil_text: 'உணர்வ துடையார்முன் சொல்லல் வளர்வதன் பாத்தியுள் நீர்சொரிந் தற்று.', transliteration: 'Unarva Thutaiyaarmun Sollal Valarvadhan Paaththiyul Neersorin Thatru', english_meaning: 'Lecturing to those who have the ability to understand (for themselves) is like watering a bed of plants that are growing (of themselves)', career_application: 'Lecturing to those who have the ability to understand (for themselves) is like watering a bed of plants that are growing (of themselves)', chapter: 'The Knowledge of the Council Chamber' },
  { id: 719, kural_number: 719, tamil_text: 'புல்லவையுள் பொச்சாந்தும் சொல்லற்க நல்லவையுள் நன்குசலச் சொல்லு வார்.', transliteration: 'Pullavaiyul Pochchaandhum Sollarka Nallavaiyul Nankusalach Chollu Vaar', english_meaning: 'Those who are able to speak good things impressively in an assembly of the good should not even forgetfully speak them in that of the low', career_application: 'Those who are able to speak good things impressively in an assembly of the good should not even forgetfully speak them in that of the low', chapter: 'The Knowledge of the Council Chamber' },
  { id: 720, kural_number: 720, tamil_text: 'அங்கணத்துள் உக்க அமிழ்தற்றால் தங்கணத்தார் அல்லார்முன் கோட்டி கொளல்.', transliteration: 'Anganaththul Ukka Amizhdhatraal Thanganaththaar Allaarmun Kotti Kolal', english_meaning: 'To utter (a good word) in the assembly of those who are of inferior rank is like dropping nectar on the ground', career_application: 'To utter (a good word) in the assembly of those who are of inferior rank is like dropping nectar on the ground', chapter: 'The Knowledge of the Council Chamber' },
  { id: 721, kural_number: 721, tamil_text: 'வகையறிந்து வல்லவை வாய்சோரார் சொல்லின் தொகையறிந்த தூய்மை யவர்.', transliteration: 'Vakaiyarindhu Vallavai Vaaisoraar Sollin Thokaiyarindha Thooimai Yavar', english_meaning: 'The pure who know the classification of words having first ascertained the nature (of the court) will not (through fear) falter in their speech before the powerful body', career_application: 'The pure who know the classification of words having first ascertained the nature (of the court) will not (through fear) falter in their speech before the powerful body', chapter: 'Not to dread the Council' },
  { id: 722, kural_number: 722, tamil_text: 'கற்றாருள் கற்றார் எனப்படுவர் கற்றார்முன் கற்ற செலச்சொல்லு வார்.', transliteration: 'Katraarul Katraar Enappatuvar Katraarmun Katra Selachchollu Vaar', english_meaning: 'Those who can agreeably set forth their acquirements before the learned will be regarded as the most learned among the learned', career_application: 'Those who can agreeably set forth their acquirements before the learned will be regarded as the most learned among the learned', chapter: 'Not to dread the Council' },
  { id: 723, kural_number: 723, tamil_text: 'பகையகத்துச் சாவார் எளியர் அரியர் அவையகத்து அஞ்சா தவர்.', transliteration: 'Pakaiyakaththuch Chaavaar Eliyar Ariyar Avaiyakaththu Anjaa Thavar', english_meaning: 'Many indeed may (fearlessly) die in the presence of (their) foes; (but) few are those who are fearless in the assembly (of the learned)', career_application: 'Many indeed may (fearlessly) die in the presence of (their) foes; (but) few are those who are fearless in the assembly (of the learned)', chapter: 'Not to dread the Council' },
  { id: 724, kural_number: 724, tamil_text: 'கற்றார்முன் கற்ற செலச்சொல்லித் தாம்கற்ற மிக்காருள் மிக்க கொளல்.', transliteration: 'Katraarmun Katra Selachchollith Thaamkatra Mikkaarul Mikka Kolal', english_meaning: '(Ministers) should agreeably set forth their acquirements before the learned and acquire more (knowledge) from their superiors (in learning)', career_application: '(Ministers) should agreeably set forth their acquirements before the learned and acquire more (knowledge) from their superiors (in learning)', chapter: 'Not to dread the Council' },
  { id: 725, kural_number: 725, tamil_text: 'ஆற்றின் அளவறிந்து கற்க அவையஞ்சா மாற்றங் கொடுத்தற் பொருட்டு.', transliteration: 'Aatrin Alavarindhu Karka Avaiyanjaa Maatrang Kotuththar Poruttu', english_meaning: 'In order to reply fearlessly before a foreign court, (ministers) should learn logic according to the rules (of grammar)', career_application: 'In order to reply fearlessly before a foreign court, (ministers) should learn logic according to the rules (of grammar)', chapter: 'Not to dread the Council' },
  { id: 726, kural_number: 726, tamil_text: 'வாளொடென் வன்கண்ணர் அல்லார்க்கு நூலொடென் நுண்ணவை அஞ்சு பவர்க்கு.', transliteration: 'Vaaloten Vankannar Allaarkku Nooloten Nunnavai Anju Pavarkku', english_meaning: 'What have they to do with a sword who are not valiant, or they with learning who are afraid of an intelligent assembly ?', career_application: 'What have they to do with a sword who are not valiant, or they with learning who are afraid of an intelligent assembly ?', chapter: 'Not to dread the Council' },
  { id: 727, kural_number: 727, tamil_text: 'பகையகத்துப் பேடிகை ஒள்வாள் அவையகத்து அஞ்சு மவன்கற்ற நூல்.', transliteration: 'Pakaiyakaththup Petikai Olvaal Avaiyakaththu Anju Mavankatra Nool', english_meaning: 'The learning of him who is diffident before an assembly is like the shining sword of an hermaphrodite in the presence of his foes', career_application: 'The learning of him who is diffident before an assembly is like the shining sword of an hermaphrodite in the presence of his foes', chapter: 'Not to dread the Council' },
  { id: 728, kural_number: 728, tamil_text: 'பல்லவை கற்றும் பயமிலரே நல்லவையுள் நன்கு செலச்சொல்லா தார்.', transliteration: 'Pallavai Katrum Payamilare Nallavaiyul Nanku Selachchollaa Thaar', english_meaning: 'Those who cannot agreeably speak good things before a good assembly are indeed unprofitable persons inspite of all their various acquirements', career_application: 'Those who cannot agreeably speak good things before a good assembly are indeed unprofitable persons inspite of all their various acquirements', chapter: 'Not to dread the Council' },
  { id: 729, kural_number: 729, tamil_text: 'கல்லா தவரின் கடையென்ப கற்றறிந்தும் நல்லா ரவையஞ்சு வார்.', transliteration: 'Kallaa Thavarin Kataiyenpa Katrarindhum Nallaa Ravaiyanju Vaar', english_meaning: 'They who, though they have learned and understood, are yet afraid of the assembly of the good, are said to be inferior (even) to the illiterate', career_application: 'They who, though they have learned and understood, are yet afraid of the assembly of the good, are said to be inferior (even) to the illiterate', chapter: 'Not to dread the Council' },
  { id: 730, kural_number: 730, tamil_text: 'உளரெனினும் இல்லாரொடு ஒப்பர் களன்அஞ்சிக் கற்ற செலச்சொல்லா தார்.', transliteration: 'Ulareninum Illaarotu Oppar Kalananjik Katra Selachchollaa Thaar', english_meaning: 'Those who through fear of the assembly are unable to set forth their learning in an interesting manner, though alive, are yet like the dead', career_application: 'Those who through fear of the assembly are unable to set forth their learning in an interesting manner, though alive, are yet like the dead', chapter: 'Not to dread the Council' },
  { id: 731, kural_number: 731, tamil_text: 'தள்ளா விளையுளும் தக்காரும் தாழ்விலாச் செல்வரும் சேர்வது நாடு.', transliteration: 'Thallaa Vilaiyulum Thakkaarum Thaazhvilaach Chelvarum Servadhu Naatu', english_meaning: 'A kingdom is that in which (those who carry on) a complete cultivation, virtuous persons, and', career_application: 'A kingdom is that in which (those who carry on) a complete cultivation, virtuous persons, and', chapter: 'The Land' },
  { id: 732, kural_number: 732, tamil_text: 'பெரும்பொருளால் பெட்டக்க தாகி அருங்கேட்டால் ஆற்ற விளைவது நாடு.', transliteration: 'Perumporulaal Pettakka Thaaki Arungettaal Aatra Vilaivadhu Naatu', english_meaning: 'A kingdom is that which is desire for its immense wealth, and which grows greatly in prosperity, being free from destructive causes', career_application: 'A kingdom is that which is desire for its immense wealth, and which grows greatly in prosperity, being free from destructive causes', chapter: 'The Land' },
  { id: 733, kural_number: 733, tamil_text: 'பொறையொருங்கு மேல்வருங்கால் தாங்கி இறைவற்கு இறையொருங்கு நேர்வது நாடு.', transliteration: 'Poraiyorungu Melvarungaal Thaangi Iraivarku Iraiyorungu Nervadhu Naatu', english_meaning: 'A kingdom is that which can bear any burden that may be pressed on it (from adjoining kingdoms) and (yet) pay the full tribute to its sovereign', career_application: 'A kingdom is that which can bear any burden that may be pressed on it (from adjoining kingdoms) and (yet) pay the full tribute to its sovereign', chapter: 'The Land' },
  { id: 734, kural_number: 734, tamil_text: 'உறுபசியும் ஓவாப் பிணியும் செறுபகையும் சேரா தியல்வது நாடு.', transliteration: 'Urupasiyum Ovaap Piniyum Serupakaiyum Seraa Thiyalvadhu Naatu', english_meaning: 'A kingdom is that which continues to be free from excessive starvation, irremediable epidemics, and destructive foes', career_application: 'A kingdom is that which continues to be free from excessive starvation, irremediable epidemics, and destructive foes', chapter: 'The Land' },
  { id: 735, kural_number: 735, tamil_text: 'பல்குழுவும் பாழ்செய்யும் உட்பகையும் வேந்தலைக்கும் கொல்குறும்பும் இல்லது நாடு.', transliteration: 'Palkuzhuvum Paazhseyyum Utpakaiyum Vendhalaikkum Kolkurumpum Illadhu Naatu', english_meaning: 'A kingdom is that which is without various (irregular) associations, destructive internal enemies, and murderous savages who (sometimes) harass the sovereign', career_application: 'A kingdom is that which is without various (irregular) associations, destructive internal enemies, and murderous savages who (sometimes) harass the sovereign', chapter: 'The Land' },
  { id: 736, kural_number: 736, tamil_text: 'கேடறியாக் கெட்ட இடத்தும் வளங்குன்றா நாடென்ப நாட்டின் தலை.', transliteration: 'Ketariyaak Ketta Itaththum Valangundraa Naatenpa Naattin Thalai', english_meaning: 'The learned say that the best kingdom is that which knows no evil (from its foes), and, if injured (at all), suffers no diminution in its fruitfulness', career_application: 'The learned say that the best kingdom is that which knows no evil (from its foes), and, if injured (at all), suffers no diminution in its fruitfulness', chapter: 'The Land' },
  { id: 737, kural_number: 737, tamil_text: 'இருபுனலும் வாய்ந்த மலையும் வருபுனலும் வல்லரணும் நாட்டிற்கு உறுப்பு.', transliteration: 'Irupunalum Vaaindha Malaiyum Varupunalum Vallaranum Naattirku Uruppu', english_meaning: 'The constituents of a kingdom are the two waters (from above and below), well situated hills and an undestructible fort', career_application: 'The constituents of a kingdom are the two waters (from above and below), well situated hills and an undestructible fort', chapter: 'The Land' },
  { id: 738, kural_number: 738, tamil_text: 'பிணியின்மை செல்வம் விளைவின்பம் ஏமம் அணியென்ப நாட்டிவ் வைந்து.', transliteration: 'Piniyinmai Selvam Vilaivinpam Emam Aniyenpa Naattiv Vaindhu', english_meaning: 'Freedom from epidemics, wealth, produce, happiness and protection (to subjects); these five, the learned, say, are the ornaments of a kingdom', career_application: 'Freedom from epidemics, wealth, produce, happiness and protection (to subjects); these five, the learned, say, are the ornaments of a kingdom', chapter: 'The Land' },
  { id: 739, kural_number: 739, tamil_text: 'நாடென்ப நாடா வளத்தன நாடல்ல நாட வளந்தரு நாடு.', transliteration: 'Naatenpa Naataa Valaththana Naatalla Naata Valandharu Naatu', english_meaning: 'The learned say that those are kingdom whose wealth is not laboured for, and those not, whose wealth is only obtained through labour', career_application: 'The learned say that those are kingdom whose wealth is not laboured for, and those not, whose wealth is only obtained through labour', chapter: 'The Land' },
  { id: 740, kural_number: 740, tamil_text: 'ஆங்கமை வெய்தியக் கண்ணும் பயமின்றே வேந்தமை வில்லாத நாடு.', transliteration: 'Aangamai Veydhiyak Kannum Payamindre Vendhamai Villaadha Naatu', english_meaning: 'Although in possession of all the above mentioned excellences, these are indeed of no use to a country, in the absence of harmony between the sovereign and the sujects', career_application: 'Although in possession of all the above mentioned excellences, these are indeed of no use to a country, in the absence of harmony between the sovereign and the sujects', chapter: 'The Land' },
  { id: 741, kural_number: 741, tamil_text: 'ஆற்று பவர்க்கும் அரண்பொருள் அஞ்சித்தற் போற்று பவர்க்கும் பொருள்.', transliteration: 'Aatru Pavarkkum Aranporul Anjiththar Potru Pavarkkum Porul', english_meaning: 'A fort is an object of importance to those who march (against their foes) as well as to those who through fear (of pursuers) would seek it for shelter', career_application: 'A fort is an object of importance to those who march (against their foes) as well as to those who through fear (of pursuers) would seek it for shelter', chapter: 'The Fortification' },
  { id: 742, kural_number: 742, tamil_text: 'மணிநீரும் மண்ணும் மலையும் அணிநிழற் காடும் உடைய தரண்.', transliteration: 'Manineerum Mannum Malaiyum Aninizhar Kaatum Utaiya Tharan', english_meaning: 'A fort is that which has everlasting water, plains, mountains and cool shady forests', career_application: 'A fort is that which has everlasting water, plains, mountains and cool shady forests', chapter: 'The Fortification' },
  { id: 743, kural_number: 743, tamil_text: 'உயர்வகலம் திண்மை அருமைஇந் நான்கின் அமைவரண் என்றுரைக்கும் நூல்.', transliteration: 'Uyarvakalam Thinmai Arumaiin Naankin Amaivaran Endruraikkum Nool', english_meaning: 'The learned say that a fortress is an enclosure having these four (qualities) viz, height, breadth, strength and inaccessibility', career_application: 'The learned say that a fortress is an enclosure having these four (qualities) viz, height, breadth, strength and inaccessibility', chapter: 'The Fortification' },
  { id: 744, kural_number: 744, tamil_text: 'சிறுகாப்பிற் பேரிடத்த தாகி உறுபகை ஊக்கம் அழிப்ப தரண்.', transliteration: 'Sirukaappir Peritaththa Thaaki Urupakai Ookkam Azhippa Tharan', english_meaning: 'A fort is that which has an extensive space within, but only small places to be guarded, and such as can destroy the courage of besieging foes', career_application: 'A fort is that which has an extensive space within, but only small places to be guarded, and such as can destroy the courage of besieging foes', chapter: 'The Fortification' },
  { id: 745, kural_number: 745, tamil_text: 'கொளற்கரிதாய்க் கொண்டகூழ்த் தாகி அகத்தார் நிலைக்கெளிதாம் நீரது அரண்.', transliteration: 'Kolarkaridhaaik Kontakoozhth Thaaki Akaththaar Nilaikkelidhaam Neeradhu Aran', english_meaning: 'A fort is that which cannot be captured, which abounds in suitable provisions, and affords a position of easy defence to its inmates', career_application: 'A fort is that which cannot be captured, which abounds in suitable provisions, and affords a position of easy defence to its inmates', chapter: 'The Fortification' },
  { id: 746, kural_number: 746, tamil_text: 'எல்லாப் பொருளும் உடைத்தாய் இடத்துதவும் நல்லாள் உடையது அரண்.', transliteration: 'Ellaap Porulum Utaiththaai Itaththudhavum Nallaal Utaiyadhu Aran', english_meaning: 'A fort is that which has all (needful) things, and excellent heroes that can help it against destruction (by foes)', career_application: 'A fort is that which has all (needful) things, and excellent heroes that can help it against destruction (by foes)', chapter: 'The Fortification' },
  { id: 747, kural_number: 747, tamil_text: 'முற்றியும் முற்றா தெறிந்தும் அறைப்படுத்தும் பற்றற் கரியது அரண்.', transliteration: 'Mutriyum Mutraa Therindhum Araippatuththum Patrar Kariyadhu Aran', english_meaning: 'A fort is that which cannot be captured by blockading, assaulting, or undermining it', career_application: 'A fort is that which cannot be captured by blockading, assaulting, or undermining it', chapter: 'The Fortification' },
  { id: 748, kural_number: 748, tamil_text: 'முற்றாற்றி முற்றி யவரையும் பற்றாற்றிப் பற்றியார் வெல்வது அரண்.', transliteration: 'Mutraatri Mutri Yavaraiyum Patraatrip Patriyaar Velvadhu Aran', english_meaning: 'That is a fort whose inmates are able to overcome without losing their ground, even abler men who have besieged it', career_application: 'That is a fort whose inmates are able to overcome without losing their ground, even abler men who have besieged it', chapter: 'The Fortification' },
  { id: 749, kural_number: 749, tamil_text: 'முனைமுகத்து மாற்றலர் சாய வினைமுகத்து வீறெய்தி மாண்ட தரண்.', transliteration: 'Munaimukaththu Maatralar Saaya Vinaimukaththu Veereydhi Maanta Tharan', english_meaning: 'A fort is that which derives excellence from the stratagems made (by its inmates) to defeat their enemies in the battlefield', career_application: 'A fort is that which derives excellence from the stratagems made (by its inmates) to defeat their enemies in the battlefield', chapter: 'The Fortification' },
  { id: 750, kural_number: 750, tamil_text: 'எனைமாட்சித் தாகியக் கண்ணும் வினைமாட்சி இல்லார்கண் இல்லது அரண்.', transliteration: 'Enaimaatchith Thaakiyak Kannum Vinaimaatchi Illaarkan Illadhu Aran', english_meaning: 'Although a fort may possess all (the above-said) excellence, it is, as it were without these, if its inmates possess not the excellence of action', career_application: 'Although a fort may possess all (the above-said) excellence, it is, as it were without these, if its inmates possess not the excellence of action', chapter: 'The Fortification' },
  { id: 751, kural_number: 751, tamil_text: 'பொருளல் லவரைப் பொருளாகச் செய்யும் பொருளல்லது இல்லை பொருள்.', transliteration: 'Porulal Lavaraip Porulaakach Cheyyum Porulalladhu Illai Porul', english_meaning: 'Besides wealth there is nothing that can change people of no importance into those of (some) importance', career_application: 'Besides wealth there is nothing that can change people of no importance into those of (some) importance', chapter: 'Way of Accumulating Wealth' },
  { id: 752, kural_number: 752, tamil_text: 'இல்லாரை எல்லாரும் எள்ளுவர் செல்வரை எல்லாரும் செய்வர் சிறப்பு.', transliteration: 'Illaarai Ellaarum Elluvar Selvarai Ellaarum Seyvar Sirappu', english_meaning: 'All despise the poor; (but) all praise the rich', career_application: 'All despise the poor; (but) all praise the rich', chapter: 'Way of Accumulating Wealth' },
  { id: 753, kural_number: 753, tamil_text: 'பொருளென்னும் பொய்யா விளக்கம் இருளறுக்கும் எண்ணிய தேயத்துச் சென்று.', transliteration: 'Porulennum Poiyaa Vilakkam Irularukkum Enniya Theyaththuch Chendru', english_meaning: 'The imperishable light of wealth goes into regions desired (by its owner) and destroys the darkness (of enmity therein)', career_application: 'The imperishable light of wealth goes into regions desired (by its owner) and destroys the darkness (of enmity therein)', chapter: 'Way of Accumulating Wealth' },
  { id: 754, kural_number: 754, tamil_text: 'அறன்ஈனும் இன்பமும் ஈனும் திறனறிந்து தீதின்றி வந்த பொருள்.', transliteration: 'Araneenum Inpamum Eenum Thiranarindhu Theedhindri Vandha Porul', english_meaning: 'The wealth acquired with a knowledge of the proper means and without foul practices will yield virtue and happiness', career_application: 'The wealth acquired with a knowledge of the proper means and without foul practices will yield virtue and happiness', chapter: 'Way of Accumulating Wealth' },
  { id: 755, kural_number: 755, tamil_text: 'அருளொடும் அன்பொடும் வாராப் பொருளாக்கம் புல்லார் புரள விடல்.', transliteration: 'Arulotum Anpotum Vaaraap Porulaakkam Pullaar Purala Vital', english_meaning: '(Kings) should rather avoid than seek the accumulation of wealth which does not flow in with mercy and love', career_application: '(Kings) should rather avoid than seek the accumulation of wealth which does not flow in with mercy and love', chapter: 'Way of Accumulating Wealth' },
  { id: 756, kural_number: 756, tamil_text: 'உறுபொருளும் உல்கு பொருளும்தன் ஒன்னார்த் தெறுபொருளும் வேந்தன் பொருள்.', transliteration: 'Uruporulum Ulku Porulumdhan Onnaarth Theruporulum Vendhan Porul', english_meaning: 'The spoils of slaughtered foes; these are the royal revenues', career_application: 'The spoils of slaughtered foes; these are the royal revenues', chapter: 'Way of Accumulating Wealth' },
  { id: 757, kural_number: 757, tamil_text: 'அருளென்னும் அன்பீன் குழவி பொருளென்னும் செல்வச் செவிலியால் உண்டு.', transliteration: 'Arulennum Anpeen Kuzhavi Porulennum Selvach Cheviliyaal Untu', english_meaning: 'The child mercy which is borne by love grows under the care of the rich nurse of wealth', career_application: 'The child mercy which is borne by love grows under the care of the rich nurse of wealth', chapter: 'Way of Accumulating Wealth' },
  { id: 758, kural_number: 758, tamil_text: 'குன்றேறி யானைப்போர் கண்டற்றால் தன்கைத்தொன்று உண்டாகச் செய்வான் வினை.', transliteration: 'Kundreri Yaanaip Por Kantatraal Thankaiththondru Untaakach Cheyvaan Vinai', english_meaning: 'An undertaking of one who has wealth in one\'s hands is like viewing an elephant-fight from a hill-top', career_application: 'An undertaking of one who has wealth in one\'s hands is like viewing an elephant-fight from a hill-top', chapter: 'Way of Accumulating Wealth' },
  { id: 759, kural_number: 759, tamil_text: 'செய்க பொருளைச் செறுநர் செருக்கறுக்கும் எஃகதனிற் கூரிய தில்.', transliteration: 'Seyka Porulaich Cherunar Serukkarukkum Eqkadhanir Kooriya Thil', english_meaning: 'Accumulate wealth; it will destroy the arrogance of (your) foes; there is no weapon sharper than it', career_application: 'Accumulate wealth; it will destroy the arrogance of (your) foes; there is no weapon sharper than it', chapter: 'Way of Accumulating Wealth' },
  { id: 760, kural_number: 760, tamil_text: 'ஒண்பொருள் காழ்ப்ப இயற்றியார்க்கு எண்பொருள் ஏனை இரண்டும் ஒருங்கு.', transliteration: 'Onporul Kaazhppa Iyatriyaarkku Enporul Enai Irantum Orungu', english_meaning: 'To those who have honestly acquired an abundance of riches, the other two, (virtue and pleasure) are things easy (of acquisition)', career_application: 'To those who have honestly acquired an abundance of riches, the other two, (virtue and pleasure) are things easy (of acquisition)', chapter: 'Way of Accumulating Wealth' },
  { id: 761, kural_number: 761, tamil_text: 'உறுப்பமைந்து ஊறஞ்சா வெல்படை வேந்தன் வெறுக்கையுள் எல்லாம் தலை.', transliteration: 'Uruppamaindhu Ooranjaa Velpatai Vendhan Verukkaiyul Ellaam Thalai', english_meaning: 'The army which is complete in (its) parts and conquers without fear of wounds is the chief wealth of the king', career_application: 'The army which is complete in (its) parts and conquers without fear of wounds is the chief wealth of the king', chapter: 'The Excellence of an Army' },
  { id: 762, kural_number: 762, tamil_text: 'உலைவிடத்து ஊறஞ்சா வன்கண் தொலைவிடத்துத் தொல்படைக் கல்லால் அரிது.', transliteration: 'Ulaivitaththu Ooranjaa Vankan Tholaivitaththuth Tholpataik Kallaal Aridhu', english_meaning: 'Ancient army can alone have the valour which makes it stand by its king at the time of defeat, fearless of wounds and unmindful of its reduced strength', career_application: 'Ancient army can alone have the valour which makes it stand by its king at the time of defeat, fearless of wounds and unmindful of its reduced strength', chapter: 'The Excellence of an Army' },
  { id: 763, kural_number: 763, tamil_text: 'ஒலித்தக்கால் என்னாம் உவரி எலிப்பகை நாகம் உயிர்ப்பக் கெடும்.', transliteration: 'Oliththakkaal Ennaam Uvari Ela�ppakai Naakam Uyirppak Ketum', english_meaning: 'What if (a host of) hostile rats roar like the sea ? They will perish at the mere breath of the cobra', career_application: 'What if (a host of) hostile rats roar like the sea ? They will perish at the mere breath of the cobra', chapter: 'The Excellence of an Army' },
  { id: 764, kural_number: 764, tamil_text: 'அழிவின்றி அறைபோகா தாகி வழிவந்த வன்க ணதுவே படை.', transliteration: 'Azhivindri Araipokaa Thaaki Vazhivandha Vanka Nadhuve Patai', english_meaning: 'That indeed is an army which has stood firm of old without suffering destruction or deserting (to the enemy)', career_application: 'That indeed is an army which has stood firm of old without suffering destruction or deserting (to the enemy)', chapter: 'The Excellence of an Army' },
  { id: 765, kural_number: 765, tamil_text: 'கூற்றுடன்று மேல்வரினும் கூடி எதிர்நிற்கும் ஆற்ற லதுவே படை.', transliteration: 'Kootrutandru Melvarinum Kooti Edhirnirkum Aatra Ladhuve Patai', english_meaning: 'That indeed is an army which is capable of offering a united resistance, even if Yama advances against it with fury', career_application: 'That indeed is an army which is capable of offering a united resistance, even if Yama advances against it with fury', chapter: 'The Excellence of an Army' },
  { id: 766, kural_number: 766, tamil_text: 'மறமானம் மாண்ட வழிச்செலவு தேற்றம் எனநான்கே ஏமம் படைக்கு.', transliteration: 'Maramaanam Maanta Vazhichchelavu Thetram Enanaanke Emam Pataikku', english_meaning: 'Valour, honour, following in the excellent-footsteps (of its predecessors) and trust-worthiness; these four alone constitute the safeguard of an army', career_application: 'Valour, honour, following in the excellent-footsteps (of its predecessors) and trust-worthiness; these four alone constitute the safeguard of an army', chapter: 'The Excellence of an Army' },
  { id: 767, kural_number: 767, tamil_text: 'தார்தாங்கிச் செல்வது தானை தலைவந்த போர்தாங்கும் தன்மை அறிந்து.', transliteration: 'Thaardhaangich Chelvadhu Thaanai Thalaivandha Pordhaangum Thanmai Arindhu', english_meaning: 'That is an army which knowing the art of warding off an impending struggle, can bear against the dust-van (of a hostile force)', career_application: 'That is an army which knowing the art of warding off an impending struggle, can bear against the dust-van (of a hostile force)', chapter: 'The Excellence of an Army' },
  { id: 768, kural_number: 768, tamil_text: 'அடல்தகையும் ஆற்றலும் இல்லெனினும் தானை படைத்தகையால் பாடு பெறும்.', transliteration: 'Ataldhakaiyum Aatralum Illeninum Thaanai Pataiththakaiyaal Paatu Perum', english_meaning: 'Though destitute of courage to fight and strength (to endure), an army may yet gain renown by the splendour of its appearance', career_application: 'Though destitute of courage to fight and strength (to endure), an army may yet gain renown by the splendour of its appearance', chapter: 'The Excellence of an Army' },
  { id: 769, kural_number: 769, tamil_text: 'சிறுமையும் செல்லாத் துனியும் வறுமையும் இல்லாயின் வெல்லும் படை.', transliteration: 'Sirumaiyum Sellaath Thuniyum Varumaiyum Illaayin Vellum Patai', english_meaning: 'An army can triumph (over its foes) if it is free from diminution; irremediable aversion and poverty', career_application: 'An army can triumph (over its foes) if it is free from diminution; irremediable aversion and poverty', chapter: 'The Excellence of an Army' },
  { id: 770, kural_number: 770, tamil_text: 'நிலைமக்கள் சால உடைத்தெனினும் தானை தலைமக்கள் இல்வழி இல்.', transliteration: 'Nilaimakkal Saala Utaiththeninum Thaanai Thalaimakkal Ilvazhi Il', english_meaning: 'Though an army may contain a large number of permanent soldiers, it cannot last if it has no generals', career_application: 'Though an army may contain a large number of permanent soldiers, it cannot last if it has no generals', chapter: 'The Excellence of an Army' },
  { id: 771, kural_number: 771, tamil_text: 'என்னைமுன் நில்லன்மின் தெவ்விர் பலரென்னை முன்நின்று கல்நின் றவர்.', transliteration: 'Ennaimun Nillanmin Thevvir Palarennai Munnindru Kalnin Ravar', english_meaning: 'O my foes, stand not before my leader; (for) many are those who did so but afterwards stood (in the shape of) statues', career_application: 'O my foes, stand not before my leader; (for) many are those who did so but afterwards stood (in the shape of) statues', chapter: 'Military Spirit' },
  { id: 772, kural_number: 772, tamil_text: 'கான முயலெய்த அம்பினில் யானை பிழைத்தவேல் ஏந்தல் இனிது.', transliteration: 'Kaana Muyaleydha Ampinil Yaanai Pizhaiththavel Endhal Inidhu', english_meaning: 'It is more pleasant to hold the dart that has missed an elephant than that which has hit hare in the forest', career_application: 'It is more pleasant to hold the dart that has missed an elephant than that which has hit hare in the forest', chapter: 'Military Spirit' },
  { id: 773, kural_number: 773, tamil_text: 'பேராண்மை என்ப தறுகண்ஒன் றுற்றக்கால் ஊராண்மை மற்றதன் எஃகு.', transliteration: 'Peraanmai Enpa Tharukanon Rutrakkaal Ooraanmai Matradhan Eqku', english_meaning: 'The learned say that fierceness (incontest with a foe) is indeed great valour; but to become a benefactor in case of accident (to a foe) is the extreme (limit) of that valour', career_application: 'The learned say that fierceness (incontest with a foe) is indeed great valour; but to become a benefactor in case of accident (to a foe) is the extreme (limit) of that valour', chapter: 'Military Spirit' },
  { id: 774, kural_number: 774, tamil_text: 'கைவேல் களிற்றொடு போக்கி வருபவன் மெய்வேல் பறியா நகும்.', transliteration: 'Kaivel Kalitrotu Pokki Varupavan Meyvel Pariyaa Nakum', english_meaning: 'The hero who after casting the lance in his hand on an elephant, comes (in search of another) will pluck the one (that sticks) in his body and laugh (exultingly)', career_application: 'The hero who after casting the lance in his hand on an elephant, comes (in search of another) will pluck the one (that sticks) in his body and laugh (exultingly)', chapter: 'Military Spirit' },
  { id: 775, kural_number: 775, tamil_text: 'விழித்தகண் வேல்கொண டெறிய அழித்திமைப்பின் ஒட்டன்றோ வன்க ணவர்க்கு.', transliteration: 'Vizhiththakan Velkona Teriya Azhiththimaippin Ottandro Vanka Navarkku', english_meaning: 'Is it not a defeat to the valiant to wink and destroy their ferocious look when a lance in cast at them (by their foe) ?', career_application: 'Is it not a defeat to the valiant to wink and destroy their ferocious look when a lance in cast at them (by their foe) ?', chapter: 'Military Spirit' },
  { id: 776, kural_number: 776, tamil_text: 'விழுப்புண் படாதநாள் எல்லாம் வழுக்கினுள் வைக்கும்தன் நாளை எடுத்து.', transliteration: 'Vizhuppun Pataadhanaal Ellaam Vazhukkinul Vaikkumdhan Naalai Etuththu', english_meaning: 'The hero will reckon among wasted days all those on which he had not received severe wounds', career_application: 'The hero will reckon among wasted days all those on which he had not received severe wounds', chapter: 'Military Spirit' },
  { id: 777, kural_number: 777, tamil_text: 'சுழலும் இசைவேண்டி வேண்டா உயிரார் கழல்யாப்புக் காரிகை நீர்த்து.', transliteration: 'Suzhalum Isaiventi Ventaa Uyiraar Kazhalyaappuk Kaarikai Neerththu', english_meaning: 'The fastening of ankle-ring by those who disire a world-wide renown and not (the safety of) their lives is like adorning (themselves)', career_application: 'The fastening of ankle-ring by those who disire a world-wide renown and not (the safety of) their lives is like adorning (themselves)', chapter: 'Military Spirit' },
  { id: 778, kural_number: 778, tamil_text: 'உறின்உயிர் அஞ்சா மறவர் இறைவன் செறினும் சீர்குன்றல் இலர்.', transliteration: 'Urinuyir Anjaa Maravar Iraivan Serinum Seerkundral Ilar', english_meaning: 'The heroes who are not afraid of losing their life in a contest will not cool their ardour, even if the king prohibits (their fighting)', career_application: 'The heroes who are not afraid of losing their life in a contest will not cool their ardour, even if the king prohibits (their fighting)', chapter: 'Military Spirit' },
  { id: 779, kural_number: 779, tamil_text: 'இழைத்தது இகவாமைச் சாவாரை யாரே பிழைத்தது ஒறுக்கிற் பவர்.', transliteration: 'Izhaiththadhu Ikavaamaich Chaavaarai Yaare Pizhaiththadhu Orukkir Pavar', english_meaning: 'Who would reproach with failure those who seal their oath with their death ?', career_application: 'Who would reproach with failure those who seal their oath with their death ?', chapter: 'Military Spirit' },
  { id: 780, kural_number: 780, tamil_text: 'புரந்தார்கண் நீர்மல்கச் சாகிற்பின் சாக்காடு இரந்துகோள் தக்கது உடைத்து.', transliteration: 'Purandhaarkan Neermalkach Chaakirpin Saakkaatu Irandhukol Thakkadhu Utaiththu', english_meaning: 'If (heroes) can so die as to fill with tears the eyes of their rulers, such a death deserves to be obtained even by begging', career_application: 'If (heroes) can so die as to fill with tears the eyes of their rulers, such a death deserves to be obtained even by begging', chapter: 'Military Spirit' },
  { id: 781, kural_number: 781, tamil_text: 'செயற்கரிய யாவுள நட்பின் அதுபோல் வினைக்கரிய யாவுள காப்பு.', transliteration: 'Seyarkariya Yaavula Natpin Adhupol Vinaikkariya Yaavula Kaappu', english_meaning: 'What so sure defence \'gainst all that foe can do?', career_application: 'What so sure defence \'gainst all that foe can do?', chapter: 'Friendship' },
  { id: 782, kural_number: 782, tamil_text: 'நிறைநீர நீரவர் கேண்மை பிறைமதிப் பின்னீர பேதையார் நட்பு.', transliteration: 'Niraineera Neeravar Kenmai Piraimadhip Pinneera Pedhaiyaar Natpu', english_meaning: 'The friendship of the wise waxes like the new moon; (but) that of fools wanes like the full moon', career_application: 'The friendship of the wise waxes like the new moon; (but) that of fools wanes like the full moon', chapter: 'Friendship' },
  { id: 783, kural_number: 783, tamil_text: 'நவில்தொறும் நூல்நயம் போலும் பயில்தொறும் பண்புடை யாளர் தொடர்பு.', transliteration: 'Navildhorum Noolnayam Polum Payildhorum Panputai Yaalar Thotarpu', english_meaning: 'Like learning, the friendship of the noble, the more it is cultivated, the more delightful does it become', career_application: 'Like learning, the friendship of the noble, the more it is cultivated, the more delightful does it become', chapter: 'Friendship' },
  { id: 784, kural_number: 784, tamil_text: 'நகுதற் பொருட்டன்று நட்டல் மிகுதிக்கண் மேற்செனறு இடித்தற் பொருட்டு.', transliteration: 'Nakudhar Poruttandru Nattal Mikudhikkan Mersenaru Itiththar Poruttu', english_meaning: 'Friendship is to be practised not for the purpose of laughing but for that of being beforehand in giving one another sharp rebukes in case of transgression', career_application: 'Friendship is to be practised not for the purpose of laughing but for that of being beforehand in giving one another sharp rebukes in case of transgression', chapter: 'Friendship' },
  { id: 785, kural_number: 785, tamil_text: 'புணர்ச்சி பழகுதல் வேண்டா உணர்ச்சிதான் நட்பாங் கிழமை தரும்.', transliteration: 'Punarchchi Pazhakudhal Ventaa Unarchchidhaan Natpaang Kizhamai Tharum', english_meaning: 'Living together and holding frequent intercourse are not necessary (for friendship); (mutual) understanding can alone create a claim for it', career_application: 'Living together and holding frequent intercourse are not necessary (for friendship); (mutual) understanding can alone create a claim for it', chapter: 'Friendship' },
  { id: 786, kural_number: 786, tamil_text: 'முகநக நட்பது நட்பன்று நெஞ்சத்து அகநக நட்பது நட்பு.', transliteration: 'Mukanaka Natpadhu Natpandru Nenjaththu Akanaka Natpadhu Natpu', english_meaning: 'The love that dwells (merely in the smiles of the face is not friendship; (but) that which dwells deep in the smiles of the heart is true friendship', career_application: 'The love that dwells (merely in the smiles of the face is not friendship; (but) that which dwells deep in the smiles of the heart is true friendship', chapter: 'Friendship' },
  { id: 787, kural_number: 787, tamil_text: 'அழிவி னவைநீக்கி ஆறுய்த்து அழிவின்கண் அல்லல் உழப்பதாம் நட்பு.', transliteration: 'Azhivi Navaineekki Aaruyththu Azhivinkan Allal Uzhappadhaam Natpu', english_meaning: '(True) friendship turns aside from evil (ways) makes (him) walk in the (good) way, and, in case of loss if shares his sorrow (with him)', career_application: '(True) friendship turns aside from evil (ways) makes (him) walk in the (good) way, and, in case of loss if shares his sorrow (with him)', chapter: 'Friendship' },
  { id: 788, kural_number: 788, tamil_text: 'உடுக்கை இழந்தவன் கைபோல ஆங்கே இடுக்கண் களைவதாம் நட்பு.', transliteration: 'Utukkai Izhandhavan Kaipola Aange Itukkan Kalaivadhaam Natpu', english_meaning: '(True) friendship hastens to the rescue of the afflicted (as readily) as the hand of one whose garment is loosened (before an assembly)', career_application: '(True) friendship hastens to the rescue of the afflicted (as readily) as the hand of one whose garment is loosened (before an assembly)', chapter: 'Friendship' },
  { id: 789, kural_number: 789, tamil_text: 'நட்பிற்கு வீற்றிருக்கை யாதெனின் கொட்பின்றி ஒல்லும்வாய் ஊன்றும் நிலை.', transliteration: 'Natpirku Veetrirukkai Yaadhenin Kotpindri Ollumvaai Oondrum Nilai', english_meaning: 'Friendship may be said to be on its throne when it possesses the power of supporting one at all times and under all circumstances, (in the practice or virtue and wealth)', career_application: 'Friendship may be said to be on its throne when it possesses the power of supporting one at all times and under all circumstances, (in the practice or virtue and wealth)', chapter: 'Friendship' },
  { id: 790, kural_number: 790, tamil_text: 'இனையர் இவரெமக்கு இன்னம்யாம் என்று புனையினும் புல்லென்னும் நட்பு.', transliteration: 'Inaiyar Ivaremakku Innamyaam Endru Punaiyinum Pullennum Natpu', english_meaning: 'Though friends may praise one another saying, "He is so intimate with us, and we so much (with him)"; (still) such friendship will appear mean', career_application: 'Though friends may praise one another saying, "He is so intimate with us, and we so much (with him)"; (still) such friendship will appear mean', chapter: 'Friendship' },
  { id: 791, kural_number: 791, tamil_text: 'நாடாது நட்டலிற் கேடில்லை நட்டபின் வீடில்லை நட்பாள் பவர்க்கு.', transliteration: 'Naataadhu Nattalir Ketillai Nattapin Veetillai Natpaal Pavarkku', english_meaning: 'As those who are of a friendly nature will not forsake (a friend) after once loving (him), there is no evil so great as contracting a friendship without due inquiry', career_application: 'As those who are of a friendly nature will not forsake (a friend) after once loving (him), there is no evil so great as contracting a friendship without due inquiry', chapter: 'Investigation in forming Friendships' },
  { id: 792, kural_number: 792, tamil_text: 'ஆய்ந்தாய்ந்து கொள்ளாதான் கேண்மை கடைமுறை தான்சாம் துயரம் தரும்.', transliteration: 'Aaindhaaindhu Kollaadhaan Kenmai Kataimurai Thaansaam Thuyaram Tharum', english_meaning: 'The friendship contracted by him who has not made repeated inquiry will in the end grieve (him) to death', career_application: 'The friendship contracted by him who has not made repeated inquiry will in the end grieve (him) to death', chapter: 'Investigation in forming Friendships' },
  { id: 793, kural_number: 793, tamil_text: 'குணமும் குடிமையும் குற்றமும் குன்றா இனனும் அறிந்தியாக்க நட்பு.', transliteration: 'Kunamum Kutimaiyum Kutramum Kundraa Inanum Arindhiyaakka Natpu', english_meaning: 'Make friendship (with one) after ascertaining (his) character, birth, defects and the whole of one\'s relations', career_application: 'Make friendship (with one) after ascertaining (his) character, birth, defects and the whole of one\'s relations', chapter: 'Investigation in forming Friendships' },
  { id: 794, kural_number: 794, tamil_text: 'குடிப்பிறந்து தன்கண் பழிநாணு வானைக் கொடுத்தும் கொளல்வேண்டும் நட்பு.', transliteration: 'Kutippirandhu Thankan Pazhinaanu Vaanaik Kotuththum Kolalventum Natpu', english_meaning: 'The friendship of one who belongs to a (good) family and is afraid of (being charged with) guilt, is worth even purchasing', career_application: 'The friendship of one who belongs to a (good) family and is afraid of (being charged with) guilt, is worth even purchasing', chapter: 'Investigation in forming Friendships' },
  { id: 795, kural_number: 795, tamil_text: 'அழச்சொல்லி அல்லது இடித்து வழக்கறிய வல்லார்நடபு ஆய்ந்து கொளல்.', transliteration: 'Azhachcholli Alladhu Itiththu Vazhakkariya Vallaarnatapu Aaindhu Kolal', english_meaning: 'You should examine and secure the friendship of those who can speak so as to make you weep over a crime (before its commission) or rebuke you severely (after you have done it) and are able to teach', career_application: 'You should examine and secure the friendship of those who can speak so as to make you weep over a crime (before its commission) or rebuke you severely (after you have done it) and are able to teach', chapter: 'Investigation in forming Friendships' },
  { id: 796, kural_number: 796, tamil_text: 'கேட்டினும் உண்டோர் உறுதி கிளைஞரை நீட்டி அளப்பதோர் கோல்.', transliteration: 'Kettinum Untor Urudhi Kilaignarai Neetti Alappadhor Kol', english_meaning: 'Even in ruin there is some good; (for) it is a rod by which one may measure fully (the affection of one\'s) relations', career_application: 'Even in ruin there is some good; (for) it is a rod by which one may measure fully (the affection of one\'s) relations', chapter: 'Investigation in forming Friendships' },
  { id: 797, kural_number: 797, tamil_text: 'ஊதியம் என்பது ஒருவற்குப் பேதையார் கேண்மை ஒரீஇ விடல்.', transliteration: 'Oodhiyam Enpadhu Oruvarkup Pedhaiyaar Kenmai Oreei Vital', english_meaning: 'It is indead a gain for one to renounce the friendship of fools', career_application: 'It is indead a gain for one to renounce the friendship of fools', chapter: 'Investigation in forming Friendships' },
  { id: 798, kural_number: 798, tamil_text: 'உள்ளற்க உள்ளம் சிறுகுவ கொள்ளற்க அல்லற்கண் ஆற்றறுப்பார் நட்பு.', transliteration: 'Ullarka Ullam Sirukuva Kollarka Allarkan Aatraruppaar Natpu', english_meaning: 'Do not think of things that discourage your mind, nor contract friendship with those who would forsake you in adversity', career_application: 'Do not think of things that discourage your mind, nor contract friendship with those who would forsake you in adversity', chapter: 'Investigation in forming Friendships' },
  { id: 799, kural_number: 799, tamil_text: 'கெடுங்காலைக் கைவிடுவார் கேண்மை அடுங்காலை உள்ளினும் உள்ளஞ் சுடும்.', transliteration: 'Ketungaalaik Kaivituvaar Kenmai Atungaalai Ullinum Ullanj Chutum', english_meaning: 'The very thought of the friendship of those who have deserted one at the approach of adversity will burn one\'s mind at the time of death', career_application: 'The very thought of the friendship of those who have deserted one at the approach of adversity will burn one\'s mind at the time of death', chapter: 'Investigation in forming Friendships' },
  { id: 800, kural_number: 800, tamil_text: 'மருவுக மாசற்றார் கேண்மைஒன் றீத்தும் ஒருவுக ஒப்பிலார் நட்பு.', transliteration: 'Maruvuka Maasatraar Kenmaion Reeththum Oruvuka Oppilaar Natpu', english_meaning: 'Continue to enjoy the friendship of the pure; (but) renounce even with a gift, the friendship of those who do not agree (with the world)', career_application: 'Continue to enjoy the friendship of the pure; (but) renounce even with a gift, the friendship of those who do not agree (with the world)', chapter: 'Investigation in forming Friendships' },
  { id: 801, kural_number: 801, tamil_text: 'பழைமை எனப்படுவது யாதெனின் யாதும் கிழமையைக் கீழ்ந்திடா நட்பு.', transliteration: 'Pazhaimai Enappatuvadhu Yaadhenin Yaadhum Kizhamaiyaik Keezhndhitaa Natpu', english_meaning: 'Imtimate friendship is that which cannot in the least be injured by (things done through the) right (of longstanding intimacy)', career_application: 'Imtimate friendship is that which cannot in the least be injured by (things done through the) right (of longstanding intimacy)', chapter: 'Familiarity' },
  { id: 802, kural_number: 802, tamil_text: 'நட்பிற் குறுப்புக் கெழுதகைமை மற்றதற்கு உப்பாதல் சான்றோர் கடன்.', transliteration: 'Natpir Kuruppuk Kezhudhakaimai Matradharku Uppaadhal Saandror Katan', english_meaning: 'The constituents of friendship are (things done through) the right of intimacy; to be pleased with such a right is the duty of the wise', career_application: 'The constituents of friendship are (things done through) the right of intimacy; to be pleased with such a right is the duty of the wise', chapter: 'Familiarity' },
  { id: 803, kural_number: 803, tamil_text: 'பழகிய நட்பெவன் செய்யுங் கெழுதகைமை செய்தாங்கு அமையாக் கடை.', transliteration: 'Pazhakiya Natpevan Seyyung Kezhudhakaimai Seydhaangu Amaiyaak Katai', english_meaning: 'Of what avail is long-standing friendship, if friends do not admit as their own actions done through the right of intimacy ?', career_application: 'Of what avail is long-standing friendship, if friends do not admit as their own actions done through the right of intimacy ?', chapter: 'Familiarity' },
  { id: 804, kural_number: 804, tamil_text: 'விழைதகையான் வேண்டி இருப்பர் கெழுதகையாற் கேளாது நட்டார் செயின்.', transliteration: 'Vizhaidhakaiyaan Venti Iruppar Kezhudhakaiyaar Kelaadhu Nattaar Seyin', english_meaning: 'If friends, through the right of friendship, do (anything) without being asked, the wise will be pleased with them on account of its desirability', career_application: 'If friends, through the right of friendship, do (anything) without being asked, the wise will be pleased with them on account of its desirability', chapter: 'Familiarity' },
  { id: 805, kural_number: 805, tamil_text: 'பேதைமை ஒன்றோ பெருங்கிழமை என்றுணர்க நோதக்க நட்டார் செயின்.', transliteration: 'Pedhaimai Ondro Perungizhamai Endrunarka Nodhakka Nattaar Seyin', english_meaning: 'If friends should perform what is painful, understand that it is owing not only to ignorance, but also to the strong claims of intimacy', career_application: 'If friends should perform what is painful, understand that it is owing not only to ignorance, but also to the strong claims of intimacy', chapter: 'Familiarity' },
  { id: 806, kural_number: 806, tamil_text: 'எல்லைக்கண் நின்றார் துறவார் தொலைவிடத்தும் தொல்லைக்கண் நின்றார் தொடர்பு.', transliteration: 'Ellaikkan Nindraar Thuravaar Tholaivitaththum Thollaikkan Nindraar Thotarpu', english_meaning: 'Those who stand within the limits (of true friendship) will not even in adversity give up the intimacy of long-standing friends', career_application: 'Those who stand within the limits (of true friendship) will not even in adversity give up the intimacy of long-standing friends', chapter: 'Familiarity' },
  { id: 807, kural_number: 807, tamil_text: 'அழிவந்த செய்யினும் அன்பறார் அன்பின் வழிவந்த கேண்மை யவர்.', transliteration: 'Azhivandha Seyyinum Anparaar Anpin Vazhivandha Kenmai Yavar', english_meaning: 'Those who have (long) stood in the path of affection will not give it up even if their friends cause (them) their ruin', career_application: 'Those who have (long) stood in the path of affection will not give it up even if their friends cause (them) their ruin', chapter: 'Familiarity' },
  { id: 808, kural_number: 808, tamil_text: 'கேளிழுக்கம் கேளாக் கெழுதகைமை வல்லார்க்கு நாளிழுக்கம் நட்டார் செயின்.', transliteration: 'Kelizhukkam Kelaak Kezhudhakaimai Vallaarkku Naalizhukkam Nattaar Seyin', english_meaning: 'To those who understand that by which they should not listen to (tales about) the faults of their friends, that is a (profitable) day on which the latter may commit a fault', career_application: 'To those who understand that by which they should not listen to (tales about) the faults of their friends, that is a (profitable) day on which the latter may commit a fault', chapter: 'Familiarity' },
  { id: 809, kural_number: 809, tamil_text: 'கெடாஅ வழிவந்த கேண்மையார் கேண்மை விடாஅர் விழையும் உலகு.', transliteration: 'Ketaaa Vazhivandha Kenmaiyaar Kenmai Vitaaar Vizhaiyum Ulaku', english_meaning: 'They will be loved by the world, who have not forsaken the friendship of those with whom they have kept up an unbroken long-standing intimacy', career_application: 'They will be loved by the world, who have not forsaken the friendship of those with whom they have kept up an unbroken long-standing intimacy', chapter: 'Familiarity' },
  { id: 810, kural_number: 810, tamil_text: 'விழையார் விழையப் படுப பழையார்கண் பண்பின் தலைப்பிரியா தார்.', transliteration: 'Vizhaiyaar Vizhaiyap Patupa Pazhaiyaarkan Panpin Thalaippiriyaa Thaar', english_meaning: 'Even enemies will love those who have never changed in their affection to their long-standingfriends', career_application: 'Even enemies will love those who have never changed in their affection to their long-standingfriends', chapter: 'Familiarity' },
  { id: 811, kural_number: 811, tamil_text: 'பருகுவார் போலினும் பண்பிலார் கேண்மை பெருகலிற் குன்றல் இனிது.', transliteration: 'Parukuvaar Polinum Panpilaar Kenmai Perukalir Kundral Inidhu', english_meaning: 'The decrease of friendship with those who look as if they would eat you up (through excess of love) while they are really destitute of goodness is far better than its increase', career_application: 'The decrease of friendship with those who look as if they would eat you up (through excess of love) while they are really destitute of goodness is far better than its increase', chapter: 'Evil Friendship' },
  { id: 812, kural_number: 812, tamil_text: 'உறின்நட்டு அறினொருஉம் ஒப்பிலார் கேண்மை பெறினும் இழப்பினும் என்?', transliteration: 'Urinnattu Arinoruum Oppilaar Kenmai Perinum Izhappinum En?', english_meaning: 'Of what avail is it to get or lose the friendship of those who love when there is gain and leave when there is none ?', career_application: 'Of what avail is it to get or lose the friendship of those who love when there is gain and leave when there is none ?', chapter: 'Evil Friendship' },
  { id: 813, kural_number: 813, tamil_text: 'உறுவது சீர்தூக்கும் நட்பும் பெறுவது கொள்வாரும் கள்வரும் நேர்.', transliteration: 'Uruvadhu Seerdhookkum Natpum Peruvadhu Kolvaarum Kalvarum Ner', english_meaning: 'Friendship who calculate the profits (of their friendship), prostitutes who are bent on obtaining their gains, and thieves are (all) of the same character', career_application: 'Friendship who calculate the profits (of their friendship), prostitutes who are bent on obtaining their gains, and thieves are (all) of the same character', chapter: 'Evil Friendship' },
  { id: 814, kural_number: 814, tamil_text: 'அமரகத்து ஆற்றறுக்கும் கல்லாமா அன்னார் தமரின் தனிமை தலை.', transliteration: 'Amarakaththu Aatrarukkum Kallaamaa Annaar Thamarin Thanimai Thalai', english_meaning: 'Solitude is more to be desired than the society of those who resemble the untrained horses which throw down (their riders) in the fields of battle', career_application: 'Solitude is more to be desired than the society of those who resemble the untrained horses which throw down (their riders) in the fields of battle', chapter: 'Evil Friendship' },
  { id: 815, kural_number: 815, tamil_text: 'செய்தேமஞ் சாராச் சிறியவர் புன்கேண்மை எய்தலின் எய்தாமை நன்று.', transliteration: 'Seydhemanj Chaaraach Chiriyavar Punkenmai Eydhalin Eydhaamai Nandru', english_meaning: 'It is far better to avoid that to contract the evil friendship of the base who cannot protect (their friends) even when appointed to do so', career_application: 'It is far better to avoid that to contract the evil friendship of the base who cannot protect (their friends) even when appointed to do so', chapter: 'Evil Friendship' },
  { id: 816, kural_number: 816, tamil_text: 'பேதை பெருங்கெழீஇ நட்பின் அறிவுடையார் ஏதின்மை கோடி உறும்.', transliteration: 'Pedhai Perungezheei Natpin Arivutaiyaar Edhinmai Koti Urum', english_meaning: 'The hatred of the wise is ten-million times more profitable than the excessive intimacy of the fool', career_application: 'The hatred of the wise is ten-million times more profitable than the excessive intimacy of the fool', chapter: 'Evil Friendship' },
  { id: 817, kural_number: 817, tamil_text: 'நகைவகைய ராகிய நட்பின் பகைவரால் பத்தடுத்த கோடி உறும்.', transliteration: 'Nakaivakaiya Raakiya Natpin Pakaivaraal Paththatuththa Koti Urum', english_meaning: 'What comes from enemies is a hundred million times more profitable than what comes from the friendship of those who cause only laughter', career_application: 'What comes from enemies is a hundred million times more profitable than what comes from the friendship of those who cause only laughter', chapter: 'Evil Friendship' },
  { id: 818, kural_number: 818, tamil_text: 'ஒல்லும் கருமம் உடற்று பவர்கேண்மை சொல்லாடார் சோர விடல்.', transliteration: 'Ollum Karumam Utatru Pavarkenmai Sollaataar Sora Vital', english_meaning: 'Gradually abandon without revealing (beforehand) the friendship of those who pretend inability to carry out what they (really) could do', career_application: 'Gradually abandon without revealing (beforehand) the friendship of those who pretend inability to carry out what they (really) could do', chapter: 'Evil Friendship' },
  { id: 819, kural_number: 819, tamil_text: 'கனவினும் இன்னாது மன்னோ வினைவேறு சொல்வேறு பட்டார் தொடர்பு.', transliteration: 'Kanavinum Innaadhu Manno Vinaiveru Solveru Pattaar Thotarpu', english_meaning: 'The friendship of those whose actions do not agree with their words will distress (one) even in (one\'s) dreams', career_application: 'The friendship of those whose actions do not agree with their words will distress (one) even in (one\'s) dreams', chapter: 'Evil Friendship' },
  { id: 820, kural_number: 820, tamil_text: 'எனைத்தும் குறுகுதல் ஓம்பல் மனைக்கெழீஇ மன்றில் பழிப்பார் தொடர்பு.', transliteration: 'Enaiththum Kurukudhal Ompal Manaikkezheei Mandril Pazhippaar Thotarpu', english_meaning: 'Avoid even the least approach to a contraction of friendship with those who would love you in private but ridicule you in public', career_application: 'Avoid even the least approach to a contraction of friendship with those who would love you in private but ridicule you in public', chapter: 'Evil Friendship' },
  { id: 821, kural_number: 821, tamil_text: 'சீரிடம் காணின் எறிதற்குப் பட்டடை நேரா நிரந்தவர் நட்பு.', transliteration: 'Seeritam Kaanin Eridharkup Pattatai Neraa Nirandhavar Natpu', english_meaning: 'The friendship of those who behave like friends without inward affection is a weapon that may be thrown when a favourable opportunity presents itself', career_application: 'The friendship of those who behave like friends without inward affection is a weapon that may be thrown when a favourable opportunity presents itself', chapter: 'Unreal Friendship' },
  { id: 822, kural_number: 822, tamil_text: 'இனம்போன்று இனமல்லார் கேண்மை மகளிர் மனம்போல வேறு படும்.', transliteration: 'Inampondru Inamallaar Kenmai Makalir Manampola Veru Patum', english_meaning: 'The friendship of those who seem to be friends while they are not, will change like the love of women', career_application: 'The friendship of those who seem to be friends while they are not, will change like the love of women', chapter: 'Unreal Friendship' },
  { id: 823, kural_number: 823, tamil_text: 'பலநல்ல கற்றக் கடைத்து மனநல்லர் ஆகுதல் மாணார்க் கரிது.', transliteration: 'Palanalla Katrak Kataiththu Mananallar Aakudhal Maanaark Karidhu', english_meaning: 'Though (one\'s) enemies may have mastered many good books, it will be impossible for them to become truly loving at heart', career_application: 'Though (one\'s) enemies may have mastered many good books, it will be impossible for them to become truly loving at heart', chapter: 'Unreal Friendship' },
  { id: 824, kural_number: 824, tamil_text: 'முகத்தின் இனிய நகாஅ அகத்தின்னா வஞ்சரை அஞ்சப் படும்.', transliteration: 'Mukaththin Iniya Nakaaa Akaththinnaa Vanjarai Anjap Patum', english_meaning: 'One should fear the deceitful who smile sweetly with their face but never love with their heart', career_application: 'One should fear the deceitful who smile sweetly with their face but never love with their heart', chapter: 'Unreal Friendship' },
  { id: 825, kural_number: 825, tamil_text: 'மனத்தின் அமையா தவரை எனைத்தொன்றும் சொல்லினால் தேறற்பாற்று அன்று.', transliteration: 'Manaththin Amaiyaa Thavarai Enaiththondrum Sollinaal Therarpaatru Andru', english_meaning: 'In nothing whatever is it proper to rely on the words of those who do not love with their heart', career_application: 'In nothing whatever is it proper to rely on the words of those who do not love with their heart', chapter: 'Unreal Friendship' },
  { id: 826, kural_number: 826, tamil_text: 'நட்டார்போல் நல்லவை சொல்லினும் ஒட்டார்சொல் ஒல்லை உணரப் படும்.', transliteration: 'Nattaarpol Nallavai Sollinum Ottaarsol Ollai Unarap Patum', english_meaning: 'Though (one\'s) foes may utter good things as though they were friends, once will at once understand (their evil, import)', career_application: 'Though (one\'s) foes may utter good things as though they were friends, once will at once understand (their evil, import)', chapter: 'Unreal Friendship' },
  { id: 827, kural_number: 827, tamil_text: 'சொல்வணக்கம் ஒன்னார்கண் கொள்ளற்க வில்வணக்கம் தீங்கு குறித்தமை யான்.', transliteration: 'Solvanakkam Onnaarkan Kollarka Vilvanakkam Theengu Kuriththamai Yaan', english_meaning: 'Since the bending of the bow bespeaks evil, one should not accept (as good) the humiliating speeches of one\'s foes', career_application: 'Since the bending of the bow bespeaks evil, one should not accept (as good) the humiliating speeches of one\'s foes', chapter: 'Unreal Friendship' },
  { id: 828, kural_number: 828, tamil_text: 'தொழுதகை யுள்ளும் படையொடுங்கும் ஒன்னார் அழுதகண் ணீரும் அனைத்து.', transliteration: 'Thozhudhakai Yullum Pataiyotungum Onnaar Azhudhakan Neerum Anaiththu', english_meaning: 'A weapon may be hid in the very hands with which (one\'s) foes adore (him) (and) the tears they shed are of the same nature', career_application: 'A weapon may be hid in the very hands with which (one\'s) foes adore (him) (and) the tears they shed are of the same nature', chapter: 'Unreal Friendship' },
  { id: 829, kural_number: 829, tamil_text: 'மிகச்செய்து தம்மெள்ளு வாரை நகச்செய்து நட்பினுள் சாப்புல்லற் பாற்று.', transliteration: 'Mikachcheydhu Thammellu Vaarai Nakachcheydhu Natpinul Saappullar Paatru', english_meaning: 'It is the duty of kings to affect great love but make it die (inwardly); as regard those foes who shew them great friendship but despise them (in their heart)', career_application: 'It is the duty of kings to affect great love but make it die (inwardly); as regard those foes who shew them great friendship but despise them (in their heart)', chapter: 'Unreal Friendship' },
  { id: 830, kural_number: 830, tamil_text: 'பகைநட்பாம் காலம் வருங்கால் முகநட்டு அகநட்பு ஒரீஇ விடல்.', transliteration: 'Pakainatpaam Kaalam Varungaal Mukanattu Akanatpu Oreei Vital', english_meaning: 'When one\'s foes begin to affect friendship, one should love them with one\'s looks, and, cherishing no love in the heart, give up (even the former)', career_application: 'When one\'s foes begin to affect friendship, one should love them with one\'s looks, and, cherishing no love in the heart, give up (even the former)', chapter: 'Unreal Friendship' },
  { id: 831, kural_number: 831, tamil_text: 'பேதைமை என்பதொன்று யாதெனின் ஏதங்கொண்டு ஊதியம் போக விடல்.', transliteration: 'Pedhaimai Enpadhondru Yaadhenin Edhangontu Oodhiyam Poka Vital', english_meaning: 'Folly is one (of the chief defects); it is that which (makes one) incur loss and forego gain', career_application: 'Folly is one (of the chief defects); it is that which (makes one) incur loss and forego gain', chapter: 'Folly' },
  { id: 832, kural_number: 832, tamil_text: 'பேதைமையுள் எல்லாம் பேதைமை காதன்மை கையல்ல தன்கட் செயல்.', transliteration: 'Pedhaimaiyul Ellaam Pedhaimai Kaadhanmai Kaiyalla Thankat Seyal', english_meaning: 'The greatest folly is that which leads one to take delight in doing what is forbidden', career_application: 'The greatest folly is that which leads one to take delight in doing what is forbidden', chapter: 'Folly' },
  { id: 833, kural_number: 833, tamil_text: 'நாணாமை நாடாமை நாரின்மை யாதொன்றும் பேணாமை பேதை தொழில்', transliteration: 'Naanaamai Naataamai Naarinmai Yaadhondrum Penaamai Pedhai Thozhil', english_meaning: 'Shamelessness indifference (to what must be sought after), harshness, and aversion for everything (that ought to be desired) are the qualities of the fool', career_application: 'Shamelessness indifference (to what must be sought after), harshness, and aversion for everything (that ought to be desired) are the qualities of the fool', chapter: 'Folly' },
  { id: 834, kural_number: 834, tamil_text: 'ஓதி உணர்ந்தும் பிறர்க்குரைத்தும் தானடங்காப் பேதையின் பேதையார் இல்.', transliteration: 'Odhi Unarndhum Pirarkkuraiththum Thaanatangaap Pedhaiyin Pedhaiyaar Il', english_meaning: 'There are no greater fools than he who, though he has read and understood (a great deal) and even taught it to others, does not walk according to his own teaching', career_application: 'There are no greater fools than he who, though he has read and understood (a great deal) and even taught it to others, does not walk according to his own teaching', chapter: 'Folly' },
  { id: 835, kural_number: 835, tamil_text: 'ஒருமைச் செயலாற்றும் பேதை எழுமையும் தான்புக் கழுந்தும் அளறு.', transliteration: 'Orumaich Cheyalaatrum Pedhai Ezhumaiyum Thaanpuk Kazhundhum Alaru', english_meaning: 'A fool can procure in a single birth a hell into which he may enter and suffer through all the seven births', career_application: 'A fool can procure in a single birth a hell into which he may enter and suffer through all the seven births', chapter: 'Folly' },
  { id: 836, kural_number: 836, tamil_text: 'பொய்படும் ஒன்றோ புனைபூணும் கையறியாப் பேதை வினைமேற் கொளின்.', transliteration: 'Poipatum Ondro Punaipoonum Kaiyariyaap Pedhai Vinaimer Kolin', english_meaning: 'If the fool, who knows not how to act undertakes a work, he will (certainly) fail (But) is it all ? He will even adorn himself with fetters', career_application: 'If the fool, who knows not how to act undertakes a work, he will (certainly) fail (But) is it all ? He will even adorn himself with fetters', chapter: 'Folly' },
  { id: 837, kural_number: 837, tamil_text: 'ஏதிலார் ஆரத் தமர்பசிப்பர் பேதை பெருஞ்செல்வம் உற்றக் கடை.', transliteration: 'Edhilaar Aarath Thamarpasippar Pedhai Perunjelvam Utrak Katai', english_meaning: 'If a fool happens to get an immense fortune, his neighbours will enjoy it while his relations starve', career_application: 'If a fool happens to get an immense fortune, his neighbours will enjoy it while his relations starve', chapter: 'Folly' },
  { id: 838, kural_number: 838, tamil_text: 'மையல் ஒருவன் களித்தற்றால் பேதைதன் கையொன்று உடைமை பெறின்.', transliteration: 'Maiyal Oruvan Kaliththatraal Pedhaidhan Kaiyondru Utaimai Perin', english_meaning: 'A fool happening to possess something is like the intoxication of one who is (already) giddy', career_application: 'A fool happening to possess something is like the intoxication of one who is (already) giddy', chapter: 'Folly' },
  { id: 839, kural_number: 839, tamil_text: 'பெரிதினிது பேதையார் கேண்மை பிரிவின்கண் பீழை தருவதொன் றில்.', transliteration: 'Peridhinidhu Pedhaiyaar Kenmai Pirivinkan Peezhai Tharuvadhon Ril', english_meaning: 'The friendship between fools is exceedingly delightful (to each other): for at parting there will be', career_application: 'The friendship between fools is exceedingly delightful (to each other): for at parting there will be', chapter: 'Folly' },
  { id: 840, kural_number: 840, tamil_text: 'கழாஅக்கால் பள்ளியுள் வைத்தற்றால் சான்றோர் குழாஅத்துப் பேதை புகல்.', transliteration: 'Kazhaaakkaal Palliyul Vaiththatraal Saandror Kuzhaaaththup Pedhai Pukal', english_meaning: 'The appearance of a fool in an assembly of the learned is like placing (one\'s) unwashed feet on a bed', career_application: 'The appearance of a fool in an assembly of the learned is like placing (one\'s) unwashed feet on a bed', chapter: 'Folly' },
  { id: 841, kural_number: 841, tamil_text: 'அறிவின்மை இன்மையுள் இன்மை பிறிதின்மை இன்மையா வையா துலகு.', transliteration: 'Arivinmai Inmaiyul Inmai Piridhinmai Inmaiyaa Vaiyaa Thulaku', english_meaning: 'The want of wisdom is the greatest of all wants; but that of wealth the world will not regard as such', career_application: 'The want of wisdom is the greatest of all wants; but that of wealth the world will not regard as such', chapter: 'Ignorance' },
  { id: 842, kural_number: 842, tamil_text: 'அறிவிலான் நெஞ்சுவந்து ஈதல் பிறிதியாதும் இல்லை பெறுவான் தவம்.', transliteration: 'Arivilaan Nenjuvandhu Eedhal Piridhiyaadhum Illai Peruvaan Thavam', english_meaning: '(The cause of) a fool cheerfully giving (something) is nothing else but the receiver\'s merit (in a former birth)', career_application: '(The cause of) a fool cheerfully giving (something) is nothing else but the receiver\'s merit (in a former birth)', chapter: 'Ignorance' },
  { id: 843, kural_number: 843, tamil_text: 'அறிவிலார் தாந்தம்மைப் பீழிக்கும் பீழை செறுவார்க்கும் செய்தல் அரிது.', transliteration: 'Arivilaar Thaandhammaip Peezhikkum Peezhai Seruvaarkkum Seydhal Aridhu', english_meaning: 'The suffering that fools inflict upon themselves is hardly possible even to foes', career_application: 'The suffering that fools inflict upon themselves is hardly possible even to foes', chapter: 'Ignorance' },
  { id: 844, kural_number: 844, tamil_text: 'வெண்மை எனப்படுவ தியாதெனின் ஒண்மை உடையம்யாம் என்னும் செருக்கு.', transliteration: 'Venmai Enappatuva Thiyaadhenin Onmai Utaiyamyaam Ennum Serukku', english_meaning: 'What is called want of wisdom is the vanity which says, "We are wise"', career_application: 'What is called want of wisdom is the vanity which says, "We are wise"', chapter: 'Ignorance' },
  { id: 845, kural_number: 845, tamil_text: 'கல்லாத மேற்கொண் டொழுகல் கசடற வல்லதூஉம் ஐயம் தரும்.', transliteration: 'Kallaadha Merkon Tozhukal Kasatara Valladhooum Aiyam Tharum', english_meaning: 'Fools pretending to know what has not been read (by them) will rouse suspicion even as to what they have thoroughly mastered', career_application: 'Fools pretending to know what has not been read (by them) will rouse suspicion even as to what they have thoroughly mastered', chapter: 'Ignorance' },
  { id: 846, kural_number: 846, tamil_text: 'அற்றம் மறைத்தலோ புல்லறிவு தம்வயின் குற்றம் மறையா வழி.', transliteration: 'Atram Maraiththalo Pullarivu Thamvayin Kutram Maraiyaa Vazhi', english_meaning: 'Even to cover one\'s nakedness would be folly, if (one\'s) faults were not covered (by forsaking them)', career_application: 'Even to cover one\'s nakedness would be folly, if (one\'s) faults were not covered (by forsaking them)', chapter: 'Ignorance' },
  { id: 847, kural_number: 847, tamil_text: 'அருமறை சோரும் அறிவிலான் செய்யும் பெருமிறை தானே தனக்கு.', transliteration: 'Arumarai Sorum Arivilaan Seyyum Perumirai Thaane Thanakku', english_meaning: 'The fool who neglects precious counsel does, of his own accord, a great injury to himself', career_application: 'The fool who neglects precious counsel does, of his own accord, a great injury to himself', chapter: 'Ignorance' },
  { id: 848, kural_number: 848, tamil_text: 'ஏவவும் செய்கலான் தான்தேறான் அவ்வுயிர் போஒம் அளவுமோர் நோய்.', transliteration: 'Evavum Seykalaan Thaandheraan Avvuyir Poom Alavumor Noi', english_meaning: 'The fool will not perform (his duties) even when advised nor ascertain them himself; such a soul is a', career_application: 'The fool will not perform (his duties) even when advised nor ascertain them himself; such a soul is a', chapter: 'Ignorance' },
  { id: 849, kural_number: 849, tamil_text: 'காணாதான் காட்டுவான் தான்காணான் காணாதான் கண்டானாம் தான்கண்ட வாறு.', transliteration: 'Kaanaadhaan Kaattuvaan Thaankaanaan Kaanaadhaan Kantaanaam Thaankanta Vaaru', english_meaning: 'One who would teach a fool will (simply) betray his folly; and the fool would (still) think himself "wise in his own conceit"', career_application: 'One who would teach a fool will (simply) betray his folly; and the fool would (still) think himself "wise in his own conceit"', chapter: 'Ignorance' },
  { id: 850, kural_number: 850, tamil_text: 'உலகத்தார் உண்டென்பது இல்லென்பான் வையத்து அலகையா வைக்கப் படும்.', transliteration: 'Ulakaththaar Untenpadhu Illenpaan Vaiyaththu Alakaiyaa Vaikkap Patum', english_meaning: 'He who denies the existence of what the world believes in will be regarded as a demon on earth', career_application: 'He who denies the existence of what the world believes in will be regarded as a demon on earth', chapter: 'Ignorance' },
  { id: 851, kural_number: 851, tamil_text: 'இகலென்ப எல்லா உயிர்க்கும் பகலென்னும் பண்பின்மை பார஧க்கும் நோய்.', transliteration: 'Ikalenpa Ellaa Uyirkkum Pakalennum Panpinmai Paarikkum Noi', english_meaning: 'The disease which fosters the evil of disunion among all creatures is termed hatred by the wise', career_application: 'The disease which fosters the evil of disunion among all creatures is termed hatred by the wise', chapter: 'Hostility' },
  { id: 852, kural_number: 852, tamil_text: 'பகல்கருதிப் பற்றா செயினும் இகல்கருதி இன்னாசெய் யாமை தலை.', transliteration: 'Pakalkarudhip Patraa Seyinum Ikalkarudhi Innaasey Yaamai Thalai', english_meaning: 'Though disagreeable things may be done from (a feeling of) disunion, it is far better that nothing painful be done from (that of) hatred', career_application: 'Though disagreeable things may be done from (a feeling of) disunion, it is far better that nothing painful be done from (that of) hatred', chapter: 'Hostility' },
  { id: 853, kural_number: 853, tamil_text: 'இகலென்னும் எவ்வநோய் நீக்கின் தவலில்லாத் தாவில் விளக்கம் தரும்.', transliteration: 'Ikalennum Evvanoi Neekkin Thavalillaath Thaavil Vilakkam Tharum', english_meaning: 'To rid one-self of the distressing dtsease of hatred will bestow (on one) a never-decreasing imperishable fame', career_application: 'To rid one-self of the distressing dtsease of hatred will bestow (on one) a never-decreasing imperishable fame', chapter: 'Hostility' },
  { id: 854, kural_number: 854, tamil_text: 'இன்பத்துள் இன்பம் பயக்கும் இகலென்னும் துன்பத்துள் துன்பங் கெடின்.', transliteration: 'Inpaththul Inpam Payakkum Ikalennum Thunpaththul Thunpang Ketin', english_meaning: 'If hatred which is the greatest misery is destroyed, it will yield the greatest delight', career_application: 'If hatred which is the greatest misery is destroyed, it will yield the greatest delight', chapter: 'Hostility' },
  { id: 855, kural_number: 855, tamil_text: 'இகலெதிர் சாய்ந்தொழுக வல்லாரை யாரே மிக்லூக்கும் தன்மை யவர்.', transliteration: 'Ikaledhir Saaindhozhuka Vallaarai Yaare Mikalookkum Thanmai Yavar', english_meaning: 'Who indeed would think of conquering those who naturally shrink back from hatred ?', career_application: 'Who indeed would think of conquering those who naturally shrink back from hatred ?', chapter: 'Hostility' },
  { id: 856, kural_number: 856, tamil_text: 'இகலின் மிகலினிது என்பவன் வாழ்க்கை தவலும் கெடலும் நணித்து.', transliteration: 'Ikalin Mikalinidhu Enpavan Vaazhkkai Thavalum Ketalum Naniththu', english_meaning: 'Failure and ruin are not far from him who says it is sweet to excel in hatred', career_application: 'Failure and ruin are not far from him who says it is sweet to excel in hatred', chapter: 'Hostility' },
  { id: 857, kural_number: 857, tamil_text: 'மிகல்மேவல் மெய்ப்பொருள் காணார் இகல்மேவல் இன்னா அறிவி னவர்.', transliteration: 'Mikalmeval Meypporul Kaanaar Ikalmeval Innaa Arivi Navar', english_meaning: 'Who only know to work men woe, fulfilled of enmity', career_application: 'Who only know to work men woe, fulfilled of enmity', chapter: 'Hostility' },
  { id: 858, kural_number: 858, tamil_text: 'இகலிற்கு எதிர்சாய்தல் ஆக்கம் அதனை மிக்லூக்கின் ஊக்குமாம் கேடு.', transliteration: 'Ikalirku Edhirsaaidhal Aakkam Adhanai Mikalookkin Ookkumaam Ketu', english_meaning: 'Shrinking back from hatred will yield wealth; indulging in its increase will hasten ruin', career_application: 'Shrinking back from hatred will yield wealth; indulging in its increase will hasten ruin', chapter: 'Hostility' },
  { id: 859, kural_number: 859, tamil_text: 'இகல்காணான் ஆக்கம் வருங்கால் அதனை மிகல்காணும் கேடு தரற்கு.', transliteration: 'Ikalkaanaan Aakkam Varungaal Adhanai Mikalkaanum Ketu Thararku', english_meaning: 'At the approach of wealth one will not think of hatred (but) to secure one\'s ruin, one will look to its increase', career_application: 'At the approach of wealth one will not think of hatred (but) to secure one\'s ruin, one will look to its increase', chapter: 'Hostility' },
  { id: 860, kural_number: 860, tamil_text: 'இகலானாம் இன்னாத எல்லாம் நகலானாம் நன்னயம் என்னும் செருக்கு.', transliteration: 'Ikalaanaam Innaadha Ellaam Nakalaanaam Nannayam Ennum Serukku', english_meaning: 'All calamities are caused by hatred; but by the delight (of friendship) is caused the great wealth of good virtues', career_application: 'All calamities are caused by hatred; but by the delight (of friendship) is caused the great wealth of good virtues', chapter: 'Hostility' },
  { id: 861, kural_number: 861, tamil_text: 'வலியார்க்கு மாறேற்றல் ஓம்புக ஓம்பா மெலியார்மேல் மேக பகை.', transliteration: 'Valiyaarkku Maaretral Ompuka Ompaa Meliyaarmel Meka Pakai', english_meaning: 'Avoid offering resistance to the strong; (but) never fail to cherish enmity towards the weak', career_application: 'Avoid offering resistance to the strong; (but) never fail to cherish enmity towards the weak', chapter: 'The Might of Hatred' },
  { id: 862, kural_number: 862, tamil_text: 'அன்பிலன் ஆன்ற துணையிலன் தான்துவ்வான் என்பரியும் ஏதிலான் துப்பு.', transliteration: 'Anpilan Aandra Thunaiyilan Thaandhuvvaan Enpariyum Edhilaan Thuppu', english_meaning: 'How can he who is unloving, destitute of powerful aids, and himself without strength overcome the might of his foe ?', career_application: 'How can he who is unloving, destitute of powerful aids, and himself without strength overcome the might of his foe ?', chapter: 'The Might of Hatred' },
  { id: 863, kural_number: 863, tamil_text: 'அஞ்சும் அறியான் அமைவிலன் ஈகலான் தஞ்சம் எளியன் பகைக்கு.', transliteration: 'Anjum Ariyaan Amaivilan Eekalaan Thanjam Eliyan Pakaikku', english_meaning: 'In the estimation of foes miserably weak is he, who is timid, ignorant, unsociable and niggardly', career_application: 'In the estimation of foes miserably weak is he, who is timid, ignorant, unsociable and niggardly', chapter: 'The Might of Hatred' },
  { id: 864, kural_number: 864, tamil_text: 'நீங்கான் வெகுளி நிறையிலன் எஞ்ஞான்றும் யாங்கணும் யார்க்கும் எளிது.', transliteration: 'Neengaan Vekuli Niraiyilan Egngnaandrum Yaanganum Yaarkkum Elidhu', english_meaning: 'He who neither refrains from anger nor keeps his secrets will at all times and in all places be easily conquered by all', career_application: 'He who neither refrains from anger nor keeps his secrets will at all times and in all places be easily conquered by all', chapter: 'The Might of Hatred' },
  { id: 865, kural_number: 865, tamil_text: 'வழிநோக்கான் வாய்ப்பன செய்யான் பழிநோக்கான் பண்பிலன் பற்றார்க்கு இனிது.', transliteration: 'Vazhinokkaan Vaaippana Seyyaan Pazhinokkaan Panpilan Patraarkku Inidhu', english_meaning: '(A) pleasing (object) to his foes is he who reads not moral works, does nothing that is enjoined by them cares not for reproach and is not possessed of good qualities', career_application: '(A) pleasing (object) to his foes is he who reads not moral works, does nothing that is enjoined by them cares not for reproach and is not possessed of good qualities', chapter: 'The Might of Hatred' },
  { id: 866, kural_number: 866, tamil_text: 'காணாச் சினத்தான் கழிபெருங் காமத்தான் பேணாமை பேணப் படும்.', transliteration: 'Kaanaach Chinaththaan Kazhiperung Kaamaththaan Penaamai Penap Patum', english_meaning: 'Highly to be desired is the hatred of him whose anger is blind, and whose lust increases beyond measure', career_application: 'Highly to be desired is the hatred of him whose anger is blind, and whose lust increases beyond measure', chapter: 'The Might of Hatred' },
  { id: 867, kural_number: 867, tamil_text: 'கொடுத்தும் கொளல்வேண்டும் மன்ற அடுத்திருந்து மாணாத செய்வான் பகை.', transliteration: 'Kotuththum Kolalventum Mandra Atuththirundhu Maanaadha Seyvaan Pakai', english_meaning: 'It is indeed necessary to obtain even by purchase the hatred of him who having begun (a work) does what is not conductive (to its accomplishment)', career_application: 'It is indeed necessary to obtain even by purchase the hatred of him who having begun (a work) does what is not conductive (to its accomplishment)', chapter: 'The Might of Hatred' },
  { id: 868, kural_number: 868, tamil_text: 'குணனிலனாய்க் குற்றம் பலவாயின் மாற்றார்க்கு இனனிலனாம் ஏமாப் புடைத்து.', transliteration: 'Kunanilanaaik Kutram Palavaayin Maatraarkku Inanilanaam Emaap Putaiththu', english_meaning: 'He will become friendless who is without (any good) qualities and whose faults are many; (such a character) is a help to (his) foes', career_application: 'He will become friendless who is without (any good) qualities and whose faults are many; (such a character) is a help to (his) foes', chapter: 'The Might of Hatred' },
  { id: 869, kural_number: 869, tamil_text: 'செறுவார்க்குச் சேணிகவா இன்பம் அறிவிலா அஞ்சும் பகைவர்ப் பெறின்.', transliteration: 'Seruvaarkkuch Chenikavaa Inpam Arivilaa Anjum Pakaivarp Perin', english_meaning: 'There will be no end of lofty delights to the victorious, if their foes are (both) ignorant and timid', career_application: 'There will be no end of lofty delights to the victorious, if their foes are (both) ignorant and timid', chapter: 'The Might of Hatred' },
  { id: 870, kural_number: 870, tamil_text: 'கல்லான் வெகுளும் சிறுபொருள் எஞ்ஞான்றும் ஒல்லானை ஒல்லா தொளி.', transliteration: 'Kallaan Vekulum Siruporul Egngnaandrum Ollaanai Ollaa Tholi', english_meaning: 'The light (of fame) will never be gained by him who gains not the trifling reputation of having fought an unlearned (foe)', career_application: 'The light (of fame) will never be gained by him who gains not the trifling reputation of having fought an unlearned (foe)', chapter: 'The Might of Hatred' },
  { id: 871, kural_number: 871, tamil_text: 'பகைஎன்னும் பண்பி லதனை ஒருவன் நகையேயும் வேண்டற்பாற்று அன்று.', transliteration: 'Pakaiennum Panpi Ladhanai Oruvan Nakaiyeyum Ventarpaatru Andru', english_meaning: 'The evil of hatred is not of a nature to be desired by one even in sport', career_application: 'The evil of hatred is not of a nature to be desired by one even in sport', chapter: 'Knowing the Quality of Hate' },
  { id: 872, kural_number: 872, tamil_text: 'வில்லேர் உழவர் பகைகொளினும் கொள்ளற்க சொல்லேர் உழவர் பகை.', transliteration: 'Viller Uzhavar Pakaikolinum Kollarka Soller Uzhavar Pakai', english_meaning: 'Though you may incur the hatred of warriors whose ploughs are bows, incur not that of ministers whose ploughs are words', career_application: 'Though you may incur the hatred of warriors whose ploughs are bows, incur not that of ministers whose ploughs are words', chapter: 'Knowing the Quality of Hate' },
  { id: 873, kural_number: 873, tamil_text: 'ஏமுற் றவரினும் ஏழை தமியனாய்ப் பல்லார் பகைகொள் பவன்.', transliteration: 'Emur Ravarinum Ezhai Thamiyanaaip Pallaar Pakaikol Pavan', english_meaning: 'He who being alone, incurs the hatred of many is more infatuated than even mad men', career_application: 'He who being alone, incurs the hatred of many is more infatuated than even mad men', chapter: 'Knowing the Quality of Hate' },
  { id: 874, kural_number: 874, tamil_text: 'பகைநட்பாக் கொண்டொழுகும் பண்புடை யாளன் தகைமைக்கண் தங்கிற்று உலகு.', transliteration: 'Pakainatpaak Kontozhukum Panputai Yaalan Thakaimaikkan Thangitru Ulaku', english_meaning: 'Whose worthy rule can change his foes to friends', career_application: 'Whose worthy rule can change his foes to friends', chapter: 'Knowing the Quality of Hate' },
  { id: 875, kural_number: 875, tamil_text: 'தன்துணை இன்றால் பகையிரண்டால் தான்ஒருவன் இன்துணையாக் கொள்கவற்றின் ஒன்று.', transliteration: 'Thandhunai Indraal Pakaiyirantaal Thaanoruvan Indhunaiyaak Kolkavatrin Ondru', english_meaning: 'He who is alone and helpless while his foes are two should secure one of them as an agreeable help (to himself)', career_application: 'He who is alone and helpless while his foes are two should secure one of them as an agreeable help (to himself)', chapter: 'Knowing the Quality of Hate' },
  { id: 876, kural_number: 876, tamil_text: 'தேறினும் தேறா விடினும் அழிவின்கண் தேறான் பகாஅன் விடல்.', transliteration: 'Thera�num Theraa Vitinum Azhivinkan Theraan Pakaaan Vital', english_meaning: 'Though (one\'s foe is) aware or not of one\'s misfortune one should act so as neither to join nor separate (from him)', career_application: 'Though (one\'s foe is) aware or not of one\'s misfortune one should act so as neither to join nor separate (from him)', chapter: 'Knowing the Quality of Hate' },
  { id: 877, kural_number: 877, tamil_text: 'நோவற்க நொந்தது அறியார்க்கு மேவற்க மென்மை பகைவர் அகத்து.', transliteration: 'Novarka Nondhadhu Ariyaarkku Mevarka Menmai Pakaivar Akaththu', english_meaning: 'Relate not your suffering even to friends who are ignorant of it, nor refer to your weakness in the presence of your foes', career_application: 'Relate not your suffering even to friends who are ignorant of it, nor refer to your weakness in the presence of your foes', chapter: 'Knowing the Quality of Hate' },
  { id: 878, kural_number: 878, tamil_text: 'வகையறிந்து தற்செய்து தற்காப்ப மாயும் பகைவர்கண் பட்ட செருக்கு.', transliteration: 'Vakaiyarindhu Tharseydhu Tharkaappa Maayum Pakaivarkan Patta Serukku', english_meaning: 'The joy of one\'s foes will be destroyed if one guards oneself by knowing the way (of acting) and securing assistance', career_application: 'The joy of one\'s foes will be destroyed if one guards oneself by knowing the way (of acting) and securing assistance', chapter: 'Knowing the Quality of Hate' },
  { id: 879, kural_number: 879, tamil_text: 'இளைதாக முள்மரம் கொல்க களையுநர் கைகொல்லும் காழ்த்த இடத்து.', transliteration: 'Ilaidhaaka Mulmaram Kolka Kalaiyunar Kaikollum Kaazhththa Itaththu', english_meaning: 'A thorny tree should be felled while young, (for) when it is grown it will destroy the hand of the feller', career_application: 'A thorny tree should be felled while young, (for) when it is grown it will destroy the hand of the feller', chapter: 'Knowing the Quality of Hate' },
  { id: 880, kural_number: 880, tamil_text: 'உயிர்ப்ப உளரல்லர் மன்ற செயிர்ப்பவர் செம்மல் சிதைக்கலா தார்.', transliteration: 'Uyirppa Ularallar Mandra Seyirppavar Semmal Sidhaikkalaa Thaar', english_meaning: 'Those who do not destroy the pride of those who hate (them) will certainly not exist even to breathe', career_application: 'Those who do not destroy the pride of those who hate (them) will certainly not exist even to breathe', chapter: 'Knowing the Quality of Hate' },
  { id: 881, kural_number: 881, tamil_text: 'நிழல்நீரும் இன்னாத இன்னா தமர்நீரும் இன்னாவாம் இன்னா செயின்.', transliteration: 'Nizhalneerum Innaadha Innaa Thamarneerum Innaavaam Innaa Seyin', english_meaning: 'Shade and water are not pleasant, (if) they cause disease; so are the qualities of (one\'s) relations not agreeable, (if) they cause pain', career_application: 'Shade and water are not pleasant, (if) they cause disease; so are the qualities of (one\'s) relations not agreeable, (if) they cause pain', chapter: 'Enmity within' },
  { id: 882, kural_number: 882, tamil_text: 'வாள்போல பகைவரை அஞ்சற்க அஞ்சுக கேள்போல் பகைவர் தொடர்பு.', transliteration: 'Vaalpola Pakaivarai Anjarka Anjuka Kelpol Pakaivar Thotarpu', english_meaning: 'Fear not foes (who say they would cut) like a sword; (but) fear the friendship of foes (who seemingly', career_application: 'Fear not foes (who say they would cut) like a sword; (but) fear the friendship of foes (who seemingly', chapter: 'Enmity within' },
  { id: 883, kural_number: 883, tamil_text: 'உட்பகை அஞ்சித்தற் காக்க உலைவிடத்து மட்பகையின் மாணத் தெறும்.', transliteration: 'Utpakai Anjiththar Kaakka Ulaivitaththu Matpakaiyin Maanath Therum', english_meaning: 'Fear internal enmity and guard yourself; (if not) it will destroy (you) in an evil hour, as surely as the tool which cuts the potter\'s clay', career_application: 'Fear internal enmity and guard yourself; (if not) it will destroy (you) in an evil hour, as surely as the tool which cuts the potter\'s clay', chapter: 'Enmity within' },
  { id: 884, kural_number: 884, tamil_text: 'மனமாணா உட்பகை தோன்றின் இனமாணா ஏதம் பலவும் தரும்.', transliteration: 'Manamaanaa Utpakai Thondrin Inamaanaa Edham Palavum Tharum', english_meaning: 'The secret enmity of a person whose mind in unreformed will lead to many evils causing disaffection among (one\'s) relations', career_application: 'The secret enmity of a person whose mind in unreformed will lead to many evils causing disaffection among (one\'s) relations', chapter: 'Enmity within' },
  { id: 885, kural_number: 885, tamil_text: 'உறல்முறையான் உட்பகை தோன்றின் இறல்முறையான் ஏதம் பலவும் தரும்.', transliteration: 'Uralmuraiyaan Utpakai Thondrin Iralmuraiyaan Edham Palavum Tharum', english_meaning: 'If there appears internal hatred in a (king\'s) family; it will lead to many a fatal crime', career_application: 'If there appears internal hatred in a (king\'s) family; it will lead to many a fatal crime', chapter: 'Enmity within' },
  { id: 886, kural_number: 886, tamil_text: 'ஒன்றாமை ஒன்றியார் கட்படின் எஞ்ஞான்றும் பொன்றாமை ஒன்றல் அரிது.', transliteration: 'Ondraamai Ondriyaar Katpatin Egngnaandrum Pondraamai Ondral Aridhu', english_meaning: 'If hatred arises among (one\'s) own people, it will be hardly possible (for one) to escape death', career_application: 'If hatred arises among (one\'s) own people, it will be hardly possible (for one) to escape death', chapter: 'Enmity within' },
  { id: 887, kural_number: 887, tamil_text: 'செப்பின் புணர்ச்சிபோல் கூடினும் கூடாதே உட்பகை உற்ற குடி.', transliteration: 'Seppin Punarchchipol Kootinum Kootaadhe Utpakai Utra Kuti', english_meaning: 'Never indeed will a family subject to internal hatred unite (really) though it may present an apparent union like that of a casket and its lid', career_application: 'Never indeed will a family subject to internal hatred unite (really) though it may present an apparent union like that of a casket and its lid', chapter: 'Enmity within' },
  { id: 888, kural_number: 888, tamil_text: 'அரம்பொருத பொன்போலத் தேயும் உரம்பொருது உட்பகை உற்ற குடி.', transliteration: 'Aramporudha Ponpolath Theyum Uramporudhu Utpakai Utra Kuti', english_meaning: 'A family subject to internal hatred will wear out and lose its strength like iron that has been filed away', career_application: 'A family subject to internal hatred will wear out and lose its strength like iron that has been filed away', chapter: 'Enmity within' },
  { id: 889, kural_number: 889, tamil_text: 'எட்பக வன்ன சிறுமைத்தே ஆயினும் உட்பகை உள்ளதாங் கேடு.', transliteration: 'Etpaka Vanna Sirumaiththe Aayinum Utpakai Ulladhaang Ketu', english_meaning: 'Although internal hatred be as small as the fragment of the sesamum (seed), still does destruction dwell in it', career_application: 'Although internal hatred be as small as the fragment of the sesamum (seed), still does destruction dwell in it', chapter: 'Enmity within' },
  { id: 890, kural_number: 890, tamil_text: 'உடம்பாடு இலாதவர் வாழ்க்கை குடங்கருள் பாம்போடு உடனுறைந் தற்று.', transliteration: 'Utampaatu Ilaadhavar Vaazhkkai Kutangarul Paampotu Utanurain Thatru', english_meaning: 'Living with those who do not agree (with one) is like dwelling with a cobra (in the same) hut', career_application: 'Living with those who do not agree (with one) is like dwelling with a cobra (in the same) hut', chapter: 'Enmity within' },
  { id: 891, kural_number: 891, tamil_text: 'ஆற்றுவார் ஆற்றல் இகழாமை போற்றுவார் போற்றலுள் எல்லாம் தலை.', transliteration: 'Aatruvaar Aatral Ikazhaamai Potruvaar Potralul Ellaam Thalai', english_meaning: 'Not to disregard the power of those who can carry out (their wishes) is more important than all the watchfulness of those who guard (themselves against evil)', career_application: 'Not to disregard the power of those who can carry out (their wishes) is more important than all the watchfulness of those who guard (themselves against evil)', chapter: 'Not Offending the Great' },
  { id: 892, kural_number: 892, tamil_text: 'பெரியாரைப் பேணாது ஒழுகிற் பெரியாரால் பேரா இடும்பை தரும்.', transliteration: 'Periyaaraip Penaadhu Ozhukir Periyaaraal Peraa Itumpai Tharum', english_meaning: 'To behave without respect for the great (rulers) will make them do (us) irremediable evils', career_application: 'To behave without respect for the great (rulers) will make them do (us) irremediable evils', chapter: 'Not Offending the Great' },
  { id: 893, kural_number: 893, tamil_text: 'கெடல்வேண்டின் கேளாது செய்க அடல்வேண்டின் ஆற்று பவர்கண் இழுக்கு.', transliteration: 'Ketalventin Kelaadhu Seyka Atalventin Aatru Pavarkan Izhukku', english_meaning: 'If a person desires ruin, let him not listen to the righteous dictates of law, but commit crimes against those who are able to slay (other sovereigns)', career_application: 'If a person desires ruin, let him not listen to the righteous dictates of law, but commit crimes against those who are able to slay (other sovereigns)', chapter: 'Not Offending the Great' },
  { id: 894, kural_number: 894, tamil_text: 'கூற்றத்தைக் கையால் விளித்தற்றால் ஆற்றுவார்க்கு ஆற்றாதார் இன்னா செயல்.', transliteration: 'Kootraththaik Kaiyaal Viliththatraal Aatruvaarkku Aatraadhaar Innaa Seyal', english_meaning: 'The weak doing evil to the strong is like beckoning Yama to come (and destroy them)', career_application: 'The weak doing evil to the strong is like beckoning Yama to come (and destroy them)', chapter: 'Not Offending the Great' },
  { id: 895, kural_number: 895, tamil_text: 'யாண்டுச்சென்று யாண்டும் உளராகார் வெந்துப்பின் வேந்து செறப்பட் டவர்.', transliteration: 'Yaantuch Chendru Yaantum Ularaakaar Vendhuppin Vendhu Serappat Tavar', english_meaning: 'Those who have incurred the wrath of a cruel and mighty potentate will not prosper wherever they may go', career_application: 'Those who have incurred the wrath of a cruel and mighty potentate will not prosper wherever they may go', chapter: 'Not Offending the Great' },
  { id: 896, kural_number: 896, tamil_text: 'எரியால் சுடப்படினும் உய்வுண்டாம் உய்யார் பெரியார்ப் பிழைத்தொழுகு வார்.', transliteration: 'Eriyaal Sutappatinum Uyvuntaam Uyyaar Periyaarp Pizhaiththozhuku Vaar', english_meaning: 'Though burnt by a fire (from a forest), one may perhaps live; (but) never will he live who has shown disrespect to the great (devotees)', career_application: 'Though burnt by a fire (from a forest), one may perhaps live; (but) never will he live who has shown disrespect to the great (devotees)', chapter: 'Not Offending the Great' },
  { id: 897, kural_number: 897, tamil_text: 'வகைமாண்ட வாழ்க்கையும் வான்பொருளும் என்னாம் தகைமாண்ட தக்கார் செறின்.', transliteration: 'Vakaimaanta Vaazhkkaiyum Vaanporulum Ennaam Thakaimaanta Thakkaar Serin', english_meaning: 'If a king incurs the wrath of the righteous great, what will become of his government with its splendid auxiliaries and (all) its untold wealth ?', career_application: 'If a king incurs the wrath of the righteous great, what will become of his government with its splendid auxiliaries and (all) its untold wealth ?', chapter: 'Not Offending the Great' },
  { id: 898, kural_number: 898, tamil_text: 'குன்றன்னார் குன்ற மதிப்பின் குடியொடு நின்றன்னார் மாய்வர் நிலத்து.', transliteration: 'Kundrannaar Kundra Madhippin Kutiyotu Nindrannaar Maaivar Nilaththu', english_meaning: 'If (the) hill-like (devotees) resolve on destruction, those who seemed to be everlasting will be destroyed root and branch from the earth', career_application: 'If (the) hill-like (devotees) resolve on destruction, those who seemed to be everlasting will be destroyed root and branch from the earth', chapter: 'Not Offending the Great' },
  { id: 899, kural_number: 899, tamil_text: 'ஏந்திய கொள்கையார் சீறின் இடைமுரிந்து வேந்தனும் வேந்து கெடும்.', transliteration: 'Endhiya Kolkaiyaar Seerin Itaimurindhu Vendhanum Vendhu Ketum', english_meaning: 'Kings even fall from high estate and perish in the flame', career_application: 'Kings even fall from high estate and perish in the flame', chapter: 'Not Offending the Great' },
  { id: 900, kural_number: 900, tamil_text: 'இறந்தமைந்த சார்புடையர் ஆயினும் உய்யார் சிறந்தமைந்த சீரார் செறின்.', transliteration: 'Irandhamaindha Saarputaiyar Aayinum Uyyaar Sirandhamaindha Seeraar Serin', english_meaning: 'Though in possession of numerous auxiliaries, they will perish who are-exposed to the wrath of the noble whose penance is boundless', career_application: 'Though in possession of numerous auxiliaries, they will perish who are-exposed to the wrath of the noble whose penance is boundless', chapter: 'Not Offending the Great' },
  { id: 901, kural_number: 901, tamil_text: 'மனைவிழைவார் மாண்பயன் எய்தார் வினைவிழையார் வேண்டாப் பொருளும் அது.', transliteration: 'Manaivizhaivaar Maanpayan Eydhaar Vinaivizhaiyaar Ventaap Porulum Adhu', english_meaning: 'Those who lust after their wives will not attain the excellence of virtue; and it is just this that is not desired by those who are bent on acquiring wealth', career_application: 'Those who lust after their wives will not attain the excellence of virtue; and it is just this that is not desired by those who are bent on acquiring wealth', chapter: 'Being led by Women' },
  { id: 902, kural_number: 902, tamil_text: 'பேணாது பெண்விழைவான் ஆக்கம் பெரியதோர் நாணாக நாணுத் தரும்.', transliteration: 'Penaadhu Penvizhaivaan Aakkam Periyadhor Naanaaka Naanuth Tharum', english_meaning: 'The wealth of him who, regardless (of his manliness), devotes himself to his wife\'s feminine nature will cause great shame (to ali men) and to himself;', career_application: 'The wealth of him who, regardless (of his manliness), devotes himself to his wife\'s feminine nature will cause great shame (to ali men) and to himself;', chapter: 'Being led by Women' },
  { id: 903, kural_number: 903, tamil_text: 'இல்லாள்கண் தாழ்ந்த இயல்பின்மை எஞ்ஞான்றும் நல்லாருள் நாணுத் தரும்.', transliteration: 'Illaalkan Thaazhndha Iyalpinmai Egngnaandrum Nallaarul Naanuth Tharum', english_meaning: 'The frailty that stoops to a wife will always make (her husband) feel ashamed among the good', career_application: 'The frailty that stoops to a wife will always make (her husband) feel ashamed among the good', chapter: 'Being led by Women' },
  { id: 904, kural_number: 904, tamil_text: 'மனையாளை அஞ்சும் மறுமையி லாளன் வினையாண்மை வீறெய்த லின்று.', transliteration: 'Manaiyaalai Anjum Marumaiyi Laalan Vinaiyaanmai Veereydha Lindru', english_meaning: 'The undertaking of one, who fears his wife and is therefore destitute of (bliss), will never be applauded', career_application: 'The undertaking of one, who fears his wife and is therefore destitute of (bliss), will never be applauded', chapter: 'Being led by Women' },
  { id: 905, kural_number: 905, tamil_text: 'இல்லாளை அஞ்சுவான் அஞ்சுமற் றெஞ்ஞான்றும் நல்லார்க்கு நல்ல செயல்.', transliteration: 'Illaalai Anjuvaan Anjumar Regngnaandrum Nallaarkku Nalla Seyal', english_meaning: 'He that fears his wife will always be afraid of doing good deeds (even) to the good', career_application: 'He that fears his wife will always be afraid of doing good deeds (even) to the good', chapter: 'Being led by Women' },
  { id: 906, kural_number: 906, tamil_text: 'இமையாரின் வாழினும் பாடிலரே இல்லாள் அமையார்தோள் அஞ்சு பவர்.', transliteration: 'Imaiyaarin Vaazhinum Paatilare Illaal Amaiyaardhol Anju Pavar', english_meaning: 'They that fear the bamboo-like shoulders of their wives will be destitute of manliness though they may flourish like the Gods', career_application: 'They that fear the bamboo-like shoulders of their wives will be destitute of manliness though they may flourish like the Gods', chapter: 'Being led by Women' },
  { id: 907, kural_number: 907, tamil_text: 'பெண்ணேவல் செய்தொழுகும் ஆண்மையின் நாணுடைப் பெண்ணே பெருமை உடைத்து.', transliteration: 'Penneval Seydhozhukum Aanmaiyin Naanutaip Penne Perumai Utaiththu', english_meaning: 'Even shame faced womanhood is more to be esteemed than the shameless manhood that performs', career_application: 'Even shame faced womanhood is more to be esteemed than the shameless manhood that performs', chapter: 'Being led by Women' },
  { id: 908, kural_number: 908, tamil_text: 'நட்டார் குறைமுடியார் நன்றாற்றார் நன்னுதலாள் பெட் டாங்கு ஒழுகு பவர்.', transliteration: 'Nattaar Kuraimutiyaar Nandraatraar Nannudhalaal Pettaangu Ozhuku Pavar', english_meaning: 'Those who yield to the wishes of their wives will neither relieve the wants of (their) friends nor perform virtuous deeds', career_application: 'Those who yield to the wishes of their wives will neither relieve the wants of (their) friends nor perform virtuous deeds', chapter: 'Being led by Women' },
  { id: 909, kural_number: 909, tamil_text: 'அறவினையும் ஆன்ற பொருளும் பிறவினையும் பெண்ஏவல் செய்வார்கண் இல்.', transliteration: 'Aravinaiyum Aandra Porulum Piravinaiyum Peneval Seyvaarkan Il', english_meaning: 'From those who obey the commands of their wives are to be expected neither deeds of virtue, nor those of wealth nor (even) those of pleasure', career_application: 'From those who obey the commands of their wives are to be expected neither deeds of virtue, nor those of wealth nor (even) those of pleasure', chapter: 'Being led by Women' },
  { id: 910, kural_number: 910, tamil_text: 'எண்சேர்ந்த நெஞ்சத் திடனுடையார்க்கு எஞ்ஞான்றும் பெண்சேர்ந்தாம் பேதைமை இல்.', transliteration: 'Enserndha Nenjath Thitanutaiyaarkku Egngnaandrum Penserndhaam Pedhaimai Il', english_meaning: 'The foolishness that results from devotion to a wife will never be found in those who possess a reflecting mind and a prosperity (flowing) therefrom', career_application: 'The foolishness that results from devotion to a wife will never be found in those who possess a reflecting mind and a prosperity (flowing) therefrom', chapter: 'Being led by Women' },
  { id: 911, kural_number: 911, tamil_text: 'அன்பின் விழையார் பொருள்விழையும் ஆய்தொடியார் இன்சொல் இழுக்குத் தரும்.', transliteration: 'Anpin Vizhaiyaar Porulvizhaiyum Aaidhotiyaar Insol Izhukkuth Tharum', english_meaning: 'The sweet words of elegant braceleted (prostitutes) who desire (a man) not from affection but from avarice, will cause sorrow', career_application: 'The sweet words of elegant braceleted (prostitutes) who desire (a man) not from affection but from avarice, will cause sorrow', chapter: 'Wanton Women' },
  { id: 912, kural_number: 912, tamil_text: 'பயன்தூக்கிப் பண்புரைக்கும் பண்பின் மகளிர் நயன்தூக்கி நள்ளா விடல்.', transliteration: 'Payandhookkip Panpuraikkum Panpin Makalir Nayandhookki Nallaa Vital', english_meaning: 'One must ascertain the character of the ill-natured women who after ascertaining the wealth (of a man) speak (as if they were) good natured-ones, and avoid intercourse (with them)', career_application: 'One must ascertain the character of the ill-natured women who after ascertaining the wealth (of a man) speak (as if they were) good natured-ones, and avoid intercourse (with them)', chapter: 'Wanton Women' },
  { id: 913, kural_number: 913, tamil_text: 'பொருட்பெண்டிர் பொய்ம்மை முயக்கம் இருட்டறையில் ஏத஧ல் பிணந்தழீஇ அற்று.', transliteration: 'Porutpentir Poimmai Muyakkam Iruttaraiyil Edhil Pinandhazheei Atru', english_meaning: 'The false embraces of wealth-loving women are like (hired men) embracing a strange corpse in a dark room', career_application: 'The false embraces of wealth-loving women are like (hired men) embracing a strange corpse in a dark room', chapter: 'Wanton Women' },
  { id: 914, kural_number: 914, tamil_text: 'பொருட்பொருளார் புன்னலந் தோயார் அருட்பொருள் ஆயும் அறிவி னவர்.', transliteration: 'Porutporulaar Punnalan Thoyaar Arutporul Aayum Arivi Navar', english_meaning: 'The wise who seek the wealth of grace will not desire the base favours of those who regard wealth (and not pleasure) as (their) riches', career_application: 'The wise who seek the wealth of grace will not desire the base favours of those who regard wealth (and not pleasure) as (their) riches', chapter: 'Wanton Women' },
  { id: 915, kural_number: 915, tamil_text: 'பொதுநலத்தார் புன்னலம் தோயார் மதிநலத்தின் மாண்ட அறிவி னவர்.', transliteration: 'Podhunalaththaar Punnalam Thoyaar Madhinalaththin Maanta Arivi Navar', english_meaning: 'Those whose knowledge is made excellent by their (natural) sense will not covet the trffling delights', career_application: 'Those whose knowledge is made excellent by their (natural) sense will not covet the trffling delights', chapter: 'Wanton Women' },
  { id: 916, kural_number: 916, tamil_text: 'தந்நலம் பாரிப்பார் தோயார் தகைசெருக்கிப் புன்னலம் பாரிப்பார் தோள்.', transliteration: 'Thannalam Paarippaar Thoyaar Thakaiserukkip Punnalam Paarippaar Thol', english_meaning: 'Those who would spread (the fame of) their own goodness will not desire the shoulders of those,who rejoice in their accomplishments and bestow their despicable favours (on all who pay)', career_application: 'Those who would spread (the fame of) their own goodness will not desire the shoulders of those,who rejoice in their accomplishments and bestow their despicable favours (on all who pay)', chapter: 'Wanton Women' },
  { id: 917, kural_number: 917, tamil_text: 'நிறைநெஞ்சம் இல்லவர் தோய்வார் பிறநெஞ்சிற் பேணிப் புணர்பவர் தோள்.', transliteration: 'Nirainenjam Illavar Thoivaar Piranenjir Penip Punarpavar Thol', english_meaning: 'Those who are destitute of a perfectly (reformed) mind will covet the shoulders of those who embrace (them) while their hearts covet other things', career_application: 'Those who are destitute of a perfectly (reformed) mind will covet the shoulders of those who embrace (them) while their hearts covet other things', chapter: 'Wanton Women' },
  { id: 918, kural_number: 918, tamil_text: 'ஆயும் அறிவினர் அல்லார்க்கு அணங்கென்ப மாய மகளிர் முயக்கு.', transliteration: 'Aayum Arivinar Allaarkku Anangenpa Maaya Makalir Muyakku', english_meaning: 'The wise say that to such as are destitute of discerning sense the embraces of faithless women are (as ruinous as those of) the celestail female', career_application: 'The wise say that to such as are destitute of discerning sense the embraces of faithless women are (as ruinous as those of) the celestail female', chapter: 'Wanton Women' },
  { id: 919, kural_number: 919, tamil_text: 'வரைவிலா மாணிழையார் மென்தோள் புரையிலாப் பூரியர்கள் ஆழும் அளறு.', transliteration: 'Varaivilaa Maanizhaiyaar Mendhol Puraiyilaap Pooriyarkal Aazhum Alaru', english_meaning: 'The delicate shoulders of prostitutes with excellent jewels are a hell into which are plunged the ignorant base', career_application: 'The delicate shoulders of prostitutes with excellent jewels are a hell into which are plunged the ignorant base', chapter: 'Wanton Women' },
  { id: 920, kural_number: 920, tamil_text: 'இருமனப் பெண்டிரும் கள்ளும் கவறும் திருநீக்கப் பட்டார் தொடர்பு.', transliteration: 'Irumanap Pentirum Kallum Kavarum Thiruneekkap Pattaar Thotarpu', english_meaning: 'Treacherous women, liquor, and gambling are the associates of such as have forsaken by Fortune', career_application: 'Treacherous women, liquor, and gambling are the associates of such as have forsaken by Fortune', chapter: 'Wanton Women' },
  { id: 921, kural_number: 921, tamil_text: 'உட்கப் படாஅர் ஒளியிழப்பர் எஞ்ஞான்றும் கட்காதல் கொண்டொழுகு வார்.', transliteration: 'Utkap Pataaar Oliyizhappar Egngnaandrum Katkaadhal Kontozhuku Vaar', english_meaning: 'Those who always thirst after drink will neither inspire fear (in others) nor retain the light (of their fame)', career_application: 'Those who always thirst after drink will neither inspire fear (in others) nor retain the light (of their fame)', chapter: 'Not Drinking Palm-Wine' },
  { id: 922, kural_number: 922, tamil_text: 'உண்ணற்க கள்ளை உணில்உண்க சான்றோரான் எண்ணப் படவேண்டா தார்.', transliteration: 'Unnarka Kallai Unilunka Saandroraan Ennap Pataventaa Thaar', english_meaning: 'Let no liquor be drunk; if it is desired, let it be drunk by those who care not for esteem of the great', career_application: 'Let no liquor be drunk; if it is desired, let it be drunk by those who care not for esteem of the great', chapter: 'Not Drinking Palm-Wine' },
  { id: 923, kural_number: 923, tamil_text: 'ஈன்றாள் முகத்தேயும் இன்னாதால் என்மற்றுச் சான்றோர் முகத்துக் களி.', transliteration: 'Eendraal Mukaththeyum Innaadhaal Enmatruch Chaandror Mukaththuk Kali', english_meaning: 'Intoxication is painful even in the presence of (one\'s) mother; what will it not then be in that of the wise ?', career_application: 'Intoxication is painful even in the presence of (one\'s) mother; what will it not then be in that of the wise ?', chapter: 'Not Drinking Palm-Wine' },
  { id: 924, kural_number: 924, tamil_text: 'நாண்என்னும் நல்லாள் புறங்கொடுக்கும் கள்ளென்னும் பேணாப் பெருங்குற்றத் தார்க்கு.', transliteration: 'Naanennum Nallaal Purangotukkum Kallennum Penaap Perungutrath Thaarkku', english_meaning: 'The fair maid of modesty will turn her back on those who are guilty of the great and abominable crime of drunkenness', career_application: 'The fair maid of modesty will turn her back on those who are guilty of the great and abominable crime of drunkenness', chapter: 'Not Drinking Palm-Wine' },
  { id: 925, kural_number: 925, tamil_text: 'கையறி யாமை உடைத்தே பொருள்கொடுத்து மெய்யறி யாமை கொளல்.', transliteration: 'Kaiyari Yaamai Utaiththe Porulkotuththu Meyyari Yaamai Kolal', english_meaning: 'To give money and purchase unconsciousness is the result of one\'s ignorance of (one\'s own actions)', career_application: 'To give money and purchase unconsciousness is the result of one\'s ignorance of (one\'s own actions)', chapter: 'Not Drinking Palm-Wine' },
  { id: 926, kural_number: 926, tamil_text: 'துஞ்சினார் செத்தாரின் வேறல்லர் எஞ்ஞான்றும் நஞ்சுண்பார் கள்ளுண் பவர்.', transliteration: 'Thunjinaar Seththaarin Verallar Egngnaandrum Nanjunpaar Kallun Pavar', english_meaning: 'They that sleep resemble the deed; (likewise) they that drink are no other than poison-eaters', career_application: 'They that sleep resemble the deed; (likewise) they that drink are no other than poison-eaters', chapter: 'Not Drinking Palm-Wine' },
  { id: 927, kural_number: 927, tamil_text: 'உள்ளொற்றி உள்ளூர் நகப்படுவர் எஞ்ஞான்றும் கள்ளொற்றிக் கண்சாய் பவர்', transliteration: 'Ullotri Ulloor Nakappatuvar Egngnaandrum Kallotrik Kansaai Pavar', english_meaning: 'Those who always intoxicate themselves by a private (indulgence in) drink; will have their secrets detected and laughed at by their fellow-townsmen', career_application: 'Those who always intoxicate themselves by a private (indulgence in) drink; will have their secrets detected and laughed at by their fellow-townsmen', chapter: 'Not Drinking Palm-Wine' },
  { id: 928, kural_number: 928, tamil_text: 'களித்தறியேன் என்பது கைவிடுக நெஞ்சத்து ஒளித்ததூஉம் ஆங்கே மிகும்.', transliteration: 'Kaliththariyen Enpadhu Kaivituka Nenjaththu Oliththadhooum Aange Mikum', english_meaning: 'Let (the drunkard) give up saying "I have never drunk"; (for) the moment (he drinks) he will simply betray his former attempt to conceal', career_application: 'Let (the drunkard) give up saying "I have never drunk"; (for) the moment (he drinks) he will simply betray his former attempt to conceal', chapter: 'Not Drinking Palm-Wine' },
  { id: 929, kural_number: 929, tamil_text: 'களித்தானைக் காரணம் காட்டுதல் கீழ்நீர்க் குளித்தானைத் தீத்துரீஇ அற்று.', transliteration: 'Kaliththaanaik Kaaranam Kaattudhal Keezhneerk Kuliththaanaith Theeththureei Atru', english_meaning: 'Reasoning with a drunkard is like going under water with a torch in search of a drowned man', career_application: 'Reasoning with a drunkard is like going under water with a torch in search of a drowned man', chapter: 'Not Drinking Palm-Wine' },
  { id: 930, kural_number: 930, tamil_text: 'கள்ளுண்ணாப் போழ்திற் களித்தானைக் காணுங்கால் உள்ளான்கொல் உண்டதன் சோர்வு.', transliteration: 'Kallunnaap Pozhdhir Kaliththaanaik Kaanungaal Ullaankol Untadhan Sorvu', english_meaning: 'When (a drunkard) who is sober sees one who is not, it looks as if he remembered not the evil effects of his (own) drink', career_application: 'When (a drunkard) who is sober sees one who is not, it looks as if he remembered not the evil effects of his (own) drink', chapter: 'Not Drinking Palm-Wine' },
  { id: 931, kural_number: 931, tamil_text: 'வேண்டற்க வென்றிடினும் சூதினை வென்றதூஉம் தூண்டிற்பொன் மீன்விழுங்கி அற்று.', transliteration: 'Ventarka Vendritinum Soodhinai Vendradhooum Thoontirpon Meenvizhungi Atru', english_meaning: 'Though able to win, let not one desire gambling; (for) even what is won is like a fish swallowing the iron in fish-hook', career_application: 'Though able to win, let not one desire gambling; (for) even what is won is like a fish swallowing the iron in fish-hook', chapter: 'Gambling' },
  { id: 932, kural_number: 932, tamil_text: 'ஒன்றெய்தி நூறிழக்கும் சூதர்க்கும் உண்டாங்கொல் நன்றெய்தி வாழ்வதோர் ஆறு.', transliteration: 'Ondreydhi Noorizhakkum Soodharkkum Untaangol Nandreydhi Vaazhvadhor Aaru', english_meaning: 'That they may good obtain, and see a prosperous day? Is there indeed a means of livelihood that can bestow happiness on gamblers who gain one and lose a hundred?', career_application: 'That they may good obtain, and see a prosperous day? Is there indeed a means of livelihood that can bestow happiness on gamblers who gain one and lose a hundred?', chapter: 'Gambling' },
  { id: 933, kural_number: 933, tamil_text: 'உருளாயம் ஓவாது கூறின் பொருளாயம் போஒய்ப் புறமே படும்.', transliteration: 'Urulaayam Ovaadhu Koorin Porulaayam Pooip Purame Patum', english_meaning: 'If the king is incessantly addicted to the rolling dice in the hope of gain, his wealth and the resources thereof will take their departure and fall into other\'s hands', career_application: 'If the king is incessantly addicted to the rolling dice in the hope of gain, his wealth and the resources thereof will take their departure and fall into other\'s hands', chapter: 'Gambling' },
  { id: 934, kural_number: 934, tamil_text: 'சிறுமை பலசெய்து சீரழக்கும் சூதின் வறுமை தருவதொன்று இல்.', transliteration: 'Sirumai Palaseydhu Seerazhikkum Soodhin Varumai Tharuvadhondru Il', english_meaning: 'There is nothing else that brings (us) poverty like gambling which causes many a misery and destroys (one\'s) reputation', career_application: 'There is nothing else that brings (us) poverty like gambling which causes many a misery and destroys (one\'s) reputation', chapter: 'Gambling' },
  { id: 935, kural_number: 935, tamil_text: 'கவறும் கழகமும் கையும் தருக்கி இவறியார் இல்லாகி யார்.', transliteration: 'Kavarum Kazhakamum Kaiyum Tharukki Ivariyaar Illaaki Yaar', english_meaning: 'Penniless are those who by reason of their attachment would never forsake gambling, the gamblingplace and the handling (of dice)', career_application: 'Penniless are those who by reason of their attachment would never forsake gambling, the gamblingplace and the handling (of dice)', chapter: 'Gambling' },
  { id: 936, kural_number: 936, tamil_text: 'அகடாரார் அல்லல் உழப்பர்சூ தென்னும் முகடியான் மூடப்பட் டார்.', transliteration: 'Akataaraar Allal Uzhapparsoo Thennum Mukatiyaan Mootappat Taar', english_meaning: 'Those who are swallowed by the goddess called "gambling" will never have their hunger satisfied, but suffer the pangs of hell in the next world', career_application: 'Those who are swallowed by the goddess called "gambling" will never have their hunger satisfied, but suffer the pangs of hell in the next world', chapter: 'Gambling' },
  { id: 937, kural_number: 937, tamil_text: 'பழகிய செல்வமும் பண்பும் கெடுக்கும் கழகத்துக் காலை புகின்.', transliteration: 'Pazhakiya Selvamum Panpum Ketukkum Kazhakaththuk Kaalai Pukin', english_meaning: 'To waste time at the place of gambling will destroy inherited wealth and goodness of character', career_application: 'To waste time at the place of gambling will destroy inherited wealth and goodness of character', chapter: 'Gambling' },
  { id: 938, kural_number: 938, tamil_text: 'பொருள்கெடுத்துப் பொய்மேற் கொளீஇ அருள்கெடுத்து அல்லல் உழப்பிக்கும் சூது.', transliteration: 'Porul Ketuththup Poimer Koleei Arulketuththu Allal Uzhappikkum Soodhu', english_meaning: 'Gambling destroys property, teaches falsehood, puts an end to benevolence, and brings in misery (here and hereafter)', career_application: 'Gambling destroys property, teaches falsehood, puts an end to benevolence, and brings in misery (here and hereafter)', chapter: 'Gambling' },
  { id: 939, kural_number: 939, tamil_text: 'உடைசெல்வம் ஊண்ஒளி கல்விஎன்று ஐந்தும் அடையாவாம் ஆயங் கொளின்.', transliteration: 'Utaiselvam Oonoli Kalviendru Aindhum Ataiyaavaam Aayang Kolin', english_meaning: 'The habit of gambling prevents the attainment of these five: clothing, wealth, food, fame and learning', career_application: 'The habit of gambling prevents the attainment of these five: clothing, wealth, food, fame and learning', chapter: 'Gambling' },
  { id: 940, kural_number: 940, tamil_text: 'இழத்தொறூஉம் காதலிக்கும் சூதேபோல் துன்பம் உழத்தொறூஉம் காதற்று உயிர்.', transliteration: 'Izhaththoru�um Kaadhalikkum Soodhepol Thunpam Uzhaththoru�um Kaadhatru Uyir', english_meaning: 'As the gambler loves (his vice) the more he loses by it, so does the soul love (the body) the more it suffers through it', career_application: 'As the gambler loves (his vice) the more he loses by it, so does the soul love (the body) the more it suffers through it', chapter: 'Gambling' },
  { id: 941, kural_number: 941, tamil_text: 'மிகினும் குறையினும் நோய்செய்யும் நூலோர் வளிமுதலா எண்ணிய மூன்று.', transliteration: 'Mikinum Kuraiyinum Noiseyyum Noolor Valimudhalaa Enniya Moondru', english_meaning: 'If (food and work are either) excessive or deficient, the three things enumerated by (medical) writers, flatulence, biliousness, and phlegm, will cause (one) disease', career_application: 'If (food and work are either) excessive or deficient, the three things enumerated by (medical) writers, flatulence, biliousness, and phlegm, will cause (one) disease', chapter: 'Medicine' },
  { id: 942, kural_number: 942, tamil_text: 'மருந்தென வேண்டாவாம் யாக்கைக்கு அருந்தியது அற்றது போற்றி உணின்.', transliteration: 'Marundhena Ventaavaam Yaakkaikku Arundhiyadhu Atradhu Potri Unin', english_meaning: 'No medicine is necessary for him who eats after assuring (himself) that what he has (already) eaten has been digested', career_application: 'No medicine is necessary for him who eats after assuring (himself) that what he has (already) eaten has been digested', chapter: 'Medicine' },
  { id: 943, kural_number: 943, tamil_text: 'அற்றால் அறவறிந்து உண்க அஃதுடம்பு பெற்றான் நெடிதுய்க்கும் ஆறு.', transliteration: 'Atraal Aravarindhu Unka Aqdhutampu Petraan Netidhuykkum Aaru', english_meaning: 'If (one\'s food has been) digested let one eat with moderation; (for) that is the way to prolong the life of an embodied soul', career_application: 'If (one\'s food has been) digested let one eat with moderation; (for) that is the way to prolong the life of an embodied soul', chapter: 'Medicine' },
  { id: 944, kural_number: 944, tamil_text: 'அற்றது அறிந்து கடைப்பிடித்து மாறல்ல துய்க்க துவரப் பசித்து.', transliteration: 'Atradhu Arindhu Kataippitiththu Maaralla Thuykka Thuvarap Pasiththu', english_meaning: '(First) assure yourself that your food has been digested and never fail to eat, when very hungry, whatever is not disagreeable (to you)', career_application: '(First) assure yourself that your food has been digested and never fail to eat, when very hungry, whatever is not disagreeable (to you)', chapter: 'Medicine' },
  { id: 945, kural_number: 945, tamil_text: 'மாறுபாடு இல்லாத உண்டி மறுத்துண்ணின் ஊறுபாடு இல்லை உயிர்க்கு.', transliteration: 'Maarupaatu Illaadha Unti Maruththunnin Oorupaatu Illai Uyirkku', english_meaning: 'There will be no disaster to one\'s life if one eats with moderation, food that is not disagreeable', career_application: 'There will be no disaster to one\'s life if one eats with moderation, food that is not disagreeable', chapter: 'Medicine' },
  { id: 946, kural_number: 946, tamil_text: 'இழிவறிந்து உண்பான்கண் இன்பம்போல் நிற்கும் கழிபேர் இரையான்கண் நோய்.', transliteration: 'Izhivarindhu Unpaankan Inpampol Nirkum Kazhiper Iraiyaankan Noi', english_meaning: 'As pleasure dwells with him who eats moderately, so disease (dwells) with the glutton who eats voraciously', career_application: 'As pleasure dwells with him who eats moderately, so disease (dwells) with the glutton who eats voraciously', chapter: 'Medicine' },
  { id: 947, kural_number: 947, tamil_text: 'தீயள வன்றித் தெரியான் பெரிதுண்ணின் நோயள வின்றிப் படும்.', transliteration: 'Theeyala Vandrith Theriyaan Peridhunnin Noyala Vindrip Patum', english_meaning: 'He will be afflicted with numberless diseases, who eats immoderately, ignorant (of the rules of health)', career_application: 'He will be afflicted with numberless diseases, who eats immoderately, ignorant (of the rules of health)', chapter: 'Medicine' },
  { id: 948, kural_number: 948, tamil_text: 'நோய்நாடி நோய்முதல் நாடி அதுதணிக்கும் வாய்நாடி வாய்ப்பச் செயல்.', transliteration: 'Noinaati Noimudhal Naati Adhudhanikkum Vaainaati Vaaippach Cheyal', english_meaning: 'Let the physician enquire into the (nature of the) disease, its cause and its method of cure and treat it faithfully according to (medical rule)', career_application: 'Let the physician enquire into the (nature of the) disease, its cause and its method of cure and treat it faithfully according to (medical rule)', chapter: 'Medicine' },
  { id: 949, kural_number: 949, tamil_text: 'உற்றான் அளவும் பிணியளவும் காலமும் கற்றான் கருதிச் செயல்.', transliteration: 'Utraan Alavum Piniyalavum Kaalamum Katraan Karudhich Cheyal', english_meaning: 'The learned (physician) should ascertain the condition of his patient; the nature of his disease, and the season (of the year) and (then) proceed (with his treatment)', career_application: 'The learned (physician) should ascertain the condition of his patient; the nature of his disease, and the season (of the year) and (then) proceed (with his treatment)', chapter: 'Medicine' },
  { id: 950, kural_number: 950, tamil_text: 'உற்றவன் தீர்ப்பான் மருந்துழைச் செல்வானென்று அப்பால் நாற் கூற்றே மருந்து.', transliteration: 'Utravan Theerppaan Marundhuzhaich Chelvaanendru Appaal Naar Kootre Marundhu', english_meaning: 'Medical science consists of four parts, viz, patient, physician, medicine and compounder; and each of these (again) contains four sub-divisions', career_application: 'Medical science consists of four parts, viz, patient, physician, medicine and compounder; and each of these (again) contains four sub-divisions', chapter: 'Medicine' },
  { id: 951, kural_number: 951, tamil_text: 'இற்பிறந்தார் கண்அல்லது இல்லை இயல்பாகச் செப்பமும் நாணும் ஒருங்கு.', transliteration: 'Irpirandhaar Kanalladhu Illai Iyalpaakach Cheppamum Naanum Orungu', english_meaning: 'Consistency (of thought, word and deed) and fear (of sin) are conjointly natural only to the high-born', career_application: 'Consistency (of thought, word and deed) and fear (of sin) are conjointly natural only to the high-born', chapter: 'Nobility' },
  { id: 952, kural_number: 952, tamil_text: 'ஒழுக்கமும் வாய்மையும் நாணும்இம் மூன்றும் இழுக்கார் குடிப்பிறந் தார்.', transliteration: 'Ozhukkamum Vaaimaiyum Naanum Im Moondrum Izhukkaar Kutippiran Thaar', english_meaning: 'The high-born will never deviate from these three; good manners, truthfulness and modesty', career_application: 'The high-born will never deviate from these three; good manners, truthfulness and modesty', chapter: 'Nobility' },
  { id: 953, kural_number: 953, tamil_text: 'நகைஈகை இன்சொல் இகழாமை நான்கும் வகையென்ப வாய்மைக் குடிக்கு.', transliteration: 'Nakaieekai Insol Ikazhaamai Naankum Vakaiyenpa Vaaimaik Kutikku', english_meaning: 'A cheerful countenance, liberality, pleasant words, and an unreviling disposition, these four are said to be the proper qualities of the truly high-born', career_application: 'A cheerful countenance, liberality, pleasant words, and an unreviling disposition, these four are said to be the proper qualities of the truly high-born', chapter: 'Nobility' },
  { id: 954, kural_number: 954, tamil_text: 'அடுக்கிய கோடி பெறினும் குடிப்பிறந்தார் குன்றுவ செய்தல் இலர்.', transliteration: 'Atukkiya Koti Perinum Kutippirandhaar Kundruva Seydhal Ilar', english_meaning: 'Though blessed with immense wealth, the noble will never do anything unbecoming', career_application: 'Though blessed with immense wealth, the noble will never do anything unbecoming', chapter: 'Nobility' },
  { id: 955, kural_number: 955, tamil_text: 'வழங்குவ துள்வீழ்ந்தக் கண்ணும் பழங்குடி பண்பில் தலைப்பிரிதல் இன்று.', transliteration: 'Vazhanguva Thulveezhndhak Kannum Pazhanguti Panpil Thalaippiridhal Indru', english_meaning: 'Though their means fall off, those born in ancient families, will not lose their character (for liberality)', career_application: 'Though their means fall off, those born in ancient families, will not lose their character (for liberality)', chapter: 'Nobility' },
  { id: 956, kural_number: 956, tamil_text: 'சலம்பற்றிச் சால்பில செய்யார்மா சற்ற குலம்பற்றி வாழ்தும் என் பார்.', transliteration: 'Salampatrich Chaalpila Seyyaarmaa Satra Kulampatri Vaazhdhum En Paar', english_meaning: 'Those who seek to preserve the irreproachable honour of their families will not viciously do what is detrimental thereto', career_application: 'Those who seek to preserve the irreproachable honour of their families will not viciously do what is detrimental thereto', chapter: 'Nobility' },
  { id: 957, kural_number: 957, tamil_text: 'குடிப்பிறந்தார் கண்விளங்கும் குற்றம் விசும்பின் மத஧க்கண் மறுப்போல் உயர்ந்து.', transliteration: 'Kutippirandhaar Kanvilangum Kutram Visumpin Madhikkan Maruppol Uyarndhu', english_meaning: 'As spots on her bright orb that walks sublime the evening sky', career_application: 'As spots on her bright orb that walks sublime the evening sky', chapter: 'Nobility' },
  { id: 958, kural_number: 958, tamil_text: 'நலத்தின்கண் நாரின்மை தோன்றின் அவனைக் குலத்தின்கண் ஐயப் படும்.', transliteration: 'Nalaththinkan Naarinmai Thondrin Avanaik Kulaththinkan Aiyap Patum', english_meaning: 'If one of a good family betrays want of affection, his descent from it will be called in question', career_application: 'If one of a good family betrays want of affection, his descent from it will be called in question', chapter: 'Nobility' },
  { id: 959, kural_number: 959, tamil_text: 'நிலத்தில் கிடந்தமை கால்காட்டும் காட்டும் குலத்தில் பிறந்தார்வாய்ச் சொல்.', transliteration: 'Nilaththil Kitandhamai Kaalkaattum Kaattum Kulaththil Pirandhaarvaaich Chol', english_meaning: 'As the sprout indicates the nature of the soil, (so) the speech of the noble indicates (that of one\'s birth)', career_application: 'As the sprout indicates the nature of the soil, (so) the speech of the noble indicates (that of one\'s birth)', chapter: 'Nobility' },
  { id: 960, kural_number: 960, tamil_text: 'நலம்வேண்டின் நாணுடைமை வேண்டும் குலம்வேண்டின் வேண்டுக யார்க்கும் பணிவு.', transliteration: 'Nalamventin Naanutaimai Ventum Kulam Ventin Ventuka Yaarkkum Panivu', english_meaning: 'He who desires a good name must desire modesty; and he who desires (the continuance of) a family greatness must be submissive to all', career_application: 'He who desires a good name must desire modesty; and he who desires (the continuance of) a family greatness must be submissive to all', chapter: 'Nobility' },
  { id: 961, kural_number: 961, tamil_text: 'இன்றி அமையாச் சிறப்பின ஆயினும் குன்ற வருப விடல்.', transliteration: 'Indri Amaiyaach Chirappina Aayinum Kundra Varupa Vital', english_meaning: 'Actions that would degrade (one\'s) family should not be done; though they may be so important that not doing them would end in death', career_application: 'Actions that would degrade (one\'s) family should not be done; though they may be so important that not doing them would end in death', chapter: 'Honour' },
  { id: 962, kural_number: 962, tamil_text: 'சீரினும் சீரல்ல செய்யாரே சீரொடு பேராண்மை வேண்டு பவர்.', transliteration: 'Seerinum Seeralla Seyyaare Seerotu Peraanmai Ventu Pavar', english_meaning: 'Those who desire (to maintain their) honour, will surely do nothing dishonourable, even for the sake of fame', career_application: 'Those who desire (to maintain their) honour, will surely do nothing dishonourable, even for the sake of fame', chapter: 'Honour' },
  { id: 963, kural_number: 963, tamil_text: 'பெருக்கத்து வேண்டும் பணிதல் சிறிய சுருக்கத்து வேண்டும் உயர்வு.', transliteration: 'Perukkaththu Ventum Panidhal Siriya Surukkaththu Ventum Uyarvu', english_meaning: 'In great prosperity humility is becoming; dignity, in great adversity', career_application: 'In great prosperity humility is becoming; dignity, in great adversity', chapter: 'Honour' },
  { id: 964, kural_number: 964, tamil_text: 'தலையின் இழிந்த மயிரனையர் மாந்தர் நிலையின் இழிந்தக் கடை.', transliteration: 'Thalaiyin Izhindha Mayiranaiyar Maandhar Nilaiyin Izhindhak Katai', english_meaning: 'They who have fallen from their (high) position are like the hair which has fallen from the head', career_application: 'They who have fallen from their (high) position are like the hair which has fallen from the head', chapter: 'Honour' },
  { id: 965, kural_number: 965, tamil_text: 'குன்றின் அனையாரும் குன்றுவர் குன்றுவ குன்றி அனைய செயின்.', transliteration: 'Kundrin Anaiyaarum Kundruvar Kundruva Kundri Anaiya Seyin', english_meaning: 'Even those who are exalted like a hill will be thought low, if they commit deeds that are debasing', career_application: 'Even those who are exalted like a hill will be thought low, if they commit deeds that are debasing', chapter: 'Honour' },
  { id: 966, kural_number: 966, tamil_text: 'புகழ்இன்றால் புத்தேள்நாட்டு உய்யாதால் என்மற்று இகழ்வார்பின் சென்று நிலை.', transliteration: 'Pukazhindraal Puththelnaattu Uyyaadhaal Enmatru Ikazhvaarpin Sendru Nilai', english_meaning: 'Why follow men who scorn, and at their bidding wait?', career_application: 'Why follow men who scorn, and at their bidding wait?', chapter: 'Honour' },
  { id: 967, kural_number: 967, tamil_text: 'ஒட்டார்பின் சென்றொருவன் வாழ்தலின் அந்நிலையே கெட்டான் எனப்படுதல் நன்று.', transliteration: 'Ottaarpin Sendroruvan Vaazhdhala�n Annilaiye Kettaan Enappatudhal Nandru', english_meaning: 'It is better for a man to be said of him that he died in his usual state than that he eked out his life by following those who disgraced him', career_application: 'It is better for a man to be said of him that he died in his usual state than that he eked out his life by following those who disgraced him', chapter: 'Honour' },
  { id: 968, kural_number: 968, tamil_text: 'மருந்தோமற்று ஊன்ஓம்பும் வாழ்க்கை பெருந்தகைமை பீடழிய வந்த இடத்து.', transliteration: 'Marundhomatru Oonompum Vaazhkkai Perundhakaimai Peetazhiya Vandha Itaththu', english_meaning: 'For the high-born to keep their body in life when their honour is gone will certainly not prove a remedy against death', career_application: 'For the high-born to keep their body in life when their honour is gone will certainly not prove a remedy against death', chapter: 'Honour' },
  { id: 969, kural_number: 969, tamil_text: 'மயிர்நீப்பின் வாழாக் கவரிமா அன்னார் உயிர்நீப்பர் மானம் வரின்.', transliteration: 'Mayirneeppin Vaazhaak Kavarimaa Annaar Uyirneeppar Maanam Varin', english_meaning: 'Those who give up (their) life when (their) honour is at stake are like the yark which kills itself at the loss of (even one of) its hairs', career_application: 'Those who give up (their) life when (their) honour is at stake are like the yark which kills itself at the loss of (even one of) its hairs', chapter: 'Honour' },
  { id: 970, kural_number: 970, tamil_text: 'இளிவரின் வாழாத மானம் உடையார் ஒளிதொழுது ஏத்தும் உலகு.', transliteration: 'Ilivarin Vaazhaadha Maanam Utaiyaar Olidhozhudhu Eththum Ulaku', english_meaning: 'The world will (always) praise and adore the fame of the honourable who would rather die than suffer indignity', career_application: 'The world will (always) praise and adore the fame of the honourable who would rather die than suffer indignity', chapter: 'Honour' },
  { id: 971, kural_number: 971, tamil_text: 'ஒளிஒருவற்கு உள்ள வெறுக்கை இளிஒருவற்கு அஃதிறந்து வாழ்தும் எனல்.', transliteration: 'Olioruvarku Ulla Verukkai Ilioruvarku Aqdhirandhu Vaazhdhum Enal', english_meaning: 'One\'s light is the abundance of one\'s courage; one\'s darkness is the desire to live destitute of such (a state of mind.)', career_application: 'One\'s light is the abundance of one\'s courage; one\'s darkness is the desire to live destitute of such (a state of mind.)', chapter: 'Greatness' },
  { id: 972, kural_number: 972, tamil_text: 'பிறப்பொக்கும் எல்லா உயிர்க்கும் சிறப்பொவ்வா செய்தொழில் வேற்றுமை யான்.', transliteration: 'Pirappokkum Ellaa Uyirkkum Sirappovvaa Seydhozhil Vetrumai Yaan', english_meaning: 'All human beings agree as regards their birth but differ as regards their characteristics, because of the different qualities of their actions', career_application: 'All human beings agree as regards their birth but differ as regards their characteristics, because of the different qualities of their actions', chapter: 'Greatness' },
  { id: 973, kural_number: 973, tamil_text: 'மேலிருந்தும் மேலல்லார் மேலல்லர் கீழிருந்தும் கீழல்லார் கீழல் லவர்.', transliteration: 'Melirundhum Melallaar Melallar Keezhirundhum Keezhallaar Keezhal Lavar', english_meaning: 'Though (raised) above, the base cannot become great; though (brought) low, the great cannot become base', career_application: 'Though (raised) above, the base cannot become great; though (brought) low, the great cannot become base', chapter: 'Greatness' },
  { id: 974, kural_number: 974, tamil_text: 'ஒருமை மகளிரே போலப் பெருமையும் தன்னைத்தான் கொண்டொழுகின் உண்டு.', transliteration: 'Orumai Makalire Polap Perumaiyum Thannaiththaan Kontozhukin Untu', english_meaning: 'Exists while to itself is true', career_application: 'Exists while to itself is true', chapter: 'Greatness' },
  { id: 975, kural_number: 975, tamil_text: 'பெருமை யுடையவர் ஆற்றுவார் ஆற்றின் அருமை உடைய செயல்.', transliteration: 'Perumai Yutaiyavar Aatruvaar Aatrin Arumai Utaiya Seyal', english_meaning: '(Though reduced) the great will be able to perform, in the proper way, deeds difficult (for others to do)', career_application: '(Though reduced) the great will be able to perform, in the proper way, deeds difficult (for others to do)', chapter: 'Greatness' },
  { id: 976, kural_number: 976, tamil_text: 'சிறியார் உணர்ச்சியுள் இல்லை பெரியாரைப் பேணிக் கொள் வேம் என்னும் நோக்கு.', transliteration: 'Siriyaar Unarchchiyul Illai Periyaaraip Penikkol Vemennum Nokku', english_meaning: 'It is never in the nature of the base to seek the society of the great and partake of their nature', career_application: 'It is never in the nature of the base to seek the society of the great and partake of their nature', chapter: 'Greatness' },
  { id: 977, kural_number: 977, tamil_text: 'இறப்பே புரிந்த தொழிற்றாம் சிறப்புந்தான் சீரல் லவர்கண் படின்.', transliteration: 'Irappe Purindha Thozhitraam Sirappundhaan Seeral Lavarkan Patin', english_meaning: 'Even nobility of birth, wealth and learning, if in (the possession of) the base, will (only) produce everincreasing pride', career_application: 'Even nobility of birth, wealth and learning, if in (the possession of) the base, will (only) produce everincreasing pride', chapter: 'Greatness' },
  { id: 978, kural_number: 978, tamil_text: 'பணியுமாம் என்றும் பெருமை சிறுமை அணியுமாம் தன்னை வியந்து.', transliteration: 'Paniyumaam Endrum Perumai Sirumai Aniyumaam Thannai Viyandhu', english_meaning: 'The great will always humble himself; but the mean will exalt himself in self-admiration', career_application: 'The great will always humble himself; but the mean will exalt himself in self-admiration', chapter: 'Greatness' },
  { id: 979, kural_number: 979, tamil_text: 'பெருமை பெருமிதம் இன்மை சிறுமை பெருமிதம் ஊர்ந்து விடல்.', transliteration: 'Perumai Perumidham Inmai Sirumai Perumidham Oorndhu Vital', english_meaning: 'Freedom from conceit is (the nature of true) greatness; (while) obstinacy therein is (that of) meanness', career_application: 'Freedom from conceit is (the nature of true) greatness; (while) obstinacy therein is (that of) meanness', chapter: 'Greatness' },
  { id: 980, kural_number: 980, tamil_text: 'அற்றம் மறைக்கும் பெருமை சிறுமைதான் குற்றமே கூறி விடும்.', transliteration: 'Atram Maraikkum Perumai Sirumaidhaan Kutrame Koori Vitum', english_meaning: 'The great hide the faults of others; the base only divulge them', career_application: 'The great hide the faults of others; the base only divulge them', chapter: 'Greatness' },
  { id: 981, kural_number: 981, tamil_text: 'கடன்என்ப நல்லவை எல்லாம் கடன்அறிந்து சான்றாண்மை மேற்கொள் பவர்க்கு.', transliteration: 'Katanenpa Nallavai Ellaam Katanarindhu Saandraanmai Merkol Pavarkku', english_meaning: 'It is said that those who are conscious of their duty and behave with a perfect goodness will regard as natural all that is good', career_application: 'It is said that those who are conscious of their duty and behave with a perfect goodness will regard as natural all that is good', chapter: 'Perfectness' },
  { id: 982, kural_number: 982, tamil_text: 'குணநலம் சான்றோர் நலனே பிறநலம் எந்நலத்து உள்ளதூஉம் அன்று.', transliteration: 'Kunanalam Saandror Nalane Piranalam Ennalaththu Ulladhooum Andru', english_meaning: 'The only delight of the perfect is that of their goodness; all other (sensual) delights are not to be included among any (true) delights', career_application: 'The only delight of the perfect is that of their goodness; all other (sensual) delights are not to be included among any (true) delights', chapter: 'Perfectness' },
  { id: 983, kural_number: 983, tamil_text: 'அன்புநாண் ஒப்புரவு கண்ணோட்டம் வாய்மையொடு ஐந்துசால் ஊன்றிய தூண்.', transliteration: 'Anpunaan Oppuravu Kannottam Vaaimaiyotu Aindhusaal Oondriya Thoon', english_meaning: 'Affection, fear (of sin), benevolence, favour and truthfulness; these are the five pillars on which perfect goodness rests', career_application: 'Affection, fear (of sin), benevolence, favour and truthfulness; these are the five pillars on which perfect goodness rests', chapter: 'Perfectness' },
  { id: 984, kural_number: 984, tamil_text: 'கொல்லா நலத்தது நோன்மை பிறர்தீமை சொல்லா நலத்தது சால்பு.', transliteration: 'Kollaa Nalaththadhu Nonmai Pirardheemai Sollaa Nalaththadhu Saalpu', english_meaning: 'Penance consists in the goodness that kills not , and perfection in the goodness that tells not others\' faults', career_application: 'Penance consists in the goodness that kills not , and perfection in the goodness that tells not others\' faults', chapter: 'Perfectness' },
  { id: 985, kural_number: 985, tamil_text: 'ஆற்றுவார் ஆற்றல் பணிதல் அதுசான்றோர் மாற்றாரை மாற்றும் படை.', transliteration: 'Aatruvaar Aatral Panidhal Adhusaandror Maatraarai Maatrum Patai', english_meaning: 'Stooping (to inferiors) is the strength of those who can accomplish (an undertaking); and that is the weapon with which the great avert their foes', career_application: 'Stooping (to inferiors) is the strength of those who can accomplish (an undertaking); and that is the weapon with which the great avert their foes', chapter: 'Perfectness' },
  { id: 986, kural_number: 986, tamil_text: 'சால்பிற்குக் கட்டளை யாதெனின் தோல்வி துலையல்லார் கண்ணும் கொளல்.', transliteration: 'Saalpirkuk Kattalai Yaadhenin Tholvi Thulaiyallaar Kannum Kolal', english_meaning: 'The touch-stone of perfection is to receive a defeat even at the hands of one\'s inferiors', career_application: 'The touch-stone of perfection is to receive a defeat even at the hands of one\'s inferiors', chapter: 'Perfectness' },
  { id: 987, kural_number: 987, tamil_text: 'இன்னாசெய் தார்க்கும் இனியவே செய்யாக்கால் என்ன பயத்ததோ சால்பு.', transliteration: 'Innaasey Thaarkkum Iniyave Seyyaakkaal Enna Payaththadho Saalpu', english_meaning: 'Of what avail is perfect goodness if it cannot do pleasing things even to those who have pained (it) ?', career_application: 'Of what avail is perfect goodness if it cannot do pleasing things even to those who have pained (it) ?', chapter: 'Perfectness' },
  { id: 988, kural_number: 988, tamil_text: 'இன்மை ஒருவற்கு இளிவன்று சால்பென்னும் திண்மை உண் டாகப் பெறின்.', transliteration: 'Inmai Oruvarku Ilivandru Saalpennum Thinmai Un Taakap Perin', english_meaning: 'Poverty is no disgrace to one who abounds in good qualities', career_application: 'Poverty is no disgrace to one who abounds in good qualities', chapter: 'Perfectness' },
  { id: 989, kural_number: 989, tamil_text: 'ஊழி பெயரினும் தாம்பெயரார் சான்றாண்மைக்கு ஆழி எனப்படு வார்.', transliteration: 'Oozhi Peyarinum Thaampeyaraar Saandraanmaikku Aazhi Enappatu Vaar', english_meaning: 'Those who are said to be the shore of the sea of perfection will never change, though ages may change', career_application: 'Those who are said to be the shore of the sea of perfection will never change, though ages may change', chapter: 'Perfectness' },
  { id: 990, kural_number: 990, tamil_text: 'சான்றவர் சான்றாண்மை குன்றின் இருநிலந்தான் தாங்காது மன்னோ பொறை.', transliteration: 'Saandravar Saandraanmai Kundrin Irunilandhaan Thaangaadhu Manno Porai', english_meaning: 'If there is a defect in the character of the perfect, (even) the great world cannot bear (its) burden', career_application: 'If there is a defect in the character of the perfect, (even) the great world cannot bear (its) burden', chapter: 'Perfectness' },
  { id: 991, kural_number: 991, tamil_text: 'எண்பதத்தால் எய்தல் எளிதென்ப யார்மாட்டும் பண்புடைமை என்னும் வழக்கு.', transliteration: 'Enpadhaththaal Eydhal Elidhenpa Yaarmaattum Panputaimai Ennum Vazhakku', english_meaning: 'If one is easy of access to all, it will be easy for one to obtain the virtue called goodness', career_application: 'If one is easy of access to all, it will be easy for one to obtain the virtue called goodness', chapter: 'Courtesy' },
  { id: 992, kural_number: 992, tamil_text: 'அன்புடைமை ஆன்ற குடிப்பிறத்தல் இவ்விரண்டும் பண்புடைமை என்னும் வழக்கு.', transliteration: 'Anputaimai Aandra Kutippiraththal Ivvirantum Panputaimai Ennum Vazhakku', english_meaning: 'Affectionateness and birth in a good family, these two constitute what is called a proper behaviour to all', career_application: 'Affectionateness and birth in a good family, these two constitute what is called a proper behaviour to all', chapter: 'Courtesy' },
  { id: 993, kural_number: 993, tamil_text: 'உறுப்பொத்தல் மக்களொப்பு அன்றால் வெறுத்தக்க பண்பொத்தல் ஒப்பதாம் ஒப்பு.', transliteration: 'Uruppoththal Makkaloppu Andraal Veruththakka Panpoththal Oppadhaam Oppu', english_meaning: 'Resemblance of bodies is no resemblance of souls; true resemblance is the resemblance of qualities that attract', career_application: 'Resemblance of bodies is no resemblance of souls; true resemblance is the resemblance of qualities that attract', chapter: 'Courtesy' },
  { id: 994, kural_number: 994, tamil_text: 'நயனொடு நன்றி புரிந்த பயனுடையார் பண்புபா ராட்டும் உலகு.', transliteration: 'Nayanotu Nandri Purindha Payanutaiyaar Panpupaa Raattum Ulaku', english_meaning: 'The world applauds the character of those whose usefulness results from their equity and charity', career_application: 'The world applauds the character of those whose usefulness results from their equity and charity', chapter: 'Courtesy' },
  { id: 995, kural_number: 995, tamil_text: 'நகையுள்ளும் இன்னா திகழ்ச்சி பகையுள்ளும் பண்புள பாடறிவார் மாட்டு.', transliteration: 'Nakaiyullum Innaa Thikazhchchi Pakaiyullum Panpula Paatarivaar Maattu', english_meaning: 'Reproach is painful to one even in sport; those (therefore) who know the nature of others exhibit (pleasing) qualities even when they are hated', career_application: 'Reproach is painful to one even in sport; those (therefore) who know the nature of others exhibit (pleasing) qualities even when they are hated', chapter: 'Courtesy' },
  { id: 996, kural_number: 996, tamil_text: 'பண்புடையார்ப் பட்டுண்டு உலகம் அதுஇன்றேல் மண்புக்கு மாய்வது மன்.', transliteration: 'Panputaiyaarp Pattuntu Ulakam Adhuindrel Manpukku Maaivadhu Man', english_meaning: 'The (way of the) world subsists by contact with the good; if not, it would bury itself in the earth and perish', career_application: 'The (way of the) world subsists by contact with the good; if not, it would bury itself in the earth and perish', chapter: 'Courtesy' },
  { id: 997, kural_number: 997, tamil_text: 'அரம்போலும் கூர்மைய ரேனும் மரம்போல்வர் மக்கட்பண்பு இல்லா தவர்.', transliteration: 'Arampolum Koormaiya Renum Marampolvar Makkatpanpu Illaa Thavar', english_meaning: 'He who is destitute of (true) human qualities (only) resembles a tree, though he may possess the sharpness of a file', career_application: 'He who is destitute of (true) human qualities (only) resembles a tree, though he may possess the sharpness of a file', chapter: 'Courtesy' },
  { id: 998, kural_number: 998, tamil_text: 'நண்பாற்றார் ஆகி நயமில செய்வார்க்கும் பண்பாற்றார் ஆதல் கடை.', transliteration: 'Nanpaatraar Aaki Nayamila Seyvaarkkum Panpaatraar Aadhal Katai', english_meaning: 'It is wrong (for the wise) not to exhibit (good) qualities even towards those who bearing no friendship (for them) do only what is hateful', career_application: 'It is wrong (for the wise) not to exhibit (good) qualities even towards those who bearing no friendship (for them) do only what is hateful', chapter: 'Courtesy' },
  { id: 999, kural_number: 999, tamil_text: 'நகல்வல்லர் அல்லார்க்கு மாயிரு ஞாலம் பகலும்பாற் பட்டன்று இருள்.', transliteration: 'Nakalvallar Allaarkku Maayiru Gnaalam Pakalumpaar Pattandru Irul', english_meaning: 'To those who cannot rejoice, the wide world is buried darkness even in (broad) day light', career_application: 'To those who cannot rejoice, the wide world is buried darkness even in (broad) day light', chapter: 'Courtesy' },
  { id: 1000, kural_number: 1000, tamil_text: 'பண்பிலான் பெற்ற பெருஞ்செல்வம் நன்பால் கலந்தீமை யால்திரிந் தற்று.', transliteration: 'Panpilaan Petra Perunjelvam Nanpaal Kalandheemai Yaaldhirin Thatru', english_meaning: 'The great wealth obtained by one who has no goodness will perish like pure milk spoilt by the', career_application: 'The great wealth obtained by one who has no goodness will perish like pure milk spoilt by the', chapter: 'Courtesy' },
  { id: 1001, kural_number: 1001, tamil_text: 'வைத்தான்வாய் சான்ற பெரும்பொருள் அஃதுண்ணான் செத்தான் செயக்கிடந்தது இல்.', transliteration: 'Vaiththaanvaai Saandra Perumporul Aqdhunnaan Seththaan Seyakkitandhadhu Il', english_meaning: 'He who does not enjoy the immense riches he has heaped up in his house, is (to be reckoned as) dead, (for) there is nothing achieved (by him)', career_application: 'He who does not enjoy the immense riches he has heaped up in his house, is (to be reckoned as) dead, (for) there is nothing achieved (by him)', chapter: 'Wealth without Benefaction' },
  { id: 1002, kural_number: 1002, tamil_text: 'பொருளானாம் எல்லாமென்று ஈயாது இவறும் மருளானாம் மாணாப் பிறப்பு', transliteration: 'Porulaanaam Ellaamendru Eeyaadhu Ivarum Marulaanaam Maanaap Pirappu', english_meaning: 'He who knows that wealth yields every pleasure and yet is so blind as to lead miserly life will be born a demon', career_application: 'He who knows that wealth yields every pleasure and yet is so blind as to lead miserly life will be born a demon', chapter: 'Wealth without Benefaction' },
  { id: 1003, kural_number: 1003, tamil_text: 'ஈட்டம் இவறி இசைவேண்டா ஆடவர் தோற்றம் நிலக்குப் பொறை.', transliteration: 'Eettam Ivari Isaiventaa Aatavar Thotram Nilakkup Porai', english_meaning: 'A burden to the earth are men bent on the acquisition of riches and not (true) fame', career_application: 'A burden to the earth are men bent on the acquisition of riches and not (true) fame', chapter: 'Wealth without Benefaction' },
  { id: 1004, kural_number: 1004, tamil_text: 'எச்சமென்று என்எண்ணுங் கொல்லோ ஒருவரால் நச்சப் படாஅ தவன்.', transliteration: 'Echchamendru Enennung Kollo Oruvaraal Nachchap Pataaa Thavan', english_meaning: 'What will the miser who is not liked (by any one) regard as his own (in the world to come) ?', career_application: 'What will the miser who is not liked (by any one) regard as his own (in the world to come) ?', chapter: 'Wealth without Benefaction' },
  { id: 1005, kural_number: 1005, tamil_text: 'கொடுப்பதூஉம் துய்ப்பதூஉம் இல்லார்க்கு அடுக்கிய கோடியுண் டாயினும் இல்.', transliteration: 'Kotuppadhooum Thuyppadhooum Illaarkku Atukkiya Kotiyun Taayinum Il', english_meaning: 'Those who neither give (to others) nor enjoy (their property) are (truly) destitute, though possessing immense riches', career_application: 'Those who neither give (to others) nor enjoy (their property) are (truly) destitute, though possessing immense riches', chapter: 'Wealth without Benefaction' },
  { id: 1006, kural_number: 1006, tamil_text: 'ஏதம் பெருஞ்செல்வம் தான்துவ்வான் தக்கார்க்கொன்று ஈதல் இயல்பிலா தான்.', transliteration: 'Edham Perunjelvam Thaandhuvvaan Thakkaarkkondru Eedhal Iyalpilaa Thaan', english_meaning: 'He who enjoys not (his riches) nor relieves the wants of the worthy is a disease to his wealth', career_application: 'He who enjoys not (his riches) nor relieves the wants of the worthy is a disease to his wealth', chapter: 'Wealth without Benefaction' },
  { id: 1007, kural_number: 1007, tamil_text: 'அற்றார்க்கொன்று ஆற்றாதான் செல்வம் மிகநலம் பெற்றாள் தமியள்மூத் தற்று.', transliteration: 'Atraarkkondru Aatraadhaan Selvam Mikanalam Petraal Thamiyalmooth Thatru', english_meaning: 'The wealth of him who never bestows anything on the destitute is like a woman of beauty growing old without a husband', career_application: 'The wealth of him who never bestows anything on the destitute is like a woman of beauty growing old without a husband', chapter: 'Wealth without Benefaction' },
  { id: 1008, kural_number: 1008, tamil_text: 'நச்சப் படாதவன் செல்வம் நடுவூருள் நச்சு மரம்பழுத் தற்று.', transliteration: 'Nachchap Pataadhavan Selvam Natuvoorul Nachchu Marampazhuth Thatru', english_meaning: 'The wealth of him who is disliked (by all) is like the fruit-bearing of the etty tree in the midst of a town', career_application: 'The wealth of him who is disliked (by all) is like the fruit-bearing of the etty tree in the midst of a town', chapter: 'Wealth without Benefaction' },
  { id: 1009, kural_number: 1009, tamil_text: 'அன்பொரீஇத் தற்செற்று அறநோக்காது ஈட்டிய ஒண்பொருள் கொள்வார் பிறர்.', transliteration: 'Anporeeith Tharsetru Aranokkaadhu Eettiya Onporul Kolvaar Pirar', english_meaning: 'To heap up glittering wealth, their hoards shall others take', career_application: 'To heap up glittering wealth, their hoards shall others take', chapter: 'Wealth without Benefaction' },
  { id: 1010, kural_number: 1010, tamil_text: 'சீருடைச் செல்வர் சிறுதுனி மாரி வறங்கூர்ந் தனையது உடைத்து.', transliteration: 'Seerutaich Chelvar Sirudhuni Maari Varangoorn Thanaiyadhu Utaiththu', english_meaning: 'The short-lived poverty of those who are noble and rich is like the clouds becoming poor (for a while)', career_application: 'The short-lived poverty of those who are noble and rich is like the clouds becoming poor (for a while)', chapter: 'Wealth without Benefaction' },
  { id: 1011, kural_number: 1011, tamil_text: 'கருமத்தால் நாணுதல் நாணுந் திருநுதல் நல்லவர் நாணுப் பிற.', transliteration: 'Karumaththaal Naanudhal Naanun Thirunudhal Nallavar Naanup Pira', english_meaning: 'True modesty is the fear of (evil) deeds; all other modesty is (simply) the bashfulness of virtuous maids', career_application: 'True modesty is the fear of (evil) deeds; all other modesty is (simply) the bashfulness of virtuous maids', chapter: 'Shame' },
  { id: 1012, kural_number: 1012, tamil_text: 'ஊணுடை எச்சம் உயிர்க்கெல்லாம் வேறல்ல நாணுடைமை மாந்தர் சிறப்பு.', transliteration: 'Oonutai Echcham Uyirkkellaam Veralla Naanutaimai Maandhar Sirappu', english_meaning: 'Food, clothing and the like are common to all men but modesty is peculiar to the good', career_application: 'Food, clothing and the like are common to all men but modesty is peculiar to the good', chapter: 'Shame' },
  { id: 1013, kural_number: 1013, tamil_text: 'ஊனைக் குறித்த உயிரெல்லாம் நாண்என்னும் நன்மை குறித்தது சால்பு.', transliteration: 'Oonaik Kuriththa Uyirellaam Naanennum Nanmai Kuriththadhu Saalpu', english_meaning: 'As the body is the abode of the spirit, so the excellence of modesty is the abode of perfection', career_application: 'As the body is the abode of the spirit, so the excellence of modesty is the abode of perfection', chapter: 'Shame' },
  { id: 1014, kural_number: 1014, tamil_text: 'அணிஅன்றோ நாணுடைமை சான்றோர்க்கு அஃதின்றேல் பிணிஅன்றோ பீடு நடை.', transliteration: 'Aniandro Naanutaimai Saandrorkku Aqdhindrel Piniandro Peetu Natai', english_meaning: 'Is not the modesty ornament of the noble ? Without it, their haughtiness would be a pain (to others)', career_application: 'Is not the modesty ornament of the noble ? Without it, their haughtiness would be a pain (to others)', chapter: 'Shame' },
  { id: 1015, kural_number: 1015, tamil_text: 'பிறர்பழியும் தம்பழியும் நாணுவார் நாணுக்கு உறைபதி என்னும் உலகு.', transliteration: 'Pirarpazhiyum Thampazhiyum Naanuvaar Naanukku Uraipadhi Ennum Ulaku', english_meaning: 'The world regards as the abode of modesty him who fear his own and other\'s guilt', career_application: 'The world regards as the abode of modesty him who fear his own and other\'s guilt', chapter: 'Shame' },
  { id: 1016, kural_number: 1016, tamil_text: 'நாண்வேலி கொள்ளாது மன்னோ வியன்ஞாலம் பேணலர் மேலா யவர்.', transliteration: 'Naanveli Kollaadhu Manno Viyangnaalam Penalar Melaa Yavar', english_meaning: 'The great make modesty their barrier (of defence) and not the wide world', career_application: 'The great make modesty their barrier (of defence) and not the wide world', chapter: 'Shame' },
  { id: 1017, kural_number: 1017, tamil_text: 'நாணால் உயிரைத் துறப்பர் உயிர்ப்பொருட்டால் நாண்துறவார் நாணாள் பவர்.', transliteration: 'Naanaal Uyiraith Thurappar Uyirpporuttaal Naandhuravaar Naanaal Pavar', english_meaning: 'The modest would rather lose their life for the sake of modesty than lose modesty for the sake of life', career_application: 'The modest would rather lose their life for the sake of modesty than lose modesty for the sake of life', chapter: 'Shame' },
  { id: 1018, kural_number: 1018, tamil_text: 'பிறர்நாணத் தக்கது தான்நாணா னாயின் அறம்நாணத் தக்கது உடைத்து.', transliteration: 'Pirarnaanath Thakkadhu Thaannaanaa Naayin Aramnaanath Thakkadhu Utaiththu', english_meaning: 'Virtue is likely to forsake him who shamelessly does what others are ashamed of', career_application: 'Virtue is likely to forsake him who shamelessly does what others are ashamed of', chapter: 'Shame' },
  { id: 1019, kural_number: 1019, tamil_text: 'குலஞ்சுடும் கொள்கை பிழைப்பின் நலஞ்சுடும் நாணின்மை நின்றக் கடை.', transliteration: 'Kulanjutum Kolkai Pizhaippin Nalanjutum Naaninmai Nindrak Katai', english_meaning: 'Want of manners injures one\'s family; but want of modesty injures one\'s character', career_application: 'Want of manners injures one\'s family; but want of modesty injures one\'s character', chapter: 'Shame' },
  { id: 1020, kural_number: 1020, tamil_text: 'நாண்அகத் தில்லார் இயக்கம் மரப்பாவை நாணால் உயிர்மருட்டி அற்று.', transliteration: 'Naanakath Thillaar Iyakkam Marappaavai Naanaal Uyirmarutti Atru', english_meaning: 'The actions of those who are without modesty at heart are like those of puppet moved by a string', career_application: 'The actions of those who are without modesty at heart are like those of puppet moved by a string', chapter: 'Shame' },
  { id: 1021, kural_number: 1021, tamil_text: 'கருமம் செயஒருவன் கைதூவேன் என்னும் பெருமையின் பீடுடையது இல்.', transliteration: 'Karumam Seyaoruvan Kaidhooven Ennum Perumaiyin Peetutaiyadhu Il', english_meaning: 'There is no higher greatness than that of one saying I will not cease in my effort (to raise my family)', career_application: 'There is no higher greatness than that of one saying I will not cease in my effort (to raise my family)', chapter: 'The Way of Maintaining the Family' },
  { id: 1022, kural_number: 1022, tamil_text: 'ஆள்வினையும் ஆன்ற அறிவும் எனஇரண்டின் நீள்வினையால் நீளும் குடி.', transliteration: 'Aalvinaiyum Aandra Arivum Enairantin Neelvinaiyaal Neelum Kuti', english_meaning: 'One\'s family is raised by untiring perseverance in both effort and wise contrivances', career_application: 'One\'s family is raised by untiring perseverance in both effort and wise contrivances', chapter: 'The Way of Maintaining the Family' },
  { id: 1023, kural_number: 1023, tamil_text: 'குடிசெய்வல் என்னும் ஒருவற்குத் தெய்வம் மடிதற்றுத் தான்முந் துறும்.', transliteration: 'Kutiseyval Ennum Oruvarkuth Theyvam Matidhatruth Thaanmun Thurum', english_meaning: 'The Deity will clothe itself and appear before him who resolves on raising his family', career_application: 'The Deity will clothe itself and appear before him who resolves on raising his family', chapter: 'The Way of Maintaining the Family' },
  { id: 1024, kural_number: 1024, tamil_text: 'சூழாமல் தானே முடிவெய்தும் தம்குடியைத் தாழாது உஞற்று பவர்க்கு.', transliteration: 'Soozhaamal Thaane Mutiveydhum Thamkutiyaith Thaazhaadhu Ugnatru Pavarkku', english_meaning: 'Those who are prompt in their efforts (to better their family) need no deliberation, such efforts will of themselves succeed', career_application: 'Those who are prompt in their efforts (to better their family) need no deliberation, such efforts will of themselves succeed', chapter: 'The Way of Maintaining the Family' },
  { id: 1025, kural_number: 1025, tamil_text: 'குற்றம் இலனாய்க் குடிசெய்து வாழ்வானைச் சுற்றமாச் சுற்றும் உலகு.', transliteration: 'Kutram Ilanaaik Kutiseydhu Vaazhvaanaich Chutramaach Chutrum Ulaku', english_meaning: 'People will eagerly seek the friendship of the prosperous soul who has raised his family without foul means', career_application: 'People will eagerly seek the friendship of the prosperous soul who has raised his family without foul means', chapter: 'The Way of Maintaining the Family' },
  { id: 1026, kural_number: 1026, tamil_text: 'நல்லாண்மை என்பது ஒருவற்குத் தான்பிறந்த இல்லாண்மை ஆக்கிக் கொளல்.', transliteration: 'Nallaanmai Enpadhu Oruvarkuth Thaanpirandha Illaanmai Aakkik Kolal', english_meaning: 'A man\'s true manliness consists in making himself the head and benefactor of his family', career_application: 'A man\'s true manliness consists in making himself the head and benefactor of his family', chapter: 'The Way of Maintaining the Family' },
  { id: 1027, kural_number: 1027, tamil_text: 'அமரகத்து வன்கண்ணர் போலத் தமரகத்தும் ஆற்றுவார் மேற்றே பொறை.', transliteration: 'Amarakaththu Vankannar Polath Thamarakaththum Aatruvaar Metre Porai', english_meaning: 'Amid his kindred so the burthen rests upon the strong', career_application: 'Amid his kindred so the burthen rests upon the strong', chapter: 'The Way of Maintaining the Family' },
  { id: 1028, kural_number: 1028, tamil_text: 'குடிசெய்வார்க் கில்லை பருவம் மடிசெய்து மானங் கருதக் கெடும்.', transliteration: 'Kutiseyvaark Killai Paruvam Matiseydhu Maanang Karudhak Ketum', english_meaning: 'As a family suffers by (one\'s) indolence and false dignity there is to be so season (good or bad) to those who strive to raise their family', career_application: 'As a family suffers by (one\'s) indolence and false dignity there is to be so season (good or bad) to those who strive to raise their family', chapter: 'The Way of Maintaining the Family' },
  { id: 1029, kural_number: 1029, tamil_text: 'இடும்பைக்கே கொள்கலம் கொல்லோ குடும்பத்தைக் குற்ற மறைப்பான் உடம்பு.', transliteration: 'Itumpaikke Kolkalam Kollo Kutumpaththaik Kutra Maraippaan Utampu', english_meaning: 'Is it only to suffering that his body is exposed who undertakes to preserve his family from evil ?', career_application: 'Is it only to suffering that his body is exposed who undertakes to preserve his family from evil ?', chapter: 'The Way of Maintaining the Family' },
  { id: 1030, kural_number: 1030, tamil_text: 'இடுக்கண்கால் கொன்றிட வீழும் அடுத்தூன்றும் நல்லாள் இலாத குடி.', transliteration: 'Itukkankaal Kondrita Veezhum Atuththoondrum Nallaal Ilaadha Kuti', english_meaning: 'If there are none to prop up and maintain a family (in distress), it will fall at the stroke of the axe of misfortune', career_application: 'If there are none to prop up and maintain a family (in distress), it will fall at the stroke of the axe of misfortune', chapter: 'The Way of Maintaining the Family' },
  { id: 1031, kural_number: 1031, tamil_text: 'சுழன்றும்ஏர்ப் பின்னது உலகம் அதனால் உழந்தும் உழவே தலை.', transliteration: 'Suzhandrumerp Pinnadhu Ulakam Adhanaal Uzhandhum Uzhave Thalai', english_meaning: 'Agriculture, though laborious, is the most excellent (form of labour); for people, though they go about (in search of various employments), have at last to resort to the farmer', career_application: 'Agriculture, though laborious, is the most excellent (form of labour); for people, though they go about (in search of various employments), have at last to resort to the farmer', chapter: 'Farming' },
  { id: 1032, kural_number: 1032, tamil_text: 'உழுவார் உலகத்தார்க்கு ஆணிஅஃ தாற்றாது எழுவாரை எல்லாம் பொறுத்து.', transliteration: 'Uzhuvaar Ulakaththaarkku Aaniaq Thaatraadhu Ezhuvaarai Ellaam Poruththu', english_meaning: 'Agriculturists are (as it were) the linch-pin of the world for they support all other workers who cannot till the soil', career_application: 'Agriculturists are (as it were) the linch-pin of the world for they support all other workers who cannot till the soil', chapter: 'Farming' },
  { id: 1033, kural_number: 1033, tamil_text: 'உழுதுண்டு வாழ்வாரே வாழ்வார்மற் றெல்லாம் தொழுதுண்டு பின்செல் பவர்.', transliteration: 'Uzhudhuntu Vaazhvaare Vaazhvaarmar Rellaam Thozhudhuntu Pinsel Pavar', english_meaning: 'They alone live who live by agriculture; all others lead a cringing, dependent life', career_application: 'They alone live who live by agriculture; all others lead a cringing, dependent life', chapter: 'Farming' },
  { id: 1034, kural_number: 1034, tamil_text: 'பலகுடை நீழலும் தங்குடைக்கீழ்க் காண்பர் அலகுடை நீழ லவர்.', transliteration: 'Palakutai Neezhalum Thangutaikkeezhk Kaanpar Alakutai Neezha Lavar', english_meaning: 'Patriotic farmers desire to bring all other states under the control of their own king', career_application: 'Patriotic farmers desire to bring all other states under the control of their own king', chapter: 'Farming' },
  { id: 1035, kural_number: 1035, tamil_text: 'இரவார் இரப்பார்க்கொன்று ஈவர் கரவாது கைசெய்தூண் மாலை யவர்.', transliteration: 'Iravaar Irappaarkkondru Eevar Karavaadhu Kaiseydhoon Maalai Yavar', english_meaning: 'Those whose nature is to live by manual labour will never beg but give something to those who beg', career_application: 'Those whose nature is to live by manual labour will never beg but give something to those who beg', chapter: 'Farming' },
  { id: 1036, kural_number: 1036, tamil_text: 'உழவினார் கைம்மடங்கின் இல்லை விழைவதூஉம் விட்டேம்என் பார்க்கும் நிலை.', transliteration: 'Uzhavinaar Kaimmatangin Illai Vizhaivadhooum Vittemen Paarkkum Nilai', english_meaning: 'If the farmer\'s hands are slackened, even the ascetic state will fail', career_application: 'If the farmer\'s hands are slackened, even the ascetic state will fail', chapter: 'Farming' },
  { id: 1037, kural_number: 1037, tamil_text: 'தொடிப்புழுதி கஃசா உணக்கின் பிடித்தெருவும் வேண்டாது சாலப் படும்.', transliteration: 'Thotippuzhudhi Kaqsaa Unakkin Pitiththeruvum Ventaadhu Saalap Patum', english_meaning: 'If the land is dried so as to reduce one ounce of earth to a quarter, it will grow plentifully even without a handful of manure', career_application: 'If the land is dried so as to reduce one ounce of earth to a quarter, it will grow plentifully even without a handful of manure', chapter: 'Farming' },
  { id: 1038, kural_number: 1038, tamil_text: 'ஏரினும் நன்றால் எருவிடுதல் கட்டபின் நீரினும் நன்றதன் காப்பு.', transliteration: 'Erinum Nandraal Eruvitudhal Kattapin Neerinum Nandradhan Kaappu', english_meaning: 'Manuring is better than ploughing; after weeding, watching is better than watering (it)', career_application: 'Manuring is better than ploughing; after weeding, watching is better than watering (it)', chapter: 'Farming' },
  { id: 1039, kural_number: 1039, tamil_text: 'செல்லான் கிழவன் இருப்பின் நிலம்புலந்து இல்லாளின் ஊடி விடும்.', transliteration: 'Sellaan Kizhavan Iruppin Nilampulandhu Illaalin Ooti Vitum', english_meaning: 'If the owner does not (personally) attend to his cultivation, his land will behave like an angry wife and yield him no pleasure', career_application: 'If the owner does not (personally) attend to his cultivation, his land will behave like an angry wife and yield him no pleasure', chapter: 'Farming' },
  { id: 1040, kural_number: 1040, tamil_text: 'இலமென்று அசைஇ இருப்பாரைக் காணின் நிலமென்னும் நல்லாள் நகும்.', transliteration: 'Ilamendru Asaii Iruppaaraik Kaanin Nilamennum Nallaal Nakum', english_meaning: 'The maiden, Earth, will laugh at the sight of those who plead poverty and lead an idle life', career_application: 'The maiden, Earth, will laugh at the sight of those who plead poverty and lead an idle life', chapter: 'Farming' },
  { id: 1041, kural_number: 1041, tamil_text: 'இன்மையின் இன்னாதது யாதெனின் இன்மையின் இன்மையே இன்னா தது.', transliteration: 'Inmaiyin Innaadhadhu Yaadhenin Inmaiyin Inmaiye Innaa Thadhu', english_meaning: 'There is nothing that afflicts (one) like poverty', career_application: 'There is nothing that afflicts (one) like poverty', chapter: 'Poverty' },
  { id: 1042, kural_number: 1042, tamil_text: 'இன்மை எனவொரு பாவி மறுமையும் இம்மையும் இன்றி வரும்.', transliteration: 'Inmai Enavoru Paavi Marumaiyum Immaiyum Indri Varum', english_meaning: 'When cruel poverty comes on, it deprives one of both the present and future (bliss)', career_application: 'When cruel poverty comes on, it deprives one of both the present and future (bliss)', chapter: 'Poverty' },
  { id: 1043, kural_number: 1043, tamil_text: 'தொல்வரவும் தோலும் கெடுக்கும் தொகையாக நல்குரவு என்னும் நசை.', transliteration: 'Tholvaravum Tholum Ketukkum Thokaiyaaka Nalkuravu Ennum Nasai', english_meaning: 'Hankering poverty destroys at once the greatness of (one\'s) ancient descent and (the dignity of one\'s) speech', career_application: 'Hankering poverty destroys at once the greatness of (one\'s) ancient descent and (the dignity of one\'s) speech', chapter: 'Poverty' },
  { id: 1044, kural_number: 1044, tamil_text: 'இற்பிறந்தார் கண்ணேயும் இன்மை இளிவந்த சொற்பிறக்கும் சோர்வு தரும்.', transliteration: 'Irpirandhaar Kanneyum Inmai Ilivandha Sorpirakkum Sorvu Tharum', english_meaning: 'Even in those of high birth, poverty will produce the fault of uttering mean words', career_application: 'Even in those of high birth, poverty will produce the fault of uttering mean words', chapter: 'Poverty' },
  { id: 1045, kural_number: 1045, tamil_text: 'நல்குரவு என்னும் இடும்பையுள் பல்குரைத் துன்பங்கள் சென்று படும்.', transliteration: 'Nalkuravu Ennum Itumpaiyul Palkuraith Thunpangal Sendru Patum', english_meaning: 'The misery of poverty brings in its train many (more) miseries', career_application: 'The misery of poverty brings in its train many (more) miseries', chapter: 'Poverty' },
  { id: 1046, kural_number: 1046, tamil_text: 'நற்பொருள் நன்குணர்ந்து சொல்லினும் நல்கூர்ந்தார் சொற்பொருள் சோர்வு படும்.', transliteration: 'Narporul Nankunarndhu Sollinum Nalkoorndhaar Sorporul Sorvu Patum', english_meaning: 'The words of the poor are profitless, though they may be sound in thought and clear in expression', career_application: 'The words of the poor are profitless, though they may be sound in thought and clear in expression', chapter: 'Poverty' },
  { id: 1047, kural_number: 1047, tamil_text: 'அறஞ்சாரா நல்குரவு ஈன்றதா யானும் பிறன்போல நோக்கப் படும்.', transliteration: 'Aranjaaraa Nalkuravu Eendradhaa Yaanum Piranpola Nokkap Patum', english_meaning: 'He that is reduced to absolute poverty will be regarded as a stranger even by his own mother', career_application: 'He that is reduced to absolute poverty will be regarded as a stranger even by his own mother', chapter: 'Poverty' },
  { id: 1048, kural_number: 1048, tamil_text: 'இன்றும் வருவது கொல்லோ நெருநலும் கொன்றது போலும் நிரப்பு.', transliteration: 'Indrum Varuvadhu Kollo Nerunalum Kondradhu Polum Nirappu', english_meaning: 'Is the poverty that almost killed me yesterday, to meet me today too ?', career_application: 'Is the poverty that almost killed me yesterday, to meet me today too ?', chapter: 'Poverty' },
  { id: 1049, kural_number: 1049, tamil_text: 'நெருப்பினுள் துஞ்சலும் ஆகும் நிரப்பினுள் யாதொன்றும் கண்பாடு அரிது.', transliteration: 'Neruppinul Thunjalum Aakum Nirappinul Yaadhondrum Kanpaatu Aridhu', english_meaning: 'One may sleep in the midst of fire; but by no means in the midst of poverty', career_application: 'One may sleep in the midst of fire; but by no means in the midst of poverty', chapter: 'Poverty' },
  { id: 1050, kural_number: 1050, tamil_text: 'துப்புர வில்லார் துவரத் துறவாமை உப்பிற்கும் காடிக்கும் கூற்று.', transliteration: 'Thuppura Villaar Thuvarath Thuravaamai Uppirkum Kaatikkum Kootru', english_meaning: 'The destitute poor, who do not renounce their bodies, only consume their neighbour\'s salt and water', career_application: 'The destitute poor, who do not renounce their bodies, only consume their neighbour\'s salt and water', chapter: 'Poverty' },
  { id: 1051, kural_number: 1051, tamil_text: 'இரக்க இரத்தக்கார்க் காணின் கரப்பின் அவர்பழி தம்பழி அன்று.', transliteration: 'Irakka Iraththakkaark Kaanin Karappin Avarpazhi Thampazhi Andru', english_meaning: 'If you meet with those that may be begged of, you may beg; (but) if they withhold (their gift) it is their blame and not yours', career_application: 'If you meet with those that may be begged of, you may beg; (but) if they withhold (their gift) it is their blame and not yours', chapter: 'Mendicancy' },
  { id: 1052, kural_number: 1052, tamil_text: 'இன்பம் ஒருவற்கு இரத்தல் இரந்தவை துன்பம் உறாஅ வரின்.', transliteration: 'Inpam Oruvarku Iraththal Irandhavai Thunpam Uraaa Varin', english_meaning: 'Even begging may be pleasant, if what is begged for is obtained without grief (to him that begs)', career_application: 'Even begging may be pleasant, if what is begged for is obtained without grief (to him that begs)', chapter: 'Mendicancy' },
  { id: 1053, kural_number: 1053, tamil_text: 'கரப்பிலா நெஞ்சின் கடனறிவார் முன்நின்று இரப்புமோ ரேஎர் உடைத்து.', transliteration: 'Karappilaa Nenjin Katanarivaar Munnindru Irappumo Reer Utaiththu', english_meaning: 'There is even a beauty in standing before and begging of those who are liberal in their gifts and understand their duty (to beggars)', career_application: 'There is even a beauty in standing before and begging of those who are liberal in their gifts and understand their duty (to beggars)', chapter: 'Mendicancy' },
  { id: 1054, kural_number: 1054, tamil_text: 'இரத்தலும் ஈதலே போலும் கரத்தல் கனவிலும் தேற்றாதார் மாட்டு.', transliteration: 'Iraththalum Eedhale Polum Karaththal Kanavilum Thetraadhaar Maattu', english_meaning: 'To beg of such as never think of withholding (their charity) even in their dreams, is in fact the same as giving (it oneself);', career_application: 'To beg of such as never think of withholding (their charity) even in their dreams, is in fact the same as giving (it oneself);', chapter: 'Mendicancy' },
  { id: 1055, kural_number: 1055, tamil_text: 'கரப்பிலார் வையகத்து உண்மையால் கண்ணின்று இரப்பவர் மேற்கொள் வது.', transliteration: 'Karappilaar Vaiyakaththu Unmaiyaal Kannindru Irappavar Merkol Vadhu', english_meaning: 'As there are in the world those that give without refusing, there are (also) those that prefer to beg by simply standing before them', career_application: 'As there are in the world those that give without refusing, there are (also) those that prefer to beg by simply standing before them', chapter: 'Mendicancy' },
  { id: 1056, kural_number: 1056, tamil_text: 'கரப்பிடும்பை யில்லாரைக் காணின் நிரப்பிடும்பை எல்லாம் ஒருங்கு கெடும்.', transliteration: 'Karappitumpai Yillaaraik Kaanin Nirappitumpai Ellaam Orungu Ketum', english_meaning: 'All the evil of begging will be removed at the sight of those who are far from the evil of refusing', career_application: 'All the evil of begging will be removed at the sight of those who are far from the evil of refusing', chapter: 'Mendicancy' },
  { id: 1057, kural_number: 1057, tamil_text: 'இகழ்ந்தெள்ளாது ஈவாரைக் காணின் மகிழ்ந்துள்ளம் உள்ளுள் உவப்பது உடைத்து.', transliteration: 'Ikazhndhellaadhu Eevaaraik Kaanin Makizhndhullam Ullul Uvappadhu Utaiththu', english_meaning: 'Beggars rejoice exceedingly when they behold those who bestow (their alms) with kindness and courtesy', career_application: 'Beggars rejoice exceedingly when they behold those who bestow (their alms) with kindness and courtesy', chapter: 'Mendicancy' },
  { id: 1058, kural_number: 1058, tamil_text: 'இரப்பாரை இல்லாயின் ஈர்ங்கண்மா ஞாலம் மரப்பாவை சென்றுவந் தற்று.', transliteration: 'Irappaarai Illaayin Eernganmaa Gnaalam Marappaavai Sendruvan Thatru', english_meaning: 'If there were no beggars, (the actions done in) the cool wide world would only resemble the movement of a puppet', career_application: 'If there were no beggars, (the actions done in) the cool wide world would only resemble the movement of a puppet', chapter: 'Mendicancy' },
  { id: 1059, kural_number: 1059, tamil_text: 'ஈவார்கண் என்னுண்டாம் தோற்றம் இரந்துகோள் மேவார் இலாஅக் கடை.', transliteration: 'Eevaarkan Ennuntaam Thotram Irandhukol Mevaar Ilaaak Katai', english_meaning: 'What (praise) would there be to givers (of alms) if there were no beggars to ask for and reveive (them)', career_application: 'What (praise) would there be to givers (of alms) if there were no beggars to ask for and reveive (them)', chapter: 'Mendicancy' },
  { id: 1060, kural_number: 1060, tamil_text: 'இரப்பான் வெகுளாமை வேண்டும் நிரப்பிடும்பை தானேயும் சாலும் கரி.', transliteration: 'Irappaan Vekulaamai Ventum Nirappitumpai Thaaneyum Saalum Kari', english_meaning: 'He who begs ought not to be angry (at a refusal); for even the misery of (his own) poverty should be a sufficient reason (for so doing)', career_application: 'He who begs ought not to be angry (at a refusal); for even the misery of (his own) poverty should be a sufficient reason (for so doing)', chapter: 'Mendicancy' },
  { id: 1061, kural_number: 1061, tamil_text: 'கரவாது உவந்தீயும் கண்ணன்னார் கண்ணும் இரவாமை கோடி உறும்.', transliteration: 'Karavaadhu Uvandheeyum Kannannaar Kannum Iravaamai Koti Urum', english_meaning: 'Not to beg (at all) even from those excellent persons who cheerfully give without refusing, will do immense good', career_application: 'Not to beg (at all) even from those excellent persons who cheerfully give without refusing, will do immense good', chapter: 'The Dread of Mendicancy' },
  { id: 1062, kural_number: 1062, tamil_text: 'இரந்தும் உயிர்வாழ்தல் வேண்டின் பரந்து கெடுக உலகியற்றி யான்.', transliteration: 'Irandhum Uyirvaazhdhal Ventin Parandhu Ketuka Ulakiyatri Yaan', english_meaning: 'If the Creator of the world has decreed even begging as a means of livelihood, may he too go abegging and perish', career_application: 'If the Creator of the world has decreed even begging as a means of livelihood, may he too go abegging and perish', chapter: 'The Dread of Mendicancy' },
  { id: 1063, kural_number: 1063, tamil_text: 'இன்மை இடும்பை இரந்துதீர் வாமென்னும் வன்மையின் வன்பாட்ட தில்.', transliteration: 'Inmai Itumpai Irandhudheer Vaamennum Vanmaiyin Vanpaatta Thil', english_meaning: 'There is no greater folly than the boldness with which one seeks to remedy the evils of poverty by begging (rather than by working)', career_application: 'There is no greater folly than the boldness with which one seeks to remedy the evils of poverty by begging (rather than by working)', chapter: 'The Dread of Mendicancy' },
  { id: 1064, kural_number: 1064, tamil_text: 'இடமெல்லாம் கொள்ளாத் தகைத்தே இடமில்லாக் காலும் இரவொல்லாச் சால்பு.', transliteration: 'Itamellaam Kollaath Thakaiththe Itamillaak Kaalum Iravollaach Chaalpu', english_meaning: 'Even the whole world cannot sufficiently praise the dignity that would not beg even in the midst of destitution', career_application: 'Even the whole world cannot sufficiently praise the dignity that would not beg even in the midst of destitution', chapter: 'The Dread of Mendicancy' },
  { id: 1065, kural_number: 1065, tamil_text: 'தெண்ணீர் அடுபுற்கை ஆயினும் தாள்தந்தது உண்ணலின் ஊங்கினிய தில்.', transliteration: 'Thenneer Atupurkai Aayinum Thaaldhandhadhu Unnalin Oonginiya Thil', english_meaning: 'Even thin gruel is ambrosia to him who has obtained it by labour', career_application: 'Even thin gruel is ambrosia to him who has obtained it by labour', chapter: 'The Dread of Mendicancy' },
  { id: 1066, kural_number: 1066, tamil_text: 'ஆவிற்கு நீரென்று இரப்பினும் நாவிற்கு இரவின் இளிவந்த தில்.', transliteration: 'Aavirku Neerendru Irappinum Naavirku Iravin Ilivandha Thil', english_meaning: 'There is nothing more disgraceful to one\'s tongue than to use it in begging water even for a cow', career_application: 'There is nothing more disgraceful to one\'s tongue than to use it in begging water even for a cow', chapter: 'The Dread of Mendicancy' },
  { id: 1067, kural_number: 1067, tamil_text: 'இரப்பன் இரப்பாரை எல்லாம் இரப்பின் கரப்பார் இரவன்மின் என்று.', transliteration: 'Irappan Irappaarai Ellaam Irappin Karappaar Iravanmin Endru', english_meaning: 'I beseech all beggars and say, "If you need to beg, never beg of those who give unwillingly."', career_application: 'I beseech all beggars and say, "If you need to beg, never beg of those who give unwillingly."', chapter: 'The Dread of Mendicancy' },
  { id: 1068, kural_number: 1068, tamil_text: 'இரவென்னும் ஏமாப்பில் தோணி கரவென்னும் பார்தாக்கப் பக்கு விடும்.', transliteration: 'Iravennum Emaappil Thoni Karavennum Paardhaakkap Pakku Vitum', english_meaning: 'The unsafe raft of begging will split when it strikes on the rock of refusal', career_application: 'The unsafe raft of begging will split when it strikes on the rock of refusal', chapter: 'The Dread of Mendicancy' },
  { id: 1069, kural_number: 1069, tamil_text: 'இரவுள்ள உள்ளம் உருகும் கரவுள்ள உள்ளதூஉம் இன்றிக் கெடும்.', transliteration: 'Iravulla Ullam Urukum Karavulla Ulladhooum Indrik Ketum', english_meaning: 'To think of (the evil of) begging is enough to melt one\'s heart; but to think of refusal is enough to break it', career_application: 'To think of (the evil of) begging is enough to melt one\'s heart; but to think of refusal is enough to break it', chapter: 'The Dread of Mendicancy' },
  { id: 1070, kural_number: 1070, tamil_text: 'கரப்பவர்க்கு யாங்கொளிக்கும் கொல்லோ இரப்பவர் சொல்லாடப் போஒம் உயிர்.', transliteration: 'Karappavarkku Yaangolikkum Kollo Irappavar Sollaatap Poom Uyir', english_meaning: 'Saying "No" to a beggar takes away his life. (but as that very word will kill the refuser) where then would the latter\'s life hide itself ?', career_application: 'Saying "No" to a beggar takes away his life. (but as that very word will kill the refuser) where then would the latter\'s life hide itself ?', chapter: 'The Dread of Mendicancy' },
  { id: 1071, kural_number: 1071, tamil_text: 'மக்களே போல்வர் கயவர் அவரன்ன ஒப்பாரி யாங்கண்ட தில்.', transliteration: 'Makkale Polvar Kayavar Avaranna Oppaari Yaanganta Thil', english_meaning: 'The base resemble men perfectly (as regards form); and we have not seen such (exact) resemblance (among any other species)', career_application: 'The base resemble men perfectly (as regards form); and we have not seen such (exact) resemblance (among any other species)', chapter: 'Baseness' },
  { id: 1072, kural_number: 1072, tamil_text: 'நன்றறி வாரிற் கயவர் திருவுடையர் நெஞ்சத்து அவலம் இலர்.', transliteration: 'Nandrari Vaarir Kayavar Thiruvutaiyar Nenjaththu Avalam Ilar', english_meaning: 'The low enjoy more felicity than those who know what is good; for the former are not troubled with anxiety (as to the good)', career_application: 'The low enjoy more felicity than those who know what is good; for the former are not troubled with anxiety (as to the good)', chapter: 'Baseness' },
  { id: 1073, kural_number: 1073, tamil_text: 'தேவர் அனையர் கயவர் அவருந்தாம் மேவன செய்தொழுக லான்.', transliteration: 'Thevar Anaiyar Kayavar Avarundhaam Mevana Seydhozhuka Laan', english_meaning: 'The base resemble the Gods; for the base act as they like', career_application: 'The base resemble the Gods; for the base act as they like', chapter: 'Baseness' },
  { id: 1074, kural_number: 1074, tamil_text: 'அகப்பட்டி ஆவாரைக் காணின் அவரின் மிகப்பட்டுச் செம்மாக்கும் கீழ்.', transliteration: 'Akappatti Aavaaraik Kaanin Avarin Mikappattuch Chemmaakkum Keezh', english_meaning: 'The base feels proud when he sees persons whose acts meaner than his own', career_application: 'The base feels proud when he sees persons whose acts meaner than his own', chapter: 'Baseness' },
  { id: 1075, kural_number: 1075, tamil_text: 'அச்சமே கீழ்களது ஆசாரம் எச்சம் அவாவுண்டேல் உண்டாம் சிறிது.', transliteration: 'Achchame Keezhkaladhu Aasaaram Echcham Avaavuntel Untaam Siridhu', english_meaning: '(The principle of) behaviour in the mean is chiefly fear; if not, hope of gain, to some extent', career_application: '(The principle of) behaviour in the mean is chiefly fear; if not, hope of gain, to some extent', chapter: 'Baseness' },
  { id: 1076, kural_number: 1076, tamil_text: 'அறைபறை அன்னர் கயவர்தாம் கேட்ட மறைபிறர்க்கு உய்த்துரைக்க லான்.', transliteration: 'Araiparai Annar Kayavardhaam Ketta Maraipirarkku Uyththuraikka Laan', english_meaning: 'The base are like a drum that is beaten, for they unburden to others the secrets they have heard', career_application: 'The base are like a drum that is beaten, for they unburden to others the secrets they have heard', chapter: 'Baseness' },
  { id: 1077, kural_number: 1077, tamil_text: 'ஈர்ங்கை விதிரார் கயவர் கொடிறுடைக்கும் கூன்கையர் அல்லா தவர்க்கு.', transliteration: 'Eerngai Vidhiraar Kayavar Kotirutaikkum Koonkaiyar Allaa Thavarkku', english_meaning: 'The mean will not (even) shake off (what sticks to) their hands (soon after a meal) to any but those who would break their jaws with their clenched fists', career_application: 'The mean will not (even) shake off (what sticks to) their hands (soon after a meal) to any but those who would break their jaws with their clenched fists', chapter: 'Baseness' },
  { id: 1078, kural_number: 1078, tamil_text: 'சொல்லப் பயன்படுவர் சான்றோர் கரும்புபோல் கொல்லப் பயன்படும் கீழ்.', transliteration: 'Sollap Payanpatuvar Saandror Karumpupol Kollap Payanpatum Keezh', english_meaning: 'The great bestow (their alms) as soon as they are informed; (but) the mean, like the sugar-cane, only when they are tortured to death', career_application: 'The great bestow (their alms) as soon as they are informed; (but) the mean, like the sugar-cane, only when they are tortured to death', chapter: 'Baseness' },
  { id: 1079, kural_number: 1079, tamil_text: 'உடுப்பதூஉம் உண்பதூஉம் காணின் பிறர்மேல் வடுக்காண வற்றாகும் கீழ்.', transliteration: 'Utuppadhooum Unpadhooum Kaanin Pirarmel Vatukkaana Vatraakum Keezh', english_meaning: 'The base will bring an evil (accusation) against others, as soon as he sees them (enjoying) good food', career_application: 'The base will bring an evil (accusation) against others, as soon as he sees them (enjoying) good food', chapter: 'Baseness' },
  { id: 1080, kural_number: 1080, tamil_text: 'எற்றிற் குரியர் கயவரொன்று உற்றக்கால் விற்றற்கு உரியர் விரைந்து.', transliteration: 'Etrir Kuriyar Kayavarondru Utrakkaal Vitrarku Uriyar Viraindhu', english_meaning: 'The base will hasten to sell themselves as soon as a calamity has befallen them. For what else are they fitted ?', career_application: 'The base will hasten to sell themselves as soon as a calamity has befallen them. For what else are they fitted ?', chapter: 'Baseness' },
  { id: 1081, kural_number: 1081, tamil_text: 'அணங்குகொல் ஆய்மயில் கொல்லோ கனங்குழை மாதர்கொல் மாலும் என் நெஞ்சு.', transliteration: 'Anangukol Aaimayil Kollo Kananguzhai Maadharkol Maalum En Nenju', english_meaning: 'Is this jewelled female a celestial, a choice peahen, or a human being ? My mind is perplexed', career_application: 'Is this jewelled female a celestial, a choice peahen, or a human being ? My mind is perplexed', chapter: 'The Pre-marital love' },
  { id: 1082, kural_number: 1082, tamil_text: 'நோக்கினாள் நோக்கெதிர் நோக்குதல் தாக்கணங்கு தானைக்கொண் டன்ன துடைத்து.', transliteration: 'Nokkinaal Nokkedhir Nokkudhal Thaakkanangu Thaanaikkon Tanna Thutaiththu', english_meaning: 'This female beauty returning my looks is like a celestial maiden coming with an army to contend against me', career_application: 'This female beauty returning my looks is like a celestial maiden coming with an army to contend against me', chapter: 'The Pre-marital love' },
  { id: 1083, kural_number: 1083, tamil_text: 'பண்டறியேன் கூற்றென் பதனை இனியறிந்தேன் பெண்டகையால் பேரமர்க் கட்டு.', transliteration: 'Pantariyen Kootren Padhanai Iniyarindhen Pentakaiyaal Peramark Kattu', english_meaning: 'I never knew before what is called Yama; I see it now; it is the eyes that carry on a great fight with (the help of) female qualities', career_application: 'I never knew before what is called Yama; I see it now; it is the eyes that carry on a great fight with (the help of) female qualities', chapter: 'The Pre-marital love' },
  { id: 1084, kural_number: 1084, tamil_text: 'கண்டார் உயிருண்ணும் தோற்றத்தால் பெண்டகைப் பேதைக்கு அமர்த்தன கண்.', transliteration: 'Kantaar Uyirunnum Thotraththaal Pentakaip Pedhaikku Amarththana Kan', english_meaning: 'These eyes that seem to kill those who look at them are as it were in hostilities with this feminine simplicity', career_application: 'These eyes that seem to kill those who look at them are as it were in hostilities with this feminine simplicity', chapter: 'The Pre-marital love' },
  { id: 1085, kural_number: 1085, tamil_text: 'கூற்றமோ கண்ணோ பிணையோ மடவரல் நோக்கமிம் மூன்றும் உடைத்து.', transliteration: 'Kootramo Kanno Pinaiyo Matavaral Nokkamim Moondrum Utaiththu', english_meaning: 'Is it Yama, (a pair of) eyes or a hind ?- Are not all these three in the looks of this maid ?', career_application: 'Is it Yama, (a pair of) eyes or a hind ?- Are not all these three in the looks of this maid ?', chapter: 'The Pre-marital love' },
  { id: 1086, kural_number: 1086, tamil_text: 'கொடும்புருவம் கோடா மறைப்பின் நடுங்கஞர் செய்யல மன்இவள் கண்.', transliteration: 'Kotumpuruvam Kotaa Maraippin Natungagnar Seyyala Manival Kan', english_meaning: 'Her eyes will cause (me) no trembling sorrow, if they are properly hidden by her cruel arched eyebrows', career_application: 'Her eyes will cause (me) no trembling sorrow, if they are properly hidden by her cruel arched eyebrows', chapter: 'The Pre-marital love' },
  { id: 1087, kural_number: 1087, tamil_text: 'கடாஅக் களிற்றின்மேற் கட்படாம் மாதர் படாஅ முலைமேல் துகில்.', transliteration: 'Kataaak Kalitrinmer Katpataam Maadhar Pataaa Mulaimel Thukil', english_meaning: 'The cloth that covers the firm bosom of this maiden is (like) that which covers the eyes of a rutting elephant', career_application: 'The cloth that covers the firm bosom of this maiden is (like) that which covers the eyes of a rutting elephant', chapter: 'The Pre-marital love' },
  { id: 1088, kural_number: 1088, tamil_text: 'ஒண்ணுதற் கோஒ உடைந்ததே ஞாட்பினுள் நண்ணாரும் உட்குமென் பீடு.', transliteration: 'Onnudhar Koo Utaindhadhe Gnaatpinul Nannaarum Utkumen Peetu', english_meaning: 'On her bright brow alone is destroyed even that power of mine that used to terrify the most fearless', career_application: 'On her bright brow alone is destroyed even that power of mine that used to terrify the most fearless', chapter: 'The Pre-marital love' },
  { id: 1089, kural_number: 1089, tamil_text: 'பிணையேர் மடநோக்கும் நாணும் உடையாட்கு அணியெவனோ ஏதில தந்து.', transliteration: 'Pinaiyer Matanokkum Naanum Utaiyaatku Aniyevano Edhila Thandhu', english_meaning: 'Of what use are other jewels to her who is adorned with modesty, and the meek looks of a hind ?', career_application: 'Of what use are other jewels to her who is adorned with modesty, and the meek looks of a hind ?', chapter: 'The Pre-marital love' },
  { id: 1090, kural_number: 1090, tamil_text: 'உண்டார்கண் அல்லது அடுநறாக் காமம்போல் கண்டார் மகிழ்செய்தல் இன்று.', transliteration: 'Untaarkan Alladhu Atunaraak Kaamampol Kantaar Makizhseydhal Indru', english_meaning: 'Unlike boiled honey which yields delight only when it is drunk, love gives pleasure even when looked at', career_application: 'Unlike boiled honey which yields delight only when it is drunk, love gives pleasure even when looked at', chapter: 'The Pre-marital love' },
  { id: 1091, kural_number: 1091, tamil_text: 'இருநோக்கு இவளுண்கண் உள்ளது ஒருநோக்கு நோய்நோக்கொன் றந்நோய் மருந்து.', transliteration: 'Irunokku Ivalunkan Ulladhu Orunokku Noinokkon Rannoi Marundhu', english_meaning: 'There are two looks in the dyed eyes of this (fair one); one causes pain, and the other is the cure thereof', career_application: 'There are two looks in the dyed eyes of this (fair one); one causes pain, and the other is the cure thereof', chapter: 'Recognition of the Signs ' },
  { id: 1092, kural_number: 1092, tamil_text: 'கண்களவு கொள்ளும் சிறுநோக்கம் காமத்தில் செம்பாகம் அன்று பெரிது.', transliteration: 'Kankalavu Kollum Sirunokkam Kaamaththil Sempaakam Andru Peridhu', english_meaning: 'A single stolen glance of her eyes is more than half the pleasure (of sexual embrace)', career_application: 'A single stolen glance of her eyes is more than half the pleasure (of sexual embrace)', chapter: 'Recognition of the Signs ' },
  { id: 1093, kural_number: 1093, tamil_text: 'நோக்கினாள் நோக்கி இறைஞ்சினாள் அஃதவள் யாப்பினுள் அட்டிய நீர்.', transliteration: 'Nokkinaal Nokki Irainjinaal Aqdhaval Yaappinul Attiya Neer', english_meaning: 'She has looked (at men) and stooped (her head); and that (sign) waters as it were (the corn of) our love', career_application: 'She has looked (at men) and stooped (her head); and that (sign) waters as it were (the corn of) our love', chapter: 'Recognition of the Signs ' },
  { id: 1094, kural_number: 1094, tamil_text: 'யான்நோக்கும் காலை நிலன்நோக்கும் நோக்காக்கால் தான்நோக்கி மெல்ல நகும்.', transliteration: 'Yaannokkum Kaalai Nilannokkum Nokkaakkaal Thaannokki Mella Nakum', english_meaning: 'When I look, she looks down; when I do not, she looks and smiles gently', career_application: 'When I look, she looks down; when I do not, she looks and smiles gently', chapter: 'Recognition of the Signs ' },
  { id: 1095, kural_number: 1095, tamil_text: 'குறிக்கொண்டு நோக்காமை அல்லால் ஒருகண் சிறக்கணித்தாள் போல நகும்', transliteration: 'Kurikkontu Nokkaamai Allaal Orukan Sirakkaniththaal Pola Nakum', english_meaning: 'She not only avoids a direct look at me, but looks as it were with a half-closed eye and smiles', career_application: 'She not only avoids a direct look at me, but looks as it were with a half-closed eye and smiles', chapter: 'Recognition of the Signs ' },
  { id: 1096, kural_number: 1096, tamil_text: 'உறாஅ தவர்போல் சொலினும் செறாஅர்சொல் ஒல்லை உணரப் படும்.', transliteration: 'Uraaa Thavarpol Solinum Seraaarsol Ollai Unarap Patum', english_meaning: 'Though they may speak harshly as if they were strangers, the words of the friendly are soon understood', career_application: 'Though they may speak harshly as if they were strangers, the words of the friendly are soon understood', chapter: 'Recognition of the Signs ' },
  { id: 1097, kural_number: 1097, tamil_text: 'செறாஅச் சிறுசொல்லும் செற்றார்போல் நோக்கும் உறாஅர்போன்று உற்றார் குறிப்பு.', transliteration: 'Seraaach Chirusollum Setraarpol Nokkum Uraaarpondru Utraar Kurippu', english_meaning: 'Little words that are harsh and looks that are hateful are (but) the expressions of lovers who wish to act like strangers', career_application: 'Little words that are harsh and looks that are hateful are (but) the expressions of lovers who wish to act like strangers', chapter: 'Recognition of the Signs ' },
  { id: 1098, kural_number: 1098, tamil_text: 'அசையியற்கு உண்டாண்டோர் ஏஎர்யான் நோக்கப் பசையினள் பைய நகும்.', transliteration: 'Asaiyiyarku Untaantor Eeryaan Nokkap Pasaiyinal Paiya Nakum', english_meaning: 'When I look, the pitying maid looks in return and smiles gently; and that is a comforting sign for me', career_application: 'When I look, the pitying maid looks in return and smiles gently; and that is a comforting sign for me', chapter: 'Recognition of the Signs ' },
  { id: 1099, kural_number: 1099, tamil_text: 'ஏதிலார் போலப் பொதுநோக்கு நோக்குதல் காதலார் கண்ணே உள.', transliteration: 'Edhilaar Polap Podhunokku Nokkudhal Kaadhalaar Kanne Ula', english_meaning: 'Both the lovers are capable of looking at each other in an ordinary way, as if they were perfect strangers', career_application: 'Both the lovers are capable of looking at each other in an ordinary way, as if they were perfect strangers', chapter: 'Recognition of the Signs ' },
  { id: 1100, kural_number: 1100, tamil_text: 'கண்ணொடு கண்இணை நோக்கொக்கின் வாய்ச்சொற்கள் என்ன பயனும் இல.', transliteration: 'Kannotu Kaninai Nokkokkin Vaaichchorkal Enna Payanum Ila', english_meaning: 'The words of the mouths are of no use whatever, when there is perfect agreement between the eyes (of lovers)', career_application: 'The words of the mouths are of no use whatever, when there is perfect agreement between the eyes (of lovers)', chapter: 'Recognition of the Signs ' },
  { id: 1101, kural_number: 1101, tamil_text: 'கண்டுகேட்டு உண்டுயிர்த்து உற்றறியும் ஐம்புலனும் ஒண்தொடி கண்ணே உள.', transliteration: 'Kantukettu Untuyirththu Utrariyum Aimpulanum Ondhoti Kanne Ula', english_meaning: 'The (simultaneous) enjoyment of the five senses of sight, hearing, taste, smell and touch can only be found with bright braceleted (women)', career_application: 'The (simultaneous) enjoyment of the five senses of sight, hearing, taste, smell and touch can only be found with bright braceleted (women)', chapter: 'Rejoicing in the Embrace' },
  { id: 1102, kural_number: 1102, tamil_text: 'பிணிக்கு மருந்து பிறமன் அணியிழை தன்நோய்க்குத் தானே மருந்து.', transliteration: 'Pinikku Marundhu Piraman Aniyizhai Thannoikkuth Thaane Marundhu', english_meaning: 'The remedy for a disease is always something different (from it); but for the disease caused by this jewelled maid, she is herself the cure', career_application: 'The remedy for a disease is always something different (from it); but for the disease caused by this jewelled maid, she is herself the cure', chapter: 'Rejoicing in the Embrace' },
  { id: 1103, kural_number: 1103, tamil_text: 'தாம்வீழ்வார் மென்றோள் துயிலின் இனிதுகொல் தாமரைக் கண்ணான் உலகு.', transliteration: 'Thaamveezhvaar Mendrol Thuyilin Inidhukol Thaamaraik Kannaan Ulaku', english_meaning: 'Can the lotus-eyed Vishnu\'s heaven be indeed as sweet to those who delight to sleep in the delicate arms of their beloved ?', career_application: 'Can the lotus-eyed Vishnu\'s heaven be indeed as sweet to those who delight to sleep in the delicate arms of their beloved ?', chapter: 'Rejoicing in the Embrace' },
  { id: 1104, kural_number: 1104, tamil_text: 'நீங்கின் தெறூஉம் குறுகுங்கால் தண்ணென்னும் தீயாண்டுப் பெற்றாள் இவள்?', transliteration: 'Neengin Theruum Kurukungaal Thannennum Theeyaantup Petraal Ival?', english_meaning: 'From whence has she got this fire that burns when I withdraw and cools when I approach ?', career_application: 'From whence has she got this fire that burns when I withdraw and cools when I approach ?', chapter: 'Rejoicing in the Embrace' },
  { id: 1105, kural_number: 1105, tamil_text: 'வேட்ட பொழுதின் அவையவை போலுமே தோட்டார் கதுப்பினாள் தோள்.', transliteration: 'Vetta Pozhudhin Avaiyavai Polume Thottaar Kadhuppinaal Thol', english_meaning: 'Each varied form of joy the soul can wish is found', career_application: 'Each varied form of joy the soul can wish is found', chapter: 'Rejoicing in the Embrace' },
  { id: 1106, kural_number: 1106, tamil_text: 'உறுதோறு உயிர்தளிர்ப்பத் தீண்டலால் பேதைக்கு அமிழ்தின் இயன்றன தோள்.', transliteration: 'Urudhoru Uyirdhalirppath Theentalaal Pedhaikku Amizhdhin Iyandrana Thol', english_meaning: 'The shoulders of this fair one are made of ambrosia, for they revive me with pleasure every time I embrace them', career_application: 'The shoulders of this fair one are made of ambrosia, for they revive me with pleasure every time I embrace them', chapter: 'Rejoicing in the Embrace' },
  { id: 1107, kural_number: 1107, tamil_text: 'தம்மில் இருந்து தமதுபாத்து உண்டற்றால் அம்மா அரிவை முயக்கு.', transliteration: 'Thammil Irundhu Thamadhupaaththu Untatraal Ammaa Arivai Muyakku', english_meaning: 'The embraces of a gold-complexioned beautiful female are as pleasant as to dwell in one\'s own house and live by one\'s own (earnings) after distributing (a portion of it in charity)', career_application: 'The embraces of a gold-complexioned beautiful female are as pleasant as to dwell in one\'s own house and live by one\'s own (earnings) after distributing (a portion of it in charity)', chapter: 'Rejoicing in the Embrace' },
  { id: 1108, kural_number: 1108, tamil_text: 'வீழும் இருவர்க்கு இனிதே வளியிடை போழப் படாஅ முயக்கு.', transliteration: 'Veezhum Iruvarkku Inidhe Valiyitai Pozhap Pataaa Muyakku', english_meaning: 'To ardent lovers sweet is the embrace that cannot be penetrated even by a breath of breeze', career_application: 'To ardent lovers sweet is the embrace that cannot be penetrated even by a breath of breeze', chapter: 'Rejoicing in the Embrace' },
  { id: 1109, kural_number: 1109, tamil_text: 'ஊடல் உணர்தல் புணர்தல் இவைகாமம் கூடியார் பெற்ற பயன்.', transliteration: 'Ootal Unardhal Punardhal Ivaikaamam Kootiyaar Petra Payan', english_meaning: 'Love quarrel, reconciliation and intercourse - these are the advantages reaped by those who marry for lust', career_application: 'Love quarrel, reconciliation and intercourse - these are the advantages reaped by those who marry for lust', chapter: 'Rejoicing in the Embrace' },
  { id: 1110, kural_number: 1110, tamil_text: 'அறிதோறு அறியாமை கண்டற்றால் காமம் செறிதோறும் சேயிழை மாட்டு.', transliteration: 'Aridhoru Ariyaamai Kantatraal Kaamam Seridhorum Seyizhai Maattu', english_meaning: 'As (one\'s) ignorance is discovered the more one learns, so does repeated intercourse with a welladorned female (only create a desire for more)', career_application: 'As (one\'s) ignorance is discovered the more one learns, so does repeated intercourse with a welladorned female (only create a desire for more)', chapter: 'Rejoicing in the Embrace' },
  { id: 1111, kural_number: 1111, tamil_text: 'நன்னீரை வாழி அனிச்சமே நின்னினும் மென்னீரள் யாம்வீழ் பவள்.', transliteration: 'Nanneerai Vaazhi Anichchame Ninninum Menneeral Yaamveezh Paval', english_meaning: 'May you flourish, O Anicham! you have a delicate nature But my beloved is more delicate than you', career_application: 'May you flourish, O Anicham! you have a delicate nature But my beloved is more delicate than you', chapter: 'The Praise of her Beauty' },
  { id: 1112, kural_number: 1112, tamil_text: 'மலர்காணின் மையாத்தி நெஞ்சே இவள்கண் பலர்காணும் பூவொக்கும் என்று.', transliteration: 'Malarkaanin Maiyaaththi Nenje Ivalkan Palarkaanum Poovokkum Endru', english_meaning: 'O my soul, fancying that flowers which are seen by many can resemble her eyes, you become confused at the sight of them', career_application: 'O my soul, fancying that flowers which are seen by many can resemble her eyes, you become confused at the sight of them', chapter: 'The Praise of her Beauty' },
  { id: 1113, kural_number: 1113, tamil_text: 'முறிமேனி முத்தம் முறுவல் வெறிநாற்றம் வேலுண்கண் வேய்த்தோ ளவட்கு.', transliteration: 'Murimeni Muththam Muruval Verinaatram Velunkan Veyththo Lavatku', english_meaning: 'The complexion of this bamboo-shouldered one is that of a shoot; her teeth, are pearls; her breath,', career_application: 'The complexion of this bamboo-shouldered one is that of a shoot; her teeth, are pearls; her breath,', chapter: 'The Praise of her Beauty' },
  { id: 1114, kural_number: 1114, tamil_text: 'காணின் குவளை கவிழ்ந்து நிலன்நோக்கும் மாணிழை கண்ணொவ்வேம் என்று.', transliteration: 'Kaanin Kuvalai Kavizhndhu Nilannokkum Maanizhai Kannovvem Endru', english_meaning: 'If the blue lotus could see, it would stoop and look at the ground saying, "I can never resemble the eyes of this excellent jewelled one."', career_application: 'If the blue lotus could see, it would stoop and look at the ground saying, "I can never resemble the eyes of this excellent jewelled one."', chapter: 'The Praise of her Beauty' },
  { id: 1115, kural_number: 1115, tamil_text: 'அனிச்சப்பூக் கால்களையாள் பெய்தாள் நுகப்பிற்கு நல்ல படாஅ பறை.', transliteration: 'Anichchappook Kaalkalaiyaal Peydhaal Nukappirku Nalla Pataaa Parai', english_meaning: 'No merry drums will be beaten for the (tender) waist of her who has adorned herself with the anicham without having removed its stem', career_application: 'No merry drums will be beaten for the (tender) waist of her who has adorned herself with the anicham without having removed its stem', chapter: 'The Praise of her Beauty' },
  { id: 1116, kural_number: 1116, tamil_text: 'மதியும் மடந்தை முகனும் அறியா பதியின் கலங்கிய மீன்.', transliteration: 'Madhiyum Matandhai Mukanum Ariyaa Padhiyin Kalangiya Meen', english_meaning: 'The stars have become confused in their places not being able to distinguish between the moon and the maid\'s countenance', career_application: 'The stars have become confused in their places not being able to distinguish between the moon and the maid\'s countenance', chapter: 'The Praise of her Beauty' },
  { id: 1117, kural_number: 1117, tamil_text: 'அறுவாய் நிறைந்த அவிர்மதிக்குப் க்குப் போல மறுவுண்டோ மாதர் முகத்து.', transliteration: 'Aruvaai Niraindha Avirmadhikkup Pola Maruvunto Maadhar Mukaththu', english_meaning: 'Could there be spots in the face of this maid like those in the bright full moon ?', career_application: 'Could there be spots in the face of this maid like those in the bright full moon ?', chapter: 'The Praise of her Beauty' },
  { id: 1118, kural_number: 1118, tamil_text: 'மாதர் முகம்போல் ஒளிவிட வல்லையேல் காதலை வாழி மத஧.', transliteration: 'Maadhar Mukampol Olivita Vallaiyel Kaadhalai Vaazhi Madhi', english_meaning: 'If you can indeed shine like the face of women, flourish, O moon, for then would you be worth loving ?', career_application: 'If you can indeed shine like the face of women, flourish, O moon, for then would you be worth loving ?', chapter: 'The Praise of her Beauty' },
  { id: 1119, kural_number: 1119, tamil_text: 'மலரன்ன கண்ணாள் முகமொத்தி யாயின் பலர்காணத் தோன்றல் மதி.', transliteration: 'Malaranna Kannaal Mukamoththi Yaayin Palarkaanath Thondral Madhi', english_meaning: 'O moon, if you wish to resemble the face of her whose eyes are like (these) flowers, do not appear so as to be seen by all', career_application: 'O moon, if you wish to resemble the face of her whose eyes are like (these) flowers, do not appear so as to be seen by all', chapter: 'The Praise of her Beauty' },
  { id: 1120, kural_number: 1120, tamil_text: 'அனிச்சமும் அன்னத்தின் தூவியும் மாதர் அடிக்கு நெருஞ்சிப் பழம்.', transliteration: 'Anichchamum Annaththin Thooviyum Maadhar Atikku Nerunjip Pazham', english_meaning: 'The anicham and the feathers of the swan are to the feet of females, like the fruit of the (thorny) Nerunji', career_application: 'The anicham and the feathers of the swan are to the feet of females, like the fruit of the (thorny) Nerunji', chapter: 'The Praise of her Beauty' },
  { id: 1121, kural_number: 1121, tamil_text: 'பாலொடு தேன்கலந் தற்றே பணிமொழி வாலெயிறு ஊறிய நீர்.', transliteration: 'Paalotu Thenkalan Thatre Panimozhi Vaaleyiru Ooriya Neer', english_meaning: 'The water which oozes from the white teeth of this soft speeched damsel is like a mixture of milk and honey', career_application: 'The water which oozes from the white teeth of this soft speeched damsel is like a mixture of milk and honey', chapter: 'Declaration of Love"s special Excellence' },
  { id: 1122, kural_number: 1122, tamil_text: 'உடம்பொடு உயிரிடை என்னமற் றன்ன மடந்தையொடு எம்மிடை நட்பு.', transliteration: 'Utampotu Uyiritai Ennamar Ranna Matandhaiyotu Emmitai Natpu', english_meaning: 'The love between me and this damsel is like the union of body and soul', career_application: 'The love between me and this damsel is like the union of body and soul', chapter: 'Declaration of Love"s special Excellence' },
  { id: 1123, kural_number: 1123, tamil_text: 'கருமணியிற் பாவாய்நீ போதாயாம் வீழும் திருநுதற்கு இல்லை இடம்.', transliteration: 'Karumaniyir Paavaainee Podhaayaam Veezhum Thirunudharku Illai Itam', english_meaning: 'O you image in the pupil (of my eye)! depart; there is no room for (my) fair-browed beloved', career_application: 'O you image in the pupil (of my eye)! depart; there is no room for (my) fair-browed beloved', chapter: 'Declaration of Love"s special Excellence' },
  { id: 1124, kural_number: 1124, tamil_text: 'வாழ்தல் உயிர்க்கன்னள் ஆயிழை சாதல் அதற்கன்னள் நீங்கும் இடத்து.', transliteration: 'Vaazhdhal Uyirkkannal Aayizhai Saadhal Adharkannal Neengum Itaththu', english_meaning: 'My fair-jewelled one resembles the living soul (when she is in union with me), the dying soul when she leaves me', career_application: 'My fair-jewelled one resembles the living soul (when she is in union with me), the dying soul when she leaves me', chapter: 'Declaration of Love"s special Excellence' },
  { id: 1125, kural_number: 1125, tamil_text: 'உள்ளுவன் மன்யான் மறப்பின் மறப்பறியேன் ஒள்ளமர்க் கண்ணாள் குணம்.', transliteration: 'Ulluvan Manyaan Marappin Marappariyen Ollamark Kannaal Kunam', english_meaning: 'If I had forgotten her who has bright battling eyes, I would have remembered (thee); but I never forget her (Thus says he to her maid)', career_application: 'If I had forgotten her who has bright battling eyes, I would have remembered (thee); but I never forget her (Thus says he to her maid)', chapter: 'Declaration of Love"s special Excellence' },
  { id: 1126, kural_number: 1126, tamil_text: 'கண்ணுள்ளின் போகார் இமைப்பின் பருகுவரா நுண்ணியர்எம் காத லவர்.', transliteration: 'Kannullin Pokaar Imaippin Parukuvaraa Nunniyarem Kaadha Lavar', english_meaning: 'My lover would not depart from mine eyes; even if I wink, he would not suffer (from pain); he is so ethereal', career_application: 'My lover would not depart from mine eyes; even if I wink, he would not suffer (from pain); he is so ethereal', chapter: 'Declaration of Love"s special Excellence' },
  { id: 1127, kural_number: 1127, tamil_text: 'கண்ணுள்ளார் காத லவராகக் கண்ணும் எழுதேம் கரப்பாக்கு அறிந்து.', transliteration: 'Kannullaar Kaadha Lavaraakak Kannum Ezhudhem Karappaakku Arindhu', english_meaning: 'As my lover abides in my eyes, I will not even paint them, for he would (then) have to conceal himself', career_application: 'As my lover abides in my eyes, I will not even paint them, for he would (then) have to conceal himself', chapter: 'Declaration of Love"s special Excellence' },
  { id: 1128, kural_number: 1128, tamil_text: 'நெஞ்சத்தார் காத லவராக வெய்துண்டல் அஞ்சுதும் வேபாக் கறிந்து.', transliteration: 'Nenjaththaar Kaadha Lavaraaka Veydhuntal Anjudhum Vepaak Karindhu', english_meaning: 'As my lover is in my heart, I am afraid of eating (anything) hot, for I know it would pain him', career_application: 'As my lover is in my heart, I am afraid of eating (anything) hot, for I know it would pain him', chapter: 'Declaration of Love"s special Excellence' },
  { id: 1129, kural_number: 1129, tamil_text: 'இமைப்பின் கரப்பாக்கு அறிவல் அனைத்திற்கே ஏதிலர் என்னும் இவ் வூர்.', transliteration: 'Imaippin Karappaakku Arival Anaiththirke Edhilar Ennum Iv Voor', english_meaning: 'I will not wink, knowing that if I did, my lover would hide himself; and for this reason, this town says, he is unloving', career_application: 'I will not wink, knowing that if I did, my lover would hide himself; and for this reason, this town says, he is unloving', chapter: 'Declaration of Love"s special Excellence' },
  { id: 1130, kural_number: 1130, tamil_text: 'உவந்துறைவர் உள்ளத்துள் என்றும் இகந்துறைவர் ஏதிலர் என்னும் இவ் வூர்.', transliteration: 'Uvandhuraivar Ullaththul Endrum Ikandhuraivar Edhilar Ennum Iv Voor', english_meaning: 'My lover dwells in my heart with perpetual delight; but the town says he is unloving and (therefore) dwells afar', career_application: 'My lover dwells in my heart with perpetual delight; but the town says he is unloving and (therefore) dwells afar', chapter: 'Declaration of Love"s special Excellence' },
  { id: 1131, kural_number: 1131, tamil_text: 'காமம் உழந்து வருந்தினார்க்கு ஏமம் மடலல்லது இல்லை வலி.', transliteration: 'Kaamam Uzhandhu Varundhinaarkku Emam Matalalladhu Illai Vali', english_meaning: 'To those who after enjoyment of sexual pleasure suffer (for want of more), there is no help so efficient as the palmyra horse', career_application: 'To those who after enjoyment of sexual pleasure suffer (for want of more), there is no help so efficient as the palmyra horse', chapter: 'The Abandonment of Reserve' },
  { id: 1132, kural_number: 1132, tamil_text: 'நோனா உடம்பும் உயிரும் மடலேறும் நாணினை நீக்கி நிறுத்து.', transliteration: 'Nonaa Utampum Uyirum Matalerum Naaninai Neekki Niruththu', english_meaning: 'Having got rid of shame, the suffering body and soul save themselves on the palmyra horse', career_application: 'Having got rid of shame, the suffering body and soul save themselves on the palmyra horse', chapter: 'The Abandonment of Reserve' },
  { id: 1133, kural_number: 1133, tamil_text: 'நாணொடு நல்லாண்மை பண்டுடையேன் இன்றுடையேன் காமுற்றார் ஏறும் மடல்.', transliteration: 'Naanotu Nallaanmai Pantutaiyen Indrutaiyen Kaamutraar Erum Matal', english_meaning: 'Modesty and manliness were once my own; now, my own is the palmyra horse that is ridden by the lustful', career_application: 'Modesty and manliness were once my own; now, my own is the palmyra horse that is ridden by the lustful', chapter: 'The Abandonment of Reserve' },
  { id: 1134, kural_number: 1134, tamil_text: 'காமக் கடும்புனல் உய்க்கும் நாணொடு நல்லாண்மை என்னும் புணை.', transliteration: 'Kaamak Katumpunal Uykkum Naanotu Nallaanmai Ennum Punai', english_meaning: 'The raft of modesty and manliness, is, alas, carried-off by the strong current of lust', career_application: 'The raft of modesty and manliness, is, alas, carried-off by the strong current of lust', chapter: 'The Abandonment of Reserve' },
  { id: 1135, kural_number: 1135, tamil_text: 'தொடலைக் குறுந்தொடி தந்தாள் மடலொடு மாலை உழக்கும் துயர்.', transliteration: 'Thotalaik Kurundhoti Thandhaal Matalotu Maalai Uzhakkum Thuyar', english_meaning: 'She with the small garland-like bracelets has given me the palmyra horse and the sorrow that is endured at night', career_application: 'She with the small garland-like bracelets has given me the palmyra horse and the sorrow that is endured at night', chapter: 'The Abandonment of Reserve' },
  { id: 1136, kural_number: 1136, tamil_text: 'மடலூர்தல் யாமத்தும் உள்ளுவேன் மன்ற படல்ஒல்லா பேதைக்கென் கண்.', transliteration: 'Mataloordhal Yaamaththum Ulluven Mandra Patalollaa Pedhaikken Kan', english_meaning: 'Mine eyes will not close in sleep on your mistress\'s account; even at midnight will I think of mounting the palmyra horse', career_application: 'Mine eyes will not close in sleep on your mistress\'s account; even at midnight will I think of mounting the palmyra horse', chapter: 'The Abandonment of Reserve' },
  { id: 1137, kural_number: 1137, tamil_text: 'கடலன்ன காமம் உழந்தும் மடலேறாப் பெண்ணின் பெருந்தக்க தில்.', transliteration: 'Katalanna Kaamam Uzhandhum Mataleraap Pennin Perundhakka Thil', english_meaning: 'There is nothing so noble as the womanly nature that would not ride the palmyra horse, though plunged a sea of lust', career_application: 'There is nothing so noble as the womanly nature that would not ride the palmyra horse, though plunged a sea of lust', chapter: 'The Abandonment of Reserve' },
  { id: 1138, kural_number: 1138, tamil_text: 'நிறையரியர் மன்அளியர் என்னாது காமம் மறையிறந்து மன்று படும்.', transliteration: 'Niraiyariyar Manaliyar Ennaadhu Kaamam Maraiyirandhu Mandru Patum', english_meaning: 'Even the Lust (of women) transgresses its secrecy and appears in public, forgetting that they are too chaste and liberal (to be overcome by it)', career_application: 'Even the Lust (of women) transgresses its secrecy and appears in public, forgetting that they are too chaste and liberal (to be overcome by it)', chapter: 'The Abandonment of Reserve' },
  { id: 1139, kural_number: 1139, tamil_text: 'அறிகிலார் எல்லாரும் என்றேஎன் காமம் மறுகின் மறுகும் மருண்டு.', transliteration: 'Arikilaar Ellaarum Endreen Kaamam Marukin Marukum Maruntu', english_meaning: 'And thus, in public ways, perturbed will rove', career_application: 'And thus, in public ways, perturbed will rove', chapter: 'The Abandonment of Reserve' },
  { id: 1140, kural_number: 1140, tamil_text: 'யாம்கண்ணின் காண நகுப அறிவில்லார் யாம்பட்ட தாம்படா ஆறு.', transliteration: 'Yaamkannin Kaana Nakupa Arivillaar Yaampatta Thaampataa Aaru', english_meaning: 'Even strangers laugh (at us) so as to be seen by us, for they have not suffered', career_application: 'Even strangers laugh (at us) so as to be seen by us, for they have not suffered', chapter: 'The Abandonment of Reserve' },
  { id: 1141, kural_number: 1141, tamil_text: 'அலரெழ ஆருயிர் நிற்கும் அதனைப் பலரறியார் பாக்கியத் தால்.', transliteration: 'Alarezha Aaruyir Na�rkum Adhanaip Palarariyaar Paakkiyath Thaal', english_meaning: 'My precious life is saved by the raise of rumour, and this, to my good luck no others are aware of', career_application: 'My precious life is saved by the raise of rumour, and this, to my good luck no others are aware of', chapter: 'The Announcement of the Rumour' },
  { id: 1142, kural_number: 1142, tamil_text: 'மலரன்ன கண்ணாள் அருமை அறியாது அலரெமக்கு ஈந்ததிவ் வூர்.', transliteration: 'Malaranna Kannaal Arumai Ariyaadhu Alaremakku Eendhadhiv Voor', english_meaning: 'Not knowing the value of her whose eyes are like flowers this town has got up a rumour about me', career_application: 'Not knowing the value of her whose eyes are like flowers this town has got up a rumour about me', chapter: 'The Announcement of the Rumour' },
  { id: 1143, kural_number: 1143, tamil_text: 'உறாஅதோ ஊரறிந்த கெளவை அதனைப் பெறாஅது பெற்றன்ன நீர்த்து.', transliteration: 'Uraaadho Oorarindha Kelavai Adhanaip Peraaadhu Petranna Neerththu', english_meaning: 'Will I not get a rumour that is known to the (whole) town ? For what I have not got is as if I had got it (already)', career_application: 'Will I not get a rumour that is known to the (whole) town ? For what I have not got is as if I had got it (already)', chapter: 'The Announcement of the Rumour' },
  { id: 1144, kural_number: 1144, tamil_text: 'கவ்வையால் கவ்விது காமம் அதுவின்றேல் தவ்வென்னும் தன்மை இழந்து.', transliteration: 'Kavvaiyaal Kavvidhu Kaamam Adhuvindrel Thavvennum Thanmai Izhandhu', english_meaning: 'Rumour increases the violence of my passion; without it it would grow weak and waste away', career_application: 'Rumour increases the violence of my passion; without it it would grow weak and waste away', chapter: 'The Announcement of the Rumour' },
  { id: 1145, kural_number: 1145, tamil_text: 'களித்தொறும் கள்ளுண்டல் வேட்டற்றால் காமம் வெளிப்படுந் தோறும் இனிது.', transliteration: 'Kaliththorum Kalluntal Vettatraal Kaamam Velippatun Thorum Inidhu', english_meaning: 'As drinking liquor is delightful (to one) whenever one is in mirth, so is lust delightful to me whenever it is the subject of rumour', career_application: 'As drinking liquor is delightful (to one) whenever one is in mirth, so is lust delightful to me whenever it is the subject of rumour', chapter: 'The Announcement of the Rumour' },
  { id: 1146, kural_number: 1146, tamil_text: 'கண்டது மன்னும் ஒருநாள் அலர்மன்னும் திங்களைப் பாம்புகொண் டற்று.', transliteration: 'Kantadhu Mannum Orunaal Alarmannum Thingalaip Paampukon Tatru', english_meaning: 'It was but a single day that I looked on (my lover); but the rumour thereof has spread like the seizure of the moon by the serpent', career_application: 'It was but a single day that I looked on (my lover); but the rumour thereof has spread like the seizure of the moon by the serpent', chapter: 'The Announcement of the Rumour' },
  { id: 1147, kural_number: 1147, tamil_text: 'ஊரவர் கெளவை எருவாக அன்னைசொல் நீராக நீளும்இந் நோய்.', transliteration: 'Ooravar Kelavai Eruvaaka Annaisol Neeraaka Neelumin Noi', english_meaning: 'This malady (of lust) is manured by the talk of women and watered by the (harsh) words of my mother', career_application: 'This malady (of lust) is manured by the talk of women and watered by the (harsh) words of my mother', chapter: 'The Announcement of the Rumour' },
  { id: 1148, kural_number: 1148, tamil_text: 'நெய்யால் எரிநுதுப்பேம் என்றற்றால் கெளவையால் காமம் நுதுப்பேம் எனல்.', transliteration: 'Neyyaal Erinudhuppem Endratraal Kelavaiyaal Kaamam Nudhuppem Enal', english_meaning: 'To say that one could extinguish passion by rumour is like extinguishing fire with ghee', career_application: 'To say that one could extinguish passion by rumour is like extinguishing fire with ghee', chapter: 'The Announcement of the Rumour' },
  { id: 1149, kural_number: 1149, tamil_text: 'அலர்நாண ஒல்வதோ அஞ்சலோம்பு என்றார் பலர்நாண நீத்தக் கடை.', transliteration: 'Alarnaana Olvadho Anjalompu Endraar Palarnaana Neeththak Katai', english_meaning: 'When the departure of him who said "fear not" has put me to shame before others, why need I be ashamed of scandal', career_application: 'When the departure of him who said "fear not" has put me to shame before others, why need I be ashamed of scandal', chapter: 'The Announcement of the Rumour' },
  { id: 1150, kural_number: 1150, tamil_text: 'தாம்வேண்டின் நல்குவர் காதலர் யாம்வேண்டும் கெளவை எடுக்கும்இவ் வூர்.', transliteration: 'Thaamventin Nalkuvar Kaadhalar Yaamventum Kelavai Etukkumiv Voor', english_meaning: 'The rumour I desire is raised by the town (itself); and my lover would if desired consent (to my following him)', career_application: 'The rumour I desire is raised by the town (itself); and my lover would if desired consent (to my following him)', chapter: 'The Announcement of the Rumour' },
  { id: 1151, kural_number: 1151, tamil_text: 'செல்லாமை உண்டேல் எனக்குரை மற்றுநின் வல்வரவு வாழ்வார்க் குரை.', transliteration: 'Sellaamai Untel Enakkurai Matrunin Valvaravu Vaazhvaark Kurai', english_meaning: 'If it is not departure, tell me; but if it is your speedy return, tell it to those who would be alive then', career_application: 'If it is not departure, tell me; but if it is your speedy return, tell it to those who would be alive then', chapter: 'Separation unendurable' },
  { id: 1152, kural_number: 1152, tamil_text: 'இன்கண் உடைத்தவர் பார்வல் பிரிவஞ்சும் புன்கண் உடைத்தால் புணர்வு.', transliteration: 'Inkan Utaiththavar Paarval Pirivanjum Punkan Utaiththaal Punarvu', english_meaning: 'His very look was once pleasing; but (now) even intercourse is painful through fear of separation', career_application: 'His very look was once pleasing; but (now) even intercourse is painful through fear of separation', chapter: 'Separation unendurable' },
  { id: 1153, kural_number: 1153, tamil_text: 'அரிதரோ தேற்றம் அறிவுடையார் கண்ணும் பிரிவோ ரிடத்துண்மை யான்.', transliteration: 'Aridharo Thetram Arivutaiyaar Kannum Pirivo Ritaththunmai Yaan', english_meaning: 'As even the lover who understands (everything) may at times depart, confidence is hardly possible', career_application: 'As even the lover who understands (everything) may at times depart, confidence is hardly possible', chapter: 'Separation unendurable' },
  { id: 1154, kural_number: 1154, tamil_text: 'அளித்தஞ்சல் என்றவர் நீப்பின் தெளித்தசொல் தேறியார்க்கு உண்டோ தவறு.', transliteration: 'Aliththanjal Endravar Neeppin Theliththasol Theriyaarkku Unto Thavaru', english_meaning: 'If he who bestowed his love and said "fear not" should depart, will it be the fault of those who believed in (his) assuring words ?', career_application: 'If he who bestowed his love and said "fear not" should depart, will it be the fault of those who believed in (his) assuring words ?', chapter: 'Separation unendurable' },
  { id: 1155, kural_number: 1155, tamil_text: 'ஓம்பின் அமைந்தார் பிரிவோம்பல் மற்றவர் நீங்கின் அரிதால் புணர்வு.', transliteration: 'Ompin Amaindhaar Pirivompal Matravar Neengin Aridhaal Punarvu', english_meaning: 'If you would save (my life), delay the departure of my destined (husband); for if he departs, intercourse will become impossible', career_application: 'If you would save (my life), delay the departure of my destined (husband); for if he departs, intercourse will become impossible', chapter: 'Separation unendurable' },
  { id: 1156, kural_number: 1156, tamil_text: 'பிரிவுரைக்கும் வன்கண்ணர் ஆயின் அரிதவர் நல்குவர் என்னும் நசை.', transliteration: 'Pirivuraikkum Vankannar Aayin Aridhavar Nalkuvar Ennum Nasai', english_meaning: 'Is hard, when he could stand, and of departure speak to me', career_application: 'Is hard, when he could stand, and of departure speak to me', chapter: 'Separation unendurable' },
  { id: 1157, kural_number: 1157, tamil_text: 'துறைவன் துறந்தமை தூற்றாகொல் முன்கை இறைஇறவா நின்ற வளை.', transliteration: 'Thuraivan Thurandhamai Thootraakol Munkai Iraiiravaa Nindra Valai', english_meaning: 'Do not the rings that begin to slide down my fingers forebode the separation of my lord ?', career_application: 'Do not the rings that begin to slide down my fingers forebode the separation of my lord ?', chapter: 'Separation unendurable' },
  { id: 1158, kural_number: 1158, tamil_text: 'இன்னாது இனன்இல்ஊர் வாழ்தல் அதனினும் இன்னாது இனியார்ப் பிரிவு.', transliteration: 'Innaadhu Inaniloor Vaazhdhal Adhaninum Innaadhu Iniyaarp Pirivu', english_meaning: 'Painful is it to live in a friendless town; but far more painful is it to part from one\'s lover', career_application: 'Painful is it to live in a friendless town; but far more painful is it to part from one\'s lover', chapter: 'Separation unendurable' },
  { id: 1159, kural_number: 1159, tamil_text: 'தொடிற்சுடின் அல்லது காமநோய் போல விடிற்சுடல் ஆற்றுமோ தீ.', transliteration: 'Thotirsutin Alladhu Kaamanoi Pola Vitirsutal Aatrumo Thee', english_meaning: 'Fire burns when touched; but, like the sickness of love, can it also burn when removed ?', career_application: 'Fire burns when touched; but, like the sickness of love, can it also burn when removed ?', chapter: 'Separation unendurable' },
  { id: 1160, kural_number: 1160, tamil_text: 'அரிதாற்றி அல்லல்நோய் நீக்கிப் பிரிவாற்றிப் பின்இருந்து வாழ்வார் பலர்.', transliteration: 'Aridhaatri Allalnoi Neekkip Pirivaatrip Pinirundhu Vaazhvaar Palar', english_meaning: 'As if there were many indeed that can consent to the impossible, kill their pain, endure separation and yet continue to live afterwards', career_application: 'As if there were many indeed that can consent to the impossible, kill their pain, endure separation and yet continue to live afterwards', chapter: 'Separation unendurable' },
  { id: 1161, kural_number: 1161, tamil_text: 'மறைப்பேன்மன் யானிஃதோ நோயை இறைப்பவர்க்கு ஊற்றுநீர் போல மிகும்.', transliteration: 'Maraippenman Yaaniqdho Noyai Iraippavarkku Ootruneer Pola Mikum', english_meaning: 'I would hide this pain from others; but it (only) swells like a spring to those who drain it', career_application: 'I would hide this pain from others; but it (only) swells like a spring to those who drain it', chapter: 'Complainings' },
  { id: 1162, kural_number: 1162, tamil_text: 'கரத்தலும் ஆற்றேன்இந் நோயைநோய் செய்தார்க்கு உரைத்தலும் நாணுத் தரும்.', transliteration: 'Karaththalum Aatrenin Noyainoi Seydhaarkku Uraiththalum Naanuth Tharum', english_meaning: 'I cannot conceal this pain, nor can I relate it without shame to him who has caused it', career_application: 'I cannot conceal this pain, nor can I relate it without shame to him who has caused it', chapter: 'Complainings' },
  { id: 1163, kural_number: 1163, tamil_text: 'காமமும் நாணும் உயிர்காவாத் தூங்கும்என் நோனா உடம்பின் அகத்து.', transliteration: 'Kaamamum Naanum Uyirkaavaath Thoongumen Nonaa Utampin Akaththu', english_meaning: '(Both) lust and shame, with my soul for their shoulder pole balance themselves on a body that cannot bear them', career_application: '(Both) lust and shame, with my soul for their shoulder pole balance themselves on a body that cannot bear them', chapter: 'Complainings' },
  { id: 1164, kural_number: 1164, tamil_text: 'காமக் கடல்மன்னும் உண்டே அதுநீந்தும் ஏமப் புணைமன்னும் இல்.', transliteration: 'Kaamak Katalmannum Unte Adhuneendhum Emap Punaimannum Il', english_meaning: 'There is indeed a flood of lust; but there is no raft of safety to cross it with', career_application: 'There is indeed a flood of lust; but there is no raft of safety to cross it with', chapter: 'Complainings' },
  { id: 1165, kural_number: 1165, tamil_text: 'துப்பின் எவனாவர் மன்கொல் துயர்வரவு நட்பினுள் ஆற்று பவர்.', transliteration: 'Thuppin Evanaavar Mankol Thuyarvaravu Natpinul Aatru Pavar', english_meaning: 'What will they prove when angry tempests lower?', career_application: 'What will they prove when angry tempests lower?', chapter: 'Complainings' },
  { id: 1166, kural_number: 1166, tamil_text: 'இன்பம் கடல்மற்றுக் காமம் அஃதடுங்கால் துன்பம் அதனிற் பெரிது.', transliteration: 'Inpam Katalmatruk Kaamam Aqdhatungaal Thunpam Adhanir Peridhu', english_meaning: 'The pleasure of lust is (as great as) the sea; but the pain of lust is far greater', career_application: 'The pleasure of lust is (as great as) the sea; but the pain of lust is far greater', chapter: 'Complainings' },
  { id: 1167, kural_number: 1167, tamil_text: 'காமக் கடும்புனல் நீந்திக் கரைகாணேன் யாமத்தும் யானே உளேன்.', transliteration: 'Kaamak Katumpunal Neendhik Karaikaanen Yaamaththum Yaane Ulen', english_meaning: 'I have swam across the terrible flood of lust, but have not seen its shore; even at midnight I am alone; still I live', career_application: 'I have swam across the terrible flood of lust, but have not seen its shore; even at midnight I am alone; still I live', chapter: 'Complainings' },
  { id: 1168, kural_number: 1168, tamil_text: 'மன்னுயிர் எல்லாம் துயிற்றி அளித்திரா என்னல்லது இல்லை துணை.', transliteration: 'Mannuyir Ellaam Thuyitri Aliththiraa Ennalladhu Illai Thunai', english_meaning: 'The night which graciously lulls to sleep all living creatures, has me alone for her companion', career_application: 'The night which graciously lulls to sleep all living creatures, has me alone for her companion', chapter: 'Complainings' },
  { id: 1169, kural_number: 1169, tamil_text: 'கொடியார் கொடுமையின் தாம்கொடிய இந்நாள் நெடிய கழியும் இரா.', transliteration: 'Kotiyaar Kotumaiyin Thaamkotiya Innaal Netiya Kazhiyum Iraa', english_meaning: 'The long nights of these days are far more cruel than the heartless one who is torturing me', career_application: 'The long nights of these days are far more cruel than the heartless one who is torturing me', chapter: 'Complainings' },
  { id: 1170, kural_number: 1170, tamil_text: 'உள்ளம்போன்று உள்வழிச் செல்கிற்பின் வெள்ளநீர் நீந்தல மன்னோஎன் கண்.', transliteration: 'Ullampondru Ulvazhich Chelkirpin Vellaneer Neendhala Mannoen Kan', english_meaning: 'Could mine eyes travel like my thoughts to the abode (of my absent lord), they would not swim in this flood of tears', career_application: 'Could mine eyes travel like my thoughts to the abode (of my absent lord), they would not swim in this flood of tears', chapter: 'Complainings' },
  { id: 1171, kural_number: 1171, tamil_text: 'கண்தாம் கலுழ்வ தெவன்கொலோ தண்டாநோய் தாம்காட்ட யாம்கண் டது.', transliteration: 'Kandhaam Kaluzhva Thevankolo Thantaanoi Thaamkaatta Yaamkan Tadhu', english_meaning: 'As this incurable malady has been caused by my eyes which showed (him) to me, why should they now weep for (him)', career_application: 'As this incurable malady has been caused by my eyes which showed (him) to me, why should they now weep for (him)', chapter: 'Eyes consumed with Grief' },
  { id: 1172, kural_number: 1172, tamil_text: 'தெரிந்துணரா நோக்கிய உண்கண் பரிந்துணராப் பைதல் உழப்பது எவன்?', transliteration: 'Therindhunaraa Nokkiya Unkan Parindhunaraap Paidhal Uzhappadhu Evan?', english_meaning: 'The dyed eyes that (then) looked without foresight, why should they now endure sorrow, without feeling sharply (their own fault)', career_application: 'The dyed eyes that (then) looked without foresight, why should they now endure sorrow, without feeling sharply (their own fault)', chapter: 'Eyes consumed with Grief' },
  { id: 1173, kural_number: 1173, tamil_text: 'கதுமெனத் தாநோக்கித் தாமே கலுழும் இதுநகத் தக்க துடைத்து.', transliteration: 'Kadhumenath Thaanokkith Thaame Kaluzhum Ithunakath Thakka Thutaiththu', english_meaning: 'They themselves looked eagerly (on him) and now they weep. Is not this to be laughed at ?', career_application: 'They themselves looked eagerly (on him) and now they weep. Is not this to be laughed at ?', chapter: 'Eyes consumed with Grief' },
  { id: 1174, kural_number: 1174, tamil_text: 'பெயலாற்றா நீருலந்த உண்கண் உயலாற்றா உய்வில்நோய் என்கண் நிறுத்து.', transliteration: 'Peyalaatraa Neerulandha Unkan Uyalaatraa Uyvilnoi Enkan Niruththu', english_meaning: 'These painted eyes have caused me a lasting mortal disease; and now they can weep no more, the tears having dried up', career_application: 'These painted eyes have caused me a lasting mortal disease; and now they can weep no more, the tears having dried up', chapter: 'Eyes consumed with Grief' },
  { id: 1175, kural_number: 1175, tamil_text: 'படலாற்றா பைதல் உழக்கும் கடலாற்றாக் காமநோய் செய்தஎன் கண்.', transliteration: 'Patalaatraa Paidhal Uzhakkum Katalaatraak Kaamanoi Seydhaen Kan', english_meaning: 'Mine eyes have caused me a lust that is greater than the sea and (they themselves) endure the torture of sleeplessness', career_application: 'Mine eyes have caused me a lust that is greater than the sea and (they themselves) endure the torture of sleeplessness', chapter: 'Eyes consumed with Grief' },
  { id: 1176, kural_number: 1176, tamil_text: 'ஓஒ இனிதே எமக்கிந்நோய் செய்தகண் தாஅம் இதற்பட் டது.', transliteration: 'Oo Inidhe Emakkinnoi Seydhakan Thaaam Itharpat Tadhu', english_meaning: 'The eyes that have given me this disease have themselves been seized with this (suffering) Oh! I am much delighted', career_application: 'The eyes that have given me this disease have themselves been seized with this (suffering) Oh! I am much delighted', chapter: 'Eyes consumed with Grief' },
  { id: 1177, kural_number: 1177, tamil_text: 'உழந்துழந் துள்நீர் அறுக விழைந்திழைந்து வேண்டி அவர்க்கண்ட கண்.', transliteration: 'Uzhandhuzhan Thulneer Aruka Vizhaindhizhaindhu Venti Avarkkanta Kan', english_meaning: 'The eyes that became tender and gazed intently on him, may they suffer so much as to dry up the fountain of their tears', career_application: 'The eyes that became tender and gazed intently on him, may they suffer so much as to dry up the fountain of their tears', chapter: 'Eyes consumed with Grief' },
  { id: 1178, kural_number: 1178, tamil_text: 'பேணாது பெட்டார் உளர்மன்னோ மற்றவர்க் காணாது அமைவில கண்.', transliteration: 'Penaadhu Pettaar Ularmanno Matravark Kaanaadhu Amaivila Kan', english_meaning: 'He is indeed here who loved me with his lips but not with his heart but mine eyes suffer from not seeing him', career_application: 'He is indeed here who loved me with his lips but not with his heart but mine eyes suffer from not seeing him', chapter: 'Eyes consumed with Grief' },
  { id: 1179, kural_number: 1179, tamil_text: 'வாராக்கால் துஞ்சா வரின்துஞ்சா ஆயிடை ஆரஞர் உற்றன கண்.', transliteration: 'Vaaraakkaal Thunjaa Varindhunjaa Aayitai Aaragnar Utrana Kan', english_meaning: 'When he is away they do not sleep; when he is present they do not sleep; in either case, mine eyes endure unbearable agony', career_application: 'When he is away they do not sleep; when he is present they do not sleep; in either case, mine eyes endure unbearable agony', chapter: 'Eyes consumed with Grief' },
  { id: 1180, kural_number: 1180, tamil_text: 'மறைபெறல் ஊரார்க்கு அரிதன்றால் எம்போல் அறைபறை கண்ணார் அகத்து.', transliteration: 'Maraiperal Ooraarkku Aridhandraal Empol Araiparai Kannaar Akaththu', english_meaning: 'It is not difficult for the people of this place to understand the secret of those whose eyes, like mine, are as it were beaten drums', career_application: 'It is not difficult for the people of this place to understand the secret of those whose eyes, like mine, are as it were beaten drums', chapter: 'Eyes consumed with Grief' },
  { id: 1181, kural_number: 1181, tamil_text: 'நயந்தவர்க்கு நல்காமை நேர்ந்தேன் பசந்தவென் பண்பியார்க்கு உரைக்கோ பிற.', transliteration: 'Nayandhavarkku Nalkaamai Nerndhen Pasandhaven Panpiyaarkku Uraikko Pira', english_meaning: 'I who (then) consented to the absence of my loving lord, to whom can I (now) relate the fact of my having turned sallow', career_application: 'I who (then) consented to the absence of my loving lord, to whom can I (now) relate the fact of my having turned sallow', chapter: 'The Pallid Hue' },
  { id: 1182, kural_number: 1182, tamil_text: 'அவர்தந்தார் என்னும் தகையால் இவர்தந்தென் மேனிமேல் ஊரும் பசப்பு.', transliteration: 'Avardhandhaar Ennum Thakaiyaal Ivardhandhen Menimel Oorum Pasappu', english_meaning: 'Sallowness, as if proud of having been caused by him, would now ride on my person', career_application: 'Sallowness, as if proud of having been caused by him, would now ride on my person', chapter: 'The Pallid Hue' },
  { id: 1183, kural_number: 1183, tamil_text: 'சாயலும் நாணும் அவர்கொண்டார் கைம்மாறா நோயும் பசலையும் தந்து.', transliteration: 'Saayalum Naanum Avarkontaar Kaimmaaraa Noyum Pasalaiyum Thandhu', english_meaning: 'He has taken (away) my beauty and modesty, and given me instead disease and sallowness', career_application: 'He has taken (away) my beauty and modesty, and given me instead disease and sallowness', chapter: 'The Pallid Hue' },
  { id: 1184, kural_number: 1184, tamil_text: 'உள்ளுவன் மன்யான் உரைப்பது அவர்திறமால் கள்ளம் பிறவோ பசப்பு.', transliteration: 'Ulluvan Manyaan Uraippadhu Avardhiramaal Kallam Piravo Pasappu', english_meaning: 'I think (of him); and what I speak about is but his excellence; still is there sallowness; and this is deceitful', career_application: 'I think (of him); and what I speak about is but his excellence; still is there sallowness; and this is deceitful', chapter: 'The Pallid Hue' },
  { id: 1185, kural_number: 1185, tamil_text: 'உவக்காண்எம் காதலர் செல்வார் இவக்காண்என் மேனி பசப்பூர் வது.', transliteration: 'Uvakkaanem Kaadhalar Selvaar Ivakkaanen Meni Pasappoor Vadhu', english_meaning: 'Just as my lover departed then, did not sallowness spread here on my person ?', career_application: 'Just as my lover departed then, did not sallowness spread here on my person ?', chapter: 'The Pallid Hue' },
  { id: 1186, kural_number: 1186, tamil_text: 'விளக்கற்றம் பார்க்கும் இருளேபோல் கொண்கன் முயக்கற்றம் பார்க்கும் பசப்பு.', transliteration: 'Vilakkatram Paarkkum Irulepol Konkan Muyakkatram Paarkkum Pasappu', english_meaning: 'Just as darkness waits for the failing light; so does sallowness wait for the laxity of my husband\'s intercourse', career_application: 'Just as darkness waits for the failing light; so does sallowness wait for the laxity of my husband\'s intercourse', chapter: 'The Pallid Hue' },
  { id: 1187, kural_number: 1187, tamil_text: 'புல்லிக் கிடந்தேன் புடைபெயர்ந்தேன் அவ்வளவில் அள்ளிக்கொள் வற்றே பசப்பு.', transliteration: 'Pullik Kitandhen Putaipeyarndhen Avvalavil Allikkol Vatre Pasappu', english_meaning: 'I who was in close embrace just turned aside and the moment I did so, sallowness came on me like something to be seized on', career_application: 'I who was in close embrace just turned aside and the moment I did so, sallowness came on me like something to be seized on', chapter: 'The Pallid Hue' },
  { id: 1188, kural_number: 1188, tamil_text: 'பசந்தாள் இவள்என்பது அல்லால் இவளைத் துறந்தார் அவர்என்பார் இல்.', transliteration: 'Pasandhaal Ivalenpadhu Allaal Ivalaith Thurandhaar Avarenpaar Il', english_meaning: 'Besides those who say "she has turned sallow" there are none who say "he has forsaken her"', career_application: 'Besides those who say "she has turned sallow" there are none who say "he has forsaken her"', chapter: 'The Pallid Hue' },
  { id: 1189, kural_number: 1189, tamil_text: 'பசக்கமன் பட்டாங்கென் மேனி நயப்பித்தார் நன்னிலையர் ஆவர் எனின்.', transliteration: 'Pasakkaman Pattaangen Meni Nayappiththaar Nannilaiyar Aavar Enin', english_meaning: 'If he is clear of guilt who has conciliated me (to his departure) let my body suffer its due and turn sallow', career_application: 'If he is clear of guilt who has conciliated me (to his departure) let my body suffer its due and turn sallow', chapter: 'The Pallid Hue' },
  { id: 1190, kural_number: 1190, tamil_text: 'பசப்பெனப் பேர்பெறுதல் நன்றே நயப்பித்தார் நல்காமை தூற்றார் எனின்.', transliteration: 'Pasappenap Perperudhal Nandre Nayappiththaar Nalkaamai Thootraar Enin', english_meaning: 'It would be good to be said of me that I have turned sallow, if friends do not reproach with unkindness him who pleased me (then)', career_application: 'It would be good to be said of me that I have turned sallow, if friends do not reproach with unkindness him who pleased me (then)', chapter: 'The Pallid Hue' },
  { id: 1191, kural_number: 1191, tamil_text: 'தாம்வீழ்வார் தம்வீழப் பெற்றவர் பெற்றாரே காமத்துக் காழில் கனி.', transliteration: 'Thaamveezhvaar Thamveezhap Petravar Petraare Kaamaththuk Kaazhil Kani', english_meaning: 'The women who are beloved by those whom they love, have they have not got the stone-less fruit of sexual delight ?', career_application: 'The women who are beloved by those whom they love, have they have not got the stone-less fruit of sexual delight ?', chapter: 'The Solitary Anguish' },
  { id: 1192, kural_number: 1192, tamil_text: 'வாழ்வார்க்கு வானம் பயந்தற்றால் வீழ்வார்க்கு வீழ்வார் அள஧ க்கும் அளி.', transliteration: 'Vaazhvaarkku Vaanam Payandhatraal Veezhvaarkku Veezhvaar Ala� Kkum Ali', english_meaning: 'The bestowal of love by the beloved on those who love them is like the rain raining (at the proper season) on those who live by it', career_application: 'The bestowal of love by the beloved on those who love them is like the rain raining (at the proper season) on those who live by it', chapter: 'The Solitary Anguish' },
  { id: 1193, kural_number: 1193, tamil_text: 'வீழுநர் வீழப் படுவார்க்கு அமையுமே வாழுநம் என்னும் செருக்கு.', transliteration: 'Veezhunar Veezhap Patuvaarkku Amaiyume Vaazhunam Ennum Serukku', english_meaning: 'The pride that says "we shall live" suits only those who are loved by their beloved (husbands)', career_application: 'The pride that says "we shall live" suits only those who are loved by their beloved (husbands)', chapter: 'The Solitary Anguish' },
  { id: 1194, kural_number: 1194, tamil_text: 'வீழப் படுவார் கெழீஇயிலர் தாம்வீழ்வார் வீழப் படாஅர் எனின்.', transliteration: 'Veezhap Patuvaar Kezheeiyilar Thaamveezhvaar Veezhap Pataaar Enin', english_meaning: 'Even those who are esteemed (by other women) are devoid of excellence, if they are not loved by their beloved', career_application: 'Even those who are esteemed (by other women) are devoid of excellence, if they are not loved by their beloved', chapter: 'The Solitary Anguish' },
  { id: 1195, kural_number: 1195, tamil_text: 'நாம்காதல் கொண்டார் நமக்கெவன் செய்பவோ தாம்காதல் கொள்ளாக் கடை.', transliteration: 'Naamkaadhal Kontaar Namakkevan Seypavo Thaamkaadhal Kollaak Katai', english_meaning: 'He who is beloved by me, what will he do to me, if I am not beloved by him ?', career_application: 'He who is beloved by me, what will he do to me, if I am not beloved by him ?', chapter: 'The Solitary Anguish' },
  { id: 1196, kural_number: 1196, tamil_text: 'ஒருதலையான் இன்னாது காமம்காப் போல இருதலை யானும் இனிது.', transliteration: 'Orudhalaiyaan Innaadhu Kaamamkaap Pola Irudhalai Yaanum Inidhu', english_meaning: 'Lust, like the weight of the KAVADI, pains if it lies in one end only but pleases if it is in both', career_application: 'Lust, like the weight of the KAVADI, pains if it lies in one end only but pleases if it is in both', chapter: 'The Solitary Anguish' },
  { id: 1197, kural_number: 1197, tamil_text: 'பருவரலும் பைதலும் காணான்கொல் காமன் ஒருவர்கண் நின்றொழுகு வான்.', transliteration: 'Paruvaralum Paidhalum Kaanaankol Kaaman Oruvarkan Nindrozhuku Vaan', english_meaning: 'Would not cupid who abides and contends in one party (only) witness the pain and sorrow (in that party)?', career_application: 'Would not cupid who abides and contends in one party (only) witness the pain and sorrow (in that party)?', chapter: 'The Solitary Anguish' },
  { id: 1198, kural_number: 1198, tamil_text: 'வீழ்வாரின் இன்சொல் பெறாஅது உலகத்து வாழ்வாரின் வன்கணார் இல்.', transliteration: 'Veezhvaarin Insol Peraaadhu Ulakaththu Vaazhvaarin Vankanaar Il', english_meaning: 'There is no one in the world so hard-hearted as those who can live without receiving (even) a kind word from their beloved', career_application: 'There is no one in the world so hard-hearted as those who can live without receiving (even) a kind word from their beloved', chapter: 'The Solitary Anguish' },
  { id: 1199, kural_number: 1199, tamil_text: 'நசைஇயார் நல்கார் எனினும் அவர்மாட்டு இசையும் இனிய செவிக்கு.', transliteration: 'Nasaiiyaar Nalkaar Eninum Avarmaattu Isaiyum Iniya Sevikku', english_meaning: 'Though my beloved bestows no love on one, still are his words sweet to my ears', career_application: 'Though my beloved bestows no love on one, still are his words sweet to my ears', chapter: 'The Solitary Anguish' },
  { id: 1200, kural_number: 1200, tamil_text: 'உறாஅர்க்கு உறுநோய் உரைப்பாய் கடலைச் செறாஅஅய் வாழிய நெஞ்சு.', transliteration: 'Uraaarkku Urunoi Uraippaai Katalaich Cheraaaai Vaazhiya Nenju', english_meaning: 'Live, O my soul, would you who relate your great sorrow to strangers, try rather to fill up your own sea (of sorrow)', career_application: 'Live, O my soul, would you who relate your great sorrow to strangers, try rather to fill up your own sea (of sorrow)', chapter: 'The Solitary Anguish' },
  { id: 1201, kural_number: 1201, tamil_text: 'உள்ளினும் தீராப் பெருமகிழ் செய்தலால் கள்ளினும் காமம் இனிது.', transliteration: 'Ullinum Theeraap Perumakizh Seydhalaal Kallinum Kaamam Inidhu', english_meaning: 'Sexuality is sweeter than liquor, because when remembered, it creates a most rapturous delight', career_application: 'Sexuality is sweeter than liquor, because when remembered, it creates a most rapturous delight', chapter: 'Sad Memories' },
  { id: 1202, kural_number: 1202, tamil_text: 'எனைத்தொனறு இனிதேகாண் காமம்தாம் வீழ்வார் நினைப்ப வருவதொன்று ஏல்.', transliteration: 'Enaiththonaru Inidhekaan Kaamamdhaam Veezhvaar Ninaippa Varuvadhondru El', english_meaning: 'Even to think of one\'s beloved gives one no pain Sexuality, in any degree, is always delightful', career_application: 'Even to think of one\'s beloved gives one no pain Sexuality, in any degree, is always delightful', chapter: 'Sad Memories' },
  { id: 1203, kural_number: 1203, tamil_text: 'நினைப்பவர் போன்று நினையார்கொல் தும்மல் சினைப்பது போன்று கெடும்.', transliteration: 'Ninaippavar Pondru Ninaiyaarkol Thummal Sinaippadhu Pondru Ketum', english_meaning: 'I feel as if I am going to sneeze but do not, and (therefore) my beloved is about to think (of me) but does not', career_application: 'I feel as if I am going to sneeze but do not, and (therefore) my beloved is about to think (of me) but does not', chapter: 'Sad Memories' },
  { id: 1204, kural_number: 1204, tamil_text: 'யாமும் உளேங்கொல் அவர்நெஞ்சத்து எந்நெஞ்சத்து ஓஒ உளரே அவர்.', transliteration: 'Yaamum Ulengol Avarnenjaththu Ennenjaththu Oo Ulare Avar', english_meaning: 'He continues to abide in my soul, do I likewise abide in his ?', career_application: 'He continues to abide in my soul, do I likewise abide in his ?', chapter: 'Sad Memories' },
  { id: 1205, kural_number: 1205, tamil_text: 'தம்நெஞ்சத்து எம்மைக் கடிகொண்டார் நாணார்கொல் எம்நெஞ்சத்து ஓவா வரல்.', transliteration: 'Thamnenjaththu Emmaik Katikontaar Naanaarkol Emnenjaththu Ovaa Varal', english_meaning: 'He who has imprisoned me in his soul, is he ashamed to enter incessantly into mine', career_application: 'He who has imprisoned me in his soul, is he ashamed to enter incessantly into mine', chapter: 'Sad Memories' },
  { id: 1206, kural_number: 1206, tamil_text: 'மற்றியான் என்னுளேன் மன்னோ அவரொடியான் உற்றநாள் உள்ள உளேன்.', transliteration: 'Matriyaan Ennulen Manno Avaroti Yaan Utranaal Ulla Ulen', english_meaning: 'I live by remembering my (former) intercourse with him; if it were not so, how could I live ?', career_application: 'I live by remembering my (former) intercourse with him; if it were not so, how could I live ?', chapter: 'Sad Memories' },
  { id: 1207, kural_number: 1207, tamil_text: 'மறப்பின் எவனாவன் மற்கொல் மறப்பறியேன் உள்ளினும் உள்ளம் சுடும்.', transliteration: 'Marappin Evanaavan Markol Marappariyen Ullinum Ullam Sutum', english_meaning: 'I have never forgotten (the pleasure); even to think of it burns my soul; could I live, if I should ever forget it ?', career_application: 'I have never forgotten (the pleasure); even to think of it burns my soul; could I live, if I should ever forget it ?', chapter: 'Sad Memories' },
  { id: 1208, kural_number: 1208, tamil_text: 'எனைத்து நினைப்பினும் காயார் அனைத்தன்றோ காதலர் செய்யும் சிறப்பு.', transliteration: 'Enaiththu Ninaippinum Kaayaar Anaiththandro Kaadhalar Seyyum Sirappu', english_meaning: 'He will not be angry however much I may think of him; is it not so much the delight my beloved', career_application: 'He will not be angry however much I may think of him; is it not so much the delight my beloved', chapter: 'Sad Memories' },
  { id: 1209, kural_number: 1209, tamil_text: 'விளியுமென் இன்னுயிர் வேறல்லம் என்பார் அளியின்மை ஆற்ற நினைந்து.', transliteration: 'Viliyumen Innuyir Verallam Enpaar Aliyinmai Aatra Ninaindhu', english_meaning: 'My precious life is wasting away by thinking too much on the cruelty of him who said we were not different', career_application: 'My precious life is wasting away by thinking too much on the cruelty of him who said we were not different', chapter: 'Sad Memories' },
  { id: 1210, kural_number: 1210, tamil_text: 'விடாஅது சென்றாரைக் கண்ணினால் காணப் படாஅதி வாழி மதி.', transliteration: 'Vitaaadhu Sendraaraik Kanninaal Kaanap Pataaadhi Vaazhi Madhi', english_meaning: 'May you live, O Moon! Do not set, that I mine see him who has departed without quitting my soul', career_application: 'May you live, O Moon! Do not set, that I mine see him who has departed without quitting my soul', chapter: 'Sad Memories' },
  { id: 1211, kural_number: 1211, tamil_text: 'காதலர் தூதொடு வந்த கனவினுக்கு யாதுசெய் வேன்கொல் விருந்து.', transliteration: 'Kaadhalar Thoodhotu Vandha Kanavinukku Yaadhusey Venkol Virundhu', english_meaning: 'Where with shall I feast the dream which has brought me my dear one\'s messenger ?', career_application: 'Where with shall I feast the dream which has brought me my dear one\'s messenger ?', chapter: 'The Visions of the Night' },
  { id: 1212, kural_number: 1212, tamil_text: 'கயலுண்கண் யானிரப்பத் துஞ்சிற் கலந்தார்க்கு உயலுண்மை சாற்றுவேன் மன்.', transliteration: 'Kayalunkan Yaanirappath Thunjir Kalandhaarkku Uyalunmai Saatruven Man', english_meaning: 'If my fish-like painted eyes should, at my begging, close in sleep, I could fully relate my sufferings to my lord', career_application: 'If my fish-like painted eyes should, at my begging, close in sleep, I could fully relate my sufferings to my lord', chapter: 'The Visions of the Night' },
  { id: 1213, kural_number: 1213, tamil_text: 'நனவினால் நல்கா தவரைக் கனவினால் காண்டலின் உண்டென் உயிர்.', transliteration: 'Nanavinaal Nalkaa Thavaraik Kanavinaal Kaantalin Unten Uyir', english_meaning: 'My life lasts because in my dream I behold him who does not favour me in my waking hours', career_application: 'My life lasts because in my dream I behold him who does not favour me in my waking hours', chapter: 'The Visions of the Night' },
  { id: 1214, kural_number: 1214, tamil_text: 'கனவினான் உண்டாகும் காமம் நனவினான் நல்காரை நாடித் தரற்கு.', transliteration: 'Kanavinaan Untaakum Kaamam Nanavinaan Nalkaarai Naatith Thararku', english_meaning: 'There is pleasure in my dream, because in it I seek and obtain him who does not visit me in my wakefulness', career_application: 'There is pleasure in my dream, because in it I seek and obtain him who does not visit me in my wakefulness', chapter: 'The Visions of the Night' },
  { id: 1215, kural_number: 1215, tamil_text: 'நனவினால் கண்டதூஉம் ஆங்கே கனவுந்தான் கண்ட பொழுதே இனிது.', transliteration: 'Nanavinaal Kantadhooum Aange Kanavundhaan Kanta Pozhudhe Inidhu', english_meaning: 'I saw him in my waking hours, and then it was pleasant; I see him just now in my dream, and it is (equally) pleasant', career_application: 'I saw him in my waking hours, and then it was pleasant; I see him just now in my dream, and it is (equally) pleasant', chapter: 'The Visions of the Night' },
  { id: 1216, kural_number: 1216, tamil_text: 'நனவென ஒன்றில்லை ஆயின் கனவினால் காதலர் நீங்கலர் மன்.', transliteration: 'Nanavena Ondrillai Aayin Kanavinaal Kaadhalar Neengalar Man', english_meaning: 'Were there no such thing as wakefulness, my beloved (who visited me) in my dream would not depart from me', career_application: 'Were there no such thing as wakefulness, my beloved (who visited me) in my dream would not depart from me', chapter: 'The Visions of the Night' },
  { id: 1217, kural_number: 1217, tamil_text: 'நனவினால் நல்காக் கொடியார் கனவனால் என்எம்மைப் பீழிப் பது.', transliteration: 'Nanavinaal Nalkaak Kotiyaar Kanavanaal Enemmaip Peezhip Padhu', english_meaning: 'The cruel one who would not favour me in my wakefulness, what right has he to torture me in my dreams?', career_application: 'The cruel one who would not favour me in my wakefulness, what right has he to torture me in my dreams?', chapter: 'The Visions of the Night' },
  { id: 1218, kural_number: 1218, tamil_text: 'துஞ்சுங்கால் தோள்மேலர் ஆகி விழிக்குங்கால் நெஞ்சத்தர் ஆவர் விரைந்து.', transliteration: 'Thunjungaal Tholmelar Aaki Vizhikkungaal Nenjaththar Aavar Viraindhu', english_meaning: 'When I am asleep he rests on my shoulders, (but) when I awake he hastens into my soul', career_application: 'When I am asleep he rests on my shoulders, (but) when I awake he hastens into my soul', chapter: 'The Visions of the Night' },
  { id: 1219, kural_number: 1219, tamil_text: 'நனவினால் நல்காரை நோவர் கனவினால் காதலர்க் காணா தவர்.', transliteration: 'Nanavinaal Nalkaarai Novar Kanavinaal Kaadhalark Kaanaa Thavar', english_meaning: 'They who have no dear ones to behold in their dreams blame him who visits me not in my waking hours', career_application: 'They who have no dear ones to behold in their dreams blame him who visits me not in my waking hours', chapter: 'The Visions of the Night' },
  { id: 1220, kural_number: 1220, tamil_text: 'நனவினால் நம்நீத்தார் என்பர் கனவினால் காணார்கொல் இவ்வூ ரவர்.', transliteration: 'Nanavinaal Namneeththaar Enpar Kanavinaal Kaanaarkol Ivvoo Ravar', english_meaning: 'The women of this place say he has forsaken me in my wakefulness I think they have not seen him visit me in my dreams', career_application: 'The women of this place say he has forsaken me in my wakefulness I think they have not seen him visit me in my dreams', chapter: 'The Visions of the Night' },
  { id: 1221, kural_number: 1221, tamil_text: 'மாலையோ அல்லை மணந்தார் உயிருண்ணும் வேலைநீ வாழி பொழுது.', transliteration: 'Maalaiyo Allai Manandhaar Uyirunnum Velainee Vaazhi Pozhudhu', english_meaning: 'Live, O you evening are you (the former) evening? No, you are the season that slays (married) women', career_application: 'Live, O you evening are you (the former) evening? No, you are the season that slays (married) women', chapter: 'Lamentations at Eventide' },
  { id: 1222, kural_number: 1222, tamil_text: 'புன்கண்ணை வாழி மருள்மாலை எம்கேள்போல் வன்கண்ண தோநின் துணை.', transliteration: 'Punkannai Vaazhi Marulmaalai Emkelpol Vankanna Thonin Thunai', english_meaning: 'A long life to you, O dark evening! You are sightless Is your help-mate (also) as hard-hearted as mine', career_application: 'A long life to you, O dark evening! You are sightless Is your help-mate (also) as hard-hearted as mine', chapter: 'Lamentations at Eventide' },
  { id: 1223, kural_number: 1223, tamil_text: 'பனிஅரும்பிப் பைதல்கொள் மாலை துனிஅரும்பித் துன்பம் வளர வரும்.', transliteration: 'Paniarumpip Paidhalkol Maalai Thuniarumpith Thunpam Valara Varum', english_meaning: 'The evening that (once) came in with trembling and dimness (now) brings me an aversion for life and increasing sorrow', career_application: 'The evening that (once) came in with trembling and dimness (now) brings me an aversion for life and increasing sorrow', chapter: 'Lamentations at Eventide' },
  { id: 1224, kural_number: 1224, tamil_text: 'காதலர் இல்வழி மாலை கொலைக்களத்து ஏதிலர் போல வரும்.', transliteration: 'Kaadhalar Ilvazhi Maalai Kolaikkalaththu Edhilar Pola Varum', english_meaning: 'In the absence of my lover, evening comes in like slayers on the field of slaughter', career_application: 'In the absence of my lover, evening comes in like slayers on the field of slaughter', chapter: 'Lamentations at Eventide' },
  { id: 1225, kural_number: 1225, tamil_text: 'காலைக்குச் செய்தநன்று என்கொல் எவன்கொல்யான் மாலைக்குச் செய்த பகை?', transliteration: 'Kaalaikkuch Cheydhanandru Enkol Evankolyaan Maalaikkuch Cheydha Pakai?', english_meaning: 'O eve, why art thou foe! thou dost renew my grief', career_application: 'O eve, why art thou foe! thou dost renew my grief', chapter: 'Lamentations at Eventide' },
  { id: 1226, kural_number: 1226, tamil_text: 'மாலைநோய் செய்தல் மணந்தார் அகலாத காலை அறிந்த திலேன்.', transliteration: 'Maalainoi Seydhal Manandhaar Akalaadha Kaalai Arindha Thilen', english_meaning: 'Previous to my husband\'s departure, I know not the painful nature of evening', career_application: 'Previous to my husband\'s departure, I know not the painful nature of evening', chapter: 'Lamentations at Eventide' },
  { id: 1227, kural_number: 1227, tamil_text: 'காலை அரும்பிப் பகலெல்லாம் போதாகி மாலை மலரும்இந் நோய்.', transliteration: 'Kaalai Arumpip Pakalellaam Podhaaki Maalai Malarumin Noi', english_meaning: 'This malady buds forth in the morning, expands all day long and blossoms in the evening', career_application: 'This malady buds forth in the morning, expands all day long and blossoms in the evening', chapter: 'Lamentations at Eventide' },
  { id: 1228, kural_number: 1228, tamil_text: 'அழல்போலும் மாலைக்குத் தூதாகி ஆயன் குழல்போலும் கொல்லும் படை.', transliteration: 'Azhalpolum Maalaikkuth Thoodhaaki Aayan Kuzhalpolum Kollum Patai', english_meaning: 'The shepherd\'s flute now sounds as a fiery forerunner of night, and is become a weapon that slays (me)', career_application: 'The shepherd\'s flute now sounds as a fiery forerunner of night, and is become a weapon that slays (me)', chapter: 'Lamentations at Eventide' },
  { id: 1229, kural_number: 1229, tamil_text: 'பதிமருண்டு பைதல் உழக்கும் மதிமருண்டு மாலை படர்தரும் போழ்து.', transliteration: 'Padhimaruntu Paidhal Uzhakkum Madhimaruntu Maalai Patardharum Pozhdhu', english_meaning: 'When night comes on confusing (everyone\'s) mind, the (whole) town will lose its sense and be plunged in sorrow', career_application: 'When night comes on confusing (everyone\'s) mind, the (whole) town will lose its sense and be plunged in sorrow', chapter: 'Lamentations at Eventide' },
  { id: 1230, kural_number: 1230, tamil_text: 'பொருள்மாலை யாளரை உள்ளி மருள்மாலை மாயும்என் மாயா உயிர்.', transliteration: 'Porulmaalai Yaalarai Ulli Marulmaalai Maayumen Maayaa Uyir', english_meaning: 'My (hitherto) unextinguished life is now lost in this bewildering night at the thought of him who has the nature of wealth', career_application: 'My (hitherto) unextinguished life is now lost in this bewildering night at the thought of him who has the nature of wealth', chapter: 'Lamentations at Eventide' },
  { id: 1231, kural_number: 1231, tamil_text: 'சிறுமை நமக்கொழியச் சேட்சென்றார் உள்ளி நறுமலர் நாணின கண்.', transliteration: 'Sirumai Namakkozhiyach Chetchendraar Ulli Narumalar Naanina Kan', english_meaning: 'While we endure the unbearable sorrow, your eyes weep for him who is gone afar, and shun (the sight of) fragrant flowers', career_application: 'While we endure the unbearable sorrow, your eyes weep for him who is gone afar, and shun (the sight of) fragrant flowers', chapter: 'Wasting Away' },
  { id: 1232, kural_number: 1232, tamil_text: 'நயந்தவர் நல்காமை சொல்லுவ போலும் பசந்து பனிவாரும் கண்.', transliteration: 'Nayandhavar Nalkaamai Solluva Polum Pasandhu Panivaarum Kan', english_meaning: 'The discoloured eyes that shed tears profusely seem to betray the unkindness of our beloved', career_application: 'The discoloured eyes that shed tears profusely seem to betray the unkindness of our beloved', chapter: 'Wasting Away' },
  { id: 1233, kural_number: 1233, tamil_text: 'தணந்தமை சால அறிவிப்ப போலும் மணந்தநாள் வீங்கிய தோள்.', transliteration: 'Thanandhamai Saala Arivippa Polum Manandhanaal Veengiya Thol', english_meaning: 'The shoulders that swelled on the day of our union (now) seem to announce our separation clearly (to the public)', career_application: 'The shoulders that swelled on the day of our union (now) seem to announce our separation clearly (to the public)', chapter: 'Wasting Away' },
  { id: 1234, kural_number: 1234, tamil_text: 'பணைநீங்கிப் பைந்தொடி சோரும் துணைநீங்கித் தொல்கவின் வாடிய தோள்.', transliteration: 'Panaineengip Paindhoti Sorum Thunaineengith Tholkavin Vaatiya Thol', english_meaning: 'In the absence of your consort, your shoulders having lost their former beauty and fulness, your bracelets of pure gold have become loose', career_application: 'In the absence of your consort, your shoulders having lost their former beauty and fulness, your bracelets of pure gold have become loose', chapter: 'Wasting Away' },
  { id: 1235, kural_number: 1235, tamil_text: 'கொடியார் கொடுமை உரைக்கும் தொடியொடு தொல்கவின் வாடிய தோள்.', transliteration: 'Kotiyaar Kotumai Uraikkum Thotiyotu Tholkavin Vaatiya Thol', english_meaning: 'The (loosened) bracelets, and the shoulders from which the old beauty has faded, relate the cruelty of the pitiless one', career_application: 'The (loosened) bracelets, and the shoulders from which the old beauty has faded, relate the cruelty of the pitiless one', chapter: 'Wasting Away' },
  { id: 1236, kural_number: 1236, tamil_text: 'தொடியொடு தோள்நெகிழ நோவல் அவரைக் கொடியர் எனக்கூறல் நொந்து.', transliteration: 'Thotiyotu Tholnekizha Noval Avaraik Kotiyar Enakkooral Nondhu', english_meaning: 'I am greatly pained to hear you call him a cruel man, just because your shoulders are reduced and your bracelets loosened', career_application: 'I am greatly pained to hear you call him a cruel man, just because your shoulders are reduced and your bracelets loosened', chapter: 'Wasting Away' },
  { id: 1237, kural_number: 1237, tamil_text: 'பாடு பெறுதியோ நெஞ்சே கொடியார்க்கென் வாடுதோட் பூசல் உரைத்து.', transliteration: 'Paatu Perudhiyo Nenje Kotiyaarkken Vaatudhot Poosal Uraiththu', english_meaning: 'Can you O my soul! gain glory by relating to the (so-called) cruel one the clamour of my fading shoulders?', career_application: 'Can you O my soul! gain glory by relating to the (so-called) cruel one the clamour of my fading shoulders?', chapter: 'Wasting Away' },
  { id: 1238, kural_number: 1238, tamil_text: 'முயங்கிய கைகளை ஊக்கப் பசந்தது பைந்தொடிப் பேதை நுதல்.', transliteration: 'Muyangiya Kaikalai Ookkap Pasandhadhu Paindhotip Pedhai Nudhal', english_meaning: 'When I once loosened the arms that were in embrace, the forehead of the gold-braceleted women turned sallow', career_application: 'When I once loosened the arms that were in embrace, the forehead of the gold-braceleted women turned sallow', chapter: 'Wasting Away' },
  { id: 1239, kural_number: 1239, tamil_text: 'முயக்கிடைத் தண்வளி போழப் பசப்புற்ற பேதை பெருமழைக் கண்.', transliteration: 'Muyakkitaith Thanvali Pozhap Pasapputra Pedhai Perumazhaik Kan', english_meaning: 'When but a breath of breeze penetrated our embrace, her large cool eyes became sallow', career_application: 'When but a breath of breeze penetrated our embrace, her large cool eyes became sallow', chapter: 'Wasting Away' },
  { id: 1240, kural_number: 1240, tamil_text: 'கண்ணின் பசப்போ பருவரல் எய்தின்றே ஒண்ணுதல் செய்தது கண்டு.', transliteration: 'Kannin Pasappo Paruvaral Eydhindre Onnudhal Seydhadhu Kantu', english_meaning: 'Was it at the sight of what the bright forehead had done that the sallowness of her eyes became sad?', career_application: 'Was it at the sight of what the bright forehead had done that the sallowness of her eyes became sad?', chapter: 'Wasting Away' },
  { id: 1241, kural_number: 1241, tamil_text: 'நினைத்தொன்று சொல்லாயோ நெஞ்சே எனைத்தொன்றும் எவ்வநோய் தீர்க்கும் மருந்து.', transliteration: 'Ninaiththondru Sollaayo Nenje Enaiththondrum Evvanoi Theerkkum Marundhu', english_meaning: 'O my soul, will you not think and tell me some medicine be it what it may, that can cure this incurable malady?', career_application: 'O my soul, will you not think and tell me some medicine be it what it may, that can cure this incurable malady?', chapter: 'Soliloquy' },
  { id: 1242, kural_number: 1242, tamil_text: 'காதல் அவரிலர் ஆகநீ நோவது பேதைமை வாழியென் நெஞ்சு.', transliteration: 'Kaadhal Avarilar Aakanee Novadhu Pedhaimai Vaazhiyen Nenju', english_meaning: 'Is folly, fare thee well my heart!', career_application: 'Is folly, fare thee well my heart!', chapter: 'Soliloquy' },
  { id: 1243, kural_number: 1243, tamil_text: 'இருந்துள்ளி என்பரிதல் நெஞ்சே பரிந்துள்ளல் பைதல்நோய் செய்தார்கண் இல்.', transliteration: 'Irundhulli Enparidhal Nenje Parindhullal Paidhalnoi Seydhaarkan Il', english_meaning: 'O my soul! why remain (here) and suffer thinking (of him)? There are no lewd thoughts (of you) in him who has caused you this disease of sorrow', career_application: 'O my soul! why remain (here) and suffer thinking (of him)? There are no lewd thoughts (of you) in him who has caused you this disease of sorrow', chapter: 'Soliloquy' },
  { id: 1244, kural_number: 1244, tamil_text: 'கண்ணும் கொளச்சேறி நெஞ்சே இவையென்னைத் தின்னும் அவர்க்காணல் உற்று.', transliteration: 'Kannum Kolachcheri Nenje Ivaiyennaith Thinnum Avarkkaanal Utru', english_meaning: 'O my soul! take my eyes also with you, (if not), these would eat me up (in their desire) to see him', career_application: 'O my soul! take my eyes also with you, (if not), these would eat me up (in their desire) to see him', chapter: 'Soliloquy' },
  { id: 1245, kural_number: 1245, tamil_text: 'செற்றார் எனக்கை விடல்உண்டோ நெஞ்சேயாம் உற்றால் உறாஅ தவர்.', transliteration: 'Setraar Enakkai Vitalunto Nenjeyaam Utraal Uraaa Thavar', english_meaning: 'O my soul! can he who loves not though he is beloved, be forsaken saying he hates me (now)?', career_application: 'O my soul! can he who loves not though he is beloved, be forsaken saying he hates me (now)?', chapter: 'Soliloquy' },
  { id: 1246, kural_number: 1246, tamil_text: 'கலந்துணர்த்தும் காதலர்க் கண்டாற் புலந்துணராய் பொய்க்காய்வு காய்திஎன் நெஞ்சு.', transliteration: 'Kalandhunarththum Kaadhalark Kantaar Pulandhunaraai Poikkaaivu Kaaidhien Nenju', english_meaning: 'O my soul! when you see the dear one who remove dislike by intercourse, you are displeased and continue to be so Nay, your displeasure is (simply) false', career_application: 'O my soul! when you see the dear one who remove dislike by intercourse, you are displeased and continue to be so Nay, your displeasure is (simply) false', chapter: 'Soliloquy' },
  { id: 1247, kural_number: 1247, tamil_text: 'காமம் விடுஒன்றோ நாண்விடு நன்னெஞ்சே யானோ பொறேன்இவ் விரண்டு.', transliteration: 'Kaamam Vituondro Naanvitu Nannenje Yaano Poreniv Virantu', english_meaning: 'O my good soul, give up either lust or honour, as for me I can endure neither', career_application: 'O my good soul, give up either lust or honour, as for me I can endure neither', chapter: 'Soliloquy' },
  { id: 1248, kural_number: 1248, tamil_text: 'பரிந்தவர் நல்காரென்று ஏங்கிப் பிரிந்தவர் பின்செல்வாய் பேதைஎன் நெஞ்சு.', transliteration: 'Parindhavar Nalkaarendru Engip Pirindhavar Pinselvaai Pedhaien Nenju', english_meaning: 'You are a fool, O my soul! to go after my departed one, while you mourn that he is not kind enough to favour you', career_application: 'You are a fool, O my soul! to go after my departed one, while you mourn that he is not kind enough to favour you', chapter: 'Soliloquy' },
  { id: 1249, kural_number: 1249, tamil_text: 'உள்ளத்தார் காத லவரால் உள்ளிநீ யாருழைச் சேறியென் நெஞ்சு.', transliteration: 'Ullaththaar Kaadha Lavaraal Ullinee Yaaruzhaich Cheriyen Nenju', english_meaning: 'O my soul! to whom would you repair, while the dear one is within yourself?', career_application: 'O my soul! to whom would you repair, while the dear one is within yourself?', chapter: 'Soliloquy' },
  { id: 1250, kural_number: 1250, tamil_text: 'துன்னாத் துறந்தாரை நெஞ்சத்து உடையேமா இன்னும் இழத்தும் கவின்.', transliteration: 'Thunnaath Thurandhaarai Nenjaththu Utaiyemaa Innum Izhaththum Kavin', english_meaning: 'If I retain in my heart him who has left me without befriending me, I shall lose even the (inward) beauty that remains', career_application: 'If I retain in my heart him who has left me without befriending me, I shall lose even the (inward) beauty that remains', chapter: 'Soliloquy' },
  { id: 1251, kural_number: 1251, tamil_text: 'காமக் கணிச்சி உடைக்கும் நிறையென்னும் நாணுத்தாழ் வீழ்த்த கதவு.', transliteration: 'Kaamak Kanichchi Utaikkum Niraiyennum Naanuththaazh Veezhththa Kadhavu', english_meaning: 'The axe of lust can break the door of chastity which is bolted with the bolt of modesty', career_application: 'The axe of lust can break the door of chastity which is bolted with the bolt of modesty', chapter: 'Reserve Overcome' },
  { id: 1252, kural_number: 1252, tamil_text: 'காமம் எனவொன்றோ கண்ணின்றென் நெஞ்சத்தை யாமத்தும் ஆளும் தொழில்.', transliteration: 'Kaamam Enavondro Kannindren Nenjaththai Yaamaththum Aalum Thozhil', english_meaning: 'Even at midnight is my mind worried by lust, and this one thing, alas! is without mercy', career_application: 'Even at midnight is my mind worried by lust, and this one thing, alas! is without mercy', chapter: 'Reserve Overcome' },
  { id: 1253, kural_number: 1253, tamil_text: 'மறைப்பேன்மன் காமத்தை யானோ குறிப்பின்றித் தும்மல்போல் தோன்றி விடும்.', transliteration: 'Maraippenman Kaamaththai Yaano Kurippindrith Thummalpol Thondri Vitum', english_meaning: 'I would conceal my lust, but alas, it yields not to my will but breaks out like a sneeze', career_application: 'I would conceal my lust, but alas, it yields not to my will but breaks out like a sneeze', chapter: 'Reserve Overcome' },
  { id: 1254, kural_number: 1254, tamil_text: 'நிறையுடையேன் என்பேன்மன் யானோஎன் காமம் மறையிறந்து மன்று படும்.', transliteration: 'Niraiyutaiyen Enpenman Yaanoen Kaamam Maraiyirandhu Mandru Patum', english_meaning: 'I say I would be firm, but alas, my malady breaks out from its concealment and appears in public', career_application: 'I say I would be firm, but alas, my malady breaks out from its concealment and appears in public', chapter: 'Reserve Overcome' },
  { id: 1255, kural_number: 1255, tamil_text: 'செற்றார்பின் செல்லாப் பெருந்தகைமை காமநோய் உற்றார் அறிவதொன்று அன்று.', transliteration: 'Setraarpin Sellaap Perundhakaimai Kaamanoi Utraar Arivadhondru Andru', english_meaning: 'The dignity that would not go after an absent lover is not known to those who are sticken by love', career_application: 'The dignity that would not go after an absent lover is not known to those who are sticken by love', chapter: 'Reserve Overcome' },
  { id: 1256, kural_number: 1256, tamil_text: 'செற்றவர் பின்சேறல் வேண்டி அளித்தரோ எற்றென்னை உற்ற துயர்.', transliteration: 'Setravar Pinseral Venti Aliththaro Etrennai Utra Thuyar', english_meaning: 'The sorrow I have endured by desiring to go after my absent lover, in what way is it excellent?', career_application: 'The sorrow I have endured by desiring to go after my absent lover, in what way is it excellent?', chapter: 'Reserve Overcome' },
  { id: 1257, kural_number: 1257, tamil_text: 'நாணென ஒன்றோ அறியலம் காமத்தால் பேணியார் பெட்ப செயின்.', transliteration: 'Naanena Ondro Ariyalam Kaamaththaal Peniyaar Petpa Seyin', english_meaning: 'I know nothing like shame when my beloved does from love (just) what is desired (by me)', career_application: 'I know nothing like shame when my beloved does from love (just) what is desired (by me)', chapter: 'Reserve Overcome' },
  { id: 1258, kural_number: 1258, tamil_text: 'பன்மாயக் கள்வன் பணிமொழி அன்றோநம் பெண்மை உடைக்கும் படை.', transliteration: 'Panmaayak Kalvan Panimozhi Andronam Penmai Utaikkum Patai', english_meaning: 'Are not the enticing words of my trick-abounding roguish lover the weapon that breaks away my feminine firmness?', career_application: 'Are not the enticing words of my trick-abounding roguish lover the weapon that breaks away my feminine firmness?', chapter: 'Reserve Overcome' },
  { id: 1259, kural_number: 1259, tamil_text: 'புலப்பல் எனச்சென்றேன் புல்லினேன் நெஞ்சம் கலத்தல் உறுவது கண்டு.', transliteration: 'Pulappal Enachchendren Pullinen Nenjam Kalaththal Uruvadhu Kantu', english_meaning: 'I said I would feign dislike and so went (away); (but) I embraced him the moment I say my mind began to unite with him!', career_application: 'I said I would feign dislike and so went (away); (but) I embraced him the moment I say my mind began to unite with him!', chapter: 'Reserve Overcome' },
  { id: 1260, kural_number: 1260, tamil_text: 'நிணந்தீயில் இட்டன்ன நெஞ்சினார்க்கு உண்டோ புணர்ந்தூடி நிற்பேம் எனல்.', transliteration: 'Ninandheeyil Ittanna Nenjinaarkku Unto Punarndhooti Nirpem Enal', english_meaning: 'Is it possible for those whose hearts melt like fat in the fire to say they can feign a strong dislike and remain so?', career_application: 'Is it possible for those whose hearts melt like fat in the fire to say they can feign a strong dislike and remain so?', chapter: 'Reserve Overcome' },
  { id: 1261, kural_number: 1261, tamil_text: 'வாளற்றுப் புற்கென்ற கண்ணும் அவர்சென்ற நாளொற்றித் தேய்ந்த விரல்.', transliteration: 'Vaalatrup Purkendra Kannum Avarsendra Naalotrith Theyndha Viral', english_meaning: 'My finger has worn away by marking (on the wall) the days he has been absent while my eyes have lost their lustre and begin to fail', career_application: 'My finger has worn away by marking (on the wall) the days he has been absent while my eyes have lost their lustre and begin to fail', chapter: 'Mutual Desire' },
  { id: 1262, kural_number: 1262, tamil_text: 'இலங்கிழாய் இன்று மறப்பின்என் தோள்மேல் கலங்கழியும் காரிகை நீத்து.', transliteration: 'Ilangizhaai Indru Marappinen Tholmel Kalangazhiyum Kaarikai Neeththu', english_meaning: 'O you bright-jewelled maid, if I forget (him) today, my shoulders will lose their beauty even in the other life and make my bracelets loose', career_application: 'O you bright-jewelled maid, if I forget (him) today, my shoulders will lose their beauty even in the other life and make my bracelets loose', chapter: 'Mutual Desire' },
  { id: 1263, kural_number: 1263, tamil_text: 'உரன்நசைஇ உள்ளம் துணையாகச் சென்றார் வரல்நசைஇ இன்னும் உளேன்.', transliteration: 'Urannasaii Ullam Thunaiyaakach Chendraar Varalnasaii Innum Ulen', english_meaning: 'I still live by longing for the arrival of him who has gone out of love for victory and with valour as his guide', career_application: 'I still live by longing for the arrival of him who has gone out of love for victory and with valour as his guide', chapter: 'Mutual Desire' },
  { id: 1264, kural_number: 1264, tamil_text: 'கூடிய காமம் பிரிந்தார் வரவுள்ளிக் கோடுகொ டேறுமென் நெஞ்சு.', transliteration: 'Kootiya Kaamam Pirindhaar Varavullik Kotuko Terumen Nenju', english_meaning: 'My heart is rid of its sorrow and swells with rapture to think of my absent lover returning with his love', career_application: 'My heart is rid of its sorrow and swells with rapture to think of my absent lover returning with his love', chapter: 'Mutual Desire' },
  { id: 1265, kural_number: 1265, tamil_text: 'காண்கமன் கொண்கனைக் கண்ணாரக் கண்டபின் நீங்கும்என் மென்தோள் பசப்பு.', transliteration: 'Kaankaman Konkanaik Kannaarak Kantapin Neengumen Mendhol Pasappu', english_meaning: 'May I look on my lover till I am satisfied and thereafter will vanish the sallowness of my slender shoulders', career_application: 'May I look on my lover till I am satisfied and thereafter will vanish the sallowness of my slender shoulders', chapter: 'Mutual Desire' },
  { id: 1266, kural_number: 1266, tamil_text: 'வருகமன் கொண்கன் ஒருநாள் பருகுவன் பைதல்நோய் எல்லாம் கெட.', transliteration: 'Varukaman Konkan Orunaal Parukuvan Paidhalnoi Ellaam Keta', english_meaning: 'May my husband return some day; and then will I enjoy (him) so as to destroy all this agonizing sorrow', career_application: 'May my husband return some day; and then will I enjoy (him) so as to destroy all this agonizing sorrow', chapter: 'Mutual Desire' },
  { id: 1267, kural_number: 1267, tamil_text: 'புலப்பேன்கொல் புல்லுவேன் கொல்லோ கலப்பேன்கொல் கண்அன்ன கேளிர் விரன்.', transliteration: 'Pulappenkol Pulluven Kollo Kalappenkol Kananna Kelir Viran', english_meaning: 'On the return of him who is as dear as my eyes, am I displeased or am I to embrace (him); or am I to do both?', career_application: 'On the return of him who is as dear as my eyes, am I displeased or am I to embrace (him); or am I to do both?', chapter: 'Mutual Desire' },
  { id: 1268, kural_number: 1268, tamil_text: 'வினைகலந்து வென்றீக வேந்தன் மனைகலந்து மாலை அயர்கம் விருந்து.', transliteration: 'Vinaikalandhu Vendreeka Vendhan Manaikalandhu Maalai Ayarkam Virundhu', english_meaning: 'Let the king fight and gain (victories); (but) let me be united to my wife and feast the evening', career_application: 'Let the king fight and gain (victories); (but) let me be united to my wife and feast the evening', chapter: 'Mutual Desire' },
  { id: 1269, kural_number: 1269, tamil_text: 'ஒருநாள் எழுநாள்போல் செல்லும்சேண் சென்றார் வருநாள்வைத்து ஏங்கு பவர்க்கு.', transliteration: 'Orunaal Ezhunaalpol Sellumsen Sendraar Varunaalvaiththu Engu Pavarkku', english_meaning: 'To those who suffer waiting for the day of return of their distant lovers one day is as long as seven days', career_application: 'To those who suffer waiting for the day of return of their distant lovers one day is as long as seven days', chapter: 'Mutual Desire' },
  { id: 1270, kural_number: 1270, tamil_text: 'பெறின்என்னாம் பெற்றக்கால் என்னாம் உறினென்னாம் உள்ளம் உடைந்துக்கக் கால்.', transliteration: 'Perinennaam Petrakkaal Ennaam Urinennaam Ullam Utaindhukkak Kaal', english_meaning: 'After (my wife) has died of a broken heart, what good will there be if she is to receive me, has received me, or has even embraced me?', career_application: 'After (my wife) has died of a broken heart, what good will there be if she is to receive me, has received me, or has even embraced me?', chapter: 'Mutual Desire' },
  { id: 1271, kural_number: 1271, tamil_text: 'கரப்பினுங் கையிகந் தொல்லாநின் உண்கண் உரைக்கல் உறுவதொன் றுண்டு.', transliteration: 'Karappinung Kaiyikan Thollaanin Unkan Uraikkal Uruvadhon Runtu', english_meaning: 'Though you would conceal (your feelings), your painted eyes would not, for, transgressing (their bounds), they tell (me) something', career_application: 'Though you would conceal (your feelings), your painted eyes would not, for, transgressing (their bounds), they tell (me) something', chapter: 'The Reading of the Signs' },
  { id: 1272, kural_number: 1272, tamil_text: 'கண்ணிறைந்த காரிகைக் காம்பேர்தோட் பேதைக்குப் பெண்நிறைந்த நீர்மை பெரிது.', transliteration: 'Kanniraindha Kaarikaik Kaamperdhot Pedhaikkup Penniraindha Neermai Peridhu', english_meaning: 'Unusually great is the female simplicity of your maid whose beauty fills my eyes and whose shoulders resemble the bamboo', career_application: 'Unusually great is the female simplicity of your maid whose beauty fills my eyes and whose shoulders resemble the bamboo', chapter: 'The Reading of the Signs' },
  { id: 1273, kural_number: 1273, tamil_text: 'மணியில் திகழ்தரு நூல்போல் மடந்தை அணியில் திகழ்வதொன்று உண்டு.', transliteration: 'Maniyil Thikazhdharu Noolpol Matandhai Aniyil Thikazhvadhondru Untu', english_meaning: 'There is something that is implied in the beauty of this woman, like the thread that is visible in a garland of gems', career_application: 'There is something that is implied in the beauty of this woman, like the thread that is visible in a garland of gems', chapter: 'The Reading of the Signs' },
  { id: 1274, kural_number: 1274, tamil_text: 'முகைமொக்குள் உள்ளது நாற்றம்போல் பேதை நகைமொக்குள் உள்ளதொன் றுண்டு.', transliteration: 'Mukaimokkul Ulladhu Naatrampol Pedhai Nakaimokkul Ulladhon Runtu', english_meaning: 'There is something in the unmatured smile of this maid like the fragrance that is contained in an unblossomed bud', career_application: 'There is something in the unmatured smile of this maid like the fragrance that is contained in an unblossomed bud', chapter: 'The Reading of the Signs' },
  { id: 1275, kural_number: 1275, tamil_text: 'செறிதொடி செய்திறந்த கள்ளம் உறுதுயர் தீர்க்கும் மருந்தொன்று உடைத்து.', transliteration: 'Seridhoti Seydhirandha Kallam Urudhuyar Theerkkum Marundhondru Utaiththu', english_meaning: 'The well-meant departure of her whose bangles are tight-fitting contains a remedy that can cure my great sorrow', career_application: 'The well-meant departure of her whose bangles are tight-fitting contains a remedy that can cure my great sorrow', chapter: 'The Reading of the Signs' },
  { id: 1276, kural_number: 1276, tamil_text: 'பெரிதாற்றிப் பெட்பக் கலத்தல் அரிதாற்றி அன்பின்மை சூழ்வ துடைத்து.', transliteration: 'Peridhaatrip Petpak Kalaththal Aridhaatri Anpinmai Soozhva Thutaiththu', english_meaning: 'The embrace that fills me with comfort and gladness is capable of enduring (my former) sorrow and meditating on his want of love', career_application: 'The embrace that fills me with comfort and gladness is capable of enduring (my former) sorrow and meditating on his want of love', chapter: 'The Reading of the Signs' },
  { id: 1277, kural_number: 1277, tamil_text: 'தண்ணந் துறைவன் தணந்தமை நம்மினும் முன்னம் உணர்ந்த வளை.', transliteration: 'Thannan Thuraivan Thanandhamai Namminum Munnam Unarndha Valai', english_meaning: 'My bracelets have understood before me the (mental) separation of him who rules the cool seashore', career_application: 'My bracelets have understood before me the (mental) separation of him who rules the cool seashore', chapter: 'The Reading of the Signs' },
  { id: 1278, kural_number: 1278, tamil_text: 'நெருநற்றுச் சென்றார்எம் காதலர் யாமும் எழுநாளேம் மேனி பசந்து.', transliteration: 'Nerunatruch Chendraarem Kaadhalar Yaamum Ezhunaalem Meni Pasandhu', english_meaning: 'It was but yesterday my lover departed (from me); and it is seven days since my complexion turned sallow', career_application: 'It was but yesterday my lover departed (from me); and it is seven days since my complexion turned sallow', chapter: 'The Reading of the Signs' },
  { id: 1279, kural_number: 1279, tamil_text: 'தொடிநோக்கி மென்தோளும் நோக்கி அடிநோக்கி அஃதாண் டவள்செய் தது.', transliteration: 'Thotinokki Mendholum Nokki Atinokki Aqdhaan Tavalsey Thadhu', english_meaning: 'She looked at her bracelets, her tender shoulders, and her feet; this was what she did there (significantly)', career_application: 'She looked at her bracelets, her tender shoulders, and her feet; this was what she did there (significantly)', chapter: 'The Reading of the Signs' },
  { id: 1280, kural_number: 1280, tamil_text: 'பெண்ணினால் பெண்மை உடைத்தென்ப கண்ணினால் காமநோய் சொல்லி இரவு.', transliteration: 'Penninaal Penmai Utaiththenpa Kanninaal Kaamanoi Solli Iravu', english_meaning: 'To express their love-sickness by their eyes and resort to begging bespeaks more than ordinary female excellence', career_application: 'To express their love-sickness by their eyes and resort to begging bespeaks more than ordinary female excellence', chapter: 'The Reading of the Signs' },
  { id: 1281, kural_number: 1281, tamil_text: 'உள்ளக் களித்தலும் காண மகிழ்தலும் கள்ளுக்கில் காமத்திற் குண்டு.', transliteration: 'Ullak Kaliththalum Kaana Makizhdhalum Kallukkil Kaamaththir Kuntu', english_meaning: 'To please by thought and cheer by sight is peculiar, not to liquor but lust', career_application: 'To please by thought and cheer by sight is peculiar, not to liquor but lust', chapter: 'Desire for Reunion' },
  { id: 1282, kural_number: 1282, tamil_text: 'தினைத்துணையும் ஊடாமை வேண்டும் பனைத்துணையும் காமம் நிறைய வரின்.', transliteration: 'Thinaiththunaiyum Ootaamai Ventum Panaith Thunaiyum Kaamam Niraiya Varin', english_meaning: 'If women have a lust that exceeds even the measure of the palmyra fruit, they will not desire (to feign) dislike even as much as the millet', career_application: 'If women have a lust that exceeds even the measure of the palmyra fruit, they will not desire (to feign) dislike even as much as the millet', chapter: 'Desire for Reunion' },
  { id: 1283, kural_number: 1283, tamil_text: 'பேணாது பெட்பவே செய்யினும் கொண்கனைக் காணா தமையல கண்.', transliteration: 'Penaadhu Petpave Seyyinum Konkanaik Kaanaa Thamaiyala Kan', english_meaning: 'Though my eyes disregard me and do what is pleasing to my husband, still will they not be satisfied unless they see him', career_application: 'Though my eyes disregard me and do what is pleasing to my husband, still will they not be satisfied unless they see him', chapter: 'Desire for Reunion' },
  { id: 1284, kural_number: 1284, tamil_text: 'ஊடற்கண் சென்றேன்மன் தோழி அதுமறந்து கூடற்கண் சென்றது என் னெஞ்சு.', transliteration: 'Ootarkan Sendrenman Thozhi Adhumarandhu Kootarkan Sendradhu En Nenju', english_meaning: 'My heart, forgetting all, could not its love restrain', career_application: 'My heart, forgetting all, could not its love restrain', chapter: 'Desire for Reunion' },
  { id: 1285, kural_number: 1285, tamil_text: 'எழுதுங்கால் கோல்காணாக் கண்ணேபோல் கொண்கன் பழிகாணேன் கண்ட இடத்து.', transliteration: 'Ezhudhungaal Kolkaanaak Kannepol Konkan Pazhikaanen Kanta Itaththu', english_meaning: 'Like the eyes which see not the pencil that paints it, I cannot see my husband\'s fault (just) when I meet him', career_application: 'Like the eyes which see not the pencil that paints it, I cannot see my husband\'s fault (just) when I meet him', chapter: 'Desire for Reunion' },
  { id: 1286, kural_number: 1286, tamil_text: 'காணுங்கால் காணேன் தவறாய காணாக்கால் காணேன் தவறல் லவை.', transliteration: 'Kaanungaal Kaanen Thavaraaya Kaanaakkaal Kaanen Thavaral Lavai', english_meaning: 'When I see my husband, I do not see any faults; but when I do not see him, I do not see anything but faults', career_application: 'When I see my husband, I do not see any faults; but when I do not see him, I do not see anything but faults', chapter: 'Desire for Reunion' },
  { id: 1287, kural_number: 1287, tamil_text: 'உய்த்தல் அறிந்து புனல்பாய் பவரேபோல் பொய்த்தல் அறிந்தென் புலந்து.', transliteration: 'Uyththal Arindhu Punalpaai Pavarepol Poiththal Arindhen Pulandhu', english_meaning: 'Like those who leap into a stream which they know will carry them off, why should a wife feign dislike which she knows cannot hold out long?', career_application: 'Like those who leap into a stream which they know will carry them off, why should a wife feign dislike which she knows cannot hold out long?', chapter: 'Desire for Reunion' },
  { id: 1288, kural_number: 1288, tamil_text: 'இளித்தக்க இன்னா செயினும் களித்தார்க்குக் கள்ளற்றே கள்வநின் மார்பு.', transliteration: 'Iliththakka Innaa Seyinum Kaliththaarkkuk Kallatre Kalvanin Maarpu', english_meaning: 'O you rogue! your breast is to me what liquor is to those who rejoice in it, though it only gives them an unpleasant disgrace', career_application: 'O you rogue! your breast is to me what liquor is to those who rejoice in it, though it only gives them an unpleasant disgrace', chapter: 'Desire for Reunion' },
  { id: 1289, kural_number: 1289, tamil_text: 'மலரினும் மெல்லிது காமம் சிலர்அதன் செவ்வி தலைப்படு வார்.', transliteration: 'Malarinum Mellidhu Kaamam Silaradhan Sevvi Thalaippatu Vaar', english_meaning: 'Sexual delight is more delicate than a flower, and few are those who understand its real nature', career_application: 'Sexual delight is more delicate than a flower, and few are those who understand its real nature', chapter: 'Desire for Reunion' },
  { id: 1290, kural_number: 1290, tamil_text: 'கண்ணின் துனித்தே கலங்கினாள் புல்லுதல் என்னினும் தான்விதுப் புற்று.', transliteration: 'Kannin Thuniththe Kalanginaal Pulludhal Enninum Thaanvidhup Putru', english_meaning: 'She once feigned dislike in her eyes, but the warmth of her embrace exceeded my own', career_application: 'She once feigned dislike in her eyes, but the warmth of her embrace exceeded my own', chapter: 'Desire for Reunion' },
  { id: 1291, kural_number: 1291, tamil_text: 'அவர்நெஞ்சு அவர்க்காதல் கண்டும் எவன்நெஞ்சே நீஎமக்கு ஆகா தது.', transliteration: 'Avarnenju Avarkkaadhal Kantum Evannenje Neeemakku Aakaa Thadhu', english_meaning: 'O my soul! although you have seen how his soul stands by him, how is it you do not stand by me?', career_application: 'O my soul! although you have seen how his soul stands by him, how is it you do not stand by me?', chapter: 'Expostulation with Oneself' },
  { id: 1292, kural_number: 1292, tamil_text: 'உறாஅ தவர்க்கண்ட கண்ணும் அவரைச் செறாஅரெனச் சேறியென் நெஞ்சு.', transliteration: 'Uraaa Thavarkkanta Kannum Avaraich Cheraaarenach Cheriyen Nenju', english_meaning: 'O my soul! although you have known him who does not love me, still do you go to him, saying "he will not be displeased."', career_application: 'O my soul! although you have known him who does not love me, still do you go to him, saying "he will not be displeased."', chapter: 'Expostulation with Oneself' },
  { id: 1293, kural_number: 1293, tamil_text: 'கெட்டார்க்கு நட்டார்இல் என்பதோ நெஞ்சேநீ பெட்டாங்கு அவர்பின் செலல்.', transliteration: 'Kettaarkku Nattaaril Enpadho Nenjenee Pettaangu Avarpin Selal', english_meaning: 'O my soul! do you follow him at pleasure under the belief that the ruined have no friends?', career_application: 'O my soul! do you follow him at pleasure under the belief that the ruined have no friends?', chapter: 'Expostulation with Oneself' },
  { id: 1294, kural_number: 1294, tamil_text: 'இனிஅன்ன நின்னொடு சூழ்வார்யார் நெஞ்சே துனிசெய்து துவ்வாய்காண் மற்று.', transliteration: 'Inianna Ninnotu Soozhvaaryaar Nenje Thuniseydhu Thuvvaaikaan Matru', english_meaning: 'O my soul! you would not first seem sulky and then enjoy (him); who then would in future consult you about such things?', career_application: 'O my soul! you would not first seem sulky and then enjoy (him); who then would in future consult you about such things?', chapter: 'Expostulation with Oneself' },
  { id: 1295, kural_number: 1295, tamil_text: 'பெறாஅமை அஞ்சும் பெறின்பிரிவு அஞ்சும் அறாஅ இடும்பைத்தென் நெஞ்சு.', transliteration: 'Peraaamai Anjum Perinpirivu Anjum Araaa Itumpaiththen Nenju', english_meaning: 'My soul fears when it is without him; it also fears when it is with him; it is subject to incessant sorrow', career_application: 'My soul fears when it is without him; it also fears when it is with him; it is subject to incessant sorrow', chapter: 'Expostulation with Oneself' },
  { id: 1296, kural_number: 1296, tamil_text: 'தனியே இருந்து நினைத்தக்கால் என்னைத் தினிய இருந்ததென் நெஞ்சு.', transliteration: 'Thaniye Irundhu Ninaiththakkaal Ennaith Thiniya Irundhadhen Nenju', english_meaning: 'My mind has been (here) in order to eat me up (as it were) whenever I think of him in my solitude', career_application: 'My mind has been (here) in order to eat me up (as it were) whenever I think of him in my solitude', chapter: 'Expostulation with Oneself' },
  { id: 1297, kural_number: 1297, tamil_text: 'நாணும் மறந்தேன் அவர்மறக் கல்லாஎன் மாணா மடநெஞ்சிற் பட்டு.', transliteration: 'Naanum Marandhen Avarmarak Kallaaen Maanaa Matanenjir Pattu', english_meaning: 'I have even forgotten my modesty, having been caught in my foolish mind which is not dignified enough to forget him', career_application: 'I have even forgotten my modesty, having been caught in my foolish mind which is not dignified enough to forget him', chapter: 'Expostulation with Oneself' },
  { id: 1298, kural_number: 1298, tamil_text: 'எள்ளின் இளிவாம்என்று எண்ணி அவர்திறம் உள்ளும் உயிர்க்காதல் நெஞ்சு.', transliteration: 'Ellin Ilivaamendru Enni Avardhiram Ullum Uyirkkaadhal Nenju', english_meaning: 'My soul which clings to life thinks only of his (own) gain in the belief that it would be disgraceful for it to despise him', career_application: 'My soul which clings to life thinks only of his (own) gain in the belief that it would be disgraceful for it to despise him', chapter: 'Expostulation with Oneself' },
  { id: 1299, kural_number: 1299, tamil_text: 'துன்பத்திற்கு யாரே துணையாவார் தாமுடைய நெஞ்சந் துணையல் வழி.', transliteration: 'Thunpaththirku Yaare Thunaiyaavaar Thaamutaiya Nenjan Thunaiyal Vazhi', english_meaning: 'Who would help me out of one\'s distress, when one\'s own soul refuses help to one?', career_application: 'Who would help me out of one\'s distress, when one\'s own soul refuses help to one?', chapter: 'Expostulation with Oneself' },
  { id: 1300, kural_number: 1300, tamil_text: 'தஞ்சம் தமரல்லர் ஏதிலார் தாமுடைய நெஞ்சம் தமரல் வழி.', transliteration: 'Thanjam Thamarallar Edhilaar Thaamutaiya Nenjam Thamaral Vazhi', english_meaning: 'It is hardly possible for strangers to behave like relations, when one\'s own soul acts like a stranger', career_application: 'It is hardly possible for strangers to behave like relations, when one\'s own soul acts like a stranger', chapter: 'Expostulation with Oneself' },
  { id: 1301, kural_number: 1301, tamil_text: 'புல்லா திராஅப் புலத்தை அவர்உறும் அல்லல்நோய் காண்கம் சிறிது.', transliteration: 'Pullaa Thiraaap Pulaththai Avar Urum Allalnoi Kaankam Siridhu', english_meaning: 'Let us witness awhile his keen suffering; just feign dislike and embrace him not', career_application: 'Let us witness awhile his keen suffering; just feign dislike and embrace him not', chapter: 'Pouting' },
  { id: 1302, kural_number: 1302, tamil_text: 'உப்பமைந் தற்றால் புலவி அதுசிறிது மிக்கற்றால் நீள விடல்.', transliteration: 'Uppamain Thatraal Pulavi Adhusiridhu Mikkatraal Neela Vital', english_meaning: 'A little dislike is like salt in proportion; to prolong it a little is like salt a little too much', career_application: 'A little dislike is like salt in proportion; to prolong it a little is like salt a little too much', chapter: 'Pouting' },
  { id: 1303, kural_number: 1303, tamil_text: 'அலந்தாரை அல்லல்நோய் செய்தற்றால் தம்மைப் புலந்தாரைப் புல்லா விடல்.', transliteration: 'Alandhaarai Allalnoi Seydhatraal Thammaip Pulandhaaraip Pullaa Vital', english_meaning: 'For men not to embrace those who have feigned dislike is like torturing those already in agony', career_application: 'For men not to embrace those who have feigned dislike is like torturing those already in agony', chapter: 'Pouting' },
  { id: 1304, kural_number: 1304, tamil_text: 'ஊடி யவரை உணராமை வாடிய வள்ளி முதலரிந் தற்று.', transliteration: 'Ooti Yavarai Unaraamai Vaatiya Valli Mudhalarin Thatru', english_meaning: 'Not to reconcile those who have feigned dislike is like cutting a faded creeper at its root', career_application: 'Not to reconcile those who have feigned dislike is like cutting a faded creeper at its root', chapter: 'Pouting' },
  { id: 1305, kural_number: 1305, tamil_text: 'நலத்தகை நல்லவர்க்கு ஏஎர் புலத்தகை பூஅன்ன கண்ணார் அகத்து.', transliteration: 'Nalaththakai Nallavarkku Eer Pulaththakai Pooanna Kannaar Akaththu', english_meaning: 'An increased shyness in those whose eyes are like flowers is beautiful even to good and virtuous husbands', career_application: 'An increased shyness in those whose eyes are like flowers is beautiful even to good and virtuous husbands', chapter: 'Pouting' },
  { id: 1306, kural_number: 1306, tamil_text: 'துனியும் புலவியும் இல்லாயின் காமம் கனியும் கருக்காயும் அற்று.', transliteration: 'Thuniyum Pulaviyum Illaayin Kaamam Kaniyum Karukkaayum Atru', english_meaning: 'Sexual pleasure, without prolonged and short-lived dislike, is like too ripe, and unripe fruit', career_application: 'Sexual pleasure, without prolonged and short-lived dislike, is like too ripe, and unripe fruit', chapter: 'Pouting' },
  { id: 1307, kural_number: 1307, tamil_text: 'ஊடலின் உண்டாங்கோர் துன்பம் புணர்வது நீடுவ தன்று கொல் என்று.', transliteration: 'Ootalin Untaangor Thunpam Punarvadhu Neetuva Thandru Kol Endru', english_meaning: 'The doubt as to whether intercourse would take place soon or not, creates a sorrow (even) in feigned dislike', career_application: 'The doubt as to whether intercourse would take place soon or not, creates a sorrow (even) in feigned dislike', chapter: 'Pouting' },
  { id: 1308, kural_number: 1308, tamil_text: 'நோதல் எவன்மற்று நொந்தாரென்று அஃதறியும் காதலர் இல்லா வழி.', transliteration: 'Nodhal Evanmatru Nondhaarendru Aqdhariyum Kaadhalar Illaa Vazhi', english_meaning: 'What avails sorrow when I am without a wife who can understand the cause of my sorrow?', career_application: 'What avails sorrow when I am without a wife who can understand the cause of my sorrow?', chapter: 'Pouting' },
  { id: 1309, kural_number: 1309, tamil_text: 'நீரும் நிழலது இனிதே புலவியும் வீழுநர் கண்ணே இனிது.', transliteration: 'Neerum Nizhaladhu Inidhe Pulaviyum Veezhunar Kanne Inidhu', english_meaning: 'Like water in the shade, dislike is delicious only in those who love', career_application: 'Like water in the shade, dislike is delicious only in those who love', chapter: 'Pouting' },
  { id: 1310, kural_number: 1310, tamil_text: 'ஊடல் உணங்க விடுவாரோடு என்நெஞ்சம் கூடுவேம் என்பது அவா.', transliteration: 'Ootal Unanga Vituvaarotu Ennenjam Kootuvem Enpadhu Avaa', english_meaning: 'It is nothing but strong desire that makes her mind unite with me who can leave her to her own dislike', career_application: 'It is nothing but strong desire that makes her mind unite with me who can leave her to her own dislike', chapter: 'Pouting' },
  { id: 1311, kural_number: 1311, tamil_text: 'பெண்ணியலார் எல்லாரும் கண்ணின் பொதுஉண்பர் நண்ணேன் பரத்தநின் மார்பு.', transliteration: 'Penniyalaar Ellaarum Kannin Podhuunpar Nannen Paraththanin Maarpu', english_meaning: 'You are given to prostitution; all those who are born as womankind enjoy you with their eyes in an ordinary way I will not embrace you', career_application: 'You are given to prostitution; all those who are born as womankind enjoy you with their eyes in an ordinary way I will not embrace you', chapter: 'Feigned Anger' },
  { id: 1312, kural_number: 1312, tamil_text: 'ஊடி இருந்தேமாத் தும்மினார் யாம்தம்மை நீடுவாழ் கென்பாக் கறிந்து.', transliteration: 'Ooti Irundhemaath Thumminaar Yaamdhammai Neetuvaazh Kenpaak Karindhu', english_meaning: 'When I continued to be sulky he sneezed and thought I would (then) wish him a long life', career_application: 'When I continued to be sulky he sneezed and thought I would (then) wish him a long life', chapter: 'Feigned Anger' },
  { id: 1313, kural_number: 1313, tamil_text: 'கோட்டுப்பூச் சூடினும் காயும் ஒருத்தியைக் காட்டிய சூடினீர் என்று.', transliteration: 'Kottup Pooch Chootinum Kaayum Oruththiyaik Kaattiya Sootineer Endru', english_meaning: 'Even if I were adorned with a garland of branch-flowers, she would say I did so to show it to another woman', career_application: 'Even if I were adorned with a garland of branch-flowers, she would say I did so to show it to another woman', chapter: 'Feigned Anger' },
  { id: 1314, kural_number: 1314, tamil_text: 'யாரினும் காதலம் என்றேனா ஊடினாள் யாரினும் யாரினும் என்று.', transliteration: 'Yaarinum Kaadhalam Endrenaa Ootinaal Yaarinum Yaarinum Endru', english_meaning: 'When I said I loved her more than any other woman, she said "more than others, yes, more than others," and remained sulky', career_application: 'When I said I loved her more than any other woman, she said "more than others, yes, more than others," and remained sulky', chapter: 'Feigned Anger' },
  { id: 1315, kural_number: 1315, tamil_text: 'இம்மைப் பிறப்பில் பிரியலம் என்றேனாக் கண்நிறை நீர்கொண் டனள்.', transliteration: 'Immaip Pirappil Piriyalam Endrenaak Kannirai Neerkon Tanal', english_meaning: 'When I said I would never part from her in this life her eyes were filled with tears', career_application: 'When I said I would never part from her in this life her eyes were filled with tears', chapter: 'Feigned Anger' },
  { id: 1316, kural_number: 1316, tamil_text: 'உள்ளினேன் என்றேன்மற் றென்மறந்தீர் என்றென்னைப் புல்லாள் புலத்தக் கனள்.', transliteration: 'Ullinen Endrenmar Renmarandheer Endrennaip Pullaal Pulaththak Kanal', english_meaning: 'When I said I had remembered her, she said I had forgotten her and relaxing her embrace, began to feign dislike', career_application: 'When I said I had remembered her, she said I had forgotten her and relaxing her embrace, began to feign dislike', chapter: 'Feigned Anger' },
  { id: 1317, kural_number: 1317, tamil_text: 'வழுத்தினாள் தும்மினேன் ஆக அழித்தழுதாள் யாருள்ளித் தும்மினீர் என்று.', transliteration: 'Vazhuththinaal Thumminen Aaka Azhiththazhudhaal Yaarullith Thummineer Endru', english_meaning: 'When I sneezed she blessed me, but at once changed (her mind) and wept, asking, "At the thought of whom did you sneeze?"', career_application: 'When I sneezed she blessed me, but at once changed (her mind) and wept, asking, "At the thought of whom did you sneeze?"', chapter: 'Feigned Anger' },
  { id: 1318, kural_number: 1318, tamil_text: 'தும்முச் செறுப்ப அழுதாள் நுமர்உள்ளல் எம்மை மறைத்திரோ என்று.', transliteration: 'Thummuch Cheruppa Azhudhaal Numarullal Emmai Maraiththiro Endru', english_meaning: 'When I suppressed my sneezing, she wept saying, "I suppose you (did so) to hide from me your own people\'s remembrance of you"', career_application: 'When I suppressed my sneezing, she wept saying, "I suppose you (did so) to hide from me your own people\'s remembrance of you"', chapter: 'Feigned Anger' },
  { id: 1319, kural_number: 1319, tamil_text: 'தன்னை உணர்த்தினும் காயும் பிறர்க்கும்நீர் இந்நீரர் ஆகுதிர் என்று.', transliteration: 'Thannai Unarththinum Kaayum Pirarkkumneer Inneerar Aakudhir Endru', english_meaning: '\'I see\', quoth she, \'to other folks How you are wondrous kind\' Even when I try to remove her dislike, she is displeased and says, "This is the way you behave', career_application: '\'I see\', quoth she, \'to other folks How you are wondrous kind\' Even when I try to remove her dislike, she is displeased and says, "This is the way you behave', chapter: 'Feigned Anger' },
  { id: 1320, kural_number: 1320, tamil_text: 'நினைத்திருந்து நோக்கினும் காயும் அனைத்துநீர் யாருள்ளி நோக்கினீர் என்று.', transliteration: 'Ninaiththirundhu Nokkinum Kaayum Anaiththuneer Yaarulli Nokkineer Endru', english_meaning: 'Even when I look on her contemplating (her beauty), she is displeased and says, "With whose thought have you (thus) looked on my person?"', career_application: 'Even when I look on her contemplating (her beauty), she is displeased and says, "With whose thought have you (thus) looked on my person?"', chapter: 'Feigned Anger' },
  { id: 1321, kural_number: 1321, tamil_text: 'இல்லை தவறவர்க்கு ஆயினும் ஊடுதல் வல்லது அவர்அள஧க்கு மாறு.', transliteration: 'Illai Thavaravarkku Aayinum Ootudhal Valladhu Avaralikku Maaru', english_meaning: 'Although my husband is free from defects, the way in which he embraces me is such as to make me feign dislike', career_application: 'Although my husband is free from defects, the way in which he embraces me is such as to make me feign dislike', chapter: 'The Pleasures of Temporary Variance' },
  { id: 1322, kural_number: 1322, tamil_text: 'ஊடலின் தோன்றும் சிறுதுனி நல்லளி வாடினும் பாடு பெறும்.', transliteration: 'Ootalin Thondrum Sirudhuni Nallali Vaatinum Paatu Perum', english_meaning: 'His love will increase though it may (at first seem to) fade through the short-lived distress caused by (my) dislike', career_application: 'His love will increase though it may (at first seem to) fade through the short-lived distress caused by (my) dislike', chapter: 'The Pleasures of Temporary Variance' },
  { id: 1323, kural_number: 1323, tamil_text: 'புலத்தலின் புத்தேள்நாடு உண்டோ நிலத்தொடு நீரியைந் தன்னார் அகத்து.', transliteration: 'Pulaththalin Puththelnaatu Unto Nilaththotu Neeriyain Thannaar Akaththu', english_meaning: 'Is there a celestial land that can please like the feigned dislike of those whose union resembles that of earth and water?', career_application: 'Is there a celestial land that can please like the feigned dislike of those whose union resembles that of earth and water?', chapter: 'The Pleasures of Temporary Variance' },
  { id: 1324, kural_number: 1324, tamil_text: 'புல்லி விடாஅப் புலவியுள் தோன்றுமென் உள்ளம் உடைக்கும் படை.', transliteration: 'Pulli Vitaaap Pulaviyul Thondrumen Ullam Utaikkum Patai', english_meaning: 'In prolonged dislike after an embrace there is a weapon that can break my heart', career_application: 'In prolonged dislike after an embrace there is a weapon that can break my heart', chapter: 'The Pleasures of Temporary Variance' },
  { id: 1325, kural_number: 1325, tamil_text: 'தவறிலர் ஆயினும் தாம்வீழ்வார் மென்றோள் அகறலின் ஆங்கொன் றுடைத்து.', transliteration: 'Thavarilar Aayinum Thaamveezhvaar Mendrol Akaralin Aangon Rutaiththu', english_meaning: 'Though free from defects, men feel pleased when they cannot embrace the delicate shoulders of those whom they love', career_application: 'Though free from defects, men feel pleased when they cannot embrace the delicate shoulders of those whom they love', chapter: 'The Pleasures of Temporary Variance' },
  { id: 1326, kural_number: 1326, tamil_text: 'உணலினும் உண்டது அறல்இனிது காமம் புணர்தலின் ஊடல் இனிது.', transliteration: 'Unalinum Untadhu Aralinidhu Kaamam Punardhalin Ootal Inidhu', english_meaning: 'To digest what has been eaten is more delightful than to eat more; likewise love is more delightful in dislike than intercourse', career_application: 'To digest what has been eaten is more delightful than to eat more; likewise love is more delightful in dislike than intercourse', chapter: 'The Pleasures of Temporary Variance' },
  { id: 1327, kural_number: 1327, tamil_text: 'ஊடலில் தோற்றவர் வென்றார் அதுமன்னும் கூடலிற் காணப் படும்.', transliteration: 'Ootalil Thotravar Vendraar Adhumannum Kootalir Kaanap Patum', english_meaning: 'Those are conquerors whose dislike has been defeated and that is proved by the love (which', career_application: 'Those are conquerors whose dislike has been defeated and that is proved by the love (which', chapter: 'The Pleasures of Temporary Variance' },
  { id: 1328, kural_number: 1328, tamil_text: 'ஊடிப் பெறுகுவம் கொல்லோ நுதல்வெயர்ப்பக் கூடலில் தோன்றிய உப்பு.', transliteration: 'Ootip Perukuvam Kollo Nudhalveyarppak Kootalil Thondriya Uppu', english_meaning: 'Will I enjoy once more through her dislike, the pleasure of that love that makes her forehead perspire?', career_application: 'Will I enjoy once more through her dislike, the pleasure of that love that makes her forehead perspire?', chapter: 'The Pleasures of Temporary Variance' },
  { id: 1329, kural_number: 1329, tamil_text: 'ஊடுக மன்னோ ஒளியிழை யாமிரப்ப நீடுக மன்னோ இரா.', transliteration: 'Ootuka Manno Oliyizhai Yaamirappa Neetuka Manno Iraa', english_meaning: 'May the bright-jewelled one feign dislike, and may the night be prolonged for me to implore her!', career_application: 'May the bright-jewelled one feign dislike, and may the night be prolonged for me to implore her!', chapter: 'The Pleasures of Temporary Variance' },
  { id: 1330, kural_number: 1330, tamil_text: 'ஊடுதல் காமத்திற்கு இன்பம் அதற்கின்பம் கூடி முயங்கப் பெறின்.', transliteration: 'Ootudhal Kaamaththirku Inpam Adharkinpam Kooti Muyangap Perin', english_meaning: 'Dislike adds delight to love; and a hearty embrace (thereafter) will add delight to dislike', career_application: 'Dislike adds delight to love; and a hearty embrace (thereafter) will add delight to dislike', chapter: 'The Pleasures of Temporary Variance' },
];
